\end{equation} 


\subsection{Относительные минимумы в двумерном случае}\label{subsec:relative_minima_in_dimension_2}


Пусть далее $d=2$. Тогда, как показано, например, в работе \cite{german_mathnotes_2006}, множество относительных минимумов решётки $\La=A\Z^2$, где
\[
  A=
  \begin{pmatrix}
    \theta & -1 \\
    1 & \phantom{-}\eta
  \end{pmatrix},
  \qquad
  \theta>1,
  \ \
  \eta>1,
\]
совпадает с множеством вершин её четырёх полигонов Клейна
\[
  \cK_{\pmb\e}(\La)=
  \conv\Big(\Big\{ \vec z=(z_1,z_2)\in\La\backslash\{\vec 0\} \,\Big|\, \e_iz_i\geq0,\ i=1,2 \Big\}\Big),
\]
\[
  \pmb\e=(\e_1,\e_2),
  \quad
  \e_1,\e_2=\pm1.
\]
Вершины же этих полигонов Клейна соответствуют подходящим дробям чисел $\theta$, $\eta$. А именно, их вершины являются образами при действии оператора $A$ точек
\begin{equation}\label{eq:vertices}
  \pm(1,0),\quad
  \pm(0,1),\quad
  \pm(q_k,p_k),\quad
  \pm(r_k,-s_k),\quad
  k=0,1,2,\ldots,
\end{equation}
где $p_k/q_k$ и $r_k/s_k$ --- подходящие дроби чисел $\theta$ и $\eta$ соответственно. Подробное описание данного соответствия можно найти в работе \cite{german_tlyustangelov_MJCNT_2016}, а также в обзоре \cite{german_UMN_2023}.

В частности, ввиду леммы \ref{l:hyperbolic_is_also_relative} 
все гиперболические минимумы решётки $\La$ являются образами при действии оператора $A$ каких-то точек вида \eqref{eq:vertices}.


\section{Доказательство теоремы \ref{t:spectrum_of_the_weak}}\label{sec:the_proof}


Зафиксируем $\beta>1$. Построим числа
\[
  \theta=[a_0;a_1,a_2,\ldots],\qquad
  \eta=[b_0;b_1,b_2,\ldots]
\]
следующим образом. Положим $a_0=b_0=1$, $a_1=2$, $b_1=[2^\beta]+1$ и для каждого целого $k\geq2$ положим
\begin{equation}\label{eq:next_partial_qoutients_definition}
  a_k=\bigg[\frac{s_{k-1}^\beta-q_{k-2}}{q_{k-1}}\bigg]+1,
  \qquad
  b_k=\bigg[\frac{q_k^\beta-s_{k-2}}{s_{k-1}}\bigg]+1,
\end{equation}
где $[\,\cdot\,]$ обозначает целую часть, $q_k$ --- знаменатель дроби $p_k/q_k=[a_0;a_1,a_2,\ldots,a_k]$, $s_k$ --- знаменатель дроби $r_k/s_k=[b_0;b_1,b_2,\ldots,b_k]$. 


\paragraph{Оценки роста знаменателей и неполных частных.}


Ввиду рекуррентных соотношений
\[
  q_k=a_kq_{k-1}+q_{k-2},
  \qquad
  s_k=b_ks_{k-1}+s_{k-2}
\]
из \eqref{eq:next_partial_qoutients_definition} следует, что для всех натуральных $k$ справедливы неравенства
\begin{equation}\label{eq:consecutive_denominators_inequalities}
\begin{array}{ll}
  q_k>
  \dfrac{s_{k-1}^\beta-q_{k-2}}{q_{k-1}}\cdot q_{k-1}+q_{k-2}=
  s_{k-1}^\beta,
  &
  s_k>
  \dfrac{q_k^\beta-s_{k-2}}{s_{k-1}}\cdot s_{k-1}+s_{k-2}=
  q_k^\beta,
  \\ \vphantom{1^{\Big|}}
  q_k<
  s_{k-1}^\beta+q_{k-1}<
  s_{k-1}^\beta+s_{k-1}^{1/\beta}<
  2s_{k-1}^\beta,
  &
  s_k<
  q_k^\beta+s_{k-1}<
  q_k^\beta+q_k^{1/\beta}<
  2q_k^\beta,
\end{array}
\end{equation}
а для всех достаточно больших $k$
\begin{equation}\label{eq:partial_quotients_vs_denominators}
\begin{array}{l}
  a_k>
  \dfrac{s_{k-1}^\beta-q_{k-2}}{q_{k-1}}>
  \dfrac{q_{k-1}^{\beta^2}-q_{k-1}^{1/\beta^2}}{q_{k-1}}>
  \dfrac12\,q_{k-1}^{\beta^2-1},
  \\ \vphantom{1^{\bigg|}}
  a_k<
  \dfrac{s_{k-1}^\beta-q_{k-2}}{q_{k-1}}+1<
  \dfrac{2^\beta q_{k-1}^{\beta^2}}{q_{k-1}}+1=
  2^\beta q_{k-1}^{\beta^2-1}+1,
  \\ \vphantom{1^{\bigg|}}
  b_k>
  \dfrac{q_k^\beta-s_{k-2}}{s_{k-1}}>
  \dfrac{s_{k-1}^{\beta^2}-s_{k-1}^{1/\beta^2}}{s_{k-1}}>
  \dfrac12\,s_{k-1}^{\beta^2-1},
  \\ \vphantom{1^{\bigg|}}
  b_k<
  \dfrac{q_k^\beta-s_{k-2}}{s_{k-1}}+1<
  \dfrac{2^\beta s_{k-1}^{\beta^2}}{s_{k-1}}+1=
  2^\beta s_{k-1}^{\beta^2-1}+1.
\end{array}
\end{equation}
В частности,
\begin{equation}\label{eq:denominators_asymptotics}
  q_k\asymp s_{k-1}^\beta,
  \qquad
  s_k\asymp q_k^\beta
\end{equation}
и
\begin{equation}\label{eq:partial_quotients_asymptotics}
  \,\quad
  a_{k+1}\asymp
  q_k^{\beta^2-1},
  \qquad
  b_{k+1}\asymp
  s_k^{\beta^2-1}.
\end{equation}


\paragraph{Неравенства для произведений.}


Как известно (см., например, \cite{lang,khintchine_CF,schmidt_DA}),
\[
  \frac1{a_{k+1}+2}<
  q_k|q_k\theta-p_k|<
  \frac1{a_{k+1}}\,,
  \qquad
  \frac1{b_{k+1}+2}<
  s_k|s_k\eta-r_k|<
  \frac1{b_{k+1}}\,.
  \qquad
\]
Учитывая \eqref{eq:partial_quotients_vs_denominators}, получаем, что для всех достаточно больших $k$
\begin{equation}\label{eq:bounds_for_the_products}
  \frac1{2^\beta q_k^{\beta^2-1}+3}<
  q_k|q_k\theta-p_k|<
  \frac2{q_k^{\beta^2-1}}\,,
  \qquad
  \frac1{2^\beta s_k^{\beta^2-1}+3}<
  s_k|s_k\eta-r_k|<
  \frac2{s_k^{\beta^2-1}}\,.
\end{equation}
Из \eqref{eq:consecutive_denominators_inequalities} и \eqref{eq:bounds_for_the_products} следует, что при фиксированном $\beta$ для всех достаточно больших $k$ справедливо
\[
  q_k|q_k\theta-p_k|>
  \frac1{2^\beta q_k^{\beta^2-1}+3}>
  \frac6{q_k^{\beta(\beta^2-1)}}>
  \frac6{s_k^{\beta^2-1}}>
  3s_k|s_k\eta-r_k|,
  \qquad\,\
\]
\[
  s_k|s_k\eta-r_k|>
  \frac1{2^\beta s_k^{\beta^2-1}+3}>
  \frac6{s_k^{\beta(\beta^2-1)}}>
  \frac6{q_{k+1}^{\beta^2-1}}>
  3q_{k+1}|q_{k+1}\theta-p_{k+1}|.
\]
Поскольку $1<\eta<\theta<2$ и $1\leq p_k/q_k\leq2$, $1\leq r_k/s_k\leq2$ для каждого $k$, справедливы неравенства
\begin{equation}\label{eq:bounds_for_the_plus_forms}
  2q_k<q_k+p_k\eta<5q_k,
  \qquad
  2s_k<r_k\theta+s_k<5s_k.
\end{equation}
Стало быть, для всех достаточно больших $k$ выполняется
\begin{multline}\label{eq:product_decaying_qs}
  |q_k\theta-p_k|\cdot|q_k+p_k\eta|>
  2q_k|q_k\theta-p_k|
  > \\ >
  6s_k|s_k\eta-r_k|>
  \frac65\,
  |r_k\theta+s_k|\cdot|r_k-s_k\eta|,
\end{multline}
\vskip-6mm
\begin{multline}\label{eq:product_decaying_sq}
  |r_k\theta+s_k|\cdot|r_k-s_k\eta|>
  2s_k|s_k\eta-r_k|
  > \\ >
  6q_{k+1}|q_{k+1}\theta-p_{k+1}|>
  \frac65\,
  |q_{k+1}\theta-p_{k+1}|\cdot|q_{k+1}+p_{k+1}\eta|.
\end{multline}


\paragraph{Решётка $\La$ и её относительные минимумы.}


Рассмотрим решётку $\La=A\Z^2$, где
\[
  A=
  \begin{pmatrix}
    \theta & -1 \\
    1 & \phantom{-}\eta
  \end{pmatrix}.
\]
Положим $\vec v_{-1}=(\theta,1)$, $\vec w_{-1}=(1,-\eta)$ и для каждого $k\geq0$ положим 
\[
  \vec v_k=(q_k\theta-p_k,q_k+p_k\eta)=A
  \begin{pmatrix}
    \,q_k \\
    \,p_k
  \end{pmatrix},
  \qquad
  \vec w_k=(r_k\theta+s_k,r_k-s_k\eta)=A
  \begin{pmatrix}
    \phantom{-}r_k \\
    -s_k
  \end{pmatrix}.
\]
Как сказано в пункте \ref{subsec:relative_minima_in_dimension_2}, множество относительных минимумов решётки $\La$ в точности совпадает с множеством точек
\begin{equation}\label{eq:relative_minima_of_La}
  \pm\vec v_k,\quad
  \pm\vec w_k,\qquad
  k\in\Z,\ \ k\geq-1.
\end{equation}


\paragraph{Выбор точки $\vec v_m$.}


В силу \eqref{eq:bounds_for_the_plus_forms} и \eqref{eq:consecutive_denominators_inequalities} найдётся такое $K\in\N$, что для всех $k>K$ выполняются неравенства
\begin{equation}\label{eq:supnorm_growing}
\begin{array}{l}
  |\vec v_k|<5q_k<5s_k^{1/\beta}<
  5\cdot2^{-1/\beta}|\vec w_k|^{1/\beta}<
  |\vec w_k|,\quad\,\
  \\
  \vphantom{1^{\Big|}}
  |\vec w_k|<5s_k<5q_{k+1}^{1/\beta}<
  5\cdot2^{-1/\beta}|\vec v_{k+1}|^{1/\beta}<
  |\vec v_{k+1}|,
\end{array}
\end{equation}
причём, к тому же, ввиду \eqref{eq:product_decaying_qs}, \eqref{eq:product_decaying_sq}
\begin{equation}\label{eq:Pi_decaying}
  \Pi(\vec v_k)>\frac65\,\Pi(\vec w_k),
  \qquad
  \Pi(\vec w_k)>\frac65\,\Pi(\vec v_{k+1}).
\end{equation}
Из \eqref{eq:Pi_decaying} следует, что найдётся такой индекс $m>K$, для которого
\[
  \Pi(\vec v_m)<\min_{k\leq m-1}\min\big(\Pi(\vec v_k),\Pi(\vec w_k)\big).
\]
Учитывая, что множество точек \eqref{eq:relative_minima_of_La} совпадает с множеством вершин полигонов Клейна решётки $\La$, получаем, что $\vec v_m$ является гиперболическим минимумом этой решётки.


\paragraph{Последующие гиперболические минимумы.}


Покажем, что $\vec w_m$ также является гиперболическим минимумом решётки $\La$. Рассмотрим прямоугольники
\[
\begin{array}{ll}
  \cP_1=\Big\{(z_1,z_2)\in\R^2 \,\Big|\, |z_1|\leq|q_m\theta-p_m|,\ |z_2|\leq q_{m+1}+p_{m+1}\eta \Big\},
  \\ \vphantom{\Bigg|}
  \cP_2=\Big\{(z_1,z_2)\in\R^2 \,\Big|\, |z_1|\leq|q_m\theta-p_m|,\ |z_2|\leq r_m\theta+s_m \Big\},
  \\
  \cP_3=\Big\{(z_1,z_2)\in\R^2 \,\Big|\, |z_1|\leq r_m\theta+s_m,\ |z_2|\leq|q_m\theta-p_m| \Big\}
\end{array}
\]
и параллелограммы
\[
\begin{array}{ll}
  \cQ_1=\Big\{(x,y)\in\R^2 \,\Big|\, |x\theta-y|\leq|q_m\theta-p_m|,\ |x|\leq q_{m+1} \Big\},
  \\ \vphantom{\Bigg|}
  \cQ_2=\Big\{(x,y)\in\R^2 \,\Big|\, |y|\leq s_m,\ |x+y\eta|\leq|q_m\theta-p_m| \Big\},
  \\
  \cQ_3=\Big\{(x,y)\in\R^2 \,\Big|\, |y|\leq s_m,\ |x+y\eta|\leq|s_{m-1}\eta-r_{m-1}| \Big\}.
  \quad\ \
\end{array}
\]

