		\includegraphics[width=\linewidth]{Figure1.png}
		\caption{Degeneration of a planar 3D beam into an in-plane 1D beam model. The base vectors at the centroid and at an equidistant line are depicted.}
		\label{fig:Figure 1}
	\end{figure}
	%
