		\end{aligned}	
	\end{equation}
	%
The other base vector, $\iv{g}{}{2}=\ve{n}$, has unit length and is defined here through an anti-clockwise rotation of the vector $\iv{t}{}{}$ w.r.t.~cross section direction $\zeta$, i.e.
\begin{equation}
	\iv{g}{}{2}= \iv{n}{}{} = \pmb \Lambda \iv{t}{}{}, \quad \pmb 	\Lambda =
	\begin{bmatrix}
		0 & -1\\
		1 & 0
	\end{bmatrix}.
\end{equation}
 The derivatives of the basis vectors are defined via Christoffel symbols, 
	%
	\begin{equation}
		\label{eq: def: derivatives of base vectors}
		\begin{bmatrix}
			\iv{g}{}{1,1}\\
			\iv{g}{}{2,1}
		\end{bmatrix}
		=
		\begin{bmatrix}
			\ii{\Gamma}{1}{11} & \ii{\Gamma}{2}{11}\\
			\ii{\Gamma}{1}{21} & \ii{\Gamma}{2}{21}
		\end{bmatrix}
		\begin{bmatrix}
			\iv{g}{}{1}\\
			\iv{g}{}{2}
		\end{bmatrix}
		=
		\begin{bmatrix}
			\ii{\Gamma}{1}{11} & \ic{K}{}{}\\
			-K & 0
		\end{bmatrix}
		\begin{bmatrix}
			\iv{g}{}{1}\\
			\iv{g}{}{2}
		\end{bmatrix},
	\end{equation}
	%
where $K$ and $\ic{K}{}{} = g K$ are the so-called \textit{signed curvatures} w.r.t.~arc-length and parametric coordinates, respectively. 



%	Since we are dealing with plane beams, all quantities are constant along the $\zeta$ coordinate, as illustrated in \fref{fig:Figure 1}. %We will reduce the beam continuum from 2D to 1D by defining the metric of the complete beam via the metric of the beam axis. 
%	Thus, the degeneration from a 3D to a 2D beam model is straightforward. If we define an \emph{equidistant line} as a set of points with $\eta=const$, 
The position and base vectors at an arbitrary point of the beam continuum are
	%
\begin{align}
	\label{eq:def:r_eq}
	\begin{aligned}
		\veq{x} &= \ve{x} + \eta \, \ve{g}_{2}, \\
		\veq{g}_{1} &= \veq{x}_{,1} = \ve{g}_{1} - \eta \, K \,  \iv{g}{}{1}, \\
		\veq{g}_{2} &=  \ve{g}_{2} = \ve{n},
	\end{aligned}
\end{align}
%
and we designate them with an overbar. In this way, the metric of a beam in the reference configuration is defined by the metric of the beam axis. 
%Due to the BE hypothesis, the shear strain vanishes and the position of the cross section is completely determined by the position of the beam axis. 
Since the current configuration is obtained by adding the displacement field to the initial position, $\vdef{x}=\ve{x}+\ve{u}$, the relations given in \eqqref{eq:def:r_eq} are valid for every configuration \cite{2023borković}. 
%This fact gives rise to so-called \emph{rotation-free} beam theories \cite{2018borkovicb}. 


Due to the BE assumptions, the only remaining component of the Green-Lagrange strain tensor is the axial strain
	%
	\begin{equation}
		\label{eq:def:strain}
		\ieq{\epsilon}{}{11} = \frac{1}{2} \left( \ieqdef{g}{}{11} - \ieq{g}{}{11} \right),\quad \ieq{g}{}{11}= \veq{g}_{1} \cdot \veq{g}_{1}. 
	\end{equation}
	%
By neglecting the influence of higher-order terms w.r.t.~the $\eta$ coordinate and the initial curvature, the axial strain at an arbitrary point is 
	%
	\begin{equation}
		\label{eq:e11eq}
		\begin{aligned}
			\ieq{\epsilon}{}{11}&=  \ii{\epsilon}{}{11}+ \eta \kappa, \\
			\ii{\epsilon}{}{11} &:= \frac{1}{2} \left( \idef{g}{}{11} - \ii{g}{}{11} \right), \quad \ii{\kappa}{}{} :=\icdef{K}{}{} - \ic{K}{}{}. 
		\end{aligned}
	\end{equation}
	%
where $\ii{\epsilon}{}{11}$ is the axial strain of the beam axis, while $\ii{\kappa}{}{}$ is the change of curvature of the beam axis w.r.t.~the parametric convective coordinate \cite{2023borković}.
	%
%	The obtained expression \eqref{eq:e11eq} for the axial strain at an arbitrary point shows strong coupling between stretching and bending. The resulting formulation is often referred to as the \emph{strongly curved beam model} \cite{2023borkoviće}. 

%	\textcolor{blue}{Since strongly curved beams can develop significant shear strains, a consistent approach is to employ the axial strain given by \eqqref{eq:e11eq} within a shear-deformable beam theory. However, our preliminary numerical tests have shown that both BE and shear-deformable beam models return practically indistinguishable results for the considered examples. Therefore, we have used the BE beam model in this paper since it requires only displacement DOFs, which makes it significantly more efficient than the shear-deformable beam model. On the other hand, the implementation of the strongly curved model defined by \eqqref{eq:e11eq} provides improved accuracy (if strongly curved configurations occur), while it does not affect efficiency.}


We employ the hyperelastic St.~Venant--Kirchhoff material model which allows us to write the second Piola-Kirchhoff stress component as
	%
	\begin{equation}
		\label{eq:const}
		\begin{aligned}
			\ieq{S}{11}{} = E \ieq{g}{11}{} \ieq{g}{11}{} \ieq{\epsilon}{}{11}\,,
		\end{aligned}
	\end{equation}
	%
where $E$ is the Young's modulus of elasticity. Now, the strain energy of a beam is
	%
	\begin{equation}
		\label{eq:internalener}
		\begin{aligned}
			\Pi_{\mathrm{int}} = \frac{1}{2} \int_{V}^{} \ieq{S}{11}{}  \ieq{\epsilon}{}{11} \dd{\ieq{V}{}{}}.
		\end{aligned}
	\end{equation}
	%
%	In this way, the main ingredients required for the implementation of the nonlinear strongly curved BE beam model are defined. 
By introducing the velocity vector, $\mdv{x}$, the kinetic energy of a BE beam is
	%
\begin{equation}
	\label{eq:kinetic}
	\begin{aligned}
		\Pi_{\mathrm{kin}} = \frac{1}{2} \int_{V}^{} \rho \iveqmd{x}{}{} \cdot \iveqmd{x}{}{} \dd{\ieq{V}{}{}},
	\end{aligned}
\end{equation}
%
where $\rho$ is the mass density. Moreover, the work of external forces can be defined as
%
\begin{equation}
	\label{eq:external}
	\begin{aligned}
		\Pi_{\mathrm{ext}} = -\int_{V}^{} \veq{p} \cdot \veq{u} \dd{\ieq{V}{}{}},
	\end{aligned}
\end{equation}
%
where $\veq{p}$ is a body force at an equidistant point of the beam. %Finally, the weak form of equilibrium is
	%
%\begin{equation}
%	\label{eq: weak form}
%	\begin{aligned}
%		\delta \Pi_{\mathrm{tot}} = \delta \Pi_{\mathrm{int}x} +\delta \Pi_{\mathrm{kin}x}+\delta \Pi_{\mathrm{ext}x}+\delta \Pi_{\operatorname{S-S}x}^m=0.
%	\end{aligned}
%\end{equation}
%%

For further details on the variation of the potential and the IGA-based spatial discretization of unknown fields, we refer to \cite{2019borkovica, 2023borković}.


\subsection{Section-section interaction potential}
\label{sec:sec-sec}

The interaction potential between two in-plane disks, $\Pi_{\operatorname{D-D_{IP}}}$, depends only on the smallest distance between them, referred to as the normal gap $q_2$. When the disks belong to two parallel planes with an offset $q_1$, the disk-disk potential, $\Pi_{\operatorname{D-D}}$, becomes a function of both the gap and the offset. Our \emph{improved section-section interaction potential} (ISSIP) \cite{2024borkovićb} addresses this additional dimension by improving the integration approach for in-plane disks \cite{1972langbein}. The ISSIP is represented as a product of an approximate disk-disk in-plane potential, $\hat{\Pi}_{\operatorname{D-D_{IP}}}^m$, derived in \cite{1972langbein}, and a hypergeometric function, i.e.,
%
\begin{equation}
	\label{appDD1}
	\begin{aligned}
		\Pi_{\mathrm{ISSIP}}^m &= \hat{\Pi}_{\operatorname{D-D_{IP}}}^m \, _2F_1 \left(\frac{2m-7}{4},\frac{2m-5}{4};\frac{m}{2};-\frac{q_1^2}{q_2^2}\right), \\
		\hat{\Pi}_{\operatorname{D-D_{IP}}}^m &= 2^{\frac{5}{2}-m} \pi^\frac{3}{2} \sqrt{\frac{R_x R_y}{R_x + R_y}} \frac{\Gamma (m-\frac{7}{2})}{\Gamma (\frac{m}{2})^2} q_2^{\frac{7}{2}-m},
	\end{aligned}
\end{equation}
%
where $R_x$ and $R_y$ are the radii of interacting cross sections. Here, $_2F_1 \left(a,b;c;z\right)$ is the Gaussian hypergeometric function
%
\begin{equation}
	\label{eq: ip13hyp}
	\begin{aligned}
		_2F_1 \left(a,b;c;z\right)= \sum_{k=0}^{\infty} \frac{\left(a\right)_k \left(b\right)_k}{\left(c\right)_k} \frac{z^k}{k!}
	\end{aligned}
\end{equation}
%
and $\left(a\right)_k$ is the Pochhammer symbol
%
\begin{equation}
	\label{eq: ip13poch}
	\begin{aligned}
		\left(a\right)_k=\frac{\Gamma \left(a+k\right)}{\Gamma \left(k\right)},
	\end{aligned}
\end{equation}
%
where $\Gamma\left(z\right)= \int_{0}^{\infty} p^{z-1} e^{-w} \dd{w}$ is the gamma function. For even $m$, the law \eqref{appDD1} evaluates to elliptic integrals of the first and second kind, while for odd $m$ we obtain rational functions. 

To further ameliorate the ISSIP law, we have proposed replacing the approximate in-plane potential $\hat{\Pi}_{\operatorname{D-D_{IP}}}^m$ in \eqref{appDD1} with the exact one for even $m$, ${\Pi}_{\operatorname{D-D_{IP}}}^m$, \cite{2025borković}. This law is named \emph{the approximate disk-disk law}, $\operatorname{D-D_{app}}$, and it is defined as
%
\begin{equation}
	\label{appDD2}
	\begin{aligned}
		\Pi_{\operatorname{D-D_{app}}}^m = \Pi_{\operatorname{D-D_{IP}}}^m \, _2F_1 \left(\frac{2m-7}{4},\frac{2m-5}{4};\frac{m}{2};-\frac{q_1^2}{q_2^2}\right)\; \text{for} \; m=4,6,8,...
	\end{aligned}
\end{equation}
%
Using the exact $\operatorname{D-D_{IP}}$ makes the $\operatorname{D-D_{app}}$ law significantly more complicated than the ISSIP one. Expressions for the exact in-plane vdW and steric potentials are given in Notebook 2 of \cite{2025borkovićb}.

Let us compare the accuracy of these two laws for the vdW case ($m=6$). Since we are interested in modeling interactions between beams, the interaction force acting on one section of the beam $X$ is obtained by integrating the interaction force over the length of the beam $Y$. Therefore, for small and moderate separations, it is more informative to observe the disk-infinite cylinder law, than the disk-disk law. We can find a disk-infinite cylinder law by integrating ISSIP \eqref{appDD1} and $\operatorname{D-D_{app}}$ \eqref{appDD2} along $q_1$ from $-\infty$ to $\infty$. Since only the hypergeometric function depends on $q_1$ in \eqref{appDD1} and \eqref{appDD2}, the disk-infinite cylinder potentials for even $m$ are:
%
\begin{equation}
	\label{appDD1s}
	\begin{aligned}
		\Pi_{\operatorname{D-C,ISSIP}} &= \int_{-\infty}^{\infty} \Pi_{\mathrm{ISSIP}}  \dd{q_1}= \hat{\Pi}_{\operatorname{D-D_{IP}}}^m \frac{4 \sqrt{\pi} q_2 \Gamma(m/2)}{(2m-9) \Gamma(\frac{m-1}{2})}, \\
	\Pi_{\operatorname{D-C,D-D_{app}}} &= \int_{-\infty}^{\infty} \Pi_{\operatorname{D-D_{app}}}  \dd{q_1}= \Pi_{\operatorname{D-D_{IP}}}^m \frac{4 \sqrt{\pi} q_2 \Gamma(m/2)}{(2m-9) \Gamma(\frac{m-1}{2})}.
	\end{aligned}
\end{equation}
%
An important feature of the interaction potential is its scaling w.r.t.~the gap, for which we utilize a scaling factor function \cite{2025borković}. The scaling factor functions of the obtained disk-infinite cylinder potentials vs.~the gap $q_2$ for $m=6$ are shown in Fig.~\ref{fig:LJpoten3}a.
