By taking a closer look at the area of beam-beam contact, we focus on the interaction between two arbitrary cross sections in Fig.~\ref{fig:cfa}b. %illustrates the setup for modeling the beam-beam interaction by focusing on the interaction between two cross sections.
Although these cross sections can be in an arbitrary orientation, we assume that they are parallel, i.e., $\ve{t}_x \parallel \ve{t}_y$, and employ disk-disk laws from Subsection \ref{sec:sec-sec}.

To define $q_1$ and $q_2$, we need to adopt a reference local coordinate system (LCS). Choosing the LCS of either beam as the reference LCS leads to a bias. To avoid this issue, we adopt an averaged reference LCS $\left(\hat{\ve{t}}_{xy},\hat{\ve{n}}_{xy}\right)$ by adding and normalizing the basis vectors of both beams, i.e.,
%
\begin{equation}
	\label{eq: g1x2}
	\begin{aligned}
		\hat{\ve{t}}_{xy} &= \frac{\ve{t}_{xy}}{\sqrt{\ve{t}_{xy} \cdot \ve{t}_{xy}}}, \quad \ve{t}_{xy} = \ve{t}_x+\ve{t}_y, \\
		\hat{\ve{n}}_{xy} &= \ve{\Lambda} \hat{\ve{t}}_{xy}.
			%	\hat{\ve{n}}_{xy} &= \ve{\Lambda} \hat{\ve{t}}_{xy} =\frac{\ve{n}_{xy}}{\sqrt{\ve{n}_{xy} \cdot \ve{n}_{xy}}}, \quad \ve{n}_{xy} = \ve{n}_x+\ve{n}_y. \\
	\end{aligned}
\end{equation}
%
Now, we define the offset $q_1$ and gap $q_2$ by projecting the distance vector to the axes of the new reference LCS. This gives
%
\begin{equation}
	\label{eq: g1xa}
	\begin{aligned}
		q_1 &= \ve{r}\cdot \hat{\ve{t}}_{xy},   \\
		q_2 &= d - (R_x + R_y) \cos \beta , \quad d = \abs{\ve{r}\cdot \hat{\ve{n}}_{xy}} = s_{\alpha} \left(\ve{r}\cdot \hat{\ve{n}}_{xy}\right), \quad s_\alpha = \textrm{sgn} \left(\ve{r} \cdot \hat{\ve{n}}_{xy} \right),\\
		\cos \beta &= \hat{\ve{n}}_{xy} \cdot \ve{n}_x=\hat{\ve{n}}_{xy} \cdot \ve{n}_y,
	\end{aligned}
\end{equation}
%
where we also project the beam radii via angle $\beta$. This step proves crucial for some cases of small separations, depending on the orientation of sections.


Let us consider four characteristic cases of section-section orientation shown in Fig.~\ref{fig:cases}.
%
\begin{figure}[h!]
	\begin{center}
		\includegraphics[width=0.95\textwidth]{FigCases.png}
		\caption{Four characteristic cases of beam-beam and section-section interactions.}
		\label{fig:cases}
	\end{center}
\end{figure}
%
Case 2 and Case 3 are very accurately described with our disk-disk laws, since there we assume interaction between parallel cross sections. For Cases 1 and 4, this assumption is violated, and the error depends on the gap, the offset, and the angle between the cross sections. In our implementation, the definition of $q_2$ in Eq.~\eqref{eq: g1xa} improves the accuracy for Cases 1 and 4, compared to the definition in \cite{2024borkovićb}.

Furthermore, for a large offset in Case 4, the projection to the averaged LCS may lead to an overlap, i.e., the gap $q_2$ becomes negative. %Furthermore, for large cutoff distances, the gap $q_2$ can become negative in Case 4. 
Hence, we implement a minimum positive limit value for the gap, $q_\text{2,lim}=10^{-8}$. Our calculations show that this practically does not influence the accuracy, since such configurations occur for relatively large $q_1$ when the contribution from this section-section interaction is negligible. 


%
With definitions \eqref{eq: g1xa} at hand, the gradients of the gap and offset w.r.t.~positions of both beams are
%
\begin{equation}
	\label{eq: full3x66}
	\begin{aligned}
		\nabla_{\ve{x}} q_1 &=  \nabla_{\ve{x}}  \left(\ve r \cdot \hat{\ve{t}}_{xy}\right) =   \hat{\ve{t}}_{xy} = - \nabla_{\ve{y}} q_1, \\
		\nabla_{\ve{x}} q_2 &= \nabla_{\ve{x}}   \abs{\ve {r} \cdot \hat{\ve{n}}_{xy}} = s_{\alpha} \hat{\ve{n}}_{xy} = -\nabla_{\ve{y}} q_2.
	\end{aligned}
\end{equation}
%
Finally, the variations of the interaction potential between two circular cross sections, $\Pi_{\operatorname{D-D}}^m$, neglecting the interaction moment, are
%
\begin{equation}
	\label{eq: full3x}
	\begin{aligned}
		\delta_{x} \Pi_{\operatorname{D-D}}^m &= \nabla_{\ve{x}} \Pi_{\operatorname{D-D}}^m \cdot \delta \iv{u}{}{x}= \ve{f}_x \cdot \delta \iv{u}{}{x}=\ve{f} \cdot \delta \iv{u}{}{x} , \\
		\delta_{y} \Pi_{\operatorname{D-D}}^m &= \nabla_{\ve{y}} \Pi_{\operatorname{D-D}}^m \cdot \delta \iv{u}{}{y}=\ve{f}_y \cdot \delta \iv{u}{}{y}= -\ve{f} \cdot \delta \iv{u}{}{y} ,
	\end{aligned}
\end{equation}
%
where the section-section interaction force is
%
\begin{equation}
	\label{eq: full3xff}
	\begin{aligned}
		\ve{f} &=  \frac{\partial \Pi_{\operatorname{D-D}}^m }{\partial q_1} \hat{\ve{t}}_{xy} + \frac{\partial \Pi_{\operatorname{D-D}}^m }{\partial q_2}  s_\alpha \hat{\ve{n}}_{xy} = f_1  \hat{\ve{t}}_{xy} + f_2  \hat{\ve{n}}_{xy} .
	\end{aligned}
\end{equation}
%
Further details on the beam-beam formulation are given in \cite{2024borkovićb}.





	\subsection{Solution algorithms}

For the sake of completeness, we briefly discuss solution techniques for the set of spatially discretized equations of equilibrium.

Since the time-continuous analytical solution of Eq.~\eqref{eq: poten} rarely exists, we aim to find its solution at a discrete set of time instances $t_i$, $i=1,2,...,M$. In order to find this set, we start from some equilibrium configuration, defined with the vector of nodal displacements $\textbf{q}^i$, and aim to find the next one, $\textbf{q}^{i+1}$. Therefore, at instance $t_{i+1}$, the balance equation is
%
\begin{equation}
	 \textbf{M} \ddot{\textbf{q}}^{i+1}+\textbf{F}(\textbf{q}^{i+1}) -\textbf{Q}(\textbf{q}^{i+1})-\pmb{\Phi}(\textbf{q}^{i+1})=\textbf{R}(\textbf{q}^{i+1})\overset{!}{=} %\overset{!}{=} 
	\textbf{0},
	\label{eq:equil}
\end{equation}
%
where the vector of inertial nodal forces is represented as a product of the mass matrix $\textbf{M}$ and the nodal acceleration vector $\ddot{\textbf{q}}$, $\textbf{F}$ is the vector of internal nodal forces, $\textbf{Q}$ is the vector of external nodal forces, $\pmb{\Phi}$ is the vector of nodal interaction forces, and $\textbf{R}$ is the vector of residual nodal forces, which should be equal to the zero vector $\textbf{0}$ at equilibrium. 




\subsubsection{Static analysis with the Newton-Raphson algorithm}




In this subsection, we consider the quasi-static case where inertia is neglected. By the Taylor expansion w.r.t.~the configuration at $t_{i}$, equilibrium equation \eqref{eq:equil} becomes
%
\begin{equation}
	\label{eq:tayloreq}
	\textbf{R} (\textbf{q}^{i+1})= \textbf{R}(\textbf{q}^i) + \nabla \textbf{R} (\textbf{q}^i)  \Delta \textbf{q}^{i+1} + \operatorname{h.o.t.}=\textbf{K}_\text{T}^i \Delta \textbf{q}^{i+1} + \operatorname{h.o.t.}\overset{!}{=}\textbf{0}
\end{equation}
%
where $\textbf{K}_\text{T}^i=\nabla \textbf{R} (\textbf{q}^i)$ is the tangent stiffness matrix. Since this equation is nonlinear w.r.t.~the unknown increment $\Delta \textbf{q}$, we aim to solve it by an iterative Newton-Raphson (NR) procedure. For brevity, the time index is omitted in the remainder of this subsection since all quantities refer to the current time step $i+1$. If the equilibrium is not reached at the $j^{th}$ iteration, we calculate the new iterative displacement increment from
%
	\begin{equation}
		{}^j \textbf{K}_\text{T}^{} \Delta {}^{j+1} \textbf{q}^{} = {}^j\textbf{R}^{}={}^j\textbf{F}^{}-{}^j\textbf{Q}^{}-{}^j\pmb{\Phi}^{},
		\label{eq:linearized}
	\end{equation}
	and update the configuration
	\begin{equation}
		{}^{j+1}\textbf{q}^{}={}^j\textbf{q}^{}+\Delta {}^{j+1}\textbf{q}^{}.
	\end{equation}
	%
Then we calculate the residual at the updated configuration and check if it satisfies a convergence criteria that is here defined as
	%
\begin{equation}
	\frac{\norm{{}^{j+1}\textbf{R}^{}}}{\norm{{}^{j+1}\textbf{Q}^{}+{}^{j+1}\pmb{\Phi}^{}}}\le \epsilon.
\end{equation}
%
In all of our simulations in Section \ref{sec:num}, the convergence threshold is set to $\epsilon=10^{-6}$.

\subsubsection{Static analysis with the arc-length method}


The NR method from the previous subsection is applicable for the examples that do not exhibit snap-through behavior, meaning that there is no load limit points and the stiffness matrix is regular in all configurations. If there is a load limit point on the equilibrium path, as in Subsection \ref{sec:num1}, we use the arc-length (AL) method. There are many different implementations of the AL method developed for adhesion problems \cite{2006sauer,2022roy,2023roy}. In this paper, we use the modified Riks method, as employed in Abaqus \cite{2009smith}. %The procedure is briefly presented here for completeness. 


%We compared the performance of the linearized arc-length method, the cylindrical arc-length method, and the modified Riks method, \cite{1981crisfield, 2008ritto-correa}. For the numerical tests which follow in the next section, all of these variants return similar results. The exception is the last example where only the modified Riks method, as implemented in Abaqus, found the complete structural response, \cite{2009smith}. Hence, this procedure is briefly presented. 

The main idea of the AL method is to introduce a load proportionality factor $\lambda$ as an additional unknown in \eqref{eq:tayloreq}. This factor scales the total value of the external load, or the total interaction force, or both. Without losing generality, let us assume that there is only an external load acting on the system. The load proportionality factor $\lambda$ allows us to overcome load limit points by increasing or decreasing the external load during the simulation, i.e.,
\begin{equation}
		\label{eq eq for numeric1}
		\textbf{Q}^i = \ii{\lambda}{i}{} \textbf{Q}^M.
\end{equation}
%
%This approach introduces the load proportionality factor as an additional unknown in \eqref{eq:linearized}. 

Let us start from some known, converged, configuration defined with $(\textbf{q}^{i}, \ii{\lambda}{i}{})$, and search for the next equilibrium point $(\textbf{q}^{i+1}, \ii{\lambda}{i+1}{})$. The first step is to find a predictor solution, called the predictor tangential displacement vector, $\textbf{q}_\text{T}$. It is calculated from the known tangent stiffness and the total external load, i.e.,
	\begin{equation}
		\label{eq eq for numeric2}
		\textbf{K}_\text{T}^i {}^0\textbf{q}_\text{T}^{i+1} = \textbf{Q}^M.
	\end{equation}
%
The predictor load increment $\Delta \: \iii{\lambda}{0}{}{i+1}{}$ follows from a constraint equation \cite{1981crisfield, 2009smith} as
%
\begin{equation}
		\label{eq eq for numeric3}
		\Delta \: \iii{\lambda}{0}{}{i+1}{} = \pm \frac{\Delta \: \iii{l}{}{}{i+1}{}}{\sqrt{  {}^0\tilde{\textbf{q}}_\text{T}^{i+1} \: \cdotp \: {}^0\tilde{\textbf{q}}_\text{T}^{i+1}+1}},
\end{equation}
%
where $\Delta \iii{l}{}{}{i+1}{} $ is the arc-length value that is estimated for the first, and calculated for all the other increments as a function of the desired number of iterations per increment. For convenience, the displacement vectors in Eq.~\eqref{eq eq for numeric3} are scaled by the maximum displacement component of the corresponding linear solution from Eq.~\eqref{eq eq for numeric2}, and designated with tilde. The sign of the predictor solution is calculated from the condition that the projection of the predictor tangential displacement onto the previously converged displacement increment $\Delta \textbf{q}^i$ must be positive, ensuring continuation along the equilibrium path, i.e.,
%
	\begin{equation}
		\label{eq eq for numeric6}
		\Delta \, {}^0\!\lambda^{i+1} ( {}^0\tilde{\textbf{q}}^{i+1}_\text{T} \cdot \Delta \tilde{\textbf{q}}^i + \Delta\lambda ^i ) > 0.
	\end{equation}
%
In general, the predictor solution does not satisfy equilibrium and the AL iterations act as a corrector. In the remainder of this subsection, all quantities, unless specified  otherwise, are taken at the current time step $i+1$ and the time index is omitted to simplify notation. For the first iteration, the increments of displacement and load are initialized from the predictor solutions:
%
	\begin{equation}
		\label{eq eq for numeric7}
			\Delta  \, {}^1\!\textbf{q}= \Delta \, {}^0\!\lambda \, {}^0\!\textbf{q}_\text{T} \quad \textrm{and} \quad \Delta \, {}^1\!\lambda= \Delta \, {}^0\!\lambda.
	\end{equation}
%
If the convergence criteria is not met at the $j^{th}$ iteration, new tangential, ${}^{j+1}\textbf{q}_\text{T}$, and residual, $\delta {}^{j+1}\textbf{q}$, displacements are calculated from:
%
	\begin{equation}
	{}^j \textbf{K}_\text{T}\; {}^{j+1} \textbf{q}_\text{T} = \textbf{Q}^M \;\; \textrm{and} \;\; {}^j \textbf{K}_\text{T} \;\delta \, {}^{j+1}\!\textbf{q} = {^j}\textbf{R}.
	\label{eq:linearizeda}
\end{equation}
	%
Then, we update the configuration with
	%
		\begin{equation}
		\label{eq eq for numeric11a}
		\begin{aligned}
			{}^{j+1} \textbf{q} &= {}^j\textbf{q} + \delta  \, {}^{j+1}\! \textbf{q} + \delta \, {}^{j+1}\! \lambda \, \textbf{q}_\text{T}, \\
			\iii{\lambda}{j+1}{}{}{} &= {}^{j}\lambda +  \delta \, {}^{j+1}\! \lambda=\lambda ^{i} + \Delta \, {}^{j}\!\lambda + \delta \, {}^{j+1}\! \lambda,
		\end{aligned}
	\end{equation}
%
where the iterative load factor, $\delta ^{j+1} \lambda^{}$, follows from the condition that a new potential equilibrium point is orthogonal to the tangential displacement in the AL solution space, i.e.,
%
	\begin{equation}
	\label{eq eq for numeric12a}
	\delta \, {}^{j+1}\! \lambda^{} = -\frac{\delta \, {}^{j}\!\tilde{\textbf{q}}^{}\cdot {}^0\tilde{\textbf{q}}^{}_\text{T}}{{}^j \tilde{\textbf{q}}^{}_\textbf{T}\cdot {}^0\tilde{\textbf{q}}^{}_\text{T}+1}.
\end{equation}
%	
The procedure is repeated until the convergence criteria is fulfilled \cite{2009smith}.




\subsubsection{Dynamic analysis using the HHT-$\alpha$ method}

When the inertial contributions are significant, the full equilibrium equation \eqref{eq:equil} is considered.
%
%	\begin{equation}
%	 \textbf{M} \ddot{\textbf{q}}^{i+1} +\textbf{F}^{i+1}-\textbf{Q}^{i+1}-\pmb{\Phi}^{i+1}=\textbf{R}^{i+1}\overset{!}{=} \textbf{0}.
%	\label{eq:equilD}
%\end{equation}
%
Using the Hilber-Hughes-Taylor (HHT)-$\alpha$ method, and by adding a velocity-proportional damping term, $\textbf{C} \dot{\textbf{q}}^{}$, this equation is replaced by
%
\begin{equation}
	\textbf{M} \ddot{\textbf{q}}^{i+1} +\textbf{C} \dot{\textbf{q}}^{i+1} + (1+\alpha)(\textbf{F}^{i+1}-\textbf{Q}^{i+1}-\pmb{\Phi}^{i+1})-\alpha(\textbf{F}^{i}-\textbf{Q}^{i}-\pmb{\Phi}^{i})=\textbf{R}^{i+1}= \textbf{0}, 
	\label{eq:equilDa}
\end{equation}
%
where the parameter $\alpha$ introduces numerical damping into the system, and it is restricted to $-1/2 \le\alpha \le0$ \cite{1977hilber}; $\alpha=0$ corresponds to Newmark's method. Similar as for the static analysis, we aim to solve \eqref{eq:equilDa} by an iterative scheme, linearizing the nonlinear terms w.r.t.~the previously converged configuration at time $t_i$. 


The velocity at the current configuration is represented via the velocity at the previous increment, the acceleration, and the time increment
%
\begin{equation}
	\label{eq: 11a}
	\dot{\textbf{q}}^{i+1} = \dot{\textbf{q}}^{i} + \Delta t \ddot{\textbf{q}}_\gamma,
\end{equation}
%
where $\ddot{\textbf{q}}_\gamma$ is a linear combination of accelerations $\ddot{\textbf{q}}^{i}$ and $\ddot{\textbf{q}}^{i+1}$ controlled by parameter $\gamma$,

%
\begin{equation}
	\label{eq: 11}
	\ddot{\textbf{q}}_\gamma = \left(1-\gamma\right) \ddot{\textbf{q}}^i + \gamma \ddot{\textbf{q}}^{i+1}, \quad \gamma=\frac{ 1}{2}-\alpha.
\end{equation}
%
The displacement is represented similarly, considering that the acceleration varies within the time increment. Assume that the new displacement is a function of displacement and velocity at the start of the increment, and some value of acceleration
%
\begin{equation}
	\label{eq: vel1ss}
	\textbf{q}^{i+1}= \textbf{q}^{i} + \Delta t \dot{\textbf{q}}^i + \frac{1}{2} \Delta t^2 \ddot{\textbf{q}}_\beta,
\end{equation}
%
where we use the linear combination of accelerations
%
\begin{equation}
	\label{eq: acc1aa}
	\ddot{\textbf{q}}_\beta = \left(1-2\beta\right) \ddot{\textbf{q}}^i + 2 \beta \ddot{\textbf{q}}^{i+1}, \quad \beta = \frac{1}{4} (1-\alpha)^2.
\end{equation}
%
These equations allow us to update the velocity and the acceleration at the new iteration as a function of the displacement increment
%
\begin{equation}
	\label{eq: updateaa}
	\begin{aligned}
		{}^{j+1}\textbf{q}^{i+1} &= {}^j\textbf{q}^{i+1} + \Delta {}^{j+1}\textbf{q}^{i+1}\\
		{}^{j+1}\ddot{\textbf{q}}^{i+1} &= \frac{1}{\Delta t ^2 \beta}\left({}^{j+1}\textbf{q}^{i+1}-\textbf{q}^{i}\right) - \frac{1}{\Delta t \beta} \dot{\textbf{q}}^i - \frac{1-2\beta}{2\beta} \ddot{\textbf{q}}^i, \\
		{}^{j+1}\dot{\textbf{q}}^{i+1} &= \dot{\textbf{q}}^{i} + \Delta t [\left(1-\gamma\right) \ddot{\textbf{q}}^{i} + \gamma \; {}^{j+1}\ddot{\textbf{q}}^{i+1}].
	\end{aligned}
\end{equation}
%



After linearization, Eq.~\eqref{eq:equilDa} at the $j^{th}$ iteration becomes
%
\begin{equation}
	\textbf{M} \;{}^j\ddot{\textbf{q}}^{i+1} +\textbf{C} \;{}^j\dot{\textbf{q}}^{i+1} + (1+\alpha) \;{}^j\textbf{K}_\text{T}^{i+1} \;\Delta {}^{j+1}\textbf{q}^{i+1}={}^j\textbf{R}^{i+1}.
	\label{eq:equilDass}
\end{equation}
%
and by using Eq.~\eqref{eq: updateaa}, it can be written as
\begin{equation}
		{}^j \textbf{K}_\text{T,eq}^{i+1} \; \Delta {}^{j+1} \textbf{q}^{i+1} = {}^j\textbf{R}^{i+1},
		\label{eq:linearizedds}
\end{equation}
%
where
\begin{equation}
	{}^j \textbf{K}_\text{T,eq}^{i+1} = (1+\alpha) \;{}^j\textbf{K}_\text{T}^{i+1} +\frac{1}{\Delta t^2 \beta} \textbf{M} + \frac{\gamma}{\Delta t \beta} \textbf{C}.
	\label{eq:linearizedd}
\end{equation}
%
We continue iterating until the convergence is reached.

In our implementation, Rayleigh damping, which simply combines mass- and stiffness-proportional damping, i.e.~$\textbf{C}=\beta_k \textbf{K}+\beta_m \textbf{M}$, is adopted. Regarding the automatic time stepping, the half-increment residual approach is implemented \cite{1979hibbitt,2009smith}. 

		%
