\section{A presentation of $\cal{G}(\cal{A})$.} 
In this section we recall the  the category of fractions construction from \cite[Section 2.3]{klmms24} in the slightly more general setting of weak assemblers. 
\subsection{Weak assemblers}\label{sec:def-assemblers}
 The definition of an assembler \cite[Def.2.4]{zak16} involves a Grothendieck topology, but for our purposes this isn't necessary so we will remove this assumption. We need the structure of finite covering families and some additional axioms, which are also used in the definition of an assembler, that allow for the construction of $K$-theory by group completion. 
\begin{definition}\cite[Definition 2.1]{bgmmz} Given a category $\cal{C}$, a \emph{multimorphism} in $\cal{C}$ is a finite set of morphisms in $\cal{C}$ which share a codomain: 
\[\{\phi_i:  a_i \rightarrow b\}_{i \in I}. \] The set $I$ is finite and the case $I = \emptyset$ is permitted. 
    A \emph{covering family structure} on $\cal{C}$ is a collection of multimorphisms of $\cal{C}$, called \emph{covering families}, which satisfy the following axioms: 
    \begin{enumerate}[label=\bf{(C\arabic*)}]
        \item For every object $a \in \cal{C}$, $\{1_a : a \rightarrow a\} $ is a covering family.
        \item Covering families are composable. Given covering families 
        \[\{\phi_i : b_i \rightarrow c\}_{i \in I}, \, \{\psi_{ji}: a_{ji} \rightarrow b_i\}_{j  \in J_i}\] 
       then the composition 
        \[\{\psi_{ji} \circ \phi_i : a_{ji} \rightarrow c\}_{i \in I, j \in J_i}\]
        is a covering family. 
    \end{enumerate}
  A small category $\cal{C}$ with distinguished basepoint $ *\in \cal{C}$ and covering family structure is a \emph{category with covering families} if the following hold: 
  \begin{enumerate}
      \item $\hom(*,*)=\{1_*\}$ and $\hom(A,*)=\emptyset$ for $A \neq *$.
      \item For every finite set $I$, the set $\{ * \rightarrow * \}_{i \in I}$ is a covering family. 
  \end{enumerate}
  Given a category with covering families we use the following terminology.
  \begin{itemize}
      \item We say that the covering family 
      \[ \{\psi_j: b_j \rightarrow a\}_{j \in J}\]
      \emph{refines} the covering family 
      \[\{\phi_i : a_i \rightarrow a\}_{i \in I}\]
      if there exists a function $f: I \rightarrow J$ and a covering family
      \[ \{\eta_j: b_j \rightarrow a_i\}_{j \in f^{-1}(i)}\]
      for every $i \in I$, such that $\phi_{f(j)}\circ\eta_j=\psi_j$. \\
      \item We say that a multimorphism \[ \{a_i \rightarrow a\}_{i \in I}\] is \emph{disjoint} if every pullback $a_i \times_{a} a_j, j \neq i$, exists and is initial. 
  \end{itemize}

 Given categories with covering families $\cal{C}$ and $\cal{D}$, a functor $F:\cal{C} \rightarrow \cal{D}$ which preserves distinguished base points and covering family structure is a \emph{morphism of categories with covering families}. 
  \end{definition}


\begin{definition}\label{def:wasm}
 A category  $\cal{A}$ equipped with a collection of finite disjoint covers $\{a_i \rightarrow a\}_{i \in I}$ is called a  \emph{weak assembler} if the following axioms are satisfied. 
\begin{description}
\item[\namedlabel{enum:wasm-id}{(C)}] For evey object $a$ in $\cal{A}$ the identity $\{a = a\}$ is a covering family. Covering families are closed under composition. 
\item[\namedlabel{enum:wasm-initial}{(I)}] $\cal{A}$ has an initial object $\emptyset$. The empty family is a cover of $\varnothing$. Additionally, covers are closed under adding or taking away a copy of $\varnothing$. 
\item[\namedlabel{enum:wasm-refinement}{(R)}] Any two covers of an object $P$ of $\cal{A}$ have a common refinement.
\item[\namedlabel{enum:wasm-mono}{(M)}] Every morphism of $\cal{A}$ is a monomorphism.
\end{description}
\end{definition}
\begin{remark}\label{remark:ForgettingwAsmStructure}
    Forgetting some of the axioms defining a weak assembler yields a category with covering structure. 
\end{remark}

\begin{definition}\label{defsc}
    Two objects $a,b$ of a weak assembler $\cal{A}$ are \emph{scissors congruent} if there are covers $\{a_i \rightarrow a\}_{i \in I}$ and $\{b_i \rightarrow b\}$ such that $a_i \cong b_i$ for every $i \in I$.  
\end{definition}
\begin{definition}
    We define $\wasm$ to be \emph{the category of weak assemblers}. The objects are weak assembler and the morphisms are functors which preserve covering structure and the initial object. 
\end{definition}
\subsection{The category of covers $\cal{W}(\cal{A})$.}
From a weak assembler $\cal{A}$ we build a category $\cal{W}(\cal{A})$ called the category of covers. Morphisms in this category encode scissors congruence.
\begin{definition}
    Given a weak assembler $\cal{A}$ the \emph{category of covers} $\cal{W}(\cal{A})$ is defined as follows: 
    \begin{itemize}
    \item The objects of $\cal{W}(\cal{A})$ are collections of objects from $\cal{A}$ indexed by a finite set. We use the notation $\{P_i \}_{i \in I}$ where $I$ is a finite set and $P_i \in \cal{A}$.
    \item Morphisms $f:\{P_i\}_{i \in I} \rightarrow \{Q_j\}_{j \in J}$ are given by a function $f:I \rightarrow J$ and morphisms from $\cal{A}$,  $f_i: P_i \rightarrow Q_{f(i)}$ such that $\{f_i : P_i \rightarrow Q_j\}_{i \in f^{-1}(j)} $ is a cover. We record morphisms as tuples: $(f, \{f_i\}_{i \in I})$. 
    \item Composition is given by $(f, \{f_i\}_{i \in I}) \circ (g, \{g_j\}_{j \in J})=(fg, \{f_{g(j)} \circ g_j\}_{j \in J})$. 
    \item $\cal{W}(\cal{A})$ has symmetric monoidal structure given by \[ (I, \{P_i\}_{i \in I}) \sqcup (J, \{Q_j\}_{j \in J}) = (I \sqcup J, \{P_i\}_{i \in I} \sqcup \{Q_j\}_{j \in J}).\]
    \end{itemize}
\end{definition}
\begin{remark}
     Singletons  $\{P\}$ and $\{Q\}$ are connected by a zigzag of morphisms in $\cal{W}(\cal{A})$ if and only if $P$ and $Q$ are scissors congruent. 
\end{remark}
\begin{definition}
    The scissors congruence $K$-theory spectrum, $K(\cal{A})$, of an assembler $\cal{A}$ is the symmetric spectrum obtained by applying the Segal $\Gamma$ construction to $\cal{W}(\cal{A})$. 
    \end{definition}
\subsection{The groupoid of scissors congruences $\cal{G}(\cal{A})$}
\par It is known that the localization $\cal{G}(\cal{A})=\cal{W}(\cal{A})[\cal{W}(\cal{A})^{-1}]$, which we call the \emph{scissors congruence groupoid}, satisfies the conditions for a category of fractions where morphisms are represented by spans \cite[Def.2.16]{klmms24}. 
The objects of $\cal{G}(\cal{A})$ are the same as those of $\cal{W}(\cal{A})$, but morphisms are equivalence classes of spans. We will use the presentation of $\cal{G}(\cal{A})$ to give an alternate proof  that the localization functor induces a weak equivalence $B(\cal{W}(\cal{A})) \simeq B(\cal{G}(\cal{A}))$ \cite[Theorem 4.1]{klmms24}. 



\par We begin by recalling the category of fractions construction, following Gabriel and Zisman \cite[Ch.I]{gabriel2012calculus}.    

\begin{definition}Given  a subcategory of weak equivalences $W \subseteq \cal{C}$, the localization $\cal{C}[W^{-1}]$ admits a calculus of fractions if the following conditions hold. 

\begin{enumerate}[label= \bf{({CF}\arabic*)}]
\item Ore Condition. Given $f: x \rightarrow z \in W$ and and $g: y \rightarrow z \in \cal{C}$ there exist $h: w \rightarrow x \in \cal{C}$ and $i : w \rightarrow y \in W$ such that the square commutes: 
\[ \begin{tikzcd}
w \ar[r] \ar[d]& x \ar[d]  \\
y \ar[r] & z.
\end{tikzcd}\] 

\item Given \[ \begin{tikzcd} x \ar[r, "f", shift left=.75ex] \ar[r, "g"', shift right = .75ex] & y \ar[r, "h"] & z \end{tikzcd}\] such that $hf=hg$ there exists an object $w$ and morphism 
\[ \begin{tikzcd} w \ar[r, "i", dotted ]& x \ar[r, "f", shift left=.75ex] \ar[r, "g"', shift right = .75ex] & y \ar[r, "h"] & z \end{tikzcd}\] 
such that $fi=gi$.
\end{enumerate}

\par Under these conditions, the morphism sets in $\cal{C}[W^{-1}]$ can be described as spans where the left leg is in $W$, under an equivalence relation: 
\[ \cal{C}[W^{-1}](a,b) = \{a \xleftarrow{f} c \xrightarrow{g} b : f \in W  \}/ \sim .\]

Where we define $a \xleftarrow{f} c \xrightarrow{g} b \sim a \xleftarrow{h} c' \xrightarrow{i} b$ if there exists an object $x$ and morphisms $u,v$ such that the following diagram commutes: 

\[ \begin{tikzcd}
& b \ar[dl , "f"'] \ar[dr, "g"]& \\
a & \ar[u, "u"']x \ar[d, "v"]& c \\
&b' \ar[ul, "h"]\ar[ur, "i"']&
\end{tikzcd}\]
and $fu = hv \in W$.
\par Given spans $(b \leftarrow b' \rightarrow c) $ and $ (a \leftarrow a' \rightarrow )b$ , construct the diagram
\[ \begin{tikzcd}
a  &a' \ar[l] \ar[r] &b \\
& z \ar[u] \ar[r] & b' \ar[u] \ar[d]\\
& & c.
\end{tikzcd}\] 

where $z$ exists by (CF1). Then the composition is defined by  
\[ (b \leftarrow b' \rightarrow c) \circ (a \leftarrow a' \rightarrow b ) = (a \leftarrow a' \leftarrow z \rightarrow b' \rightarrow c ).\]
\par Using the calculus of fractions construction the localization functor $\iota_W:\cal{C} \rightarrow \cal{C}[W^{-1}]$ is defined by 
\[ x \xrightarrow{f} y \mapsto x \xleftarrow{1_x} x \xrightarrow{f} y. \]
\end{definition}

\par In the context of this paper, our interest in categories of  fractions comes from the following. 
\begin{proposition}[{\cite[Lemma 2.15]{klmms24}}]\label{assemblerfractions}
For $\cal{A}$ a weak assembler, $\cal{G}(\cal{A})$ has a representation as a category of fractions . 
\end{proposition}

This gives a model for $\cal{G}(\cal{A})$ that can be useful for computations. We will use the category of fractions description to show that $B(\cal{W}(\cal{A})) \simeq B(\cal{G}(\cal{A}))$.

\begin{definition}\label{definition:Filtered_cat}
Recall that a category $\cal{C}$ is \emph{filtered} if the following conditions are satisfied: 
\begin{enumerate}[label = \bf{(F\arabic*)}]
\item  For every $x,y \in \cal{C}$ there exists some $z \in \cal{C}$ such that there exist morphisms $x \rightarrow z \leftarrow y$. 
\item For every pair \begin{tikzcd} x \ar[r , shift left = .75ex, "f"]\ar[r , shift right = .75ex, "g"'] & y  \end{tikzcd} there exists an object $z$ with morphism $h: y \rightarrow z$ such that $hf=hg$. 
\end{enumerate}  
\end{definition} 

\begin{lemma}[{\cite[Def. 2.6.13]{weibel1994introduction}}]\label{lemma:Bcontractible} Filtered categories have contractible classifying spaces. 
\end{lemma}


\begin{proposition}\label{prop:locWE}
Let $\cal{C}$ be a category where every cospan can be completed to a commutative square and all morphisms are monic. Then the localization functor induces a weak equivalence $B(\cal{C}) \simeq B(\cal{C}[\cal{C}^{-1}])$.
\end{proposition}


\begin{proof}
\par Let $\iota: \cal{C} \rightarrow \cal{C}[\cal{C}^{-1}]$ be the localization functor.  Now we will show that $(\iota/c)^\op$ is a filtered category, or rather that $\iota/c$ is co-filtered.  Given two objects $x \leftarrow x' \rightarrow c$ and $y \leftarrow y' \rightarrow c$ in $\iota/c$ we can complete the cospan $x' \rightarrow c  \leftarrow y'$  to a commutative square with morphisms in $\cal{C}$ yielding a commutative diagram:
\[ \begin{tikzcd} 
x & z \ar[dl , dashed] \ar[dr , dashed] & y \\
x' \ar[u] \ar[dr] &  & y' \ar[u] \ar[dl]\\
& c. & 
\end{tikzcd}\]

By composition we have morphisms $z \rightarrow x$ and $z \rightarrow y$ from $\cal{C}$. Therefore the object $z \rightarrow c$ of $\iota/c$ maps to both the given objects $x \leftarrow x' \rightarrow c$ and $y \leftarrow y'\rightarrow c$, proving that (F1) is satisfied in $(\iota/c)^\op$. 

\par Given parallel morphisms in $\iota/c$: 
\[\begin{tikzcd}
x \ar[rr , shift right = .75, "g"'] \ar[rr, shift left = .75 ex,"f"] &&y  \\
x'\ar[u] \ar[dr] && y' \ar[u] \ar[dl]\\
& c.&
\end{tikzcd}\]

commutativity and the fact that all morphisms are isomorphisms in $\cal{C}[\cal{C}^{-1}]$ implies that $f=g$ in $\cal{C}[\cal{C}^{-1}]$. Therefore there is a diagram of the form 
\[\begin{tikzcd} 
& \ar[dl, "1_x"'] x  \ar[dr, "f"] &\\
x  & z \ar[u, "\phi"'] \ar[d, "\psi"] & y  \\
& x. \ar[ul, "1_x" ] \ar[ur , "g"']& 
\end{tikzcd} \]

which implies that $\phi=\psi$ has the property $f\phi =g \phi$. Therefore the zigzag $z \xrightarrow{\phi}  x \leftarrow x' \rightarrow c$ shows that $\iota/c$ satisfies (F2).  
Now that we have shown $\iota/c$ is contractible for all $c\in C$, we conclude by Quillen's Theorem A \cite[Ch.IV,3.7]{weibel2013k} that $\iota $ induces an equivalence on classifying spaces: $B\iota:B(\cal{C}) \simeq B\cal{C}[\cal{C}^{-1}])$. 
\end{proof}
\begin{corollary}
    If $\cal{A}$ is an assembler then $B(\cal{W}(\cal{A})) \simeq B(\cal{G}(\cal{A}))$.
\end{corollary}
\begin{proof} Let $\cal{A}$ be an assembler. And let $\cal{W}^\circ (\cal{A})$ be the version of the category of covers where we do not allow initial objects in the tuples. 
By \cite[Prop.2.11]{zak16}, we have that any cospan in $\cal{W}^\circ(\cal{A})$ can be completed to a square and every morphism is monic. Therefore $\cal{W}(\cal{A})[\cal{W}(\cal{A})^{-1}]$ satisfies the conditions of \cref{prop:locWE} above. By the adjunction used in \cite[Lemma 2.15]{klmms24} the result may be extended to the version of $\cal{G}(\cal{A})$ where initial objects are permitted. 
\end{proof}

\subsection{Homotopy orbits and the Grothendieck construction for weak assemblers}
We will recall some results and terminology from \cite{bgmmz}. Some results from this section hold for categories with covering families, a generalization of assemblers, but for our purposes we consider the case of an assembler. 


\begin{definition}
    Let $G$ be a group, considered a category with one object and only invertible morphisms. A $G$-category with covering family structure is a functor $F: G \rightarrow \catfam$. We use $*_G$ for the object of $G$. 
\end{definition}
\begin{definition}\label{def:grothwasm}
	Considering a group $G$ as a category with one object, a functor  
    \[ F: G \rightarrow \aut_{w\asm}(\cal{A})\]
    makes $\cal{A}$ a $G$-category with covering family structure. Unless multiple actions are present, we will suppress $F$ from the notation, writing $\Phi A=F(\Phi)A$ and $\Phi \psi=F(\Phi)\psi$ where $A$ is an object of $\cal{A}$ and $\psi$ a morphism of $\cal{A}$. 
	The category $\cal{A}_{hG}=G \widetilde{\int} F$ is a modification of the classical Grothendieck construction, $G\int F$ which is suitable for the pointed setting defined by: 
 \begin{align*}
     \ob \cal{A}_{hG} &= \ob F(*_G) = \ob \cal{A}\\
     \cal{A}_{hG} (a,b) &= \bigsqcup_{\Phi \in G} \cal{A}(\Phi a, b) 
\end{align*}
Composition of two arrows
\[ a \xleftarrow{(\phi,\Phi)} b \xleftarrow{(\psi,\Psi)} c\]
is defined as
\[a \xleftarrow{(\phi \Phi(\psi), \Phi\Psi)} c.\]



 In the special case when $A=*$ , we define a morphism $* \rightarrow B$ to be the same as a morphism in $\cal{C}$. If $\psi: * \rightarrow B$ and $(\phi, \Phi): B \rightarrow C$ then the composition is given by $(\phi, \Phi) \circ \psi = \phi \circ \Phi (\psi)$.
\par Covering structure is defined by declaring 
\[ \{  a  \leftarrow a_i: (\phi_i, \Phi_i)\}_{i \in I}\]  to be a cover whenever 
\[\{  a \leftarrow \Phi_ia_i: \phi_i\}_{i \in I} \] 
is a cover in $\cal{A}$.   
  \end{definition} 

\begin{remark}
    We will use the convention that the lowercase Greek letters are morphisms of the category $\cal{A}$ and the uppercase Greek letters are group elements. 
\end{remark}

\begin{proposition}\label{prop:htpyorbitwassm}
    If $\cal{A}$ is a weak assembler and $F:G \rightarrow \aut_{\wasm}(\cal{A})$ defines an action by isomorphisms of weak assemblers, then $\cal{A}_{hG}$ is a weak assembler.
\end{proposition}
\begin{proof}
  We verify axioms (R) and (M) for $\cal{A}_{hG}$. 
  \par For (M) we need to show that all morphisms in $\cal{A}_{hG}$ are monic. Suppose that the diagram 
  \[
  \begin{tikzcd}
      a & b \ar[l, "(\phi{,} \Phi)"'] & x\ar[l, "(\xi{,}\Xi)", shift left=.75ex] \ar[l, "(\omega{,}\Omega)"', shift right = .75ex] 
  \end{tikzcd}
  \]
  commutes in $\cal{A}_{hG}$ so that we have 
  \begin{align*}
      (\phi, \Phi) \circ (\omega , \Omega) &=  (\phi, \Phi) \circ (\xi, \Xi)\\
      (\phi \Phi(\omega), \Phi\Omega) &= (\phi \Phi(\xi), \Phi\Xi).
  \end{align*}
  Therefore $\phi \Phi(\omega)=\phi \Phi(\xi)$ in $\cal{A}$, which yields $\Phi(\omega)=\Phi(\xi)$ since all morphisms in $\cal{A}$ are monic. Since $G$ is a group action we have $\omega = \xi$ in $\cal{A}$. By the definition of morphism in $\cal{A}_{hG}$ we have $\Phi \Omega= \Phi \Xi$ which implies $\Omega = \Xi$ since $\Phi$ is invertible. Therefore $(\omega, \Omega) = (\xi, \Xi)$, proving that every morphism in $\cal{A}_{hG}$ is monic. 
  \par For (R) take two covers in $\cal{A}_{hG}$ 
\begin{align*}
    \{a \leftarrow b_i : &(\phi_i, \Phi_i) \}_{i \in I}\\
    \{a \leftarrow c_j : &(\psi_j, \Psi_j) \}_{j \in J}.
\end{align*}
By definition there are corresponding covers 
\begin{align*}
    \{a \leftarrow \Phi_ib_i : &\phi_i \}_{i \in I}\\
    \{a \leftarrow \Psi_j c_j : &\psi_j \}_{j \in J}.
\end{align*}
in $\cal{A}$ which have a common subdivision 
\[
\{a \leftarrow d_k : \eta_k \}_{k \in K}
\]
since $\cal{A}$ is a weak assembler.
The common subdivision includes the data of functions $f: K \rightarrow I $ and $g: K \rightarrow J$ such that there are covers
\begin{align*}
    \{\Phi_ib_i &\xleftarrow{\lambda_k} d_k\}_{k \in f^{-1}(i)}\\
    \{\Psi_j c_j &\xleftarrow{\gamma_k} d_k\}_{k \in g^{-1}(j)}
\end{align*}
for every $i \in I$ and every $j \in J$ such that 
\[
    \psi_{g(k)} \gamma_k=\eta_k = \phi_{f(k)} \lambda_k
\]
for every $k \in K$. 
\par We claim that 
\[ 
\{a \xleftarrow{(\eta_k,1_G)} d_k\}_{k \in K}
\]
is a common subdivision of the given covers from $\cal{A}_{hG}.$
Since $G$ acts by functors which preserve covering structure there are covers,
\begin{align*}
    \{b_i &\xleftarrow{\Phi^{-1}_{f(k)}(\lambda_k)} \Phi^{-1}_{f(k)}d_k\}_{k \in f^{-1}(i)}\\
    \{ c_j &\xleftarrow{\Psi_{g(k)}^{-1}(\gamma_k)} \Psi^{-1}_{g(k)}d_k\}_{k \in g^{-1}(j)}
\end{align*}
for every $i \in I$ and every $j \in J$.
Verifying that  
\[
    (\phi_{f(k)}, \Phi_{f(k)}) \circ (\Phi^{-1}_{f(k)} (\lambda_k), \Phi^{-1}_{f(k)})=(\eta_k, 1_G) = (\psi_{g(k)}, \Psi_{g(k)}) \circ (\Psi^{-1}_{g(k)} (\gamma_k), \Psi_{g(k)}^{-1})
\]
shows that $(\eta_k, 1_G)_{k \in K}$ defines a common subdivision.
\end{proof}

\begin{definition}
Since $\cal{A}_{hG}$ is a weak assembler we may take the associated category of covers $\cal{W}_{hG}$. We will make some conventions when working with $\cal{W}_{hG}$. For a morphism $(\phi_i, \Phi_i): \{a_i\}_{i \in I} \rightarrow \{b_j\}_{j \in J}$ we will write the associated set map $\underline{\phi}: I \rightarrow J$. 

\par In $\cal{W}(\cal{A}_{hG})$ we distinguish two special classes of morphisms. 
\begin{itemize}
\item A \emph{move} is a morphism of the form $(\phi_i, \Phi_i): \{a_i\}_{i \in I } \rightarrowtail \{b_i\}_{i \in I}$ such that for each component $\phi_i: a_i \rightarrow b_{\underline{\phi}(i)}$ we have $\phi_i = 1_{a_i}$.\\ 
 \item  A \emph{covering sub-map} is a morphism $(\phi_i, \Phi_i):\{a_i\}_{i \in I} \dashrightarrow \{b_j\}_{j \in J}$ such that on components $(\phi_i, \Phi_i): P_i \rightarrow Q_{\underline{\phi}(i)}$ we have $\Phi_i=1_G$. 
 \end{itemize}
 \end{definition}
 \begin{remark}
     The intuition is that moves use just group elements to rearrange a collection of pieces without changing their indices in $I$, whereas a covering sub-map sticks a collection of pieces together. There is a functor $\iota_{hG}: \cal{A} \rightarrow \cal{A}_{hG}$  defined  by 
     \[
     \iota_{hG}(a \xrightarrow{\phi} b)=a \xrightarrow{(\phi, 1_G)}b. \]
     A covering sub-map is just a morphism in the image of 
     \[ \cal{W}(\iota_{hG}) : \cal{W}(\cal{A}) \rightarrow \cal{W}(\cal{A}_{hG}).\] 
 \end{remark}

\begin{example}[{\cite[Example 4.5]{bgmmz}}]\label{htpyorbiteuc}
    Let $\cal{E}_e^n$ be the no-moving assembler of euclidean space $E^n$.  The objects are polytopes in $E^n$, the morphisms are inclusions $a \subseteq b$ where $a$ and $b$ are polytopes. A finite collection of morphisms 
    $\{\phi_i: a_i \rightarrow a\}_{i \in I}$ is a cover if $a=\bigcup a_i$ and the $a_i$ are pairwise interior disjoint. 
    \par  Let $G \leq \aut(E^n)$ be a subgroup of Euclidean isometries. 
    There is a functor $F:G \rightarrow \aut_{\wasm}(\cal{E}^{n}_{e})$ where $G$ acts by isometries. From this data we form the homotopy orbit category $(\cal{E}^n_{e})_{hG}=G \widetilde{\int}  F$. We denote this category by $\cal{E}^n_G$ as in \cite[Notation 5.2]{klmms24}. 
\end{example}
The morphisms in $\cal{A}_{hG}$ may be factored into a move followed by a covering sub-map. Morphisms in $\cal{A}_{hG}$ contain data from the $G$-action and from the data of the morphisms in $\cal{A}$: these features of a morphism can be separated in $\cal{A}_{hG}$.
 \begin{definition}[{\cite[Definition 5.3]{bgmmz}}]\label{doublecatstructure}
  There is a double category $\cal{W}(\cal{A}_{hG})$ with 
 \begin{itemize}
     \item $\ob \cal{W}^\square (\cal{A}_{hG})= \ob \cal{W} (\cal{A}_{hG})$.
     \item Horizontal morphisms are moves.
     \item Vertical morphisms are covering sub-maps.
     \item 2-cells are commuting squares in $\cal{W}(\cal{A}_{hG})$.
 \end{itemize}
\end{definition}
The following lemmas detail properties of $\cal{W}^\square (\cal{A}_{hG})$.
\begin{lemma}[{\cite[Lemma 5.3]{bgmmz}}] \label{factoring} Every morphism in $\cal{W}(\cal{A}_{hG})$ factors up to unique isomorphism as a move followed by a covering sub-map 
    \[
    \begin{tikzcd}
        \bullet && \bullet \ar[ll] \ar[dl, tail]\\
        &\bullet. \ar[ul, dotted]&
    \end{tikzcd}
    \]
\end{lemma}
\begin{lemma}[{\cite[Lemma5.5]{bgmmz}}]\label{completingsquares}
    Each diagram in $\cal{W}^{\square} (\cal{A}_{hG})$ of the form 
    \[ 
    \begin{tikzcd}
        & \{a_i\}_{i \in I} \ar[d, dotted]\\
        \{b_j\}_{j \in J} & \ar[l, tail] \{c_k\}_{k \in K}
    \end{tikzcd}
    \text{ or }
    \begin{tikzcd}
        \{b_j\}_{j \in J}& \ar[l, tail] \{a_i\}_{i \in I} \ar[d, dotted]\\
        &  \{c_k\}_{k \in K}
    \end{tikzcd}
    \] completes uniquely (up to unique isomorphism) to a 2-cell in $\cal{W}(\cal{A}_{hG})$.
\end{lemma}
\begin{lemma}\label{nomovesquare}
Any diagram of the form 
\[ \begin{tikzcd}
\{a_i\}_{i \in I} \ar[d, dotted]& \\
\{b_j\}_{j \in J}& \{c_k\}_{k \in K} \ar[l, dotted]\\
\end{tikzcd}\]
can be completed to a commutative square of the form
\[ \begin{tikzcd}
\{a_i\}_{i \in I} \ar[d, dotted]& \{d_l\}_{l \in L} \ar[d, dotted] \ar[l, dotted]\\
\{b_j\}_{j \in J}& \{c_k\}_{k \in K}. \ar[l, dotted]\\
\end{tikzcd}\]
\end{lemma}
\begin{proof}
 The subcategory of $\cal{W}(\cal{A}_{hG})$ consisting of covering sub-maps is isomorphic to $\cal{W}(\cal{A})$. The desired commuting square exists by axiom (R) in $\cal{A}$. 
\end{proof}

\begin{definition}
We call a span of the form 
\[\begin{tikzcd}
   \bullet & \ar[l, dotted]\bullet & \ar[l, tail]  \ar[r, dotted] \bullet & \bullet 
\end{tikzcd}\]
a \emph{DMC-span}. Since an inverted covering sub-map can be thought of as a dissection, we use DMC for  "dissection, move, covering sub-map." 
\end{definition}
\begin{notation}
    We follow the decluttering convention of \cite[Notation 5.7]{bgmmz}. We write $f_{i|j}$ in place of $(f_i)_j$ for the $j$-th component of the morphism $f_i$. 
\end{notation}
 \begin{proposition}\label{prop:rep}
 Every morphism 
\[ \begin{tikzcd}
\{a_{0|i}\}_{i \in I_0}  & \{b_{0|j}\}_{j\in J_0}   \ar[l, "(\phi_j{,}  \Phi_j)"'] \ar[r, "(\psi_j {,} \Psi_j)"] & \{a_{1|i}\}_{i \in I_1}
\end{tikzcd} \] 
in $\cal{G}(\cal{A}) $ can be represented by an DMC-span.  
\end{proposition}

\begin{proof}
By applying the factorization into a move followed by a covering sub-map to the given span we obtain the commutative diagram: 

\[ \begin{tikzcd}
\{a_{0|i}\}_{i \in I_0}  && \{b_{0|j}\}_{j\in J_0} \ar[dl, tail, "\{\Phi_j\}"'] \ar[dr, tail, "\{ \Psi_j\}"]  \ar[ll, "(\phi_j{,}  \Phi_j)"'] \ar[rr, "(\psi_j {,} \Psi_j)"] && \{a_{1|i}\}_{i \in I_1}  \\
&\{\phi_j b_{0|j}\}_{j \in J_0}\ar[ul, dotted, "\{\phi_j\}"]&& \{\Psi_{j}b_{0|j}\}_{j \in J_0}. \ar[ur, dotted, "\{\psi_j\}"'] \ar[ll, tail, "\{\Phi_j \Psi^{-1}_j\}"]&
\end{tikzcd}\]
The move at the bottom exists by the fact that, for a group action, moves are invertible and the inverse of a move is a move. We have produced the desired equivalence. Since we are working in the groupoid $\cal{G}(\cal{A})$ every morphinism is invertible so the composite along the bottom of the diagram represents the same morphism as the composite along the top. 
\end{proof}
\begin{definition}\label{dmcrefinement}
    We say that the DMC-span 
\[\begin{tikzcd}
    \bullet & \bullet \ar[l, dotted, red] & \bullet \ar[l, tail, red] \ar[r, dotted, red]& \bullet
\end{tikzcd}\]
is a \emph{refinement} of the DMC-span 
\[\begin{tikzcd}
    \bullet & \bullet \ar[l, dotted, blue] & \bullet \ar[l, tail, blue] \ar[r, dotted, blue]& \bullet
\end{tikzcd}\]
if there exists a commuting diagram 
\[\begin{tikzcd}
& \bullet \ar[d, dotted]\ar[dl, dotted, red]& \bullet \ar[d, dotted] \ar[l, tail, red] \ar[dr, dotted, red] & \\
\bullet & \ar[l, dotted, blue]\bullet & \bullet \ar[l, tail, blue] \ar[r, dotted, blue]& \bullet 
\end{tikzcd}\]
in $\cal{W}(\cal{A}_{hG})$.
\end{definition}

\begin{definition}\label{commonsub}
    We say that two DMC-spans: 
   \[\begin{tikzcd}
       \{a_{i}\}_{i \in I} & \{\Phi_j b_{j}\}_{j \in J} \ar[l, dotted, "\{\phi_j\}"']& \{ b_{j}\}_{j \in J} \ar[l, tail, "\{\Phi_j\}"'] \ar[r, dotted, "\{\psi_j\}"] & \{c_{k}\}_{k \in K}\\
      \{a_{i}\}_{i \in I} & \{\Phi'_j b'_{j}\}_{j \in J'} \ar[l, dotted, "\{\phi'_j\}"']& \{ b'_{j}\}_{j \in J'} \ar[l, tail, "\{\Phi'_j\}"'] \ar[r, dotted, "\{\psi'_j\}"] & \{c_{k}\}_{k \in K}
   \end{tikzcd}\]
    \emph{differ by a common subdivision} if there exists a commuting diagram of the form: 
    \[\begin{tikzcd}
      & \{\Phi_j b_{j}\}_{j \in J} \ar[dl, dotted, "\{\phi_j\}"']& \{ b_{j}\}_{j \in J} \ar[l, tail, "\{\Phi_j\}"'] \ar[rd, dotted, "\{\psi_j\}"] & \\
      \{a_{i}\}_{i \in I}  &\{\Xi_l x_l\}_{l \in L} \ar[u, dotted, "\{\gamma_l\}"] \ar[d, dotted, "\{\theta_l\}"']&\{x_l\}_{l \in L} \ar[l, tail, "\{\Xi_l\}"'] \ar[u, dotted, "\{\omega_l\}"] \ar[d, dotted, "\{\lambda_l\}"']& \{c_k\}_{k \in K}\\
    & \{\Phi'_j b'_{j}\}_{j \in J'} \ar[ul, dotted, "\{\phi'_j\}"]& \{ b'_{j}\}_{j \in J'}. \ar[l, tail, "\{\Phi'_j\}"'] \ar[ur, dotted, "\{\psi'_j\}"'] & 
   \end{tikzcd}\]

 \end{definition}

\begin{proposition}\label{dmcrep}
    Two DMC-spans representing the same morphism in $\cal{G}(\cal{A})$ have a common subdivision. 
\end{proposition}

\begin{proof}
Given a diagram of two DMC-spans as in \cref{commonsub}  which commute in $\cal{G}(\cal{A})$ we can complete the cospan of covering sub-maps on the right to a square of covering sub-maps by \cref{nomovesquare}: 

\[
\begin{tikzcd}
    & \{\Phi_j b_{j}\}_{j \in J} \ar[dl, dotted, "\{\phi_j\}"']& \{ b_{j}\}_{j \in J} \ar[l, tail, "\{\Phi_j\}"'] \ar[rd, dotted, "\{\psi_j\}"] & \\
      \{a_{i}\}_{i \in I}  & &\{x_l\}_{l \in L}  \ar[u, dotted, "\{\eta_l\}"] \ar[d, dotted, "\{\lambda_l\}"']& \{c_k\}_{k \in K}\\
    & \{\Phi'_j b'_{j}\}_{j \in J'} \ar[ul, dotted, "\{\phi'_j\}"]& \{ b'_{j}\}_{j \in J'}. \ar[l, tail, "\{\Phi'_j\}"'] \ar[ur, dotted, "\{\psi'_j\}"'] & 
\end{tikzcd}
\]
The above diagram commutes in $\cal{G}(\cal{A})$since the outer hexagon commutes and the square on the right commutes. 
\par Now we use \cref{completingsquares} to complete the covering sub-maps followed by moves to squares obtaining a commuting diagram of the form:
\[\begin{tikzcd}
    & \{\Phi_j b_{j}\}_{j \in J} \ar[ddl, dotted, "\{\phi_j\}"']& \{ b_{j}\}_{j \in J} \ar[l, tail, "\{\Phi_j\}"'] \ar[rdd, dotted, "\{\psi_j\}"] & \\
    &\{\Xi_l x_l\}_{l \in L}  \ar[u, dotted, "\{\delta_l\}"]& &\\
      \{a_{i}\}_{i \in I}  & &\{x_l\}_{l \in L}  \ar[uu, dotted, "\{\eta_l\}"'] \ar[dd, dotted, "\{\lambda_l\}"] \ar[ul, tail, "\{\Xi_l\}"'] \ar[dl, tail, "\{\Theta_l\}"]& \{c_k\}_{k \in K}\\
      &\{\Theta_l x_l\}_{l \in L}  \ar[uu, tail, "\{\Xi_l \Theta^{-1}_l\}"]\ar[d,dotted, "\{\omega_l\}"] &&\\
    & \{\phi'_j b'_{j}\}_{j \in J'} \ar[uul, dotted, "\{\phi'_j\}"]& \{ b'_{j}\}_{j \in J'}. \ar[l, tail, "\{\Phi'_j\}"'] \ar[uur, dotted, "\{\psi'_j\}"'] &
\end{tikzcd}\]
The triangle on the left commutes in $\cal{G}(\cal{A})$: 
\[
(\phi'_{\underline{\omega}(l)}\omega_l,1_G)=(\phi_{\underline{\delta}(l)}\delta_l,\Xi_l \Theta^{-1}_l).
\]
Assuming that all empty covers have been removed, this implies $1_G = \Xi_l \Theta_l^{-1} $ and therefore $\{\Xi_l x_l\}=\{\Theta_l x_l\}$. An updated diagram is displayed below.
\[
\begin{tikzcd}
    & \{\Phi_j b_{j}\}_{j \in J} \ar[dl, dotted, "\{\phi_j\}"']& \{ b_{j}\}_{j \in J} \ar[l, tail, "\{\Phi_j\}"'] \ar[rd, dotted, "\{\psi_j\}"] & \\
      \{a_{i}\}_{i \in I}  & \{\Xi x_l\}\ar[u, dotted, "\{\delta_l\}"] \ar[d, dotted, "\{\omega_l\}"']&\{x_l\}_{l \in L}  \ar[l, tail, "\{\Xi_l\}"']\ar[u, dotted, "\{\eta_l\}"] \ar[d, dotted, "\{\lambda_l\}"']& \{c_k\}_{k \in K}\\
    & \{\Phi'_j b'_{j}\}_{j \in J'} \ar[ul, dotted, "\{\phi'_j\}"]& \{ b'_{j}\}_{j \in J'} \ar[l, tail, "\{\Phi'_j\}"'] \ar[ur, dotted, "\{\psi'_j\}"'] & 
\end{tikzcd}
\]

\par Now we make a refinement to ensure the triangle on the left commutes in $\cal{W}(\cal{A})$. Since the triangle commutes in $\cal{G}(\cal{A})$ there must a morphism $(\gamma_l,\Gamma_l)_{l \in L'}$which equalizes the arrows in $\cal{W}(\cal{A})$. Using \cref{factoring}, we factor the equalizing arrow into a covering sub map $\{\Gamma_l\}_{l \in L'}$ followed by a a move $\{\gamma_l\}_{l \in L'}$. After this we may complete the resulting cospan by \cref{completingsquares} .
\[\begin{tikzcd}
&\{x_l\}_{l \in L} \ar[d, "\{\Xi_l\}", tail]&\{y_l\}_{l \in L'} \ar[d, "\{\Xi_l\}", tail] \ar[l, dotted]&\\
    \{a_i\}_{i \in I} & \{\Xi_l x_l\}_{l \in L} \ar[l, "\{\phi'_{\underline{\omega}(l)} \circ \omega_l\} "shift left=.75ex] \ar[l, "\{\phi_{\underline{\delta}(l)}\} "',shift right = .75ex ] & \{\Gamma_l y_l\}_{l \in L'} \ar[l, "\{\gamma_l\}", dotted] & \{\Gamma_l y_l\}_{l \in L'} \ar[l, "\{\Gamma_l\}", tail]
\end{tikzcd}\]

Modifying the diagram by putting $\{Y_l\}$ in place of $\{X_l\}$ forces the triangle on the left to commute.
\[
\begin{tikzcd}
    & \{\phi_j b_{j}\}_{j \in J} \ar[dl, dotted, "\{\phi_j\}"']& \{ b_{j}\}_{j \in J} \ar[l, tail, "\{\Phi_j\}"'] \ar[rd, dotted, "\{\psi_j\}"] & \\
      \{a_{i}\}_{i \in I}  &\{\Xi_l y_l\}_{l \in L'}\ar[u, dotted, "\{\delta_l\}"
      ] \ar[d, dotted, "\{\omega_l\}"]&\{y_l\}_{l \in L'}  \ar[l, tail, "\{\Xi_l\}"']\ar[u, dotted, "\{\eta_l\}"] \ar[d, dotted, "\{\lambda_l\}"']& \{c_k\}_{k \in K}\\
    & \{\Phi'_j b'_{j}\}_{j \in J'} \ar[ul, dotted, "\{\phi'_j\}"]& \{ b'_{j}\}_{j \in J'} \ar[l, tail, "\{\Phi'_j\}"'] \ar[ur, dotted, "\{\psi'_j\}"'] & 
\end{tikzcd}
\]
Therefore the given DMC-spans differ by a common subdivision. 
\end{proof}


\begin{section}{The regulator for group completion $K$-theory}
Now we will review the construction of the regulator $\cal{W}(\cal{A}_{hG}) \rightarrow (HA)_{hG}$ defined in \cite{bgmmz} .  Our aim is to extend this map to $\cal{G}(\cal{A}_{hG})$, proving \cref{theorem:regulatorextension}.
\begin{definition}[{\cite[Definition 2.11]{bgmmz}}]\label{def:cat_wedge}
     For $X$ a finite based set and $\cal{A}$ a category we define $X \sma \cal{A}=\cal{A}^{\vee X^\circ}$, where $X^\circ$ is $X$ with the basepoint removed. If $M$ is an abelian group $X \sma M=M^{\oplus X^\circ}$.
\end{definition}
\begin{definition}[{\cite[Definitions 6.1, 6.11 ]{bgmmz}}]\label{regulatorW}

 Recall that given a $G$-weak assembler $\cal{A}$, or more generally a $G$-category with covering families, a \emph{measure} on $\cal{A}$ is a $G$-module $A$ and a function $\mu$ satisfying one of the following equivalent conditions: 

\begin{itemize}
\item A $G$-equivariant function $\mu: \ob \cal{A} \rightarrow A$ such that $\mu(P)= \sum_{i \in I} \mu(a_i)$ for every covering family $\{a_i \rightarrow a\}_{i \in I}$ in $\cal{A}$. 
\item A map of $\bb{Z}[G]$-modules $\mu: K_0 (\cal{A}) \rightarrow A$.
\end{itemize}
The \emph{explicit trace} is the map $K_n (\cal{A}_{hG}) \rightarrow H_n(G;A)$ arising from a measure. We call this map the \emph{regulator} or $\mu$-\emph{regulator} if specificity is desired. The regulator obtained from the identity on $K_0(\cal{A})$ is the \emph{universal regulator}. 
\par Let $N_\bullet ^\otimes $ be the two-sided bar construction with the tensor product.  The regulator $R$ is defined in \cite{bgmmz} as a map of simplicial sets,
\[ 
R: N_\bullet \cal{W}(\cal{A}_{hG}) \rightarrow N_\bullet ^\otimes (\bb{Z} , \bb{Z}[G], A) 
\]
defined by sending the $p$-tuple 
\[
 \{a_{0|i}\}_{i \in I_0} \xleftarrow{(\phi_{1|i},\Phi_{1|i})} \{a_{1|i}\}_{i \in I_1} \xleftarrow{(\phi_{2|i}, \Phi_{2|i})} \dots \xleftarrow{(\phi_{p|i}, \Phi_{p|i})} \{a_{p|i}\}_{i \in I_p}
\]
to the sum  
\[ 
\sum_{i \in I_p} \Phi_{1|\underline{\phi_2}\dots \underline{\phi_p} (i)} \otimes \Phi_{2|\underline{\phi_3} \dots \underline{\phi_p} (i)} \otimes \dots \otimes \Phi_{p-1| \underline{\phi_p} (i)} \otimes \Phi_{p|i} \otimes \mu(a_{p|i})
\]
in $C_p (G;A)=\bb{Z}[G]^{\otimes p} \otimes A$.

By \cite[Lemma 6.10]{bgmmz} the regulator generalizes to a map of simplicial sets: 
\[ 
R_X : N_\bullet \cal{W}(X \sma \cal{A}_{hG}) \rightarrow X \otimes N_\bullet ^\otimes (\bb{Z}, \bb{Z}[G], A).
\]
 The geometric realization of this map $|R_X|$ defines a map of special $\Gamma$-spaces, and therefore a map on symmetric spectra: 
\[
K(\cal{A}_{hG}) \xrightarrow{r} |N_{\bullet}^\otimes (\bb{Z}, \bb{Z}[G], A)|\simeq (HA)_{hG}
\]
\end{definition}
\end{section}
\par For our purposes, we will construct a regulator map out of the nerve of the localization of $\cal{W}(\cal{A}_{hG})$ in the case that $\cal{A}_{hG}$ is a weak assembler. In this case, $\cal{A}_{hG}$ is also a weak assembler \cref{prop:htpyorbitwassm}.  
For $\cal{A}$ a weak assembler we define $\cal{G}(\cal{A})=\cal{W}(\cal{A})[\cal{W}(\cal{A})^{-1}]$, the groupoid constructed from $\cal{A}_{hG}$. There is a localization map $L:\cal{W}(\cal{A}_{hG} )\rightarrow \cal{G}(\cal{A}_{hG})$, which in the span model for the completion maps $c \xleftarrow{f} c'$ to the span $c \xleftarrow{f} c' \xrightarrow{\id} c'$.   
\par Our aim is to construct a regulator
\[R^\cal{G}: N_\bullet \cal{G}(\cal{A}_{hG}) \rightarrow N^\otimes _\bullet (\bb{Z}, \bb{Z}[G], A) \]
such that $R^\cal{G}$ extends the regulator $R$ defined in \cref{regulatorW}: $R = R^\cal{G} \circ N_\bullet (L)$. 

\begin{definition}\label{definition:viaduct}
 We call a flag of DMC-spans of length $m$ a \emph{viaduct of length m} if the dissection of the $i$-th DMC-span agrees with the $(i+1)$-st covering sub-map DMC-span.  We write a length $m$ viaduct: 
 \[ \begin{tikzcd}
 \{b_{0|j}\}_{j \in J}   \ar[d, dotted, "\{ \psi_{0|j}\}"]& \{ b_{1|j} \}_{j \in J }\ar[l, tail, "\{\Phi_{1|j}\}"']\ar[d, dotted, "\{\psi_{1|j}\}"] & \ar[l, tail, "\{\Phi_{2|j}\}"'] \dots 
 & \ar[l, tail, "\{\Phi_{m-1|j}\}"'] \{b_{m-1| j}\}_{j \in J}\ar[d, dotted, "\{\psi_{m-1|j}\}"]& \ar[l, tail, "\{\Phi_{m|j}\}"'] \{b_{m | j}\}_{j \in J}\ar[d, dotted, "\{\psi_{m |j}\}"] \\
 \{a_{0|i}\}_{i \in I_0}   &  \{ a_{1|i} \}_{i \in I_1}           &         &   \{a_{m-1| i}\}_{i \in I_{m-1}}         &     \{a_{m | i}\}_{i \in I_m}
 \end{tikzcd} \]
 The vertical dotted arrows are the dissections and covering sub-maps which coincide. 
 \end{definition}

\begin{remark}
In the notation used for the viaduct we have $b_{k|j}=\Phi_{k+1|j} \Phi_{k+2|j} \dots \Phi_{m|j} b_{m|j}$. 
\end{remark}
\par  We extend the notion of refinement and common refinement from DMC-spans to viaducts. When no confusion may arise, we will declutter diagrams by omitting the names of morphisms and representing objects by dots. 
 \begin{definition}\label{viaductrefinement}
Given two viaducts of  length $m$: 
\[ \begin{tikzcd}
    \bullet \ar[d,red, dotted]& \bullet \ar[l,red, tail] \ar[d,red, dotted]& \dots \ar[l,red, tail] & \bullet \ar[l,red,tail] \ar[d,red,dotted]& \bullet\ar[l,red,tail] \ar[d,red,dotted]\\
    \bullet&\bullet&&\bullet&\bullet
\end{tikzcd}\]
\[ \begin{tikzcd}
    \bullet \ar[d, blue, dotted]& \bullet \ar[l,blue,tail] \ar[d,blue,dotted]& \dots \ar[l,blue,tail] & \bullet \ar[l,blue,tail] \ar[d,blue,dotted]& \bullet\ar[l,blue,tail] \ar[d,blue,dotted]\\
    \bullet&\bullet&&\bullet&\bullet
\end{tikzcd}\]
we say that the red viaduct \emph{refines} the blue viaduct if there are black covering maps making the following diagram commute: 
\[\begin{tikzcd}
   \bullet \ar[d, red, dotted] \ar[dd, dotted, bend left = 55]& \bullet \ar[l, red, tail]\ar[d, red, dotted] \ar[dd, dotted, bend left = 55] & \dots \ar[l, red, tail]&\bullet \ar[l, red, tail] \ar[d, red, dotted] \ar[dd, dotted, bend left = 55]& \bullet \ar[l, red, tail] \ar[d, red, dotted] \ar[dd, dotted, bend left = 55]\\
   \bullet & \bullet &  & \bullet & \bullet \\
