\section{Structural Interpretations}\label{sec:struc.interpre}
%----------------------------
\subsection{Nonseparable Models and Related Assumptions}
%----------------------------
We introduce the following nonseparable model to characterize the dependence structure.
\begin{assumptionS} Let $m(\cdot,\cdot,\cdot)$ be a measurable function of unknown form. \label{A:struct.m.l}~
	\begin{itemize}
		\item[(a)] The status quo outcome $Y$ is generated by
		\begin{align}
			Y=m(D,X,\varepsilon), \label{eq:status.quo.Y}
		\end{align}
		where $D$ is the continuous policy variable, $X$ is a vector of covariates, and $\varepsilon$ represents the unobserved disturbance. Suppose that $m(d,x,e)$ is continuously differentiable in $d$ for each $(x,e)$. The partial derivative $\partial_d m(\cdot,\cdot,\cdot)$ is termed the structural derivative.

		\item[(b)] The counterfactual outcome $Y^t$ is generated by
		\begin{align}
			Y^t=m(\pi_t(D),X,\varepsilon)=:m(D^t,X,\varepsilon), \label{eq:counterfactual.Y}
		\end{align}
		where $\pi_0(d)\equiv d$ (status quo policy). For each $d$, assume $\pi_t(d)$ is continuously differentiable in $t$ at $t=0$, with bounded derivative $\dot{\pi}(d):=\partial_t\pi_t(d)|_{t=0}$.
	\end{itemize}
\end{assumptionS}

To derive the structural interpretation, the following conditions are required.
\begin{assumptionR}[Regularity]\label{A:regularity}~
	\begin{itemize}
		\item[(a)] The CDF $F_Y$ is continuously differentiable on its support \(\supp{Y}\), with density $f_Y$ satisfying \(0<f_Y(y)<\infty\) for every \(y\in \supp{Y}\).

		\item[(b)] Let $\dot{m}(d,x,e):=\partial_t m(\pi_t(d),x,e)|_{t=0}=\dot{\pi}(d)\partial_d m(d,x,e)$. Suppose that $\dot{m}(\cdot,\cdot,\cdot)$ is measurable and satisfies
		\begin{align*}
			\pbb{\Big}{\big| m(\pi_t(D),X,\varepsilon) - m(D,X,\varepsilon) - t \,\dot{m}(D,X,\varepsilon) \big| \geq \nu t } = o(t) 
		\end{align*}
		as $t \downarrow 0$ for every $\nu > 0$.

		\item[(c)] The distribution of $(Y,\dot{m}(D,X,\varepsilon))$ is absolutely continuous with density $f_{Y,\dot{m}}(y,y')$ that is continuous in $y$ for each $y'$. Furthermore, there exists a Lebesgue integrable function $g:\R \to \R$ satisfying $\int |y' g(y')|\,dy' < \infty$ and a positive constant \(C\) such that $f_{Y,\dot{m}}(y,y') \leq C |g(y')|$ for all \((y,y')\).
	\end{itemize}
\end{assumptionR}
Assumption \ref{A:regularity} does not impose structural conditions like the invariance of \(F_{Y|D,X}\) under small manipulations, as assumed in \citet{firpo2009}. Assumption \ref{A:regularity} (a) implies that $Y$ is continuously distributed with a regular density. Assumptions \ref{A:regularity}(b)--(c) are analogous to \citeauthor{hm2007}'s (\citeyear{hm2007}) Assumptions A3--A4, implying smooth variation in the structural response $\dot{m}$.


The directional derivative structure of \(\theta_\Gamma\) motivates our focus on smooth functionals \(\Gamma\). 
\textit{Hadamard-differentiable} functionals encompass key causal statistics for policy analysis, including means, quantiles, and common inequality measures (e.g., the Gini coefficient).\footnote{For additional Hadamard-differentiable inequality measures, see, e.g., \citet{rothe2010joe} and \citet{firpo2016}.} This differentiability is necessary for both the functional Delta method (\citealp{vaart2000}) and standard bootstrap inference (\citealp{fang2019}).

Formally, let $(\mathbb{D},\|\cdot\|_{\mathbb{D}})$ and $(\mathbb{B},\|\cdot\|_{\mathbb{B}})$ be normed spaces.
A functional $\Gamma:\mathbb{D}_\Gamma \subseteq \mathbb{D} \to \mathbb{B}$ is \textit{Hadamard-differentiable} at $F\in\mathbb{D}_\Gamma$ tangentially to a set $\mathbb{D}_0 \subseteq \mathbb{D}$, if there exists a continuous linear functional $\Gamma'_{F}: \mathbb{D}_0 \to \mathbb{B}$ such that
\begin{align*}
	\lim_{t \downarrow 0} \left|\left| \frac{\Gamma(F + t h_t) - \Gamma(F)}{t} -\Gamma'_{F}(h)\right|\right|_{\mathbb{B}} = 0
\end{align*}
for every sequence $\{h_t\}\subset \mathbb{D}$ satisfying $h_t \to h\in\mathbb{D}_0$ and $F+th_t\in \mathbb{D}_\Gamma$, where $\Gamma'_F$ is called the \textit{Hadamard derivative} of $\Gamma$ at $F$. See, for example,  \citet[Chapter 20.2]{vaart2000} for more details.


%***************************************************
\subsection{Structural Representation of the MPE}
%***************************************************
\begin{theorem}[Structural Representation of $\theta_\Gamma$]\label{thm:struct.theta}
	Under Assumptions \ref{A:struct.m.l} and \ref{A:regularity}, we obtain
	\begin{align*}
		\theta_{id}(y) :=\lim_{t\downarrow 0} \frac{F_{Y^t}(y)-F_Y(y)}{t}
		= \EEc{\big}{\omega^f(y,D)\,\partial_d m(D,X,\varepsilon)}{Y=y}
	\end{align*}
	for every $y\in \supp{Y}$, where $\omega^f(y,d):=-f_Y(y)\dot{\pi}(d)$.
	If $\Gamma$ is Hadamard-differentiable at $F_Y$, we have
	\begin{align*}
		\theta_\Gamma
		= \Gamma'_{F_Y} \Big( \EEc{\big}{\omega^f(\cdot,D)\,\partial_d m(D,X,\varepsilon)}{Y=\cdot}\Big), 
	\end{align*}
	where \(\Gamma'_{F_Y}\) denotes the Hadamard derivative of \(\Gamma\) at \(F_Y\).
\end{theorem}
Theorem \ref{thm:struct.theta} states that: (i) the marginal effect of counterfactual changes in \(F_D\) on the outcome CDF \(F_Y(y)\), equals the weighted average structural effect for individuals with \(Y=y\). (ii) For any Hadamard-differentiable transformation \(\Gamma\), the marginal impact on \(\Gamma(F_Y)\) is given by the Hadamard derivative of \(\Gamma\) at \(F_Y\), applied to the weighted average structural effect function identified in (i).

Theorem \ref{thm:struct.theta} extends the literature in two principal ways: (i) When considering \(\pi_t(\cdot) = H^{-1}_t(F_D(\cdot))\), where \(H_t\) is the counterfactual CDF of \(F_D\), Theorem \ref{thm:struct.theta} offers a structural interpretation of \citeauthor{rothe2012}'s (\citeyear{rothe2012}) \textit{marginal partial distributional policy effect}. (ii) For \(\Gamma=Q_\tau\), it provides a structural interpretation for the \textit{unconditional quantile effect} studied by \citet{mms2024}, as formalized below.
\begin{corollary}[Structural Representation of $\theta_Q$] \label{cory:struct.theta.Q}
	For \(\Gamma=Q_\tau\), under the assumptions of Theorem \ref{thm:struct.theta} and assuming the support \(\supp{Y}\) is compact,  we obtain
	\begin{align*}
		\theta_Q(\tau)=\EEc{\big}{\dot{\pi}(D)\,\partial_d m(D,X,\varepsilon)}{Y=q_\tau}
	\end{align*}
	for every \(\tau \in (0,1)\), where \(q_\tau := Q_Y(\tau)\).
\end{corollary}
Corollary \ref{cory:struct.theta.Q} states that the MPE of a counterfactual change in \(F_D\) on the \(\tau\)-th quantile of the outcome distribution, \(Q_\tau(F_Y)\), equals the weighted average structural derivative for individuals with outcome value \(q_\tau\), with weights determined by the policy function \(\pi_t\). 

