\subsection{Structural Representation of the UQR}\label{sec:struct.uqr}
%--------------------------------------------------------------
This section extends the structural interpretation of the \textit{unconditional quantile partial effect} (UQPE) proposed by \citet{firpo2009}. 
For comparison purposes, we focus on the location shift \(D^t=D+t\) and denote \(\theta_Q\) as \(\theta_Q^L\) for this specific case. 
The UQPE of \citet[p. 958]{firpo2009} is defined as
\begin{align*}
	\beta^{\mathrm{UQR}}(\tau)
	&:=-\frac{\EE{\big}{\partial_d{F_{Y|D,X}(q_\tau|D,X)}}}{f_Y(q_\tau)}.
\end{align*}
We denote this UQPE as \(\beta^{\mathrm{UQR}}(\tau)\), which corresponds to their \textit{unconditional quantile regression} (UQR) estimand rather than an unobserved parameter.

Note that \(\theta_Q^L\) is not equal to  \(\beta^{\mathrm{UQR}}\) under the standard regularity assumptions mentioned above. Consequently, Corollary \ref{cory:struct.theta.Q} cannot be used to structurally interpret  \(\beta^{\mathrm{UQR}}\) as \( \E[\partial_dm(D,X,\varepsilon)|Y=q_\tau]\) under these assumptions.   \citet{firpo2009}, however, demonstrate that \(\theta_Q^L(\tau)=\beta^{\mathrm{UQR}}(\tau)\) holds under the structural assumption \(F_{Y^t|D+t,X} = F_{Y|D,X}\). 
A broader question thus emerges: What does the UQR estimand $\beta^{\mathrm{UQR}}$ identify in nonseparable models when structural assumptions are not imposed? To address this question formally, we introduce the following conditions.
\begin{assumptionR}[Regularity] \label{A:regular.hm}
	For each $(d,x)\in\supp{D}\times\supp{X}$:
	\begin{itemize}
		\item[(a)] The conditional distribution of $Y$ given $(D,X)$ is absolutely continuous, with density $f_{Y|D,X}(\cdot|d,x)$ that is strictly positive, bounded and continuous on its support. Furthermore, \(F_{Y|D,X}(y|d,x)\) is continuously differentiable in \(d\) for each $(y,x)$.

		\item[(b)] $\partial_d m(d,x,\cdot)$ is measurable and satisfies
		\[
		\pbc{\Big}{\big| m(d+\delta,x,\varepsilon) - m(d,x,\varepsilon) - \delta\,\partial_d m(d,x,\varepsilon) \big| \geq \nu \delta}{D=d,X=x} = o(\delta)
		\]
		as $\delta \downarrow 0$ for every $\nu > 0$.
		\item[(c)] The conditional distribution of \((Y,\partial_d m(d,x,\varepsilon))\) given \((D,X)\) is absolutely continuous, with density $f_{Y,\partial_dm^{d,x}|D,X}(\cdot,y'|d,x)$ that is continuous for each $(y',d,x)$. Furthermore, there exists a Lebesgue integrable function $g:\R\to\R$ satisfying $\int |y'g(y')|\,dy'<\infty$ and a positive constant $C$ such that $f_{Y,\partial_dm^{d,x}|D,X}(y,y'|d,x) \leq C |g(y')|$ for every \((y,y',d,x)\).

		\item[(d)] $\pb[m(d',x,\varepsilon)=Q_{Y|D,X}(\alpha|d,x)|D=d,X=x]=0$ for $d'$ in a neighborhood of $d$. The conditional distribution of \(\varepsilon\) given \((D,X)\) is absolutely continuous with the strictly positive density $f_{\varepsilon|D,X}(\cdot|d,x)$. Furthermore, $f_{\varepsilon|D,X}(e|d,x)$ is partially differentiable in \(d\) for each \((e,x)\), and satisfies
		\(\sup_{|\delta| \leq c} \left| \frac{f_{\varepsilon|D,X}(e|d+\delta,x)-f_{\varepsilon|D,X}(e|d,x)}{\delta}\right| < \infty\) 
		for some positive constant $c$.
	\end{itemize}
\end{assumptionR}
Assumptions \ref{A:regular.hm}(a)--(b) correspond to \citeauthor{hm2007}'s (\citeyear{hm2007}) Assumptions A2--A3, where the continuous differentiability of \(F_{Y|D,X}(y|\cdot,x)\) is equivalent to that of \(Q_{Y|D,X}(\alpha|\cdot,x)\). Assumptions \ref{A:regular.hm}(c) parallels Assumption A4 in \citet{hm2007}, ensuring smooth variation in the structural effect \(\partial_dm\). 
Finally, Assumption \ref{A:regular.hm}(d) aligns with Assumption A1 in \citet{hm2009}, which facilitates decomposition of the endogeneity-induced bias in the UQR estimand.

\begin{theorem}[Structural Representation of \(\beta^{\mathrm{UQR}}\)]\label{thm:struct.uqr.reg}
	Under Assumptions \ref{A:struct.m.l} and \ref{A:regular.hm}, we obtain
	\begin{align*}
		\beta^{\mathrm{UQR}}(\tau)
		=\EEc{\big}{\partial_dm(D,X,\varepsilon)}{Y=q_\tau} - \frac{\EE{\big}{\I{Y\leq q_\tau}\,\partial_d{\ln\big(f_{\varepsilon|D,X}(\varepsilon|D,X)\big)}}}{f_Y(q_\tau)} 
	\end{align*}
	for every $\tau \in (0,1)$.
\end{theorem}
Theorem \ref{thm:struct.uqr.reg} generalizes Proposition 1 of \citet{firpo2009}. Note that if conditional independence $\varepsilon \indep D|X$ are satisfied, we have \(\partial_d\ln(f_{\varepsilon|D,X}(\varepsilon|d,x)) = 0\) and  
\begin{align}
	\beta^{\mathrm{UQR}}(\tau)= \EEc{\big}{\partial_d{m(D,X,\varepsilon)}}{Y=q_\tau}, \label{eq:struct.uqr}
\end{align}
%where .
Therefore, under conditional independence, the estimand \(\beta^{\mathrm{UQR}}(\tau)\) is interpreted as the average structural effect for individuals with outcome value \(q_\tau\). Furthermore, if $e\mapsto m(d,x,e)$ is strictly monotonic, as assumed by \citeauthor{firpo2009}'s (\citeyear{firpo2009}) Proposition 1, we can derive their result using Equation (\ref{eq:struct.uqr}).

\begin{remark}
	For identifying \(\theta_Q^L\) via \(\theta_Q^L(\tau)=\beta^{\mathrm{UQR}}(\tau)\), the conditional independence assumption $\varepsilon \indep D|X$ is stronger than the distributional invariance condition \(F_{Y^t|D+t,X}=F_{Y|D,X}\) used by \citet{firpo2009}. This is because
	\[F_{Y^t|D+t,X}(\cdot|d,x)=\int \I{m(d,x,e)\leq \cdot}\,dF_{\varepsilon|D+t,X}(e|d,x),\]
	and  under $\varepsilon \indep D|X$, we have \(F_{\varepsilon|D+t,X}(e|d,x)=F_{\varepsilon|X}(e|x) = F_{\varepsilon|D,X}(e|d,x)\).
	Nonetheless, the conditional independence remains essential for the structural interpretation of $\beta^{\mathrm{UQR}}(\tau)$, as established in Theorem \ref{thm:struct.uqr.reg} or initially demonstrated by \citet{firpo2009}.
\end{remark}

