\section{ Ensemble interpolating between complex and real Ginibre}\label{interpol}

In this section we prove the statement of the Theorem \ref{Theorem1} which gives the joint probability density ${\cal P}_N(z,{\bf v})$ of complex eigenvalue $z$ and corresponding right eigenvector ${\bf v}$ for  the  interpolating Ginibre ensemble defined in Eq.(\ref{def_interpolating}). The starting point is the identity
Eq.(\ref{main_practical}) where we substitute the integral representations Eq. (\ref{Gaudelta_vec}) and Eq.(\ref{Berezin_int}) resulting in

\begin{equation}\label{JPDinter1}
{\cal P}_N(z,{\bf v})=\frac{1}{\pi}\lim_{|w-z|\to 0}\frac{\partial^2}{\partial w\partial \overline{w}}\lim_{\epsilon\to 0}
\int_{\mathbb{C}^N}\frac{d{\bf k}d{\bf k}^*}{(2\pi)^{2N}}e^{-\epsilon\frac{{\bf k}^*{\bf k}}{2}-\frac{i}{2}\left[z{\bf k}^*{\bf v}+\overline{z}
{\bf v}^*{\bf k}\right]}
\end{equation}
\[
\times \int \exp{-\frac{i}{2}\left[w\left(\mathbf{\Psi}_1^T\mathbf{\Phi}_2\right)
  +\overline{w} \left(\mathbf{\Psi}_2^T\mathbf{\Phi}_1\right)\right]}\,{\cal D}(\mathbf{\Psi},\mathbf{\Phi}) \,\left\langle e^{\frac{i}{2}\mbox{\small Tr }\left(XB_{21}+X^*B_{12}\right)}\right\rangle_{X}
\]
where we introduced $N\times N$ matrices
\begin{equation}\label{Bmat}
B_{21}={\bf v}\otimes {\bf k}^*-\mathbf{\Phi}_2\otimes \mathbf{\Psi}^T_1, \quad B_{12}={\bf k}\otimes {\bf v}^*-\mathbf{\Phi}_1\otimes \mathbf{\Psi}^T_2
\end{equation}
Now one can exploit the following identity for the average taken over the ensemble of real Ginibre matrices $G^{(R)}$ (to lighten the notations we omit the upper index $(R)$
henceforth):
 \begin{equation}\label{RGin_ave}
 \left\langle e^{\frac{i}{2}\mbox{\small Tr }\left(GB_{1}+G^TB_{2}\right)}\right\rangle_{G}=e^{\frac{1}{2}\mbox{\small Tr }\left(B_1^TB_{1}+B_2^TB_{2}+2B_1B_2\right)}
\end{equation}
valid for any two matrices $B_{1}$ and $B_2$. Recalling the definition Eq.(\ref{def_interpolating}) of the ensemble of matrices $X$
 one may see that
\[
\left\langle e^{\frac{i}{2}\mbox{\small Tr }\left(XB_{21}+X^*B_{12}\right)}\right\rangle_{X}=
\left\langle e^{\frac{i}{2}\sqrt{\frac{1+\tau}{2}}\mbox{\small Tr }\left(G_1B_{21}+G_1^TB_{12}\right)}\right\rangle_{G_1}
\left\langle e^{-\frac{1}{2}\sqrt{\frac{1-\tau}{2}}\mbox{\small Tr }\left(G_2B_{21}-G_2^TB_{12}\right)}\right\rangle_{G_2}
\]
\begin{equation}
=e^{-\frac{1}{8}\tau\mbox{\small Tr }\left(B^T_{21}B_{21}+B^T_{12}B_{12}\right)-\frac{1}{4}\mbox{\small Tr }\left(B_{21}B_{12}\right)}
\end{equation}
with the parameter $\tau\in[0,1]$ controlling the interpolation. The definitions Eq.(\ref{Bmat}) imply that
\[
\mbox{\small Tr }\left(B^T_{21}B_{21}\right)=2\left({\bf k}^*\mathbf{\Psi}_1\right)\left(\mathbf{\Phi}^T_2{\bf v}\right)+\overline{\left({\bf k}^T{\bf k}\right)}\left({\bf v}^T{\bf v}\right), \quad \mbox{\small Tr }\left(B^T_{12}B_{12}\right)=2\left({\bf v}^*\mathbf{\Psi}_2\right) \left(\mathbf{\Phi}^T_1{\bf k}\right)+
\left({\bf k}^T{\bf k}\right)\overline{\left({\bf v}^T{\bf v}\right)}
\]
and after recalling the normalization $\left({\bf v}^*{\bf v}\right)=1$ also
\[
\mbox{\small Tr }\left(B_{21}B_{12}\right)=\left({\bf k}^*{\bf k}\right)-
\left({\bf v}^*\mathbf{\Phi}_2\right)\left(\mathbf{\Psi}^T_1{\bf k}\right)-\left({\bf k}^*\mathbf{\Psi}_1\right)\left(\mathbf{\Psi}_2^T{\bf v}\right)
-\left(\mathbf{\Psi}_1^T\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^T\mathbf{\Phi}_2\right)
\]
Collecting all the factors one arrives at
\begin{equation}\label{JPDinter2}
{\cal P}_N(z,{\bf v})=\frac{1}{\pi}\lim_{|w-z|\to 0}\frac{\partial^2}{\partial w\partial \overline{w}}\lim_{\epsilon\to 0}
 \int \, {\cal D}(\mathbf{\Psi},\mathbf{\Phi})e^{-\frac{i}{2}\left[w\left(\mathbf{\Psi}_1^T\mathbf{\Phi}_2\right)
  +\overline{w} \left(\mathbf{\Psi}_2^T\mathbf{\Phi}_1\right)\right]+\frac{1}{4}\left(\mathbf{\Psi}_1^T\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^T\mathbf{\Phi}_2\right)}
  \end{equation}
\begin{equation}\label{JPDinter2a}
\times \int_{\mathbb{C}^N}\frac{d{\bf k}d{\bf k}^*}{(2\pi)^{2N}}e^{-\left(\frac{1}{2}+\epsilon\right)\frac{{\bf k}^*{\bf k}}{2}-\frac{\tau}{8}\left[\left({\bf k}^T{\bf k}\right)\overline{\left({\bf v}^T{\bf v}\right)}+\overline{\left({\bf k}^T{\bf k}\right)}\left({\bf v}^T{\bf v}\right)\right]+\frac{1}{4}\left[{\bf k}^*{\bf b}_1+{\bf b}_2^T{\bf k}\right]}\,,
\end{equation}
where we defined two vectors ${\bf b}_{1,2}$ by
\begin{equation}\label{def_b}
{\bf b}_1:=-2iz{\bf v}+\mathbf{\Phi}_1\left(\mathbf{\Psi}^T_2{\bf v}\right)-\tau \mathbf{\Psi}_1\left(\mathbf{\Phi}^T_2{\bf v}\right), \quad
{\bf b}^T_2:=-2i\overline{z}{\bf v}^*+\left({\bf v}^*\mathbf{\Phi}_2\right)\mathbf{\Psi}_1^T-\tau \left({\bf v}^*\mathbf{\Psi}_2\right)\mathbf{\Phi}_1^T.
\end{equation}
The integral over ${\bf k}, {\bf k}^*$ in Eq.(\ref{JPDinter2a}) is obviously Gaussian, and can be most conveniently evaluated after presenting the integration going
over two real vectors ${\bf k}_{1,2}$ defined by ${\bf k}={\bf k}_1+i{\bf k}_2$, so that
\[
{\bf k}^*{\bf k}={\bf k}_1^T{\bf k}_1+{\bf k}_2^T{\bf k}_2 \,\, \mbox{and} \,\, {\bf k}^T{\bf k}={\bf k}_1^T{\bf k}_1-{\bf k}_2^T{\bf k}_2+2i{\bf k}_1^T{\bf k}_2.
\]
Further introducing $2N-$component real vector $\tilde{\bf k}=({\bf k}_1,{\bf k}_2)^T$ one finds that
\begin{equation}\label{quad_form1}
-\left(\frac{1}{2}+\epsilon\right)\frac{{\bf k}^*{\bf k}}{2}-\frac{\tau}{8}\left[\left({\bf k}^T{\bf k}\right)\overline{\left({\bf v}^T{\bf v}\right)}+\overline{\left({\bf k}^T{\bf k}\right)}\left({\bf v}^T{\bf v}\right)\right]\frac{1}{4}\left[{\bf k}^*{\bf b}_1+{\bf b}_2^T{\bf k}\right]=-\frac{1}{2}\tilde{\bf k}^TC_{\epsilon}\tilde{\bf k}
+\frac{1}{4}\tilde{\bf k}^T{\bf b}
\end{equation}
where we denoted
\begin{equation}\label{quad_form2}
C_{\epsilon}=\frac{1}{2}\left(\begin{array}{cc} 1+2\epsilon+\tau \Re({\bf v}^T{\bf v}) & \tau \Im({\bf v}^T{\bf v})\\
\tau \Im({\bf v}^T{\bf v}) & 1+2\epsilon-\tau \Re({\bf v}^T{\bf v})\end{array}\right)\otimes {\bf 1}_N, \quad
 {\bf b}=\left(\begin{array}{c}{\bf b}_1+{\bf b}_2\\ -i\left({\bf b}_1+{\bf b}_2\right)\end{array}\right).
\end{equation}
As $|{\bf v}^T{\bf v}|\le 1$ the matrix $C_{\epsilon}$ is positive definite, with eigenvalues $\lambda_{\pm}=1+2\epsilon\pm \tau |{\bf v}^T{\bf v}|>0$ for any $\epsilon>0$ and $0\le \tau \le 1$. In fact it remains positive definite in the limit $\epsilon\to 0$
as long as either $\tau<1$ or for $\tau=1$ keeping $\Im z\ne 0$. Indeed, in the latter case the corresponding eigenvectors ${\bf v}$ are not purely real with probability one,
hence $|{\bf v}^T{\bf v}|<{\bf v}^*{\bf v}=1$ . We then conclude that for $0\le \tau<1$ and any $z\in \mathbb{C}$ or for  $\Im z\ne 0$ and any $0\le \tau\le 1$  one can safely proceed with setting $\epsilon=0$, and this will be assumed throughout the computations below. The only case when $\epsilon>0$ must be kept to ensure the convergence of the integral is for real eigenvalues of the real Ginibre ensemble when simultaneously  $\tau=1$ and $Im z=0$. Indeed, in that case the eigenvector ${\bf v}$ is real, implying $|{\bf v}^T{\bf v}|=1$, hence $\lambda_{-}=2\epsilon$.
In this way one may check to be able to recover exactly e.g. the singular contribution Eq.(\ref{denGinOEreal}) to the density of eigenvalues. We will not pursue this line explicitly,
as in fact there exists an alternative way to extract that contribution, see the discussion above the Proposition (\ref{Propscaled}).


 Now the Gaussian integration over the vector $\tilde{\bf k}$
 can be straightforwardly performed, yielding the factor proportional to
 \[
 \frac{1}{\left(\frac{\lambda_{-}\lambda_{+}}{4}\right)^{N/2}}\exp{\frac{1}{32}{\bf b}^TC^{-1}_{0}{\bf b}}
 =  {\left(\frac{4}{D}\right)^{N/2}}
 \exp{-\frac{\tau}{8D}\left[{\bf b}_1^T{\bf b}_1\overline{\left({\bf v}^T{\bf v}\right)}+{\bf b}_2^T{\bf b}_2\left({\bf v}^T{\bf v}\right)
 \right]+\frac{1}{4D}{\bf b}_1^T{\bf b}_2}
 \]
 where we exploited the expression for the inverse of the matrix $C_0=\lim_{\epsilon\to 0}C_{\epsilon}$ given explicitly by
  \begin{equation}\label{quad_form_inverse}
  C^{-1}_{0}=\frac{2}{D}\left(\begin{array}{cc} 1-\tau \Re({\bf v}^T{\bf v}) & -\tau \Im({\bf v}^T{\bf v})\\
-\tau \Im({\bf v}^T{\bf v}) & 1+\tau \Re({\bf v}^T{\bf v})\end{array}\right)\otimes {\bf 1}_N, \quad D=1-\tau^2|{\bf v}^T{\bf v}|^2.
\end{equation}
Substituting here the expressions for ${\bf b}_{1,2}$ from Eq.(\ref{def_b}) and introducing the following 3 matrices of size $N\times N$:
\begin{equation}\label{def_M}
{\cal M}=\tau^2 \left({\bf v}^T{\bf v}\right)\,\overline{{\bf v}\otimes {\bf v}^{T}}+\tau^2 \overline{ \left({\bf v}^T{\bf v}\right)}\,
{\bf v}\otimes {\bf v}^{T}-\tau^2\overline{{\bf v}\otimes {\bf v}^*}-{\bf v}\otimes {\bf v}^*
\end{equation}
\begin{equation}\label{def_K12}
{\cal K}_{12}=w{\bf 1}_N+\frac{\overline{z}\tau}{D} \left({\bf v}^T{\bf v}\right)\,\overline{{\bf v}\otimes {\bf v}^{T}}+
\frac{z\tau^2}{D} \overline{ \left({\bf v}^T{\bf v}\right)}\,{\bf v}\otimes {\bf v}^{T}-
\frac{1}{D}\left(\overline{z}\tau\overline{{\bf v}\otimes {\bf v}^*}+z{\bf v}\otimes {\bf v}^*\right)
\end{equation}
and
\begin{equation}\label{def_K21}
{\cal K}_{12}=\overline{w}{\bf 1}_N+\frac{z\tau}{D}\overline{ \left({\bf v}^T{\bf v}\right)}\,{\bf v}\otimes {\bf v}^{T}+
\frac{\overline{z}\tau^2}{D}  \left({\bf v}^T{\bf v}\right)\,\overline{{\bf v}\otimes {\bf v}^{T}}-
\frac{1}{D}\left(z\tau\overline{{\bf v}\otimes {\bf v}^*}+\overline{z}{\bf v}\otimes {\bf v}^*\right)
\end{equation}
allows us to represent our main object of interest as
\[
{\cal P}_N(z,{\bf v})\propto  {\left(\frac{4}{D}\right)^{N/2}}e^{-\frac{1}{D}\left[|z|^2-\frac{1}{2}\tau(z^2+\overline{z}^2)|{\bf v}^T{\bf v}|^2\right]}
\]
\begin{equation}\label{JPDinter3}
\times \lim_{|w-z|\to 0}\frac{\partial^2}{\partial w\partial \overline{w}}
 \int \, {\cal D}(\mathbf{\Psi},\mathbf{\Phi})e^{-\frac{i}{2}\left[\left(\mathbf{\Psi}_1^T{\cal K}_{12}\mathbf{\Phi}_2\right)
  + \left(\mathbf{\Psi}_2^T{\cal K}_{21}\mathbf{\Phi}_1\right)\right]+\frac{1}{4}\left(\mathbf{\Psi}_1^T\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^T\left\{{\bf 1}_N+\frac{\cal M}{D}\right\}\mathbf{\Phi}_2\right)}
  \end{equation}
The last term in the exponent is quartic in anticommuting variable, so it is expedient to employ a variant of the Hubbard-Stratonovich transformation:
\begin{equation}\label{HS_trafo1}
e^{\frac{1}{4}\left(\mathbf{\Psi}_1^T\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^T\left\{{\bf 1}_N+\frac{\cal M}{D}\right\}\mathbf{\Phi}_2\right)}
=\int e^{-q\overline{q}-\frac{q}{2} \left(\mathbf{\Psi}_1^T\mathbf{\Phi}_1\right)-\frac{\overline{q}}{2} \left(\mathbf{\Psi}_2^T\left\{{\bf 1}_N+\frac{\cal M}{D}\right\}\mathbf{\Phi}_2\right)}\,\frac{dqd\overline{q}}{\pi}.
\end{equation}
Substituting this relation back to Eq.(\ref{JPDinter3}) allows to perform the (by now, Gaussian) integral over anticommuting variables, eventually resulting in
\begin{equation}\label{JPDinter4}
{\cal P}_N(z,{\bf v})\propto  {\left(\frac{4}{D}\right)^{N/2}}e^{-\frac{1}{D}\left[|z|^2-\frac{1}{2}\tau(z^2+\overline{z}^2)|{\bf v}^T{\bf v}|^2\right]}
 \lim_{|w-z|\to 0}\frac{\partial^2}{\partial w\partial \overline{w}}
 \int e^{-q\overline{q}}\det{{\cal T}_N(|q|^2)},
  \end{equation}
  where we defined
  \begin{equation}\label{Tmat}
   {\cal T}_N(|q|^2)=|q|^2\left[{\bf 1}_N+\frac{\cal M}{D}\right]+{\cal K}_{21}{\cal K}_{12}\,.
   \end{equation}
A simple inspection shows that the matrix ${\cal T}_N(|q|^2)$ has $(N-2)$-degenerate eigenvalue $|q|^2+|w|^2$ with corresponding eigenvectors spanning
the space orthogonal to both ${\bf v}$ and ${\bf v}^*$, and two more non-trivial eigenvalues $\lambda_{1,2}$ with eigenvectors in the space spanned by
${\bf v}$ and ${\bf v}^*$. In these notations one may therefore write
\begin{equation}\label{det_T_interm}
\det{{\cal T}_N(|q|^2)}=\left(|q|^2+|w|^2\right)^{N-2}\lambda_1\lambda_2.
\end{equation}
To determine the product $\lambda_1\lambda_2$ one needs to compute the action of ${\cal T}_N(|q|^2)$ in the space spanned by
${\bf v}$ and ${\bf v}^*$. Introducing the notations
\begin{equation}\label{notations}
\delta w=w-z, \quad \zeta=z-\tau \overline{z}
\end{equation}
we first find that
\begin{equation}\label{actionK12}
{\cal K}_{12}{\bf v}=\delta w{\bf v}, \quad {\cal K}_{12}{\bf v}^*=-\left(1-\tau^2\right)\frac{z}{D}\overline{\left({\bf v}^T{\bf v}\right)}\,\,{\bf v}
+\left(\delta w+\frac{\zeta+\tau|{\bf v}^T{\bf v}|^2 \overline{\zeta}}{D}\right){\bf v}^*
\end{equation}
and
\begin{equation}\label{actionK21}
{\cal K}_{21}{\bf v}=\left(\overline{\delta w}+\frac{\tau|{\bf v}^T{\bf v}|^2 \zeta}{D}\right){\bf v}-\frac{\tau\left({\bf v}^T{\bf v}\right) \zeta}{D} {\bf v}^*,
\quad
{\cal K}_{21}{\bf v}^*=-\frac{\overline{\zeta}}{D}\overline{\left({\bf v}^T{\bf v}\right)}\,\,{\bf v}+\left(\overline{\delta w}+\frac{\overline{\zeta}}{D}\right)\,{\bf v}^*
\end{equation}
in turn implying
\begin{equation}\label{actionK21K12v}
{\cal K}_{21}{\cal K}_{12}{\bf v}=\delta w\left[\left(\overline{\delta w}+\frac{\tau|{\bf v}^T{\bf v}|^2 \zeta}{D}\right){\bf v}-\frac{\tau\left({\bf v}^T{\bf v}\right) \zeta}{D} {\bf v}^*\right]
\end{equation}
and
\begin{equation}\label{actionK21K12v*}
{\cal K}_{21}{\cal K}_{12}{\bf v}^*=-\frac{\overline{\left({\bf v}^T{\bf v}\right)}}{D}\left[\overline{\zeta}\left(\delta w+\frac{\zeta+\tau|{\bf v}^T{\bf v}|^2 \overline{\zeta}}{D}\right)+\left(1-\tau^2\right)z\left(\overline{\delta w}+\frac{\tau|{\bf v}^T{\bf v}|^2 \zeta}{D}\right)\right]{\bf v}
\end{equation}
\[
+\left[\left(\delta w+\frac{\zeta+\tau|{\bf v}^T{\bf v}|^2 \overline{\zeta}}{D}\right)\left(\overline{\delta w}+\frac{\overline{\zeta}}{D}\right)+\frac{\tau(1-\tau^2)|{\bf v}^T{\bf v}|^2 z \zeta}{D^2}
\right]{\bf v}^*
\]
We also have
\begin{equation}\label{actionM}
\left({\bf 1}_N+\frac{\cal M}{D}\right){\bf v}=0, \quad \left({\bf 1}_N+\frac{\cal M}{D}\right){\bf v}^*=-\frac{1-\tau^2}{D}
\left[\overline{\left({\bf v}^T{\bf v}\right)}{\bf v}-{\bf v}^*\right]
\end{equation}
Combining all these expressions one may find the characteristic equation $\det{\left({\cal F}-\lambda{\bf 1}_2\right)}=0$, where the matrix ${\cal F}$ is specified below:
\begin{equation}\label{calF}
\left(\begin{array}{cc}\left(\overline{\delta w}+\frac{\tau|{\bf v}^T{\bf v}|^2 \zeta}{D}\right)\delta w & -\frac{\overline{\left({\bf v}^T{\bf v}\right)}}{D}
\left[|q|^2(1-\tau^2)+\overline{\zeta}\left(\delta w+\frac{\zeta+\tau|{\bf v}^T{\bf v}|^2 \overline{\zeta}}{D}\right)+(1-\tau^2)z
\left(\overline{\delta w}+\frac{\tau|{\bf v}^T{\bf v}|^2 \zeta}{D}\right)\right]\\-\frac{\tau \zeta}{D}\left({\bf v}^T{\bf v}\right)\delta w  &
\frac{1-\tau^2}{D}\left(|q|^2+\frac{\tau\zeta z}{D}|{\bf v}^T{\bf v}|^2\right)+\left(\delta w+\frac{\zeta+\tau|{\bf v}^T{\bf v}|^2 \overline{\zeta}}{D}\right)
\left(\overline{\delta w}+\frac{\overline{\zeta}}{D}\right) \end{array}\right)
\end{equation}
The two roots of the characteristic equations are precisely the two eigenvalues $\lambda_1$ and $\lambda_2$, hence $\lambda_1\lambda_2=\det{\cal F}(\delta w, \overline{\delta w})$.
At this point it is useful to look back at Eq.(\ref{JPDinter4}) and Eq.(\ref{det_T_interm}) and recall that for our goals we need to evaluate in fact the following limit:
\begin{equation}\label{limit}
\lim_{|\delta w|\to 0}\frac{\partial^2}{\partial (\delta w)\,\partial \overline{(\delta w)}}\,\left\{
\left[|q|^2+(z+\delta w)(\overline{z}+\overline{\delta w})\right]^{N-2}\det{\cal F}(\delta w, \overline{\delta w})\right\}
\end{equation}
On the other hand, with an explicit computation one may check that
\begin{equation}\label{detcalF}
\det{\cal F}(\delta w, \overline{\delta w})=F|\delta w|^2+\mbox{higher order terms},
\end{equation}
where {\it higher order terms}  vanish faster than $|\delta w|^2$ at $|\delta w|\to 0$, and the coefficient $F$ is given by
\begin{equation}\label{detcalF}
F=\frac{1-\tau^2}{D}|q|^2+\frac{\left|\zeta+\tau \overline{\zeta}|{\bf v}^T{\bf v}|^2\right|^2}{D^2}.
\end{equation}
The limit in Eq.(\ref{limit}) is then immediately evaluated and is equal simply  to $\left(|q|^2+|z|^2\right]^{N-2}\,F$. Combining
all factors  and definitions together, restoring the correct normalization and using $R=|q|^2$ as the integration variable one finally arrives at an explicit expression for the joint probability density of an eigenvalue $z$ and the right normalized eigenvector ${\bf v}$
in the form:
\[
{\cal P}_N(z,{\bf v})= \frac{1}{\pi \Gamma(N)} \left(\frac{1}{D}\right)^{N/2}\,e^{-\frac{1}{D}\left(|z|^2-\frac{1}{2}\tau(z^2+\overline{z}^2)|{\bf v}^T{\bf v}|^2\right)}
\]
\begin{equation}\label{JPDfin1}
\times  \int_0^{\infty} dR e^{-R}\left[R+|z|^2\right]^{N-2}\left(\frac{1-\tau^2}{D}R+\frac{\left|z-\tau \overline{z}+\tau (\overline{z}-\tau z)|{\bf v}^T{\bf v}|^2\right|^2}{D^2}\right),  \quad D=1-\tau^2|{\bf v}^T{\bf v}|^2.
  \end{equation}
 Shifting  the integration variable $R+|z|^2\to v\in [|z|^2, \infty)$ and performing straightforward algebraic manipulations the above can be brought to the form
\[
{\cal P}_N(z,{\bf v})= \frac{1}{\pi \Gamma(N)} \left(\frac{1}{D}\right)^{N/2}\, e^{-\left(1-\frac{1}{D}\right)\frac{2\tau |z|^2-(z^2+\overline{z}^2)}{2\tau}}\int_{|z|^2}^{\infty} dv\, e^{-v}v^{N-2}
\]
\begin{equation}\label{JPDfin2}
\times  \left\{\frac{1-\tau^2}{D}v+|z|^2\left(1- \frac{1-\tau^2}{D}\right)-\tau(z^2+\overline{z}^2)\frac{1-|{\bf v}^T{\bf v}|^2}{D}+\tau^2|z|^2\left(\frac{1-|{\bf v}^T{\bf v}|^2}{D}\right)^2\right\}
  \end{equation}

Using the definition Eq.(\ref{gamma_incom}) and the identity
\[\frac{1-|{\bf v}^T{\bf v}|^2}{D}=\frac{1}{\tau^2}\left(1-\frac{1-\tau^2}{D}\right)\]
the form of Eq.(\ref{JPDfin2}) is finally reduced to one
presented in the Theorem (\ref{Theorem1}), see Eq.(\ref{MainJPDinterpolating}).


\section{ Ensemble of additive deformations of complex Ginibre matrices}

In this section we prove the statement of Theorem \ref{Theorem2} by applying our method to the ensemble of an additive deformation of the complex Ginibre ensemble
\begin{equation}\label{additive_def}
G_{A}=G_0+A
\end{equation}
where $G_{0}$ is taken from the ensemble of complex $N\times N$ Ginibre matrices and $A$ is an arbitrary fixed matrix of size $N$.
Following the same initial steps as in the previous section we have the following representation for the JPD of eigenvalue $z$ and
normalized right eigenvector ${\bf v}$ (cf. Eq.(\ref{JPDinter1}):
\begin{equation}\label{JPDadditive1}
{\cal P}^{(A)}_N(z,{\bf v})=\frac{1}{\pi}\lim_{|w-z|\to 0}\frac{\partial^2}{\partial w\partial \overline{w}}\lim_{\epsilon\to 0}
\int_{\mathbb{C}^N}\frac{d{\bf k}d{\bf k}^*}{(2\pi)^{2N}}e^{-\epsilon\frac{{\bf k}^*{\bf k}}{2}+\frac{i}{2}\left[{\bf k}^*(A-z{\bf 1}){\bf v}+
{\bf v}^*(A^*-\overline{z}{\bf 1}){\bf k}\right]}
\end{equation}
\[
\times \int \exp{-\frac{i}{2}\left[\left(\mathbf{\Psi}_1^*(A-w{\bf 1})\mathbf{\Phi}_2\right)
  + \left(\mathbf{\Psi}_2^*(A^*-\overline{w}{\bf 1})\mathbf{\Phi}_1\right)\right]}\,{\cal D}(\mathbf{\Psi},\mathbf{\Phi}) \,\left\langle e^{\frac{i}{2}\mbox{\small Tr }\left(XB_{21}+X^*B_{12}\right)}\right\rangle_{X}
\]
where we renamed $\mathbf{\Psi}^T_{1,2}\to \mathbf{\Psi}^*_{1,2}$ so that the matrices $B_{12}$ and $B_{21}$ are now defined as
\begin{equation}\label{Bmat_additive}
B_{21}={\bf v}\otimes {\bf k}^*-\mathbf{\Phi}_2\otimes \mathbf{\Psi}^*_1, \quad B_{12}={\bf k}\otimes {\bf v}^*-\mathbf{\Phi}_1\otimes \mathbf{\Psi}^*_2
\end{equation}
The ensemble average is now performed with the help of Eq.(\ref{RGin_ave}) where we put $\tau=0$ yielding
\begin{equation}\label{ans_ave}
 \left\langle e^{\frac{i}{2}\mbox{\small Tr }\left(XB_{21}+X^*B_{12}\right)}\right\rangle_{X}=e^{-\frac{1}{4}\left[{\bf k}^*{\bf k}-
 \left({\bf k}^*\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^*{\bf v}\right)- \left({\bf v}^*\mathbf{\Phi}_2\right)\left(\mathbf{\Psi}_1^*{\bf k}\right)
 -\left(\mathbf{\Psi}_1^*\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^*\mathbf{\Phi}_2\right)\right]}
\end{equation}
Substituting the above back to Eq.(\ref{JPDadditive1}) we see that the exponential becomes
 a Hermitian quadratic form $\frac{1}{2}\left(\epsilon+\frac{1}{2}\right){\bf k}^*{\bf k}$ which is positive definite even for $\epsilon=0$. Hence the $\epsilon-$regularization can be safely  omitted, with the corresponding Gaussian integral readily evaluated, yielding the factor:
 \begin{equation}\label{factor}
 e^{-\mathbf{v}^*\left(A^*-\overline{w}{\bf 1}\right)\left(A-w{\bf 1}\right){\bf v}-\frac{i}{2}\mathbf{\Psi}_1^*\left[(A-w{\bf 1}\right]{\bf v}\otimes {\bf v}^*\mathbf{\Phi}_2 -\frac{i}{2}\mathbf{\Psi}_2^*\left[{\bf v}\otimes {\bf v}^*(A^*-\overline{w}{\bf 1}\right]\mathbf{\Phi}_1-\frac{1}{4}\left(\mathbf{\Psi}_1^*\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^*\left({\bf v}\otimes {\bf v}^*\right)\mathbf{\Phi}_2\right)}
  \end{equation}
Substituting this back to Eq.(\ref{JPDadditive1}) and combining with the last exponential factor in Eq.(\ref{ans_ave}) we arrive at
\[
{\cal P}^{(A)}_N(z,{\bf v})=\frac{1}{\pi N}e^{-\mathbf{v}^*\left(A^*-\overline{w}{\bf 1}\right)\left(A-w{\bf 1}\right){\bf v}}
\]
\begin{equation}\label{JPDadditive2}
\times \lim_{|w-z|\to 0}\frac{\partial^2}{\partial w\partial \overline{w}}  \int e^{\frac{i}{2}\left(\mathbf{\Psi}_1^*,\mathbf{\Psi}_2^*\right){\large \cal H}(w,\overline{w})\left(\begin{array}{c}\mathbf{\Phi}_1\\ \mathbf{\Phi}_2\end{array}\right)+
\frac{1}{4}\left(\mathbf{\Psi}_1^*\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^*\left({\bf 1}_N-{\bf v}\otimes {\bf v}^*\right)\mathbf{\Phi}_2\right)}\,{\cal D}(\mathbf{\Psi},\mathbf{\Phi})
 \end{equation}
where we defined the following matrix
\begin{equation}
{\cal H}(w,\overline{w})=\left(\begin{array}{cc} 0 & \left(A-w{\bf 1}\right)-\left(A-z{\bf 1}\right){\bf v}\otimes {\bf v}^*
 \\ \left(A^*-\overline{w}{\bf 1}\right)-{\bf v}\otimes {\bf v}^*\left(A^*-\overline{z}{\bf 1}\right) &0 \end{array}\right)
\end{equation}
To facilitate the further evaluation, we again employ a variant
 of the Hubbard-Stratonovich transformation, cf. (\ref{HS_trafo1}) :
\begin{equation}\label{HS_trafo2}
e^{\frac{1}{4}\left(\mathbf{\Psi}_1^*\mathbf{\Phi}_1\right)\left(\mathbf{\Psi}_2^*\left({\bf 1}_N-{\bf v}\otimes {\bf v}^*\right)\mathbf{\Phi}_2\right)}
=\int e^{-q\overline{q}+\frac{q}{2} \left(\mathbf{\Psi}_1^*\mathbf{\Phi}_1\right)+\frac{\overline{q}}{2} \left(\mathbf{\Psi}_2^*\left({\bf 1}_N-{\bf v}\otimes {\bf v}^*\right)\mathbf{\Phi}_2\right)}\,\frac{dqd\overline{q}}{\pi}.
\end{equation}
Substituting the above back to Eq.(\ref{JPDadditive2}) and performing the Gaussian integral over antcommuting variables yields
\[
{\cal P}^{(A)}_N(z,{\bf v})=\frac{1}{\pi N}e^{-\mathbf{v}^*\left(A^*-\overline{w}{\bf 1}\right)\left(A-w{\bf 1}\right){\bf v}}
\]
\begin{equation}\label{JPDadditive2}
\times {\small
\lim_{|w-z|\to 0}\frac{\partial^2}{\partial w\partial \overline{w}}  \int  e^{-q\overline{q}}\, \det{\left[\left(\begin{array}{cc}q{\bf 1}_N & 0\\ 0& \overline{q}\left({\bf 1}_N-{\bf v}\otimes {\bf v}^*\right)\end{array}\right)+i{\cal H}(w,\overline{w})\right]}\,\frac{dqd\overline{q}}{\pi}}
 \end{equation}
To evaluate the remaining limit we set the notations
\begin{equation}\label{def Proj}
 w:=z+\delta w,\quad  \overline{w}:=\overline{z}+\overline{\delta w}, \quad P({\bf v}):={\bf 1}_N-{\bf v}\otimes {\bf v}^*=P^*({\bf v}),\,\, A_z:=A-z{\bf 1}_N
\end{equation}
and after applying the Schur's formula (cf. Eq.(\ref{Schur}) for the determinant of block matrices aim at computing
\[
\lim_{|\delta w|\to 0}\frac{\partial^2}{\partial (\delta w)\partial (\overline{\delta w})}\det{\left\{|q|^2 P({\bf v})+\left(A_z P({\bf v})-\delta w{\bf 1}_N\right)^*\left(A_z P({\bf v})-\delta w{\bf 1}_N\right) \right\}}
\]
 Further introduce a unitary matrix $U_{\bf v}=({\bf v}|{\bf v}_1|\ldots|{\bf v}_{N-1})$, where the columns of the matrix are vectors ${\bf v}_{i},\,i=1,\ldots,N-1$ from an orthonormal basis spanning the subspace in $\mathbb{C}^N$  orthogonal to the vector ${\bf v}$. It is then obvious that $P({\bf v})U_{\bf v}=(0|{\bf v}_1|\ldots|{\bf v}_{N-1})$.
 As $\det{\left\{\ldots\right\}}=\det{U^*_{\bf v}\left\{\ldots \right\}U_{\bf v}}$ we arrive at the task of evaluating
 \[
\det{\left[U^*_{\bf v}\left\{|q|^2 P({\bf v})+P({\bf v})A^*_zA_z P({\bf v})-\delta w P({\bf v})A^*_z-\overline{\delta w} A_zP({\bf v})+|\delta w|^2{\bf 1}_N\right\}U_{\bf v}\right]}
\]
Explicit computation shows that the matrix under the determinant in the above expression has the following block structure:
\begin{equation}\label{block}
\left(\begin{array}{cc}|\delta w|^2 & -\overline{\delta w}\, {\bf t}^*\\  -\delta w\, {\bf t} & {\cal R}(\delta w, \overline{\delta w})\end{array}\right)
\end{equation}
where we introduced the vector ${\bf t}\in \mathbb{C}^{(N-1)}$ with components ${\bf t}_i={\bf v}^*_iA_z^*{\bf v}$ and the $(N-1)\times (N-1)$ matrix ${\cal R}(\delta w, \overline{\delta w})$ with entries
\begin{equation}\label{Rmat}
\left[{\cal R}(\delta w, \overline{\delta w})\right]_{ij}=(|q|^2+|\delta w|^2)\delta_{ij}+{\bf v}_i^*A_z^*A_z{\bf v}_j-\delta w {\bf v}^*_iA_z^*{\bf v}_j-
\overline{\delta w}{\bf v}^*_iA_z{\bf v}_j
\end{equation}
The structure of the matrix in Eq.(\ref{block}) implies that its determinant can be represented by the Schur determinant formula as:
\begin{equation}\label{blockSchur}
\det{\left[{\cal R}(\delta w, \overline{\delta w})\right]}\left(1-{\bf t}^*{\cal R}^{-1}(\delta w, \overline{\delta w}){\bf t}\right)|\delta w|^2
\end{equation}
Now it is obvious that
\begin{equation}\label{lim}
\lim_{|\delta w|\to 0}\frac{\partial^2}{\partial (\delta w)\partial (\overline{\delta w})}
\left\{\det{\left[{\cal R}(\delta w, \overline{\delta w})\right]}\left(1-{\bf t}^*{\cal R}^{-1}(\delta w, \overline{\delta w}){\bf t}\right)|\delta w|^2\right\}
\end{equation}
\begin{equation}
=\det{\left[{\cal R}(0,0)\right]}\left(1-{\bf t}^*{\cal R}^{-1}(0,0){\bf t}\right)=\det{\left({\cal R}(0,0)-{\bf t}\otimes {\bf t}^*\right)}
\end{equation}
Now combining the expressions
\[
\left[{\cal R}(0,0)\right]_{ij}=|q|^2\delta_{ij}+{\bf v}^*_iA^*_zA_z{\bf v}_i, \quad \left[{\bf t}\otimes {\bf t}^*\right]_{ij}=\left({\bf v}^*_iA^*_z{\bf v}\right)
\left({\bf v}^*A^*_z{\bf v}_j\right)
\]
we have
\begin{equation}\label{def T}
\left[{\cal R}(0,0)-{\bf t}\otimes {\bf t}^*\right]_{ij}=|q|^2\delta_{ij}+T_{ij}, \quad T_{ij}={\bf v}^*_iA^*_zP({\bf v})A_z {\bf v}_j,
\end{equation}
resulting in the explicit formula for the JPD of an eigenvalue $z$ and the eigenvector ${\bf v}$ for the additively perturbed complex Ginibre ensemble
 \begin{equation}\label{JPDadditive_fin}
{\cal P}^{(A)}_N(z,{\bf v})=\frac{1}{\pi N}e^{-\mathbf{v}^*A^*_zA_z{\bf v}} \int  e^{-|q|^2}\, \det{\left[|q|^2
{\bf 1}_{N-1}+T({\bf v})\right]}\,\frac{dqd\overline{q}}{\pi}
\end{equation}
where we recall that
\begin{equation}\label{def_not_proj}
  \left[T({\bf v})\right]_{ij}={\bf v}^*_iA^*_zP({\bf v})A_z {\bf v}_j \quad  \mbox{where} \quad P({\bf v}):={\bf 1}_N-{\bf v}\otimes {\bf v}^*=P^*({\bf v}), \quad A_z:=A-z{\bf 1}_N, \quad.
\end{equation}
Note that $T({\bf v})$ is of the size $(N-1)\times (N-1)$.  Introducing now the $N\times N$ matrix
\begin{equation}\label{TAVproof}
T_A({\bf v})=A_z^*\,P({\bf v})\,A_z\,P({\bf v})
\end{equation}
and recalling that $\sum_{i=1}^{N-1}{\bf v}_i\otimes {\bf v}^*_i={\bf 1}_N-{\bf v}\otimes {\bf v}^*=P({\bf v})$ one can easily check the following identity:
\begin{equation}\label{TAVient}
\mbox{Tr} \left[T({\bf v})\right]^k=\mbox{Tr} \left[T_A({\bf v})\right]^k, \quad  \forall k=0, 1, 2, \ldots
\end{equation}
This fact combined with the Taylor expansion of  $\log \det{\left[|q|^2
{\bf 1}_{N-1}-T({\bf v})\right]}$  in Eq.(\ref{JPDadditive_fin}) shows after simple algebra that the latter expression is equivalent to Eq.(\ref{MainJPDadditivedef}) featuring in the Theorem \ref{Theorem2}.



\section{Appendices}
\subsection{Appendix A: Proof of the identity Eq.(\ref{main_integral_identity})}

Consider a $N\times N$ matrix $B$ assuming that its determinant is nonvanishing, and a vector ${\bf v}\in \mathbb{C}^N $.
We aim at proving the following distributional identity:
\begin{equation}\label{main_integral_identity_AppA}
\frac{1}{\pi} \int_{\mathbf{S}^c_N} \delta^{(2N)} \left(B{\bf v}\right)\,d\mu_H({\bf v})=\delta^{(2)}\left(\det(B)\right)\,.
\end{equation}

\subsubsection{Direct proof by induction}


We start with two observations.  First, the integration over a complex unit sphere defined by the condition ${\bf v}^*{\bf v}=1$ with respect to the corresponding uniform $U(N)$ invariant Haar's measure $d\mu_H({\bf v})$ can be equivalently replaced by integration over $\mathbb{C}^N$ with respect to the measure $d\mu_N=\delta\left({\bf v}^*{\bf v}-1\right)\,d^2{\bf v}_N$.
Second, for a complex $z\in \mathbb{C}^N$ we recall the equivalence between two measures: $\delta^{(2)}(z)d^{2}z=\frac{1}{\pi}\delta\left(|z|^2\right)d^{2}z$.
Hence a modified statement equivalent to Eq.(\ref{main_integral_identity_AppA}) is the following:

\begin{proposition}
with the above assumptions the identity
\begin{equation}\label{main_integral_identity_variant}
\int_{\mathbb{C}^N} \delta^{(2N)} \left(B{\bf v}\right)\,\delta\left({\bf v}^*{\bf v}-1\right)\,d^2{\bf v}=\delta\left(|\det B|^2\right)
\end{equation}
\end{proposition}
holds for any integer size $N\ge 1$. The proof will proceed by induction in size.

\begin{proof}
For $N=1$ the validity of Eq.(\ref{main_integral_identity_variant}) immediately follows after passing to polar coordinates
$v=|v|e^{i\theta}, \quad d^2\,v=|v|\,d|v|\,d\theta$ and  using the equivalence between the measures:
 $\delta^{(2)}(bv)d^{2}v=\frac{1}{\pi}\delta\left(|b|^2|v|^2\right)d^{2}v$.

Now we assume validity of Eq.(\ref{main_integral_identity_variant}) for complex matrices of size $N-1$, and consider
  matrix $B$ of size $N$, assuming first that the entry $B_{11}$ is non-vanishing. We then may write the block decomposition for such $B$ and ${\bf v}\in \mathbb{C}^N$ as
\begin{equation}\label{decomp}
B=\left(\begin{array}{cc} B_{11} & {\bf b}^*_{1}\\{\bf b}_{2} & B_{N-1}\end{array} \right), \quad {\bf v}= \left(\begin{array}{c} v_1 \\ {\bf v}_{N-1}\end{array} \right).
\end{equation}
where $v_1\in \mathbb{C}$, both ${\bf b}_{1}$ and ${\bf b}_{2}$ are vectors in $\mathbb{C}^{N-1}$ and $B_{N-1}$ is a complex of size $(N-1)\times(N-1)$.

Note that one of Schur determinant formulas associated with such a decomposition reads:
\begin{equation}\label{Schur}
\det{B}=B_{11}\det{\left(B_{N-1}-\frac{1}{B_{11}}{\bf b}_{2}\otimes {\bf b}^*_{1}\right)}.
\end{equation}
Using the suggested decomposition one can rewrite the right-hand side of Eq.(\ref{main_integral_identity_variant}) for $N=M$ as
\[
\int_{\mathbb{C}^N}\delta^{(2M)} \left(B{\bf v}\right)\,\delta\left({\bf v}^*{\bf v}-1\right) \,d^2{\bf v}\,
\]
\begin{equation}\label{main_integral_identity_variant_1}
=\int_{\mathbb{C}^{N-1}} d^{2}{\bf v}_{N-1}\int_{\mathbb{C}}\delta^{(2)}\left(B_{11} v_1+{\bf b}_{1}^*{\bf v}_{N-1}\right)\,\delta^{2(N-1)}
\left({\bf b}_{2}\,v_1+B_{N-1}{\bf v}_{N-1}\right)
\end{equation}
\[
\times \delta\left(|v_1|^2+{\bf v}^*_{N-1}{\bf v}_{N-1}-1\right)\,d^2v_1
\]
The integration over $v_1$ can be immediately performed exploiting the factor $\delta^{(2)}\left(B_{11} v_1+{\bf b}_{1}^*{\bf v}_{N-1}\right)$
 yielding
\begin{equation}\label{main_integral_identity_variant_2}
\int_{\mathbb{C}^N} \,\delta^{(2N)} \left(B{\bf v}\right)\,\delta\left({\bf v}^*{\bf v}_-1\right)\,d^2{\bf v}\,=|B_{11}|^{-2}\int_{\mathbb{C}^{N-1}} \delta^{(2(N-1))}\left(\left[B_{N-1}-{\bf b}_{2}\otimes{\bf b}_1^*/B_{11}\right]{\bf v}_{N-1}\right)
\end{equation}
\[
\times \delta\left({\bf v}^*_{N-1}\left[{\bf 1}_{N-1}+\frac{{\bf b}_{1}\otimes {\bf b}^*_{1}}{|B_{11}|^2}\right]{\bf v}_{N}-1\right)\,d^2{\bf v}_{N-1}\,
\]
Now changing ${\bf v}_{N-1}\to {\bf w}_{N-1}$ via ${\bf v}_{N-1}=\left[{\bf 1}_{N-1}+\frac{{\bf b}_{1}\otimes {\bf b}^*_{1}}{|B_{11}|^2}\right]^{-1/2}
 {\bf w}_{N-1}$ brings the above integral
to
\[
\int_{\mathbb{C}^N} \,d^2{\bf v}_{N}\,\delta^{(2N)} \left(B {\bf v}\right)\,\delta\left({\bf v}^*{\bf v}-1\right)=|B_{11}|^{-2}
\det^{-1}\left[{\bf 1}_{N-1}+\frac{{\bf b}_{1}\otimes {\bf b}^*_{1}}{|B_{11}|^2}\right]
\]
 \begin{equation}\label{main_integral_identity_variant_3}
\times
\int_{\mathbb{C}^{N-1}} \delta^{(2{N-1})}\left(\left(B_{N-1}-{\bf b}_{2}\otimes{\bf b}_1^*/B_{11}\right)\left[{\bf 1}_{N-1}+\frac{{\bf b}_{1}\otimes {\bf b}^*_{1}}{|B_{11}|^2}\right]^{-1/2}{\bf w}_{N-1}\right)
\end{equation}
\[
\times \delta\left({\bf w}_{N-1}^*{\bf w}_{N-1}-1\right)\,d^2{\bf w}_{N-1}\,
\]
The remaining integral in Eq.(\ref{main_integral_identity_variant_3}) is exactly of the form
 Eq.(\ref{main_integral_identity_variant}) for size $N-1$, hence by using our  induction assumption
yields the factor
\[
\delta\left(\left|\det{\left(B_{N-1}-{\bf b}_{2}\otimes{\bf b}_1^*/B_{11}\right)}\right|^2
\left|\det{\left[{\bf 1}_{N-1}+\frac{{\bf b}_{1}\otimes {\bf b}^*_{1}}{|B_{11}|^2}\right]}^{-1}\right|\right)
\]
Combining all factors, employing the Schur determinant formula Eq.(\ref{Schur}) and using $\delta(cx)=|c|^{-1}\delta(x)$ for real $c\ne 0$ and real $x$
one arrives at the factor $\delta\left(|\det{B}|^2\right)$, thus proving Eq.(\ref{main_integral_identity_variant}) for $N$, hence for any positive integer.

It remains to show that the conclusion remains valid if $B_{11}=0$. According to our assumption $\det{B}\ne 0$ at least one element in the first row
must be nonzero, let it be $B_{1k}$ with some $2\le k\le N$. Now take the identity matrix ${\bf 1}_N$, interchange the first and the $k_{th}$ column and call the resulting unitary matrix $P_k$.   Make in Eq.(\ref{main_integral_identity_variant}) the change of variabals ${\bf v}=P_k\tilde{{\bf v}}$. Using invariance of the Haar's measure we
see that the change is equivalent to simply changing $B\to \tilde{B}=BP_k$ in Eq.(\ref{main_integral_identity_variant}). As the matrix $\tilde{B}$ has now the entry
$\tilde{B}_{11}=B_{1k}\ne 0$ we conclude that the result of integration yields the factor $\delta\left(|\det{\tilde{B}}|^2\right)=\delta\left(|\det{B}|^2\right)$
proving the required statement.
 \end{proof}
\begin{remark}
For matrices $B$ with real entries the same method yields a similar identity:
\begin{equation}\label{main_integral_real}
\int_{{\bf S}^R} \delta^{(N)} \left(B{\bf v}\right)\,d\mu_H({\bf v})=\delta\left(\det(B)\right)\,,
\end{equation}
where now the integration goes over the vectors confined to the real $N-$dimensional sphere ${\bf S}^R$ of unit radius, with the uniform real $O(N)$-invariant Haar's measure
$d\mu_H({\bf v})$.
\end{remark}

\subsubsection{Proof by relating to Itzykson-Zuber-HarishChandra integral}
\label{Zirn}
To provide an alternative proof\footnote{The idea of the proof was suggested to the author by M.R. Zirnbauer} of Eq.(\ref{main_integral_identity_AppA}) one starts with the Gaussan-regularized version of $\delta^{2N}({\bf u}), \,{\bf u}\in {C}^N$:
\begin{equation}\label{Gaureg_AppA}
\delta_{\epsilon}^{2N}({\bf u})=\frac{1}{(2\pi\epsilon)^N}e^{-\frac{{\bf u}^*{\bf u}}{2\epsilon}}, \quad \epsilon>0.
\end{equation}
Replacing in this way $\delta^{(2N)} \left(B{\bf v}\right)$ in the integrand in the left-hand side of Eq.(\ref{main_integral_identity_AppA}), the latter integral takes the form:
\begin{equation}\label{main_integral_identity_AppA_reg1}
L_{\epsilon}^{(N)}(B^*B)=\frac{1}{(2\pi\epsilon)^N} \int_{\mathbf{S}^c_N} e^{-\frac{{\bf v}^*B^*B{\bf v}}{2\epsilon}} \,d\mu_H({\bf v}).
\end{equation}
 By representing  $B^*B=U\Sigma U$, with some unitary $U\in U(N)$ and the diagonal matrix of squared singular values
 $\Sigma=diag\left(\sigma_1^2,\ldots,\sigma_N^2\right)$, we see that due to invariance of the Haar's measure the result of the integration depends only on $\Sigma$
 but not on $U$. Therefore the result remains the same if we average over $U$ with the Haar's measure, implying:
  \begin{equation}\label{main_integral_identity_AppA_reg2}
L_{\epsilon}^{(N)}(\Sigma)=  \int_{\mathbf{S}^c_N} \left[\frac{1}{(2\pi\epsilon)^N} \int_{U(N)}\,e^{-\frac{{\bf v}^*U^*\Sigma U{\bf v}}{2\epsilon}}d\mu_H(U)\right]\,d\mu_H({\bf v}).
\end{equation}
The inner intergral can be rewritten in the suggestive form:
\begin{equation}\label{main_integral_identity_AppA_reg3}
 \frac{1}{(2\pi\epsilon)^N}  \int_{U(N)}\,e^{-\frac{\mbox{\tiny Tr}\left(U^*\Sigma UA_{\bf v}\right)}{2\epsilon}}d\mu_H(U), \quad A_v={\bf v}\otimes {\bf v}^*,
\end{equation}
showing that it is a particular case of the famous Itzykson-Zuber-HarishChandra integral (IZHC) integral\cite{IZ,HC1956}:
\begin{equation}\label{IZHC}
 \int_{U(N)}\,e^{t\,\mbox{\tiny Tr}\left(U^* B UA\right)}\,d\mu_H(U)=\frac{C_N}{t^{N(N-1)/2}}\frac{\det{e^{b_ia_j}}}{\Delta(B)\Delta(A)}
\end{equation}
where $C_N=\prod_{k=1}^{N-1}k!$ and $b_i$ and $a_i$ are eigenvalues of matrices $B$ and $A$, respectively, while $\Delta(B)=\prod_{i<j}(b_i-b_j)$.
For simplicity we illustrate the following procedure with the simplest non-trivial case $N=2$, indicating necessary changes for a general-$N$ case in the end.
For $N=2$ in our particular case we have $C_2=1, t=(2\epsilon)^{-1}, b_1=\sigma_1^2,  b_2=\sigma_2^2, a_1={\bf v}^*{\bf v}=1, a_2=0$, which immediately gives
 \begin{equation}\label{main_integral_identity_AppA_reg4}
L_{\epsilon}^{(2)}(\sigma_1^2,\sigma_2^2)=  -\frac{1}{2\pi^2\epsilon}\left(\frac{e^{-\frac{\sigma_1^2}{2\epsilon}}}{\sigma_1^2-\sigma_2^2}+\frac{e^{-\frac{\sigma_2^2}{2\epsilon}}}{\sigma_2^2-\sigma_1^2}\right)
\end{equation}
Our next step is to demonstrate the following identity:
\begin{equation}\label{limident1}
\lim_{\epsilon\to 0}L_{\epsilon}^{(2)}(x_1,x_2)=\frac{1}{\pi^2}\delta(x_1x_2)=\frac{1}{\pi^2}\left(\frac{\delta(x_1)}{x_2}+\frac{\delta(x_2)}{x_1}\right),
\end{equation}
which should be understood to hold by integrating both sides against the test functions $\phi(x_1,x_2)$ over the domain
$D^{(2)}_{+}:=\{x_1\in\mathbb{R}_+,\,x_2\in\mathbb{R}_+\}$ with the Lebesgue measure $dx_1dx_2$. For the test functions we require to be continuous in
$D^{(2)}_{+}$ and satisfying the conditions $\int_{\mathbb{R}_+}\phi(0,x_2)\frac{dx_2}{x_2}<\infty$ and $\int_{\mathbb{R}_+}\phi(x_1,0)\frac{dx_1}{x_1}<\infty$. Indeed we have
\[
\int\int_{D^{(2)}_{+}} L_{\epsilon}^{(2)}(x_1,x_2)\phi(x_1,x_2)=-\frac{1}{2\pi^2\epsilon}\left(\int_{\mathbb{R}_+} dx_2\int_{\mathbb{R}_+}dx_1
\frac{e^{-\frac{x_1}{2\epsilon}}\phi(x_1,x_2)}{x_1-x_2}+\int_{\mathbb{R}_+} dx_1\int_{\mathbb{R}_+}dx_2
\frac{e^{-\frac{x_2}{2\epsilon}}\phi(x_1,x_2)}{x_2-x_1}\right)
\]
\[=-\frac{1}{2\pi^2}\left(\int_{\mathbb{R}_+} dx_2\int_{\mathbb{R}_+}dx_1
\frac{e^{-\frac{x_1}{2}}\phi(\epsilon x_1,x_2)}{\epsilon x_1-x_2}+\int_{\mathbb{R}_+} dx_1\int_{\mathbb{R}_+}dx_2
\frac{e^{-\frac{x_2}{2}}\phi(x_1,\epsilon x_2)}{\epsilon x_2-x_1}\right)
\]
Taking the limit $\epsilon \to 0$ straightforwardly in the above one sees that
 \begin{equation}\label{limident2}
\lim_{\epsilon\to 0}\int\int_{D^{(2)}_{+}} L_{\epsilon}^{(2)}(x_1,x_2)\phi(x_1,x_2)=\frac{1}{\pi^2}\left(\int_{\mathbb{R}_+}\phi(0,x_2)\frac{dx_2}{x_2}+
\int_{\mathbb{R}_+}\phi(x_1,0)\frac{dx_1}{x_1} \right)
\end{equation}
\[
=\int\int_{D^{(2)}_{+}} \frac{1}{\pi^2}\left(\frac{\delta(x_1)}{x_2}+\frac{\delta(x_2)}{x_1}\right) \phi(x_1,x_2),
\]
thus verifying the identity Eq.(\ref{limident1}).

In the case of a general $N\ge 2$ one proceeds in a very similar way by using the fact that $A_{\bf v}={\bf v}\otimes {\bf v}^*$ is a rank-one matrix, so that
$a_1=1$ but $a_{2\le i\le N}=0$. In this special case the IZHC integral takes the following simple form:
 \begin{equation}\label{IZHC_rank1}
 \int_{U(N)}\,e^{t\,\mbox{\tiny Tr}\left(U^* B UA\right)}\,d\mu_H(U)=\frac{C_N}{t^{N(N-1)/2}}\sum_{i=1}^N\frac{e^{b_ia_1}}{\prod_{j\ne i}(b_i-b_j)}
\end{equation}
 leading to the identity
 \begin{equation}\label{limident3}
\lim_{\epsilon\to 0}L_{\epsilon}^{(N)}(x_1,\ldots,x_N)=\frac{1}{\pi^2}\delta\left(\prod_{i=1}^N x_i\right)=\frac{1}{\pi^2}\sum_{i=1}^N \frac{\delta(x_i)}{\prod_{j\ne i}x_j}
\end{equation}
which again should be understood to hold by integrating both sides against the test functions $\phi(x_1,\ldots,x_N)$ over the domain
$D^{(N)}_{+}:=\{x_1\in\mathbb{R}_+,\ldots, x_N\in\mathbb{R}_+\}$ with the Lebesgue measure $dx_1\ldots dx_N$. The test functions should satisfy
the conditions of continuity in $D^{(N)}_{+}$ as well as finiteness of certain obvious integrals. Recalling that in terms of singular values
of $B$ we have $\prod_{i=1}^N x_i=\prod_{i=1}^N \sigma^2_i=\det{(B^*B)}=|\det{B}|^2$ completes the proof.

\subsection{Appendix B: proof of the relation Eq.(\ref{Meta_Kac_Rice_right_eigenvec})}



The goal of this Appendix is to demonstrate that the statement of Theorem \ref{MainMetaTheorem} is a direct consequence of the multivariate Kac-Rice counting formula
 Eq.(\ref{Kac-Rice_counting_multi}). 
 Our starting point is rewriting the right eigen-equation  $X\,\mathbf{v}=z \mathbf{v}$ together with the normalization ${\bf v}^*{\bf v}=1$ as a set of real equations.
 For this we separate the real and imaginary parts of relevant variables via
 \begin{equation}\label{ real_notations}
 X=A+iB, \quad {\bf v}={\bf s}+i{\bf t}, \quad z=\lambda_1+i\lambda_2
 \end{equation}
 and further use the short-hand notations $A_{\lambda}=A-\lambda{\bf 1}_N, \,\, B_{\lambda}=B-\lambda{\bf 1}_N$.
Then the set of real equations satisfied by $2N+2$ real variables ${\bf s}^T=(s_1,\ldots,s_N),{\bf t}^T=(t_1,\ldots,t_N),\lambda_1,\lambda_2$  takes the following form:
\begin{equation}\label{coupled real_equations 1}
A_{\lambda_1}{\bf s}-B_{\lambda_2}{\bf t}=0, \quad B_{\lambda_2}{\bf s}+A_{\lambda_1}{\bf t}=0, \quad {\bf s}^T{\bf s}+{\bf t}^T{\bf t}=1
\end{equation}
supplemented by an extra real condition satisfied by the first coordinates $s_1,t_1$:
\begin{equation}\label{coupled real_equations 2}
\sin{\theta}s_1-\cos{\theta}t_1=0.
\end{equation} 
%one may notice that both the equation $X\,\mathbf{v}=z \mathbf{v}$
%and the normalization ${\bf v}^*{\bf v}=1$ are invariant with respect to the transformation ${\bf v}\to e^{i\theta}{\bf v}$, hence leave the overall phase of the right eigenvector arbitrary.
  The relation  Eq.(\ref{coupled real_equations 2}) is equivalent to fixing the ratio $v_1/\overline{v}_1=e^{2i\theta}$ and hence serves to fix the phase of the first entry of the right eigenvector up to a trivial change in the overall sign: $\theta\to\theta+\pi$. 

To apply the multivariate Kac-Rice counting formula
 Eq.(\ref{Kac-Rice_counting_multi}) to the present problem, we introduce the vector ${\bf x}=({\bf s},{\bf t},\lambda_1,\lambda_2)^T$ with $2N+2$ real components,
 and write the Jacobian matrix $J({\bf x})=\left(\frac{\partial f_i}{\partial x_j}\right)$ arising from Eqs.(\ref{coupled real_equations 1})- (\ref{coupled real_equations 2}) in the natural block form:
 \begin{equation}\label{blockJacobian 1}
 J({\bf x})=\left(\begin{array}{cc}J_{AB} & \begin{array}{cc} -{\bf s} & {\bf t}\\ -{\bf t} & -{\bf s} \end{array}
 \\ \begin{array}{cc} 2{\bf s}^T & 2{\bf t}^T\\ \sin{\theta}{\bf e}^T & -\cos{\theta} {\bf e}^T \end{array} &
 \begin{array}{cc} 0 & 0\\ 0 & 0 \end{array}\end{array}  \right), \quad J_{AB}=\left(\begin{array}{cc} A_{\lambda_1} & - B_{\lambda_2} \\ B_{\lambda_2} & A_{\lambda_1} \end{array}\right)
\end{equation}
and ${\bf e}^T=(1,0,\ldots,0)$. One may further notice that the matrix $J_{AB}$ can be block-diagonalized as
\begin{equation}\label{blockJacobian 2}
 J_{AB}=U_M^*\,\left(\begin{array}{cc} A_{\lambda_1} - iB_{\lambda_2} & 0 \\ 0 & A_{\lambda_1}+i B_{\lambda_2}  \end{array}\right)\,U_M,
 \quad U_M=\frac{1}{\sqrt{2}}\left(\begin{array}{cc}{\bf 1}_N & - i{\bf 1}_N   \\ - i{\bf 1}_N  & {\bf 1}_N   \end{array}\right)
\end{equation}
with the matrix $U_M$ being unitary. Recalling $A_{\lambda_1}+i B_{\lambda_2}=X-z{\bf 1}_N$ we therefore have:
\begin{equation}\label{blockJacobian 3}
 J^{-1}_{AB}=U_M^*\,\left(\begin{array}{cc} (X^*-\overline{z}{\bf 1}_N)^{-1} & 0 \\ 0 & (X-z{\bf 1}_N)^{-1} \end{array}\right)\,U_M,
 \quad \mbox{and}\quad \det{J_{AB}}=\left|\det{\left(X-z{\bf 1}_N\right)}\right|^2.
\end{equation}
Applying now  the Schur determinant formula Eq.(\ref{Schur}) to evaluating $\det{J({\bf x})}$ we  see that
\begin{equation}\label{blockJacobian 4}
|\det{J({\bf x})}| = 2|\det{J_{AB}}|\,\left|\det\left\{\left(\begin{array}{cc} {\bf s}^T & {\bf t}^T\\ \sin{\theta}{\bf e}^T & -\cos{\theta} {\bf e}^T \end{array}\right)J_{AB}^{-1}\left(\begin{array}{cc} {\bf s} & {\bf t}\\ {\bf t} & -{\bf s} \end{array}\right)\right\}\right|.
\end{equation}
Recalling ${\bf v}={\bf s}+i{\bf t}$ and $\overline{\bf v}={\bf s}-i{\bf t}$ one may check that
\[U_M\left(\begin{array}{cc} {\bf s} & {\bf t}\\ {\bf t} & -{\bf s} \end{array}\right)=\frac{1}{\sqrt{2}}
\left(\begin{array}{cc} \overline{\bf v} & i \overline{\bf v}\\ -i{\bf v} & -{\bf v} \end{array}\right), \quad \left(\begin{array}{cc} {\bf s}^T & {\bf t}^T\\ \sin{\theta}{\bf e}^T & -\cos{\theta} {\bf e}^T \end{array}\right)U^*=\frac{1}{\sqrt{2}}\left(\begin{array}{cc} {\bf v}^T & i {\bf v}^*\\ -ie^{i\theta}{\bf e}^T & -e^{-i\theta}{\bf e}^T \end{array}\right).
\]
and after straightforward algebra further arrive at
\begin{equation}\label{blockJacobian 5}
|\det{J({\bf x})}| = \frac{1}{2}|\det{J_{AB}}|\,\left|\det{\left(\begin{array}{cc} J_{11} & J_{12}\\ J_{21} & J_{22} \end{array}\right)}\right|.
\end{equation}
where
\begin{equation}\label{blockJacobian 6a}
 J_{11} ={\bf v}^* \left(\frac{1}{X^*-\overline{z}{\bf 1}_N}+\frac{1}{X-z{\bf 1}_N}\right){\bf v}, \quad  J_{12} = -i{\bf v}^* \left(\frac{1}{X^*-\overline{z}{\bf 1}_N}-\frac{1}{X-z{\bf 1}_N}\right){\bf v}
\end{equation}
\begin{equation}\label{blockJacobian 6b}
 \quad  J_{21} = -i\left(e^{i\theta}{\bf v}^* \frac{1}{X^*-\overline{z}{\bf 1}_N}\,{\bf e}-e^{-i\theta}{\bf e}^T\frac{1}{X-z{\bf 1}_N}\,{\bf v}\right), \quad
 J_{22} =e^{i\theta}{\bf v}^* \frac{1}{X^*-\overline{z}{\bf 1}_N}\,{\bf e}+e^{i\theta}{\bf e}^T\frac{1}{X-z{\bf 1}_N}\,{\bf v},
\end{equation}
Combining all the factors, and assuming the parameter $\theta$ given, we see that the multivariate Kac-Rice formula  counting
 Eq.(\ref{Kac-Rice_counting_multi}) in our case produces the following expression for the joint density of the normalized complex-valued right eigenvector ${\bf v}=(v_1,\ldots,v_N)^T$ and the corresponding complex eigenvalue $z$:
 \begin{equation}\label{JD_comp_interm}
 \Pi_{N,\theta}=\frac{1}{2}\delta({\bf v}^*{\bf v}-1)\delta\left(\frac{i}{2}\left[e^{-i\theta}v_1-e^{-i\theta}\overline{v_1}\right]\right)
 \delta^{(2N)}\left[(X-z{\bf 1}_N){\bf v}\right]\left|\det{(X-z{\bf 1}_N)}\right|^2 \left|\det{\left(\begin{array}{cc} J_{11} & J_{12}\\ J_{21} & J_{22} \end{array}\right)}\right|.
 \end{equation}
Evidently, the factor $\delta^{(2N)}\left[(X-z{\bf 1}_N){\bf v}\right]$ ensures that the right-hand side is non-vanishing if and only if the vector  ${\bf v}$
coincides with one of the normalized right eigenvectors ${\bf v}_i, \, i=1, \ldots,N$ and simultaneously $z\to z_i$ with the same index. In such a limit the product of
determinant factors
in the right-hand side considerably simplifies. To see this we first set ${\bf v} ={\bf v}_i$ but keep
  $z\ne z_i$. We see that in such a limit the entries  $J_{pq}$ in Eqs.(\ref{blockJacobian 6a})-(\ref{blockJacobian 6b}) take the form:
 \begin{equation}\label{blockJacobian 6asimp}
 J_{11} =\frac{1}{\overline{z}_i-\overline{z}}+\frac{1}{z_i-z}, \quad  J_{12} = i\left(\frac{1}{\overline{z}_i-\overline{z}}-\frac{1}{z_i-z}\right)
  \end{equation}
\begin{equation}\label{blockJacobian 6bsimp}
 \quad  J_{21} = -i\left(e^{i\theta}\frac{\overline{v_{1i}}}{\overline{z}_i-\overline{z}}-e^{-i\theta}\frac{v_{1i}}{z_i-z}\right), \quad
 J_{22} = e^{i\theta}\frac{\overline{v_{1i}}}{\overline{z}_i-\overline{z}}+e^{-i\theta}\frac{v_{1i}}{z_i-z}
\end{equation}
which allows one to compute
\begin{equation}\label{blockJacobian_simp1}
\left|\det{\left(\begin{array}{cc} J_{11} & J_{12}\\ J_{21} & J_{22} \end{array}\right)}\right|=2\left|e^{-i\theta}v_{1i}+e^{i\theta}\overline{v_{1i}}\right|\frac{1}{|z-z_i|^2}.
\end{equation}
and further shows that the following limit is well defined:
\begin{equation}\label{blockJacobian_simp1}
\lim_{{\bf v}\to {\bf v}_i, \, z\to z_i}\left|\det{(X-z{\bf 1}_N)}\right|^2\left|\det{\left(\begin{array}{cc} J_{11} & J_{12}\\ J_{21} & J_{22} \end{array}\right)}\right|
=2\left|e^{-i\theta}v_{1i}+e^{i\theta}\overline{v_{1i}}\right|\prod_{j\ne i}^N{|z_i-z_j|^2}
\end{equation}
Now using the identity:
\[
\lim_{ z\to z_i}\left[\frac{d}{dz}\det{(X-z{\bf 1}_N)}\right]=-\prod_{j\ne i}^N\,(z_i-z_j)
\]
we see that Eq.(\ref{JD_comp_interm}) is equivalent for a given $\theta$ to
 \begin{equation}\label{JD_comp_interm1}
 \Pi_{N,\theta}=\delta({\bf v}^*{\bf v}-1)
 \delta^{(2N)}\left[(X-z{\bf 1}_N){\bf v}\right]\left|\frac{d}{dz}\det{(X-z{\bf 1}_N)}\right|^2
 \end{equation}
 \[\times \delta\left(\frac{i}{2}\left[e^{-i\theta}v_1-e^{-i\theta}\overline{v_1}\right]\right)\left|e^{-i\theta}v_{1i}+e^{i\theta}\overline{v_{1i}}\right|.
 \]
Finally, using the polar parametrization $v_{1i}=|v_1|e^{i\theta_1}$ one easily checks the identity
\[\delta\left(\frac{i}{2}\left[e^{-i\theta}v_1-e^{-i\theta}\overline{v_1}\right]\right)\left|e^{-i\theta}v_{1i}+e^{i\theta}\overline{v_{1i}}\right|=
2\left[\delta(\theta-\theta_1)+ \delta(\theta-\theta_1-\pi)\right]
 \]
which reflects that in the chosen way  Eq.(\ref{coupled real_equations 2}) of fixing the phase $\theta$ the eigenvectors are still determined up to the overall sign: ${\bf v}_i\to -{\bf v}_i$. Remembering this and getting rid of the immaterial overall phase $\theta$ of the eigenvector by averaging over it
finally reduces Eq.(\ref{JD_comp_interm1}) to the form  Eq. (\ref{Meta_Kac_Rice_right_eigenvec}).

\subsection{Appendix C: Proof of the Lemma \ref{IntLemma}}
For convenience of the reader we repeat the statement of the Lemma below:\\[0.5ex]
{\it
 The idenity
\begin{equation}\label{sphereintegralApp}
\int_{\mathbf{S}^{(c)}_N}  f(|{\bf v}^T{\bf v}|^2)\,d\mu_H({\bf v})=\frac{N-1}{2}\int_0^1(1-u)^{(N-3)/2}f(u)\,du,
\end{equation}
holds true for any function $f(u), \, u\in \mathbb{R}$ such that the above integrals exist, assuming $N\ge 2$.
}

\begin{proof}
It is convenient to parametrize ${\bf v}\in \mathbb{C}^N$ as ${\bf v}={\bf p}_1+i{\bf p}_2$ with ${\bf p}_{1,2}\in \mathbb{R}^N$
which implies
\[
|{\bf v}^T{\bf v}|^2=({\bf p}^T_1{\bf p}_1-{\bf p}_2^T{\bf p}_2)^2+4\left({\bf p}^T_1{\bf p}_2\right)^2
\]
and further express the Haar's measure on the unit complex sphere $\mathbf{S}^{(c)}_N$ using the Dirac $\delta-$function as
\begin{equation}\label{Haar}
d\mu_H({\bf v})\propto \delta\left({\bf p}^T_1{\bf p}_1+{\bf p}_2^T{\bf p}_2-1\right)d{\bf p}_1d{\bf p}_2\, ,
\end{equation}
where here and henceforth we omit arising multiplicative factors as their product can be easily fixed in the very end.
Hence in the new coordinates the integral in question takes the form
\begin{equation}\label{sphereintegral_A}
\int_{\mathbf{S}^{(c)}_N}  f(|{\bf v}^T{\bf v}|^2)\,d\mu_H({\bf v})\propto \int_{\mathbb{R}^N} d{\bf p}_1\int_{\mathbb{R}^N} d{\bf p}_2 \delta\left({\bf p}^T_1{\bf p}_1+{\bf p}_2^T{\bf p}_2-1\right)f\left[({\bf p}^T_1{\bf p}_1-{\bf p}_2^T{\bf p}_2)^2+4\left({\bf p}^T_1{\bf p}_2\right)^2\right].
\end{equation}
To evaluate such an integral we may use a trick suggested in \cite{YF2002} of introducing the (non-negative definite) real symmetric matrix
$Q=\left(\begin{array}{cc}{\bf p}^T_1{\bf p}_1 & {\bf p}^T_1{\bf p}_2\\
{\bf p}^T_2{\bf p}_1 & {\bf p}^T_2{\bf p}_2\end{array}\right)\ge 0$  and using it as the new integration variable in Eq.(\ref{sphereintegral_A}).
Such a change incurs a certain Jacobian and the corresponding formulas can be found, e.g. in Eqs. (10)-(12) in \cite{FyoSom2007}. Following this way one finds after straightforward manipulations
\begin{equation}\label{sphereintegral_B}
\int_{\mathbf{S}^{(c)}_N}  f(|{\bf v}^T{\bf v}|^2)\,d\mu_H({\bf v})\propto \frac{\pi^{N-1/2}}{\Gamma\left(\frac{N}{2}\right)\Gamma\left(\frac{N-1}{2}\right)} \int_{Q\ge 0} dQ  \det{Q}^{\frac{N-3}{2}} \delta\left(\mbox{\small Tr}Q-1\right)
f\left[\left(\mbox{\small Tr}Q\right)^2-4\det{Q}\right].
\end{equation}
Writing $Q$ in terms of the eigenvalues $q_1$ and $q_2$ as $Q=O\,\mbox{diag}(q_1,q_2)\,O^*$, with $O^TO={\bf 1}_2$ implying $dQ\propto |q_1-q_2|dq_1dq_2\,d\mu(O)$
we further rewrite the above as
\begin{equation}\label{sphereintegral_C}
\int_{\mathbf{S}^{(c)}_N}  f(|{\bf v}^T{\bf v}|^2)\,d\mu_H({\bf v})\propto  \int_{0}^{\infty}dq_1\int_{0}^{\infty}dq_2\,|q_1-q_2|   (q_1q_2)^{\frac{N-3}{2}} \delta(q_1+q_2-1)
f[1-4q_1q_2].
\end{equation}
and after performing the integration over $q_2$ one arrives at
\begin{equation}\label{sphereintegral_D}
\int_{\mathbf{S}^{(c)}_N}  f(|{\bf v}^T{\bf v}|^2)\,d\mu_H({\bf v}) \propto \int_{0}^{1}dq_1|2q_1-1|   \left[q_1(1-q_1)\right]^{\frac{N-3}{2}}
f[\left(2q_1-1\right)^2].
\end{equation}
Finally, one may notice the invariance of the integrand with respect to the change $q_1\to 1-q_1$, so it is equal to twice the same integral with the upper limit $q_1=1/2$.
Introducing the variable $u=(2q-1)^2$ so that $q_1(1-q_1)=(1-u)/4$ and restoring the accumulated multiplicative constant by setting $f=1$ one arrives to the statement of the lemma.

 \end{proof}




\subsection{Appendix D: Hikami-Pnini formula}
Our starting point is the formula Eq.(\ref{HikamiPnini}) for the mean density of complex eigenvalues of a Ginibre matrix additively
perturbed by a fixed normal matrix with distinct eigenvalues $a_1,\ldots,a_N$. For convenience of the reader we repeat it below, using the notation $d_i=z-a_i, \, \forall i=1,\ldots,N$:
\begin{equation}\label{HikamiPnini0}
p_N^{(A,norm)}(z)=\frac{1}{\pi N}\frac{\partial^2}{\partial z\partial \overline{z}}\int_0^1\,\frac{dp}{p^2}\,\oint_{\gamma}
\frac{dt}{2\pi i}\frac{e^{-pt}}{t}\prod_{i=1}^N\frac{t(1-p)-|d_i|^2}{t-|d_i|^2}
\end{equation}
Using the identity
\begin{equation} \label{ident_sym1}
\frac{1}{\prod_{i=1}^N (t-|d_i|^2)}=\sum_{i=1}^N \frac{1}{t-|d_i|^2}\prod_{k\ne i}\frac{1}{|d_i|^2-|d_k|^2}
\end{equation}
we can rewrite Eq.(\ref{HikamiPnini0}) in the form
\begin{equation}\label{HikamiPnini1}
p_N^{(A,norm)}(z)=\frac{1}{\pi N}\int_0^1\,\frac{dp}{p^2}\,\frac{\partial^2}{\partial z\partial \overline{z}}\sum_{i=1}^N\prod_{k\ne i}\frac{1}{|d_i|^2-|d_k|^2}\,\oint_{\gamma}
\frac{dt}{2\pi i}\frac{e^{-pt}}{t}\frac{\prod_{k=1}^N \left(t(1-p)-|d_k|^2\right)}{t-|d_i|^2}.
\end{equation}
Now the contour integral can be evaluated by residue theorem with two poles at $t=0$ and $t=|d_i|^2$, yielding
\begin{equation}\label{HikamiPninicont}
\oint_{\gamma}
\frac{dt}{2\pi i}\frac{e^{-pt}}{t}\frac{\prod_{k=1}^N \left(t(1-p)-|d_k|^2\right)}{t-|d_i|^2}=(-1)^{N-1}\prod_{k\ne i}|d_k|^2-pe^{-p|d_i|^2}
\prod_{k\ne i}  \left(t(1-p)-|d_k|^2\right).
\end{equation}
Substituting this back to Eq.(\ref{HikamiPnini1}) and using that
\[
\frac{\partial^2}{\partial z\partial \overline{z}}\sum_{i=1}^N\prod_{k\ne i}\frac{|d_k|^2}{|d_i|^2-|d_k|^2}=\frac{\partial^2}{\partial z\partial \overline{z}}\, (-1)=0
\]
one arrives at
\begin{equation}\label{HikamiPnini1}
p_N^{(A,norm)}(z)=\frac{1}{\pi N}\int_0^1\,\frac{dp}{p}\,\frac{\partial^2}{\partial z\partial \overline{z}}\sum_{i=1}^Ne^{-p|d_i|^2}\,\prod_{k\ne i}
\frac{\left(|d_i|^2(1-p)-|d_k|^2\right)}{|d_i|^2-|d_k|^2}\,.
\end{equation}
which is equivalent to Eq.(\ref{HikamiPnini_my}).

\subsection{Appendix E: Proof of the Corollary \ref{cor2.10}}
We aim at analysing implications of (\ref{MainJPDadditivedef}) for a general rank-one {\it non-normal} deformation matrix $A$ parametrized  by a single complex eigenvalue $a\in \mathbb{C}$ and two complex vectors: the left ${\bf l}$ and the right ${\bf r}$ so that
\begin{equation}\label{rank_one_gen_proof}
 A=a\,{\bf r}\otimes {\bf l}^*, \quad \mbox{with}\quad a\in \mathbb{C}\ \quad \mbox{and s.t.}\,\, {\bf l}^*{\bf r}=1.
 \end{equation}
 In fact in this case we find it is slightly easier to start with an equivalent form of (\ref{MainJPDadditivedef}) given by Eq.(\ref{JPDadditive_fin}) which we
 repeat for convenience below:
 \begin{equation}\label{JPDadditive_fin_proof}
{\cal P}^{(A)}_N(z,{\bf v})=\frac{1}{\pi}e^{-\mathbf{v}^*A^*_zA_z{\bf v}} \int  e^{-R}\, \det{\left[R\,
{\bf 1}_{N-1}+T({\bf v})\right]}\,dR
\end{equation}
where the entries of $(N-1)\times (N-1)$ matrix are given by $T_{ij}={\bf v}^*_iA^*_zP({\bf v})A_z {\bf v}_j$, with $P({\bf v})={\bf 1}_N-{\bf v}\otimes {\bf v}^*$ and the vectors ${\bf v},{\bf v}_1, \ldots, {\bf v}_{N-1}$ forming an orthonormal basis of $\mathbb{C}^N$.  It is also convenient to introduce the notations:
\begin{equation}\label{lr_notations}
{\bf p}:=P({\bf v}){\bf r}, \quad {\tilde{\bf p}}:=\left(\begin{array}{c}{\bf v}_1^*{\bf p}\\{\bf v}_2^*{\bf p} \\ \ldots \\ \ldots \\ {\bf v}_{N-1}^*{\bf p}  \end{array}\right),
\quad {\tilde{\bf l}}:=\left(\begin{array}{c}{\bf v}_1^*{\bf l}\\{\bf v}_2^*{\bf l} \\ \ldots \\ \ldots \\ {\bf v}_{N-1}^*{\bf l}  \end{array}\right),
\end{equation}
in terms of which the matrix $T({\bf v})$ can be readily expressed as
\begin{equation}\label{Tmat_proof}
T({\bf v})=|z|^2{\bf 1}_{N-1}+\tilde{T}({\bf v}), \quad \tilde{T}({\bf v})=|a|^2\left({\bf p}^*{\bf p}\right)\tilde{{\bf l}}\otimes \tilde{{\bf l}}^*-a\overline{z}\tilde{{\bf p}}\otimes \tilde{{\bf l}}^*
-\overline{a}z\tilde{{\bf l}}\otimes \tilde{{\bf p}}^*.
\end{equation}
Obviously, the matrix  $\tilde{T}({\bf v})$ is rank-2, with $(N-3)$ eigenvalues equal zero, and 2 nonvanishing eigenvalues $\lambda_{1}$ and $\lambda_2$
corresponding to eigenvectors ${\bf u}_{1,2}$ belonginging to the space of linear combinations   ${\bf u}=\alpha\,\tilde{{\bf l}}+\beta  \tilde{{\bf p}}, \, (\alpha,\beta)\ne (0,0)$. This implies the system of 2 linear equations satisfied by  $(\alpha,\beta)$ and $\lambda$:
\begin{equation}
\begin{array}{c}
\alpha\left\{\left[|a|^2\left({\bf p}^*{\bf p}\right)\left(\tilde{{\bf l}}^*\tilde{{\bf l}}\right)-\overline{a}z\left(\tilde{{\bf p}}^*\tilde{{\bf l}}\right)\right]-\lambda\right\}+\beta\left[|a|^2\left({\bf p}^*{\bf p}\right)\left(\tilde{{\bf l}}^*\tilde{{\bf p}}\right)-\overline{a}z\left(\tilde{{\bf p}}^*\tilde{{\bf p}}\right)\right]=0\\ \alpha\,\overline{z}a\left(\tilde{{\bf l}}^*\tilde{{\bf l}}\right)+\beta\left[a\overline{z}\left(\tilde{{\bf l}}^*\tilde{{\bf p}}\right)+\lambda \right]=0
\end{array},
\end{equation}
with the corresponding characteristic equation
\[
\lambda^2+\lambda\left[z\overline{a}\left(\tilde{{\bf p}}^*\tilde{{\bf l}}\right)+a\overline{z}\left(\tilde{{\bf l}}^*\tilde{{\bf p}}\right)
-|a|^2\left({\bf p}^*{\bf p}\right)\left(\tilde{{\bf l}}^*\tilde{{\bf l}}\right)\right]+|a|^2|z|^2
\left[\left({\bf p}^*{\bf l}\right)\left(\tilde{{\bf l}}^*\tilde{{\bf p}}\right)-\left({\bf l}^*{\bf l}\right)\left(\tilde{{\bf p}}^*\tilde{{\bf p}}\right)\right]=0.
\]
Taking into account the relations
\[
\tilde{{\bf p}}^*\tilde{{\bf p}}={\bf p}^*{\bf p}={\bf r}^*P({\bf v}){\bf r}, \quad \tilde{{\bf l}}^*\tilde{{\bf p}}={\bf l}^*P({\bf v}){\bf p}={\bf l}^*P({\bf v}){\bf r}
\]
one finds that the characteristic equation implies the following relations for the nontrivial eigenvalues $\lambda_{12}$:
\begin{equation}\label{Vieta}
\begin{array}{c}
\lambda_1+\lambda_2=-\overline{a}z\,{\bf r}^*P({\bf v}){\bf l}-\overline{z}a\,{\bf l}^*P({\bf v}){\bf r}+|a|^2\,\left({\bf r}^*P({\bf v}){\bf r}\right)\,
\left({\bf l}^*P({\bf v}){\bf l}\right)\\ \lambda_1\lambda_2=-|a|^2|z|^2\left[\left({\bf l}^*P({\bf v}){\bf l}\right)\,\left({\bf r}^*P({\bf v}){\bf r}\right)-
\left({\bf l}^*P({\bf v}){\bf r}\right)\,\left({\bf r}^*P({\bf v}){\bf l}\right)\right]
\end{array},
\end{equation}
Now the determinant entering Eq.(\ref{JPDadditive_fin_proof}) can be obviously evaluated as
\[\det{\left[R\,
{\bf 1}_{N-1}+T({\bf v})\right]}=(|q|^2+|z|^2)^{N-3}(|q|^2+|z|^2+\lambda_1)(|q|^2+|z|^2+\lambda_2).
\]
Combining this with relations Eq.(\ref{Vieta}) and using that in the present case
\[
{\bf v}^*A_z^*A_z{\bf v}=|z|^2+|a|^2|{\bf v}^*{\bf l}|^2-\overline{z}a({\bf v}^*{\bf r}) ({\bf l}^*{\bf v})-\overline{a}z({\bf v}^*{\bf l}) ({\bf r}^*{\bf v})
\]
and employing the definition Eq.(\ref{gamma_incom}) of the incomplete $\Gamma$-function one immediately arrives to the statement of {\bf Corollary \ref{cor2.10}}.

