\end{lemma}

  \begin{proof}
    We will start with a vector $\xi_{\vec{1}} \in \Ran(q_{\vec1})$ and compute the norm of each $\xi_{\vec\imath} = e_{\vec\imath,\vec1}^{(\cK)}$ using the orthogonal decomposition \eqref{eq: master vector formula}, then show that it can only be non-zero and finite if the sum above converges.

    Note that the terms $\ip{\delta_{\vec{\imath}}, \varepsilon_{a_1,b_1}^{(w_1)} \dots \varepsilon_{a_\ell,b_\ell}^{(w_\ell)} \delta_{\vec{\jmath}}}$ are zero or one, so they are unchanged under squaring.
    We also have that
    \[
      \text{for } a \neq b, \quad \norm{ (t_b^{(v)})^{-1} \mathring{e}_{a,b}^{(v)} }_{\varphi}^2 = (t_b^{(v)})^{-2} \varphi((e_{a,b}^{(v)})^* e_{a,b}^{(v)}) = (t_b^{(v)})^{-2} \varphi(e_{b,b}^{(v)}) = (t_b^{(v)})^{-1}
    \]
    and
    \[
      \norm{ (t_b^{(v)})^{-1} \mathring{e}_{b,b}^{(v)} }_{\varphi}^2 = (t_b^{(v)})^{-2} \norm{e_{b,b}^{(v)} - \varphi(e_{b,b}^{(v)}) 1}_\varphi^2 = (t_b^{(v)})^{-2} t_b^{(v)}(1 - t_b^{(v)}) = (t_b^{(v)})^{-1} - 1.
    \]
    We therefore have
    \begin{equation} \label{eq: master norm formula}
      \norm{\xi_{\vec{\imath}}}^2 = \sum_{\vec{\jmath} \in [\vec n]} |\alpha_{\vec{\jmath}}|^2 \sum_{\ell \in \N} \sum_{w \in \mathcal{W}_\ell} \sum_{\substack{a_1,b_1 \in [n(w_1)] \\ \vdots \\ a_{\ell}, b_{\ell} \in [n(w_\ell)]}} \ip{\delta_{\vec{\imath}}, \varepsilon_{a_1,b_1}^{(w_1)} \dots \varepsilon_{a_\ell,b_\ell}^{(w_\ell)} \delta_{\vec{\jmath}}} \, \prod_{t=1}^\ell \left( \frac{1}{t_{b_t}^{(w_t)}} - \mathbf{1}_{a_t=b_t} \right).
    \end{equation}
    Defining for $v \in \cV$ the matrix
    \[
      S^{(v)} = \sum_{a,b \in [n(v)]} \frac{1}{t_{b}^{(v)}} \varepsilon_{a,b}^{(v)} \in \bigotimes_{v \in \cV} \mathbb{M}_{n(v)},
    \]   
    and note that
    \[
      \sum_{a,b \in [n(v)]} \varepsilon_{a,b}^{(v)}\left( \frac{1}{t_{b}^{(v)}} - \mathbf{1}_{a=b} \right) = S^{(v)} - 1.
    \]
    Then
    \[
      \sum_{\substack{a_1,b_1 \in [n(w_1)] \\ \vdots \\ a_{\ell}, b_{\ell} \in [n(w_\ell)]}} \ip{\delta_{\vec{\imath}}, \varepsilon_{a_1,b_1}^{(w_1)} \dots \varepsilon_{a_\ell,b_\ell}^{(w_\ell)} \delta_{\vec{\jmath}}} \, \prod_{t=1}^\ell \left( \frac{1}{t_{b_t}^{(w_t)}} - \mathbf{1}_{a_t=b_t} \right) = \ip{\delta_{\vec{\imath}}, (S^{(w_1)}-1) \dots (S^{(w_\ell)} - 1) \delta_{\vec{\jmath}}},
    \]
    and so
    \begin{equation} \label{eq: master norm formula 2}
      \norm{\xi_{\vec{\imath}}}^2 = \sum_{\ell \in \N} \sum_{w \in \mathcal{W}_\ell} \ip*{\delta_{\vec{\imath}}, (S^{(w_1)}-1) \dots (S^{(w_\ell)} - 1) \sum_{\vec{\jmath}} |\alpha_{\vec{\jmath}}|^2 \delta_{\vec{\jmath}}},
    \end{equation}
    where all the terms in the summation are nonnegative.
    We further note the following properties of the matrices, recalling that we set $s^{(v)} = \sum_{b\in[n(v)]}\frac1{t_b^{(v)}}$:
    \begin{itemize}
      \item $S^{(v)} - 1$ has nonnegative entries.
      \item $S^{(v)}$ is a rank one matrix in $\mathbb{M}_{n(v)}$ tensor the identity in the other factors.
      \item $(S^{(v)})^2 = s^{(v)} S^{(v)}$.
      %    \item $\Tr(S^{(v)}) = \sum_{b \in [n(v)]} 1/t_b^{(v)}$.
      \item $S^{(v)}$ and $S^{(v')}$ commute for all $v \neq v'$, and in fact they are in tensor position.
      \item $\sum_{\vec{\imath}} \delta_{\vec{\imath}}$ is an eigenvector of each $S^{(v)}$ with eigenvalue $s^{(v)}$.
      \item Moreover, the vector
        \[
          \gamma = \sum_{\vec{\imath} \in [\vec n]} \prod_{v \in \cV} \frac{1}{t_{i(v)}^{(v)}} \delta_{\vec{\imath}}
          = \bigotimes_{v \in \cV} \sum_{i \in [n(v)]} \frac1{t_{i(v)}^{(v)}} \delta_{i(v)}
        \]
        is an eigenvector of $(S^{(v)})^*$ with eigenvalue $s^{(v)}$.
    \end{itemize}
    % Since $S^{(v)} - 1$ has nonnegative entries and the vector $\sigma = \sum_{\vec{\jmath}} |\alpha_{\vec{\jmath}}|^2 \delta_{\vec{\jmath}}$ has nonnegative entries, we have
    % \[
    %   \sum_{\ell \in \N_0} \sum_{w \in \mathcal{W}_\ell} \ip*{\delta_{\vec{\imath}}, (S^{(w_1)}-1) \dots (S^{(w_\ell)} - 1) \sum_{\vec{\jmath}} |\alpha_{\vec{\jmath}}|^2 \delta_{\vec{\jmath}}} < \infty \iff \sum_{\ell \in \N_0} \sum_{w \in \mathcal{W}_\ell} \Tr[(S^{(w_1)}-1) \dots (S^{(w_\ell)} - 1)] < \infty.
    % \]
    % In particular, there exists a nonzero vector $\xi \in \Ran(q_{\vec{1}})$ if and only if the sum on the right-hand side converges.
    % Since the same holds for any vector, we can also substitute the eigenvector $\sum_{\vec{\imath}} \delta_{\vec{\imath}}$ and so obtain
    % \[
    %   q_{\vec{1}} \neq 0 \iff \sum_{\ell \in \N_0} \sum_{w \in \mathcal{W}_\ell} (s^{(w_1)}-1) \dots (s^{(w_\ell)} - 1) < \infty.
    % \]
    % Note that although we started with $q_{\vec{1}}$, the same argument applies with an arbitrary tuple $\vec{\imath}$ instead of $\vec{1}$.

%    Our next goal is to compute $\varphi(q_{\vec\imath})$ assuming $q_{\vec\imath}$ is non-zero.
 %   Let us start with $\xi \in \Ran(q_{\vec{1}})$.
  %  As in the previous lemma, by transporting with the partial isometries $e_{\vec{\imath},\vec{\jmath}}^{(\cK)}$, assume we have a family of vectors such that $\xi_{\vec{\imath}} = e_{\vec{\imath},\vec{\jmath}}^{(\cK)} \xi_{\vec{\jmath}}$.
  Recall that $\xi_{\vec{\imath}}$ was obtained by applying the partial isometry $e_{\vec{\imath},\vec{1}}^{(K)}$ to the vector $\xi_{\vec{1}}$ which is in the range of $q_{\vec{\imath}}$, and hence in the source subspace for this partial isometry.  Hence, $\norm{\xi_{\vec{\imath}}}$ is the same for all $\vec{\imath}$.  We will thus simplify our computation by taking linear combinations of the norms to exploit the left eigenvector $\gamma$ above.
    Namely, for each $\vec{k}$, using \eqref{eq: master norm formula 2} we have
    \begin{align*}
      \prod_{v \in \cV} s^{(v)} \norm{\xi_{\vec{k}}}^2 &= \sum_{\vec{\imath} \in [\vec n]} \left( \prod_{v \in \cV} \frac{1}{t_{i(v)}^{(v)}} \right) \norm{\xi_{\vec{\imath}}}^2 \\
      &= \sum_{\ell \in \N} \sum_{w \in \mathcal{W}_\ell} \ip*{\gamma, (S^{(w_1)}-1) \dots (S^{(w_\ell)} - 1) \sum_{\vec{\jmath}} |\alpha_{\vec{\jmath}}|^2 \delta_{\vec{\jmath}}} \\
      &= \left( \sum_{\ell \in \N} \sum_{w \in \mathcal{W}_\ell} (s^{(w_1)}-1) \dots (s^{(w_\ell)} - 1) \right) \ip*{\gamma, \sum_{\vec{\jmath}} |\alpha_{\vec{\jmath}}|^2 \delta_{\vec{\jmath}}} \\
      &= \left( \sum_{\ell \in \N} \sum_{w \in \mathcal{W}_\ell} (s^{(w_1)}-1) \dots (s^{(w_\ell)} - 1) \right) \sum_{\jmath \in [\vec n]} \prod_{v \in \cV} \frac{1}{t_{j(v)}^{(v)}} |\alpha_{\vec{\jmath}}|^2.
    \end{align*}
    In particular, if the summation in \eqref{eq: summation condition} is infinite, then the only way this equation can hold is if $\alpha_{\vec{\jmath}} = 0$ for all $\vec{\jmath}$ and so $\xi_{\vec{\imath}} = 0$ for all $\vec{\imath}$; thus, in this case $q_{\vec{\imath}} = 0$ for all $\vec{\imath}$.  On the other hand, if the summation converges, then \eqref{eq: master vector formula} from Lemma \ref{lem: master vector lemma} produces vectors in the range of $q_{\vec{\imath}}$, and so $q_{\vec{\imath}}$ is nonzero for every $\vec{\imath}$.  This proves \eqref{eq: summation condition}.


    To prove \eqref{eq: state on projection formula}, fix $\vec{\imath}$ and apply the above computations explicitly taking $\xi_{\vec{\imath}} = q_{\vec \imath}\Omega$ (and so $\xi_{\vec{\jmath}} = e_{\vec{\jmath},\vec{\imath}}^{(K)} \xi_{\vec{\imath}}$ for $\vec{\jmath} \neq \vec{\imath}$).  In the context of the decomposition \eqref{eq: master vector formula} from Lemma~\ref{lem: master vector lemma}, we have that
    \[
      \alpha_{\vec{\jmath}} = \ip{\Omega, \xi_{\vec{\jmath}}} = \varphi(e_{\vec{\jmath},\vec{\imath}} q_{\vec{\imath}}).
    \]
    Let $\sigma_t^\varphi$ be the modular group.  Recall $\sigma_t^\varphi|_{M_v} = \sigma_t^{\varphi_v}$. Since we chose the $\varphi_v |_{\mathbb{M}_{n(v)}}$ to be given by a diagonal matrix, we have that $e_{j(v),i(v)}^{(v)}$ is an eigenvector of the modular group.  Hence, so is the product $e_{\vec{\jmath},\vec{\imath}}$ and so for some $\lambda$ we have
    \[
      \varphi(e_{\vec{\jmath},\vec{\imath}} x) = \lambda \varphi(x e_{\vec{\jmath},\vec{\imath}}).
    \]
    In particular,
    \[
      \alpha_{\vec{\jmath}} 
      = \varphi(e_{\vec{\jmath},\vec{\imath}} q_{\vec{\imath}}) = \lambda \varphi(q_{\vec{\imath}} e_{\vec{\jmath},\vec{\imath}}) = 0 \text{ for } \vec{\jmath} \neq \vec{\imath}.
    \]
    Meanwhile,
    \[
      \alpha_{\vec{\imath}} = \varphi(q_{\vec{\imath}}).
    \]
    This results in
    \[
      \prod_{v \in \cV} s^{(v)} \varphi(q_{\vec{\imath}}) = \prod_{v \in \cV} s^{(v)} \norm{q_{\vec{\imath}}}_\varphi^2= \sum_{\ell \in \N} \sum_{w \in \mathcal{W}_\ell}(s^{(w_1)}-1) \dots (s^{(w_\ell)} - 1) \prod_{v \in \cV} \frac{1}{t_{i(v)}^{(v)}} \varphi(q_{\vec{\imath}})^2
    \]
    and therefore,
    \[
      \frac{1}{\varphi(q_{\vec{\imath}})} = \sum_{\ell \in \N} \sum_{w \in \mathcal{W}_\ell}(s^{(w_1)}-1) \dots (s^{(w_\ell)} - 1) \prod_{v \in \cV} \frac{1}{t_{i(v)}^{(v)} s^{(v)}},
    \]
    which proves \eqref{eq: state on projection formula}.
