  \subsection{Realization of all atomic summands} \label{subsec: realization of all}

Our next goal is to show that all type I factor summands arise from the construction in the previous sections.

	\begin{notation} \label{nota: general f d summand}
		Let $(M,\varphi) = *_{v \in \cG} (M_v,\varphi_v)$.  In the rest of this section, assume that $(N,\psi)$ is a direct summand with $N \cong B(H)$ for some Hilbert space.  Let $\pi: M \to N$ be the projection.  For each $v \in \cV$, note that $\ker(\pi \circ \iota_v)$ is an ideal in $M_v$, hence a direct summand.  Let $N_v$ be the complementary direct summand in $M_v$, and let $\pi_v: M_v \to N_v$ be the projection.  Let $1_N$ and $1_{N_v}$ denote the internal units of $N$ and $N_v$ respectively, which are central projections in $M$ and $M_v$ respectively.
	\end{notation}

        \begin{lemma}
        With the setup of Notation \ref{nota: general f d summand}, $\pi|_{N_v}$ is unital and injective and $N_v$ is atomic, i.e.\ a direct sum of type I factors.
        \end{lemma}

        \begin{proof}
        By construction, $M_v \cong N_v \oplus \ker(\pi|_{M_v})$ and so $N_v \cap \ker(\pi) = 0$, or $\pi|_{N_v}$ is injective.  Also, $1 - 1_{N_v} \in \ker(\pi|_{M_v})$, so $\pi$ is unital.

        To show that $N_v$ is atomic, we construct something like a conditional expectation from $N$ onto $N_v$.  By \cite[Remark 2.24]{CaFi2017}, there is a faithful normal state-preserving conditional expectation $E_{M_v}: M \to M_v$.  Note that $y = E_{M_v}[1_N] \in Z(M_v)$ because $1_N \in Z(M)$. Observe that for $x \in N_v$,
        \[
        E_{M_v}[\pi(x)] = E_{M_v}[x 1_N] = x E_{M_v}[1_N] = xy.
        \]
        In particular, $(1 - 1_N) y = 0$, so $y \leq 1_{N_v}$; equivalently, $y \in N_v$ because $N_v$ is an ideal in $M_v$.  On the other hand, letting $p$ be the kernel projection of $y$ as an element of $N_v$, then $E_{M_v}[\pi(p)] = py = 0$; by faithfulness of $E_{M_v}$ and injectivity of $\pi|_{N_v}$, we have $p = 0$.  Hence, the support projection of $y$ is equal to $1_{N_v}$.

        Using the spectral decomposition of $y$, there are positive elements $z_k \in Z(N_v)$ such that $p_k = z_ky$ is a projection with $p_{k+1} \geq p_k$ and $z_k y \to 1_{N_v}$ in SOT.
        Since $p_k$ commutes with $1_N$, then $p_k N p_k = (p_k \wedge 1_N) N (p_k \wedge 1_N)$ is a corner of $N$, and hence is also a type I factor.
        The map $\iota_k = \pi|_{p_k N_v}$ gives a normal unital $*$-homomorphism $p_k N_v \to p_k N p_k$, and the map $\varepsilon_k: p_k N p_k \to p_k N_v$ given by $\varepsilon_k(x) = z_k E_{M_v}(x)$ is a faithful, normal, completely positive map satisfying $\varepsilon_k \circ \iota_k = \id_{p_k N_v}$, and hence is a faithful normal conditional expectation from $p_k N p_k$ to $p_k N_v$.
        By \cite[IV.2.2.2]{Blackadar2006encyclopedia}, since there is a normal conditional expectation from the type I factor $p_k N p_k$ onto $p_k N_v$, we know $p_k N_v$ is atomic.
        Since $N_v = p_1 N_v \oplus \bigoplus_k (p_{k+1} - p_k) N_v$, we conclude that $N_v$ is atomic.
        \end{proof}

	\begin{lemma}
	With the setup of Notation \ref{nota: general f d summand}, suppose that $v$ and $v'$ are not adjacent.  Then either $N_v$ or $N_{v'}$ is $1$-dimensional.
	\end{lemma}

	\begin{proof}
        Suppose for contradiction that $N_v$ and $N_{v'}$ are both at least $2$-dimensional.  Then we can write $1_{N_v} = e_1 + e_2$ where $e_1$ and $e_2$ are projections in the centralizer of the state $\psi_v$.  Indeed, if $N_v$ has nontrivial center, $e_1$ and $e_2$ can be chosen to be central, and otherwise $N_v \cong B(H)$ and the state is given by a density operator, so choose $e_1$ and $e_2$ to be projections that commute with it.  Similarly, write $1_{N_{v'}} = f_1 + f_2$ where $f_1$ and $f_2$ are projections in the centralizer of $\psi_{v'}$.  Also let $e_0 = 1 - 1_{N_v}$ and $f_0 = 1 - 1_{N_{v'}}$.

        Let $A_v = \Span(e_0,e_1,e_2)$ and $A_{v'} = \Span(f_0,f_1,f_2)$, and let $A = A_v \vee A_{v'} \subseteq M$. Note that $A_v$ and $A_{v'}$ are freely independent, so by \cite[Theorem 2.3]{Dykema1993freedimension}, if $e_0$ and $f_0$ are not both zero, then
        \[
        A \cong A_v * A_{v'} \cong \gamma L(F_s) \oplus \bigoplus_{i,j} \gamma_{i,j} \C,
        \]
        where $s \in (1,\infty)$, and the weights $\gamma$ and $\gamma_{i,j}$ are given by $\gamma_{i,j} = \max(0,\varphi(e_i) + \varphi(f_j) - 1)$; by convention, when one of the coefficients is zero, the corresponding direct summand vanishes.  Moreover, $(i,j)$ summand is in the decomposition is exactly the span of $e_i \wedge f_j$.  Moreover, $(i,j)$ summand is in the decomposition is exactly the span of $e_i \wedge f_j$.  In case $e_0$ and $f_0$ are both zero, then we similarly have by \cite[Theorem 1.1]{Dykema1993freedimension} that
        \[
        A \cong A_v * A_{v'} \cong \gamma(\mathbb{M}_2 \otimes L^\infty[0,1]) \oplus \bigoplus_{i,j} \gamma_{i,j} \C.
        \]

        We claim that there is a state-preserving conditional expectation from $M$ onto $A$.  Indeed, since $A_v \subseteq M_v^{\varphi_v}$, there is a state-preserving conditional expectation from $M_v$ to $A_v$; similarly, from $M_{v'}$ to $A_{v'}$.  By taking the free product of these expectations by \cite{Boca1993}, there is a normal completely positive map $M_v * M_{v'} \to A_v * A_{v'}$ that restricts to the identity on $A_v * A_{v'}$, and in fact this is a state-preserving conditional expectation.  By composing with the conditional expectation from $M$ to $M_v * M_{v'}$, we obtain a state-preserving normal conditional expectation $E_A: M \to A$.

        Similarly to the previous proof, $E_A[\pi(x)] = E_A[1_N] x$ for $x \in A$.  Let $y = E_A[1_N] \in Z(A)$, and let $p$ be the support projection of $y$.  Then $x \in A$ is in $\ker(\pi)$ if and only if $xy = 0$, so that $\ker(\pi) \cap A = (1-p)A$.  Since $y \in Z(A)$, it must be some combination of $1_{L(F_s)}$ and $e_i \wedge f_j$ for $i, j = 0, 1, 2$.  Hence, there is a positive element $z$ with $zy = p$. The map $\iota = \pi|_{p A}$ gives a normal unital $*$-homomorphism $p A \to p N p$, and the map $\varepsilon: p N p \to p A$ given by $\varepsilon(x) = z E_{A}(x)$ satisfies $\varepsilon \circ \iota = \id_{pA}$, and therefore, $\iota$ is an injective $*$-homomorphism and $\varepsilon$ a faithful conditional expectation.  Since $pNp$ is a type I factor, \cite[Theorem IV.2.2.2]{Blackadar2006encyclopedia} shows that $p A$ is atomic.  Thus, $p \leq \sum_{i,j=0}^2 e_i \wedge f_j$.

        Now assume that $\max_i \varphi(e_i) \geq \max_j \varphi(f_j)$ by switching $v$ and $v'$ if necessary, and let $i$ be an index where $\varphi(e_i)$ is maximal.  Then for $i' \neq i$ and for $j \in \{0,1,2\}$, we have $\varphi(e_{i'}) + \varphi(f_j) - 1 \leq \varphi(e_{i'}) + \varphi(e_i) - 1 \leq 0$.  Therefore, $\gamma_{i',j} = 0$ whenever $i' \neq i$. Thus, $e_{i'} \leq 1 - p$, so $e_{i'} \in (1-p)A \subseteq \ker(\pi)$.  This implies that $e_{i'} \in \ker(\pi)$ for two distinct indices $i'$ in $\{0,1,2\}$, which contradicts the fact that $e_1$ and $e_2$ are in $N_v$ and hence not in the kernel of $\pi$.
	\end{proof}

	\begin{lemma}
		Assume the setup of Notation \ref{nota: general f d summand}.  Then
		\begin{enumerate}
			\item $\{v: \dim N_v > 1\}$ is a clique in $\cG$.
			\item The images $\pi(M_v)$ commute in $N$.
			\item Each $N_v$ is a factor.
		\end{enumerate}
	\end{lemma}

	\begin{proof}
		(1) is immediate from the previous lemma.

		(2) Let $\cK$ be the clique from (1).  For $v \in \cK$, the algebras $M_v$ commute since the vertices are adjacent.  Since $\pi$ is a $*$-homomorphism, the images $\pi(M_v)$ commute for $v \in \cK$.  For $v \not \in \cK$, then $\pi(M_v) = \pi(N_v)$ is $1$-dimensional, and so it equals $\C 1_N$, so $\pi(M_v)$ commutes with everything in $N$.

		(3) Suppose that $p$ is a central projection in $N_v$.  Then $\pi(p)$ is a central projection in $N$.  We assumed that $N$ is a factor, so $\pi(p) = 1_N$.  Since $\pi|_{N_v}$ is injective, $p = 1$.  Thus, $N_v$ is a factor.
	\end{proof}

        \begin{lemma} \label{lem: infinite-dimensional join decomposition}
        Suppose that $N_v$ is infinite-dimensional.  Then $v$ is adjacent to all other vertices $v'$ in $\cG$.
        \end{lemma}

        \begin{proof}
        Suppose for contradiction that $v$ is not adjacent to some $v'$.  By the previous lemma, $N_{v'}$ is $1$-dimensional.  Since we assume that $M_{v'} \neq \C$, we have $\varphi(1_{N_{v'}}) < 1$.  Recall $N_v \cong B(H)$ with $H$ infinite-dimensional, and since $N_v$ has a faithful normal state, $H$ must be separable.  So there is a sequence of minimal projections $(p_k)_{k \in \N}$ that add up to $1$.  We also have $\lim_{k \to \infty} \varphi(p_k) = 0$, so for sufficiently large $k$, $\varphi(p_k) + \varphi(1_{N_{v'}}) < 1$, which implies that $p_k \cap 1_{N_{v'}} = 0$ since they are freely independent.  Now $\pi(p_k) = p_k 1_N = p_k \pi(p_k)$ so that $\pi(p_k) \leq p_k$.  Moreover, $\pi(p_k) \leq 1_N = \pi(1_{N_{v'}}) \leq 1_{N_{v'}}$.  Thus, $\pi(p_k) \leq p_k \cap 1_{N_{v'}} = 0$.  So $p_k \in \ker(\pi)$ which contradicts that $\pi$ is injective on $N_v$.
        \end{proof}

        Letting $\cK' = \{v: \dim(N_v) = \infty\}$, we see that $\cK'$ is a clique and $\cG$ splits as a graph join of $\cK$ with the complementary graph $\cG'$, and consequently,
        \[
        (M,\psi) = \bigotimes_{v \in \cK'} (M_v,\psi_v) \otimes *_{v \in \cG'} (M_v,\psi_v).
        \]
        Thus, the classification of atomic summands for $(M,\psi)$ can be reduced to that of $*_{v \in \cG'} (M_v,\psi_v)$ (see the conclusion of the proof of Theorem \ref{thm: classification of B(H) summands} in \S \ref{subsec: conclusion of proof} for details).  So we now classify the summands for the case where the $N_v$'s are finite-dimensional.

	\begin{lemma} \label{lem: realization of all f d summands}
	Let $N$ be a type I factor summand of the graph product as in Notation \ref{nota: general f d summand}, and assume that $N_v$ is finite-dimensional for each $v$.  Then $N$ has the form given in Lemma \ref{lem: construction of f d summand and state}.
	\end{lemma}

	\begin{proof}
		Based on the previous lemma, $\cK = \{v: \dim N_v > 1\}$ is a clique, and $N_v \cong \mathbb{M}_{n(v)}$ for some $n(v) \in \N$.  Thus, assume that $N_v$ is given by matrix units as in Notation \ref{nota: fd summands in gp}, and recall $p_{\vec{\imath}} = \bigwedge_{v \in \cV} e_{i(v),i(v)}^{(v)}$.  Let $\tilde{N}$ be the finite-dimensional summand constructed in Lemma \ref{lem: construction of f d summand and state}.  We want to show that $N \subseteq \tilde{N}$.

		Since normal $*$-homomorphisms respect minima of projections, we have
		\[
		\pi(p_{\vec{\imath}}) = \bigwedge_{v \in \cV} \pi(e_{i(v),i(v)}^{(v)}) = \prod_{v \in \cV} \pi(e_{i(v),i(v)}^{(v)}) = \pi(e_{\vec{\imath},\vec{\imath}}^{(\cK)})
		\]
		where $e_{\vec{\imath},\vec{\jmath}}^{(\cK)}$ is as in Notation \ref{nota: fd summands in gp 2}.

		Note that for $x, y \in M$, we have $\pi(xy) = \pi(x) y = x \pi(y)$.  In particular, if $p$ is a projection, then $\pi(p) = \pi(p^2) = p \pi(p)$ and therefore $\pi(p) \leq p$.  Hence, $\pi(p_{\vec{\imath}}) \leq p_{\vec{\imath}}$.  We also have
		\[
		\pi(e_{\vec{\imath}, \vec{\jmath}}^{(\cK)} p_{\vec{\jmath}} e_{\vec{\jmath}, \vec{\imath}}^{(\cK)}) = e_{\vec{\imath}, \vec{\jmath}}^{(\cK)} \pi(p_{\vec{\jmath}}) e_{\vec{\jmath}, \vec{\imath}}^{(\cK)} = e_{\vec{\imath}, \vec{\jmath}}^{(\cK)} \pi(e_{\vec{\jmath},\vec{\jmath}}^{(\cK)}) e_{\vec{\jmath}, \vec{\imath}}^{(\cK)} = \pi(e_{\vec{\imath}, \vec{\jmath}}^{(\cK)} e_{\vec{\jmath},\vec{\jmath}}^{(\cK)}) e_{\vec{\jmath}, \vec{\imath}}^{(\cK)}) = \pi(e_{\vec{\imath}, \vec{\imath}}^{(\cK)}) = \pi(p_{\vec{\imath}}).
		\]
		Therefore,
		\[
		\pi(p_{\vec{\imath}}) \leq \pi(e_{\vec{\imath}, \vec{\jmath}}^{(\cK)} p_{\vec{\jmath}} e_{\vec{\jmath}, \vec{\imath}}^{(\cK)}) \leq e_{\vec{\imath}, \vec{\jmath}}^{(\cK)} p_{\vec{\jmath}} e_{\vec{\jmath}, \vec{\imath}}^{(\cK)}.
		\]
		Taking the intersection over $\vec{\jmath} \in [\vec n]$, we obtain
		\[
		\pi(e_{\vec{\imath},\vec{\imath}}^{(\cK)}) = \pi(p_{\vec{\imath}}) \leq \bigwedge_{\vec{\jmath} \in \prod_v [n(v)]} e_{\vec{\imath}, \vec{\jmath}}^{(\cK)} p_{\vec{\jmath}} e_{\vec{\jmath}, \vec{\imath}}^{(\cK)} =  q_{\vec{\imath}}.
		\]
		Therefore,
		\[
		1_N = \pi(1) = \sum_{\vec{\imath} \in \prod_v [n(v)]} \pi(e_{\vec{\imath},\vec{\imath}}^{(\cK)}) \leq \sum_{\vec{\imath} \in \prod_v [n(v)]} q_{\vec{\imath}} = 1_{\tilde{N}}.
		\]
		Since $N$ and $\tilde{N}$ are ideals, this implies that $N \subseteq \tilde{N}$.  Since $\tilde{N}$ is a factor, it is a minimal ideal in $M$, and therefore $N = \tilde{N}$ as desired.
	\end{proof}

	\section{Evaluation of the power series} \label{sec: power series}

	\subsection{Cartier and Foata's formula} \label{subsec: power series formula}

	In Lemma \ref{lem: Hilbert space computation of projections}, we showed that the projections $q_{\vec{i}}$ are nonzero if and only if
	\[
	\sum_{\ell \in \bN_0} \sum_{w \in \mathcal{W}_\ell} (s^{(w_1)} - 1) \dots (s^{(w_\ell)} - 1) < \infty.
	\]
	Our next goal is to give criteria for convergence of the power series
	\[
	f(X) = \sum_{\ell \geq 0} \sum_{w \in \mathcal{W}_\ell} X_{w_1} \dots X_{w_\ell}, \text{ where } X = (X_v)_{v \in \cV}.
	\]
	%In order to apply the formula of Cartier and Foata, we relate this to another power series
  We will accomplish this by relating it to the power series summing over all words up to $\cG$-equivalence:
	\[
  \tilde{f}(X) = \sum_{w \in \overline\cW} X_{w_1} \dots X_{w_\ell},
	\]
  where $\overline\cW$ is a set of representatives for the $\cG$-equivalence classes of words.
	%where the words are considered up to equivalence with respect to $\cG$, and $\ell$ is the length of the word.
  The relationship between these two as formal power series follows by a fairly standard combinatorial argument; see, e.g., \cite[esp. \S2.2]{GJ2004}.
  Notice that an arbitrary word can be expressed uniquely by beginning with a reduced word and replacing each letter by one or more copies of that same letter.
  Since $t_v/(1 - t_v) = \sum_{k \geq 1} t_v^k$, this decomposition gives us the identity
	\[
	\tilde{f}((X_v)_{v \in \cV}) = f\left( \left( \frac{X_v}{1 - X_v} \right)_{v \in \cV} \right).
	\]
	Furthermore, since $z / (1 + z)$ is the inverse function of $z / (1 - z)$ as a formal power series, the substitution can be reversed into
	\[
	f((X_v)_{v \in \cV}) = \tilde{f}\left( \left( \frac{X_v}{1 + X_v} \right)_{v \in \cV} \right).
	\]
	Cartier and Foata \cite[Eqn. (1)]{CF1969} give the very nice equation:
	\begin{equation} \label{eq: CF summation formula}
		\tilde{f}((X_v)_{v \in \cV}) = \left( \sum_{\cK \subseteq \cG \text{cliques}} (-1)^{|\cK|} \prod_{v \in \cK} X_v \right)^{-1}.
	\end{equation}
	In fact, this relation even holds for non-commutative power series:  If the indeterminates $X_v$ commute according to the graph $\cG$, then
	\[
	\fK_{\cG}(X) = \sum_{\cK \subseteq \cG \text{clique}} (-1)^{|\cK|} \prod_{v \in \cK} X_v
	\]
	is well defined since each term is a product of mutually commuting variables.
  Moreover, $\fK_{\cG}(X)^{-1}$ is the summation of words in the monoid generated by the $X_v$'s, which are identified up to $\cG$-equivalence.
  For example, if $\cG$ has vertex set $[n]$ and all variables commute or no variables commute, they recover the known identities
	\begin{align*}
		\paren*{(1-X_1)\cdots(1-X_n)}^{-1} &= \sum_{\alpha_1, \ldots, \alpha_n} X_1^{\alpha_1}\cdots X_n^{\alpha_n} \\
		\paren*{1 - X_1 - \cdots - X_n}^{-1} &= \sum_{r\geq 0}\sum_{i_1, \ldots, i_r} X_{i_1}\cdots X_{i_r}.
	\end{align*}

	\subsection{Conclusion of the proof of the main results} \label{subsec: conclusion of proof}

	The formal power series relation \eqref{eq: CF summation formula} enables us to give several equivalent criteria for convergence of the series $f(x_v/(1-x_v))$ for real inputs $x_v$ (usually in $[0,1]$).

	\begin{lemma} \label{lem: convergence criteria}
		Fix $\cG$, and let $f$, $\tilde{f}$, and $\fK_\cG$ be as above.  Let $(x_v)_{v \in \cV} \in [0,1]^{\cV}$.  Then the following are equivalent:
		\begin{enumerate}[(1)]
			\item $f((x_v/(1-x_v))_{v \in \cV}) < \infty$ (and in particular each $x_v < 1$);
			\item $\tilde{f}(x) < \infty$;
			\item $\fK_{\cG}(y) > 0$ for each $y \in \prod_{v \in \cV} \{0,x_v\}$;
			\item $\fK_{\cG}(y) > 0$ for each $y \in \prod_{v \in \cV} [0,x_v]$;
			\item $\fK_{\cG}(\alpha x) > 0$ for $\alpha \in [0,1]$.
		\end{enumerate}
	\end{lemma}

	\begin{proof}
		(1) $\iff$ (2).
    As mentioned above, viewing $f$ and $\tilde f$ as formal power series we have
		\[
		f((X_v/(1-X_v))_{v \in \cV}) = \tilde{f}(X).
		\]
		%where we expand $x_v / (1 - x_v) = \sum_{k \geq 1} x_v^k$.
    If we expand either sum, all the coefficients are non-negative, as are all the inputs $x_v$,
    %Since $x_v \in [0,1]$, all these terms are nonnegative,
    and hence $f((x_v/(1-x_v))_{v\in \cV}) < \infty$ if and only if $\tilde{f}(x) < \infty$.

		(2) $\implies$ (3).  Suppose $f(x) < \infty$. By direct comparison the series for $\tilde{f}$ converges absolutely at a complex tuple $z = (z_v)_{v \in \cV}$ if $|z_v| \leq x_v$, and so it defines a continuous function on this region that is analytic in the interior. Note that $1 / \fK_\cG(z)$ is also an analytic function in a neighborhood of the origin.  Since $1 / \fK_{\cG}$ agrees with $\tilde{f}$ as a formal power series, we have $\fK_{\cG}(z) f(z) = 1$ in a neighborhood of zero, hence this holds when $|z_v| < x_v$ by the identity theorem and when $|z_v| \leq x_v$ by continuity.  In particular, if $y_v \in \{0,x_v\}$, then $f(y) > 0$ and $\fK_{\cG}(y) f(y) = 1$, and so $\fK_{\cG}(y) > 0$.

		(3) $\implies$ (4).  Note that the terms in $\fK_\cG$ do not repeat the same variable twice, and so $\fK_\cG$ is an affine function of each variable individually.  Therefore, if $y$ and $y' \in [0,1]^{\cV}$ agree on $|\cV| - 1$ coordinates, and $\fK_{\cG}(y) > 0$ and $\fK_{\cG}(y') > 0$, then $\fK_{\cG}((1-\lambda)y + \lambda y') > 0$ for $\lambda \in [0,1]$.  Therefore, if we know that $\fK_\cG > 0$ on the corners of the rectangle $\prod_{v \in \cV} [0,t_v]$, then $\fK_\cG > 0$ on the entire rectangle.

		(4) $\implies$ (5).  The line segment from $0$ to $x$ is contained in the rectangle $\prod_{v \in \cV} [0,x_v]$.

		(5) $\implies$ (2).  We proceed by contrapositive.  Assume that $\tilde{f}(x) = +\infty$ and we will show that $\fK_\cG(\alpha x) = 0$ for some $\alpha \in [0,1]$.  Consider the single-variable power series in $\alpha$ given by
		\[
		h(\alpha) = \tilde{f}(\alpha x) = \sum_{\ell=0}^\infty \left( \sum_{w \in W_\ell} x_{w(1)} \dots x_{w(\ell)} \right) \alpha^\ell.
		\]
		Note that $h(\alpha)$ is an increasing lower semicontinuous function $[0,1] \to [0,\infty]$ since it is the supremum of the partial sums which are increasing and continuous.  Thus, if $h(1) = \tilde{f}(x) =\infty$, then there is a unique $r$ such that $h(\alpha) < \infty$ for $\alpha < r$ and $h(r) = \infty$, and we have $\lim_{\alpha \to r^-} h(r) = +\infty$.  Note also that $h(z)$ defines an analytic function on $|\alpha| < r$, and we have $\fK_{\cG}(z x) \tilde{f}(z x) = 1$ for $z$ in a neighborhood of zero and hence for all $|z| < r$.  Hence,
		\[
		\fK_{\cG}(r x) = \lim_{\alpha \to r^-} \fK_{\cG}(\alpha x) = \lim_{\alpha \to r^-} \frac{1}{\tilde{f}(\alpha x)} = 0
		\]
		since $\lim_{\alpha \to r^-} f(\alpha x) = +\infty$.  Therefore, $\fK_{\cG}(r x) = 0$ showing the negation of (5).
	\end{proof}

	\begin{proof}[Proof of Theorem \ref{thm: classification of finite-dimensional summands}]
		Consider the same setup as Notations \ref{nota: fd summands in gp} and \ref{nota: fd summands in gp 2}.  In Lemma \ref{lem: Hilbert space computation of projections}, we showed that the projections $q_{\vec{\imath}}$ are nonzero if and only if
		\[
		f((s^{(v)} - 1)_{v \in \cV}) < \infty, \text{ where } s^{(v)} = \sum_{j=1}^{n(v)} \frac{1}{t_j^{(v)}} = \sum_{j=1}^{n(v)} \frac{1}{\alpha^{(v)} \lambda_j^{(v)}}.
		\]
		Let
		\[
		x_v = \frac{s^{(v)} - 1}{(s^{(v)} - 1) + 1} = \frac{s^{(v)} - 1}{s^{(v)}} = 1 - 1/s^{(v)},
		\]
		so that
		\[
		s^{(v)} - 1 = \frac{t_v}{1-t_v}.
		\]
		Therefore, by Lemma \ref{lem: convergence criteria},
		\[
		f((s^{(v)} - 1)_{v \in \cV}) = f\left( \left(\frac{x_v}{1-x_v} \right)_{v \in \cV} \right) < \infty \iff \fK_{\cG}(y) > 0 \text{ for each } y \in \prod_{v \in \cV} \{0,x_v\}.
		\]
		Recall in Theorem \ref{thm: classification of finite-dimensional summands}, we defined
		\[
		\fK_{\cG'}(\vec{t}) = \sum_{\substack{\cK \subseteq \cG' \\ \text{clique}}} (-1)^{|\cK|} \prod_{v \in \cK} x_v.
		\]
		This is exactly the expression obtained by substituting $t_v$ for the variables with $v \in \cV'$ and $0$ for the variables with $v \not \in \cV'$.  Hence, $q_{\vec{\imath}} \neq 0$ if and only if $\fK_{\cG'}((1 - 1/s^{(v)})_{v \in \cV}) > 0$ for all induced subgraphs $\cG' \subseteq \cG$.

		By Lemma \ref{lem: Hilbert space computation of projections} again, when $q_{\vec{\imath}}$ is nonzero, we have
		\begin{align*}
			\varphi(q_{\vec{\imath}}) &= \prod_{v \in \cV} t_{i(v)}^{(v)} \prod_{v \in \cV} s^{(v)}  \left( \sum_{\ell \geq 0} \sum_{w \in \mathcal{W}_\ell}(s^{(w_1)}-1) \dots (s^{(w_\ell)} - 1) \right)^{-1} \\
			&= \prod_{v \in \cV} t_{i(v)}^{(v)} \prod_{v \in \cV} s^{(v)} \fK_{\cG}((1 - 1/s^{(v)})_{v \in \cV}) \\
			&= \prod_{v \in \cV} t_{i(v)}^{(v)} \prod_{v \in \cV} s^{(v)} \sum_{\substack{\cK \subseteq \cG \\ \text{clique}}} (-1)^{|\cK|}(1 - 1/s^{(v)}) \\
			&= \prod_{v \in \cV} t_{i(v)}^{(v)} \sum_{\substack{\cK \subseteq \cG \\ \text{clique}}} \prod_{v \in \cV  \setminus \cK} s^{(v)} \prod_{v \in \cK} (1 - s^{(v)})
		\end{align*}
		Now recall that the projections $q_{\vec{\imath}}$ sum up to the unit $1_N$ in the direct summand $(N,\psi)$.  Moreover,
		\[
		\sum_{\vec{\imath} \in [\vec n]} t_{i(v)}^{(v)} = \sum_{\vec{\imath} \in [\vec n]} \alpha_v \lambda_{i(v)}^{(v)} = \prod_{v \in \cV } \alpha^{(v)}.
		\]
		Hence, by summing up our formula for $\varphi(q_{\vec{\imath}})$, we obtain
		\[
		\alpha = \varphi(1_N) = \sum_{\vec{\imath} \in [\vec n]} \varphi(q_{\vec{\imath}}) = \prod_{v \in \cV} \alpha^{(v)} \sum_{\substack{\cK \subseteq \cV \\ \text{cliques}}} \prod_{v \in \cV \setminus \cK} s^{(v)} \prod_{v \in \cK} (1 - s^{(v)}),
		\]
		which is the formula asserted in Theorem \ref{thm: classification of finite-dimensional summands}.  Finally, Lemma \ref{lem: realization of all f d summands} shows that all the finite-dimensional summands of the graph product must arise from the construction of Lemma \ref{lem: construction of f d summand and state}, as asserted in Theorem \ref{thm: classification of finite-dimensional summands}.
	\end{proof}

        \begin{proof}[Proof of Theorem \ref{thm: classification of B(H) summands}]
        Let $(N,\psi)$ be direct summand in the graph product which is isomorphic to $B(H)$ for $H$ infinite-dimensional.  Using Notation \ref{nota: general f d summand}, let $\cV_1$ be the set of vertices where $(N_v,\psi_v)$ is infinite-dimensional. By Lemma \ref{lem: infinite-dimensional join decomposition}, the vertices in $\cV_1$ are adjacent to all vertices in $\cG$, and so $\cG_1$ is complete and $\cG$ decomposes as a graph join $\cG_1 + \cG_2$.  Consequently,
        \[
        (M,\varphi) = \bigotimes_{v \in \cV_1} (M_v,\varphi_v) \otimes *_{v \in \cG_2} (M_v,\varphi_v).
        \]
        By distributing tensor products over direct sums, it is easy to see that any type I factor direct summand in $(M,\varphi)$ must be the tensor product of type I factor direct summands in each $(M_v,\varphi_v)$ for $v \in \cV_1$ and a type I factor direct summand in the graph product over $\cG_2$.  By Lemma \ref{lem: realization of all f d summands}, the type I factor summands in the graph product over $\cG_2$ are all finite-dimensional and classified by Theorem \ref{thm: classification of finite-dimensional summands}.
        \end{proof}

	\begin{proof}[Proof of Theorem \ref{thm: intersection of projections}]
		Let $(M,\varphi)$ be the graph product of $(M_v,\varphi_v)$ for $v \in \cV$.  Let $p_v$ be a projection in $M_v$.  Recall that $\bigwedge_{v \in \cV} p_v \in \mathrm{W}^*((p_v)_{v \in \cV})$, and so whether $\bigwedge_{v \in \cV}$ is nonzero only depends on the behavior of $\mathrm{W}^*((p_v)_{v \in \cV})$ and the state restricted to this von Neumann algebra.  Therefore, it suffices to prove Theorem \ref{thm: intersection of projections} in the case where $M_v = \C p_v \oplus \C(1 - p_v)$.  We are thus in the situation of Notations \ref{nota: fd summands in gp} and \ref{nota: fd summands in gp 2} with $N_v = \C p_v$ and $n(v) = 1$ for all $v$.  Hence, in this case, $\alpha^{(v)} = \varphi_v(p_v)$ and $\lambda_1^{(v)} = 1$ and so $t_1^{(v)} = \alpha^{(v)}$ and $s^{(v)} = 1 / \varphi_v(p_v)$.  Hence, by Lemma \ref{lem: Hilbert space computation of projections} and Lemma \ref{lem: convergence criteria}, as in the previous proof, we have
		\[
		\bigwedge_{v \in \cV } p_v \neq 0 \iff \forall \cG' \subseteq \cG, \fK_{\cG'}((1 - 1/s^{(v)})_{v \in \cV}) = \fK_{\cG'}((1 - \varphi_v(p_v))_{v \in \cV}) > 0.
		\]
		Moreover, in this case, we have
		\[
		\varphi \left( \bigwedge_{v \in \cV } p_v \right) = \fK_{\cG}((1 - \varphi_v(p_v))_{v \in \cV})
		\]
		as asserted in Theorem \ref{thm: intersection of projections}.
	\end{proof}

	\subsection{Geometry of the region of convergence} \label{subsec: region}

	In light of Theorem \ref{thm: intersection of projections} and Theorem \ref{thm: classification of finite-dimensional summands}, to determine whether a graph product has atoms, one must test positivity of polynomials $\fK_{\cG}(x)$ where $x_v = 1 - 1/s^{(v)}$.    Hence, to understand how the atoms behave as the parameters $\alpha^{(v)}$ and $\lambda_j^{(v)}$ vary, one needs to understand the region in $[0,1]^{\cV}$ where the polynomials $\fK_{\cG'}(x)$ are positive for all induced subgraphs $\cG' \subseteq \cG$.  We denote this region by
	\begin{equation} \label{eq: region of G}
		R(\cG) := \{x \in [0,1]^{\cV}: \fK_{\cG'}(x|_{\cG'}) > 0 \text{ for induced } \cG' \subseteq \cG \}.
	\end{equation}
	In this section, we will show that $R(\cG)$ is the connected component of $[0,1]^{\cV} \cap \{\fK_{\cG} > 0\}$ containing $0$, and in many cases the boundary in the positive orthant is smooth.  We start by computing the derivatives of $\fK_{\cG}$ in hopes of applying the implicit function theorem.

	\begin{lemma} \label{lem: derivative computation}
		Let $\cG$ be a graph and let $x = (x_v)_{v \in \cV} \in \C^{\cV}$.  For each vertex $j$, let $\mathcal{S}(j)$ be the induced subgraph with vertex set $\{j: (i,j) \in \cE  \}$.  Then
		\[
		\partial_j \fK_{\cG}(x) = -\fK_{\mathcal{S}(j)}(x|_{\mathcal{S}(j)}), \text{ where } x|_{\mathcal{S}(j)} = (x_v)_{v \in \mathcal{S}(j)}.
		\]
	\end{lemma}

	\begin{proof}
		Recall $\fK_{\cG}(x)$ has one term $(-1)^{|\cK|} \prod_{v \in \cK} x_v$ for each clique $\cK$.  If $\cK$ does not contain vertex $j$, then the derivative with respect to $x_j$ is zero.  If $\cK$ does contain $j$, then by definition every vertex $v$ in $\cK$ must be in $\mathcal{S}(j)$, and so $\cK = \cK' \cup \{j\}$, where $\cK'$ is a clique in $\mathcal{S}(j)$.  Differentiating with respect to $x_j$ then produces $-(-1)^{|\cK'|} \prod_{v \in \cK'} x_v$, which yields exactly all the terms in $\fK_{\mathcal{S}(j)}(x|_{\mathcal{S}(j)})$.
	\end{proof}

	We can now determine the topological behavior of $R(\cG)$.

	\begin{lemma} \label{lem: homeomorphism}
		For a unit vector $u$ in the nonnegative orthant of $\R^{\cV}$, let
		\[
		\rho(u) = \inf \{r \in [0,\infty): \min_{\cG' \subseteq \cG} \fK_{\cG'}(ru) = 0\},
		\]
		where the minimum is taken over all induced subgraphs $\cG'$.  Then
		\begin{enumerate}
			\item $\rho(u) = \min \{r \in [0,\infty): \fK_{\cG}(ru|_{\cG'}) = 0 \}$.
			\item If $x \in [0,1]^{\cV} \setminus \set 0$, then $x \in R(\cG)$ if and only if $|x| < \rho(x / |x|)$.
			\item The mapping $u \mapsto \rho(u)$ is continuous.
			\item There is a homeomorphism
			\[
			\{y \in [0,1]^{\cV}: |y| < 1 \} \to R(\cG): y \mapsto \rho(y/|y|) y,
			\]
			where the right-hand side is interpreted as $0$ when $y = 0$.
		\end{enumerate}
	\end{lemma}

	\begin{proof}
		(1) Let $\widehat{\rho}(u) = \inf \{r \in [0,\infty): \fK_{\cG}(ru) = 0 \}$.  By construction, $\rho(u) \leq \widehat{\rho}(u)$.  On the other hand, for $r < \widehat{\rho}(u)$, we have $\fK_{\cG}(ru) > 0$, and therefore by Lemma \ref{lem: convergence criteria} (5) $\implies$ (4), we have $\fK_{\cG}(ru) > 0$ for $r < \widehat{\rho}(u)$, and therefore $\rho(u) \geq \widehat{\rho}(u)$.

		It remains to show that infimum is actually a minimum.  Looking at subgraphs with only one vertex, we see that if the $v$th coordinate of $ru$ is equal to $1$, then $\fK_{\set v}(ru_v) = 1 - ru_v = 0$.  Thus, $\rho(u)u$ must be in $[0,1]^{\cV}$ and in particular $\rho(u) \leq \sqrt{n}$.  Thus, $\{r \geq 0: \fK_{\cG}(ru) = 0\}$ is a nonempty compact set and so the infimum is achieved.

		(2) This follows from part (1) of this lemma together with Lemma \ref{lem: convergence criteria} (4) $\iff$ (5).

		(3) First, we show $\rho$ is lower semi-continuous, or in other words for each $r^* > 0$ the set $\{u: \rho(u) > r^* \}$ is open.  Let $u^*$ be in this set.  Then for each $I$, the function $\gamma(r,u) = \min_{\cG'} \fK_{\cG'}(ru)$ is strictly positive on $[0,r^*] \times \{u^*\}$.  By uniform continuity of $\gamma$ on compact sets, there is neighborhood of $O$ of $u^*$ such that $\gamma > 0$ on $[0,r^*] \times O$.  Then for $u \in O$, we have $\rho(u) > r^*$, as desired.

		Now we need to show that $\{u: \rho(u) < r^*\}$ is open for each $r^*$. Fix $u^*$ in this set.  Then $\fK_{\cG'}(\rho(u^*)u^*) = 0$ for some induced subgraph $\cG' \subseteq \cG$.  Choose such a $\cG'$ which is minimal, and consider differentiating $\fK_{\cG'}$ with respect to $r$.  By the chain rule,
		\[
		\frac{d}{dr} \Bigr|_{r = \rho(u^*)} \fK_{\cG'}(r u^*|_{\cG'}) = \sum_{j \in \cV'} u_j^* [\partial_j \fK_{\cG'}](\rho(u^*)u^*|_{\cG'}).
		\]
		For $j \in \cV'$, Lemma \ref{lem: derivative computation} shows that
		\[
		\partial_j \fK_{\cG'}(x|_{\cG'}) = -\fK_{\cG' \cap \cS(j)}(x|_{\cG' \cap \cS(j)}),
		\]
		which is nonzero at $\rho(u^*) u^*$ by minimality of $\cG'$ (here note that $\cG' \cap \cS(j)$ does not contain $j$).  It is in fact strictly negative; indeed, since $\rho(u^*) u^*$ is in the closure of $R(\cG)$, the term $\fK_{\cG' \cap \cS(j)}(\rho(u^*) u^*|_{\cG'\cap \cS(j)})$ cannot be negative.  We finally note that $u^*$ must have some nonzero coordinate in $\cV'$ since otherwise $\fK_{\cG'}(\rho(u^*)u^*|_{\cG'})$ would equal $1$.  Therefore, overall
		\[
		\frac{d}{dr} \Bigr|_{r = \rho(u^*)} \fK_{\cG'}(r u^*) = -\sum_{j \in \cV'} u_j^* \fK_{\cG' \cap \cS(j)}(\rho(u^*)u^*) < 0,
		\]
		since we have a sum of nonpositive terms at least one of which is strictly negative.  Therefore, by the implicit function theorem, there exists a neighborhood $O$ of $u^*$ in the unit sphere and a smooth function $\widehat{\rho}: O \to (0,\infty)$ such that
		\[
		\fK_{\cG'}(\widehat{\rho}(u) u|_{\cG'}) = 0.
		\]
		For $u \in [0,\infty)^{\cV} \cap O$, we have $\rho(u) \leq \widehat{\rho}(u)$ by definition of $\rho$, and hence
		\[
		\{u: \rho(u) < r_0\} \supseteq \{u \in O \cap [0,\infty)^{\cV}: \widehat{\rho}(u) < r^* \},
		\]
		which proves the desired openness.

		(4) This follows readily from (2) and (3) by basic topology.
	\end{proof}


	\begin{proposition} \label{prop: component}
		The region $R(\cG)$ is the connected component of $\{x \in [0,1]^{\cV}: \fK_{\cG}(x) > 0 \}$ containing $0$.
	\end{proposition}

	\begin{proof}
		Let $O = \{x \in [0,1]: \fK_{\cG} > 0\}$.  Then $R(\cG) \subseteq O$ by definition.  Lemma \ref{lem: homeomorphism} (4) implies that $R(\cG)$ is connected, and so $R(\cG)$ is contained in the connected component of $O$ that contains $0$.

		Conversely, consider the open sets
		\[
		U = \{x \in [0,1]^{\cV}: x \neq 0, |x| < \rho(x/|x|) \}, \qquad \cV = \{x \in [0,1]^{\cV}: x \neq 0, |x| > \rho(x/|x|) \}.
		\]
		By Lemma \ref{lem: homeomorphism} (3), $U$ and $V$ are disjoint open sets.  By Lemma \ref{lem: homeomorphism} (1), if $|x| = \rho(x/|x|)$, then $\fK_{\cG}(x) = 0$.  Therefore, $O \setminus \set 0 \subseteq U \cup V$.  Also, $U$ contains a punctured neighborhood of the origin since $\fK_{\cG}(0) = 1 > 0$.  Hence, the connected component of $0$ in $O$ is contained in $U \cup \set 0$.  By Lemma \ref{lem: homeomorphism} (2), $U = R(\cG) \setminus \set 0$.
	\end{proof}

	Next, we consider whether the boundary of $R(\cG)$ is smooth.  For this, we need to analyze more carefully when the derivatives of $\fK_{\cG}$ can vanish.


	\begin{lemma} \label{lem:joincomponent}
		Let $\cG$ be a graph and $x \in (0,\infty)^{\cV}$ with
		\[
		\min_{\cG' \subseteq \cG} \fK_{\cG'}(x) = 0,
		\]
		where $\cG'$ runs over all induced subgraphs of $\cG$.  Let $\cG_0 = (\cV_0,\cE_0)$ be a minimal induced subgraph of $\cG$ such that $\fK_{\cG_0}(x) = 0$.  Then $\cG$ decomposes as a graph join of $\cG_0$ with the complementary subgraph $\cG_1 = (\cV_1,\cE_1)$.
	\end{lemma}

	\begin{proof}
		It suffices to show that every vertex $w \in \cG_1$ is adjacent to every vertex in $\cG_0$.  Let $w \in \cV_1$, and write $\cG_w$ for the subgraph induced by $\cV_0 \cup \set w$.  Observe that
		\[
		\fK_{\cG_w}(x|_{\cG_w}) = \fK_{\cG_0}(x|_{\cG_0}) - x_w \fK_{\cS(w)}(x|_{\cS(w) \cap \cG_0});
		\]
		indeed, every clique $\cK$ in $\cG_w$ either (a) does not contain $w$ and hence appears in $\fK_{\cG_0}(x|_{\cG_0})$ or (b) contains $w$ and so is $\cK' \cup \set w$ for some clique in $\cS(w) \cap \cG_0$ and hence appears in $- x_w \fK_{\cS(w)}(x|_{\cS(w)})$ (as in Lemma \ref{lem: derivative computation}).  By assumption,
		\[
		\fK_{\cG_w}(x|_{\cG_w}) \geq 0, \qquad \fK_{\cG_0}(x|_{\cG_0}) = 0, \qquad -x_w \fK_{\cS(w) \cap \cG_0}(x|_{\cS(w) \cap \cG_0}) \leq 0.
		\]
		Therefore, the above equality forces that
		\[
		\fK_{\cG_w}(x|_{\cG_w}) = 0 = x_w \fK_{\cS(w)}(x|_{\cS(w) \cap \cG_0}).
		\]
		Since $x_w > 0$, we have $\fK_{\cS(w) \cap \cG_0}(x|_{\cS(w) \cap \cG_0}) = 0$.  By minimality of $\cG_0$, we have $\cS(w) \cap \cG_0 = \cG_0$, or $\cG_0 \subseteq \cS(w)$ which means that $w$ is adjacent to every vertex in $\cG_0$ as desired.
	\end{proof}

	\begin{proposition} \label{prop: irreducible smoothness}
		Let $\cG$ be a graph which is join-irreducible.  Then the derivatives of $\fK_{\cG}$ are nonvanishing on $\partial R(\cG) \cap (0,\infty)^{\cV}$, and hence this is a smooth submanifold of $(0,\infty)^{\cV}$.
	\end{proposition}

	\begin{proof}
		Let $x \in \partial R(\cG) \cap (0,\infty)^{\cV}$.  In light of Lemma \ref{lem: homeomorphism}, we must have $\fK_{\cG}(x) = 0$.  If $\cG_0$ is a minimal subgraph where $\fK_{\cG_0}$ vanishes, then $\cG$ decomposes as a join of $\cG_0$ and its complement, which forces $\cG_0 = \cG$ since $\cG$ is irreducible.  Therefore, $\fK_{\cG'}$ is non-vanishing for any strictly smaller subgraph.  In particular, by Lemma \ref{lem: derivative computation}, the derivatives of $\fK_{\cG}$ are non-vanishing.  Hence, the implicit function theorem implies smoothness of $\partial R(\cG) \cap (0,\infty)^{\cV}$.
	\end{proof}

	In case $\cG$ is not join-irreducible, we can analyze the graph using the join decomposition.

	\begin{lemma} \label{lem: join decomposition}
		Let $\cG$ be a graph with a join decomposition $\cG = \cG_1 + \dots + \cG_k$.  Then
		\[
		\fK_{\cG}(x) = \prod_{j=1}^k \fK_{\cG_j}(x|_{\cG_j}),
		\]
		and
		\[
		R(\cG) = R(\cG_1) \times \dots \times R(\cG_k).
		\]
	\end{lemma}

	\begin{proof}
		If $\cK$ is a clique in $\cG$, then $\cK \cap \cV_j$ is a clique in $\cG_j$ for each $j$.  Conversely, if $\cK_j$ is a clique in $\cV_j$, then by construction of the graph join, $\cK = \cK_1 \cup \dots \cup \cK_k$ is a clique in $\cG$.  Moreover,
		\[
		(-1)^{|\cK|} \prod_{v \in \cK} x_v = \prod_{j=1}^k \left[(-1)^{|\cK_j|} \prod_{v \in \cK_j} x_v \right].
		\]
		Hence, the sum over all cliques in $\cG$ decomposes as the product of sums associated to each $\cG_j$ which yields the asserted identity for the polynomials.  The identity for the regions then follows from Lemma \ref{lem: homeomorphism} (2).
	\end{proof}

	From this we can see that $R(\cG) \cap (0,\infty)^{\cV}$ is the product of open sets with smooth boundary, and the only way that $\partial R(\cG)$ can be non-smooth at a point $x \in (0,\infty)^{\cV}$ is if there are two separate indices $i$ and $j$ such that $x|_{\cG_i}$ and $x|_{\cG_j}$ are both boundary points of $R(\cG_i)$ and $R(\cG_j)$ respectively.  Meanwhile, if some of the coordinates of $x$ are allowed to be zero, then more complicated behavior can occur.  Indeed, the behavior of the derivatives is determined by what happens on the subgraph where the values of $x$ are positive.

	\begin{lemma} \label{lem:irrelevantzero}
		Let $\cG$ be a graph and $x \in [0,\infty)^{\cV}$. 
		Let $\cG_+$ be the subgraph induced by vertices $v$ where $x_v > 0$.  Then $\fK_{\cG_+}(x|_{\cG_+}) = \fK_{\cG}(x) = 0$ and for any $j \in \cV$ we have $\partial_j \fK_{\cG_+}(x|_{\cG_+}) = \mathbf{1}_{j \in \cG_+} \partial_j \fK_{\cG}(x)$.
	\end{lemma}

	\begin{proof}
		For the first, claim, since $x_v = 0$ for $v$ not in $\cG_+$, all the terms from cliques that are not contained in $\cG_+$ vanish, leaving exactly the terms in $\fK_{\cG_+}(x|_{\cG_+})$.

		For the second claim, use Lemma \ref{lem: derivative computation} together with the first claim:
		\[
		\partial_j \fK_{\cG}(x) = -\fK_{\cS(j)}(x|_{\cS(j)}) = -\fK_{\cS(j) \cap \cG_+}(x|_{\cS(j) \cap \cG_+}) = \mathbf{1}_{j \in \cG_+} \partial_j \fK_{\cG_+}(x|_{\cG_+}).  \qedhere
		\]
	\end{proof}

	\begin{proposition}
		Let $\cG$ be a graph and $x \in [0, \infty)^{\cV} \cap \partial R(\cG)$.  (Here the boundary is considered relative to $[0,\infty)^{\cV}$ rather than $\R^{\cV}$).  Let $\cG_+$ be the subgraph induced by vertices $v$ where $x_v > 0$.  Then the following are equivalent:
		\begin{enumerate}[(1)]
			\item $\partial_j \fK_{\cG}(x) = 0$ for all $j$.
			\item $\cG_+$ decomposes as a graph join $\cG_+ = \cG_0 + \cG_1$ such that $\fK_{\cG_0}(x|_{\cG_0}) = \fK_{\cG_1}(x|_{\cG_1}) = 0$.
		\end{enumerate}
	\end{proposition}

	\begin{proof}
		By Lemma \ref{lem:irrelevantzero}, condition (1) for $\cG$ and for $\cG_+$ are equivalent.  So it suffices to prove the claim when $\cG = \cG_+$.

		(1) $\implies$ (2).  Let $\cG_0$ be a minimal subgraph such that $\fK_{\cG_0}(x|_{\cG_0}) = 0$.  Then by Lemma \ref{lem:joincomponent}, $\cG = \cG_0 + \cG_1$ where $\cG_1$ is the graph on the complementary vertex set.  By Lemma \ref{lem: join decomposition},
		\[
		\fK_{\cG}(x) = \fK_{\cG_0}(x|_{\cG_0}) \fK_{\cG_1}(x|_{\cG_1}),
		\]
		and so for $j \in \cV_0$,
		\[
		0 = \partial_j \fK_{\cG}(x) = \partial_j \fK_{\cG_0}(x|_{\cG_0}) \fK_{\cG_1}(x|_{\cG_1}).
		\]
		Now $\partial_j \fK_{\cG_0}(x) < 0$ by Lemma \ref{lem: derivative computation} and minimality of $\cG_0$.  Therefore, $\fK_{\cG_1}(x|_{\cG_1})$ must be zero.

		(2) $\implies$ (1).  Suppose $\cG = \cG_0 + \cG_1$, so that $\fK_{\cG}(x) = \fK_{\cG_0}(x|_{\cG_0}) \fK_{\cG_1}(x|_{\cG_1})$.	By hypothesis, both factors vanish at the given point $x$, and therefore all derivatives of the product vanish at $x$.
	\end{proof}

