\paragraph*{S3}
\label{SI:ResultsDetails}
{\bf Details of Computations in Results.}

\textbf{Computation of BOLD responses.}
Given the model's stimulus-evoked response $\phi(\mathbf{r}, t)$ to a impulse stimulus under a given structural connectivity, the BOLD response (BOLD signal observation of the stimulus-evoked response) is approximated by $z(\mathbf{r})$, the zero temporal frequency component of $\phi(\mathbf{r}, t)$:
\begin{equation}
    z(\mathbf{r}) = \mathcal{F}[\phi](\mathbf{r}, \omega = 0) = \int_0^\infty dt \ \phi(\mathbf{r}, t). \label{SI:eq:bold}
\end{equation}
Here, $\mathcal{F}$ is the Fourier transform as an operator on $\phi$ as a function of $t$ only.
$z(\mathbf{r})$ is computed numerically at each grid point $\mathbf{r}_{ij}$ by computing the matrix $Z = \left(z(\mathbf{r}_{ij})\right)_{ij}$. 
$Z$ is computed as the matrix series
\begin{equation}
    Z = \Delta t \,\sum_{n=1}^\infty \Phi[n] \,,
\end{equation}
where $\Phi[n] =\left(\phi_{ij}^n\right)_{ij}$.
To compute the above series, we iteratively compute the partial sum 
\begin{align*}
    Y[m] = \Delta t \,\sum_{n=0}^{m\cdot N_t}  \Phi[n] \text{ for } m = 1, 2, \ldots
\end{align*}
We stop the iteration when the cosine distance between the vectors  $\mathrm{vec}(Y[m]), \mathrm{vec}(Y[m-1])$, the vectorizations of the matrices $Y[m], Y[m-1]$, is less than the threshold $\mathrm{tol}=10^{-5}$. 
The last computed $Y[m]$ is taken as an approximate scalar multiple of $Z$, since the cosine distance between $\mathrm{vec}(Y[m])$ and $\mathrm{vec}(Z)$ is close to zero.
To compute $Z$ from $Y_m$, we use the fact that, by integrating both sides of \eqref{SI:eq:modeldetailed} over both space $\Omega$ and time $[0, \infty)$, one obtains
\begin{align*}
    (1-\nu_0) \left(\int_\Omega d^2\mathbf{r} \ z(\mathbf{r}) \right) &= \int_0^\infty dt \int_\Omega d^2 \mathbf{r} \ \delta(\mathbf{r} - \mathbf{r}_0) \delta(t - t_0) = 1 \\
    \implies \int_\Omega d^2\mathbf{r} \ z(\mathbf{r}) &= (1-\nu_0)^{-1}.
\end{align*}
Accordingly, $Z$ is computed by scalar mutliplying $Y[m]$ so that the sum of all elements in $Z$ is $(\Delta x)^{-2} (1 - \nu_0)^{-1}$.

\textbf{Computation of Cosine Dissimilarity Metrics.}
The cosine dissimilarity between the stimulus-evoked dynamics of the geometric model and any hybrid model containing additional FNPs, in response to the same impulse stimulus, is defined by
\begin{equation}
    C_\phi(t) = 1 - \frac{\int_\Omega d^2 \mathbf{r} \ \phi(\mathbf{r}, t) \phi_0(\mathbf{r}, t)}
    {\sqrt{\int_\Omega d^2 \mathbf{r} \left(\phi(\mathbf{r}, t)\right)^2} \sqrt{\int_\Omega d^2 \mathbf{r} \left(\phi_0(\mathbf{r}, t)\right)^2}}\,, \label{SI:eq:cosinedissimilarity}
\end{equation}
where $\phi_0$ and $\phi$ are the geometric model's and hybrid model's activity respectively.
Similarly, the cosine dissimilarity between the evoked BOLD response of the geometric model and any hybrid model containing additional FNPs, in response to the same impulse stimulus, is defined by
\begin{equation}
    C_z = 1 - \frac{\int_\Omega d^2 \mathbf{r} \ z(\mathbf{r}) z_0(\mathbf{r})}
    {\sqrt{\int_\Omega d^2 \mathbf{r} \left(z(\mathbf{r})\right)^2} \sqrt{\int_\Omega d^2 \mathbf{r} \left(z_0(\mathbf{r})\right)^2}}\,, \label{SI:eq:cosinedissimilaritybold}
\end{equation}
where $z_0$ and $z$ are the geometric model's and hybrid model's BOLD responses respectively.
$C_\phi(t)$ is used in our investigations to quantify the perturbation of an FNP, or a connectome of multiple FNPs on the model's stimulus-evoked dynamics over time, and $C_z$ quantifies the perturbation on the evoked BOLD response.
To compute $C_\phi(t_n)$, where $t_n=n\Delta t$ is a timestep in the simulation, we computed the cosine distance between the vectors $\mathrm{vec}(\Phi[n])$ and $\mathrm{vec}(\Phi_0[n])$, where $\Phi[n] = \left(\phi(\mathbf{r}_{ij}, t_n)\right)_{ij}, \Phi_0[n] = \left(\phi_0(\mathbf{r}_{ij}, t_n)\right)_{ij}$.
Similarly, $C_z$ is computed as the cosine distance between $\mathrm{vec}(Z)$ and $\mathrm{vec}(Z_0)$, where $Z = \left(z(\mathbf{r}_{ij})\right)_{ij}, Z_0 = \left(z_0(\mathbf{r}_{ij})\right)_{ij}$.


\textbf{Computation of Spatial Correlation Function.}
The spatial correlation function with reference point $\mathbf{p}$, denoted $\gamma_\mathbf{p}:\Omega\to[-1, 1]:\mathbf{r}\to \mathrm{corr}(\phi(\mathbf{p},t),\phi(\mathbf{r}, t))$, returns the Pearson correlation between the model's noise-driven activity at point $\mathbf{p}$ and any input point $\mathbf{r}$ on $\Omega$.
In our investigations, we numerically compute $\gamma_\mathbf{p}$ evaluated at all grid points $\mathbf{r}_{ij}$ by computing the matrix $\Gamma = \left(\gamma_\mathbf{p}(\mathbf{r}_{ij})\right)_{ij}$.
Each element of $\Gamma$ is computed as
\begin{align*}
    &\gamma_\mathbf{p}(\mathbf{r}_{ij}) = \lim_{m\to\infty} r_{ij}[m], \\
    &\qquad r_{ij}[m] = \frac{\frac{\sum_{n=1}^{m\cdot N_t}\phi_\mathbf{p}^n \phi_{ij}^n}{m \cdot N_t} - \frac{\sum_{n=1}^{m\cdot N_t}\phi_\mathbf{p}^n}{m \cdot N_t} \cdot \frac{\sum_{n=1}^{m\cdot N_t} \phi_{ij}^n}{m \cdot N_t}}{\sqrt{ \frac{\sum_{n=1}^{m\cdot N_t}\left(\phi_\mathbf{p}^n \right)^2}{m \cdot N_t} - \left( \frac{\sum_{n=1}^{m\cdot N_t}\phi_\mathbf{p}^n}{m \cdot N_t} \right)^2} \sqrt{ \frac{\sum_{n=1}^{m\cdot N_t}\left(\phi_{ij}^n \right)^2}{m \cdot N_t} - \left( \frac{\sum_{n=1}^{m\cdot N_t}\phi_{ij}^n}{m \cdot N_t} \right)^2 }},
\end{align*}
where $\phi_{\mathbf{p}}^n$ is the simulated time series $\phi(\mathbf{r}, t_n)$ at point $\mathbf{p} = (0.15,0.15)$.
For grid size $N_x = 200$ and domain length $L = 0.4$, $\phi_{\mathbf{p}}^n$ is the time series $\phi_{75,75}^n$. 
Iteratively with $m = 1,2,\ldots$, we compute the matrix $R[m] = (r_{ij}[m])_{ij}$.
We stop the iteration when the correlation between the vectors $\mathrm{vec}(R[m]), \mathrm{vec}(R[m-1])$ is less than the threshold $\mathrm{tol} = 10^{-7}$.
The last attained $R[m]$ is then taken as the numerical computation of $\Gamma$.

\textbf{Sampling of Connectomes with non-random properties}
Connectomes constrained by non-random properties (exponential distance rule, hub specificity and rich-club specificity) are sampled using a rejection-sampling algorithm.
The source and target point of each FNP is sampled uniformly and independently on $\Omega$, but is accepted only if the sampled source and target passes a acceptance-rejection test tailored to the non-random property under investigation; otherwise the source and target is sampled again.
Once the sampled source and target is accepted, the next FNP is sampled in a similar manner.
We emphasize, however, that each connectome we generate is constrained by one of the three non-random properties only.

\textbf{Acceptance-rejection Test for Exponential Distance Rule constraint. }
To sample an FNP with parameter $\lambda_e$, a source $\mathbf{r}_1$ and target $\mathbf{r}_2$ is first sampled uniformly from $\Omega$.
A value $u$ is then sampled from the $\mathrm{Uniform}[0,1]$ distribution.
$\mathbf{r}_1$ and $\mathbf{r}_2$ are accepted if $u<\exp(-100\lambda_e l)$, where $\lambda_e \in [0, 1]$ is the selected decay parameter, and $l$ is the Euclidean distance between the source and target (with periodic boundary conditions).
Otherwise, $\mathbf{r}_1$, $\mathbf{r}_2$ and $u$ are resampled.
In this way, the probability that a FNP exists with source $\mathbf{r}_1$ and target $\mathbf{r}_2$, for any two given points $\mathbf{r}_1$ and $\mathbf{r}_2$, is 
\begin{align}
\mathbb{P}\left(\text{FNP $\mathbf{r}_1 \to \mathbf{r}_2$} \ | \ \mathbf{r}_1, \mathbf{r}_2\right) = \exp \left( -100\lambda_e \| \mathbf{r}_1 - \mathbf{r}_2 \| \right). \label{SI:eq:edr}
\end{align}

\textbf{Acceptance-rejection Test for Hub Specificity constraint. }
To sample an FNP with parameter $\lambda_h$, a value $u$ is first sampled from the $\mathrm{Uniform}[0,1]$ distribution.
If $u < \lambda_h$, the source and target points of the FNP are repetitively sampled uniformly from $\Omega$ and accepted when the FNP is hub-connecting, i.e., the FNP connects a point inside any one hub with a point outside that hub.
Otherwise, if $u \geq \lambda_h$, the source and target points are sampled once and accepted. 
In this way, the probability that any given FNP is hub-connecting is 
\begin{align}
    \mathbb{P}\left(\text{FNP is hub-connecting}\right) = (1 - \lambda_h)p_h + \lambda_h, \label{SI:eq:hubspecificity}
\end{align}
where $p_h$ is the probability that a uniformly sampled FNP is hub-connecting.
As $\lambda_h$ increases from $0$ to $1$, $\mathbb{P}\left(\text{FNP is hub-connecting}\right)$ increases from $p_h$ to $1$.
Theoretically,
\begin{align*}
    p_h = 1-n\left(\frac{|\Omega_h|}{|\Omega|}\right)^2-\left(1 - n \frac{|\Omega_h|}{|\Omega|}\right)^2\,,
\end{align*}
where $|\Omega_h|$ is the area of each hub, $n$ is the number of hubs, and $|\Omega|$ is the area of $\Omega$.
For our investigations ($n = 4, |\Omega_h| = |\Omega|/34$), $p_h \approx 0.22$.
$u$ is then resampled for the next FNP.

\textbf{Acceptance-rejection Test for Rich-Club Specificity constraint. }
To sample an FNP with parameter $\lambda_r$, a value $u$ is first sampled from the $\mathrm{Uniform}[0,1]$ distribution.
If $u < \lambda_r$, the source and target points of the FNP are repetitively sampled uniformly from $\Omega$ and accepted when the FNP is a rich-club connection, i.e., it connects a point inside any one hub with a point inside another hub.
Otherwise, if $u \geq \lambda_r$, the source and target points are sampled once and accepted. 
In this way, the probability that any given FNP is hub-connecting is 
\begin{align}
    \mathbb{P}\left(\text{FNP is a rich-club connection}\right) = (1 - \lambda_r)p_r + \lambda_r, \label{SI:eq:richclubspecificity}
\end{align}
where $p_r$ is the probability that a uniformly sampled FNP is a rich-club connection.
As $\lambda_r$ increases from $0$ to $1$, $\mathbb{P}\left(\text{FNP is a rich-club connection}\right)$ increases from $p_r$ to $1$.
Theoretically,
\begin{align*}
    p_r = n(n-1)\left(\frac{|\Omega_h|}{|\Omega|}\right)^2\,,
\end{align*}
where $|\Omega_h|$ is the area of each hub, $n$ is the number of hubs, and $|\Omega|$ is the area of $\Omega$.
For our investigations ($n = 4, |\Omega_h| = |\Omega|/34$), $p_r\approx 0.01$.
$u$ is then resampled for the next FNP.


