        best_aligns = best_alignment(
            out_lprobs.transpose(0, 1), tgt_tokens, seq_lens, 
            target_lens, self.decoder.get_blank_idx(), 
            zero_infinity=True
        )

        # Generate oracle sequence
        best_aligns_pad = torch.tensor(
