            best_aligns_pad % 2 == 0, self.decoder.get_blank_idx()
        )

        # Compute dynamic masking ratio
        same_num = (pred_tokens == oracle_empty).sum(1)
        keep_prob = ((seq_lens - same_num) / seq_lens * peek_factor)
        keep_prob = keep_prob.unsqueeze(-1)

        # Generate curriculum learning mask
        keep_word_mask = (
            torch.rand(pred_tokens.shape, device=word_ins_out.device) 
            < keep_prob
        ).bool()
        glat_prev = oracle_empty.masked_fill(
            ~keep_word_mask, self.decoder.get_mask_idx()
