\section{Preliminaries}\label{sec 2}



In this section, we briefly review key properties of matroids and their associated varieties. For a more detailed exposition, we refer the reader to \cite{Oxley, gelfand1987combinatorial} and \cite{Fatemeh4, Fatemeh5}. Throughout this work, for positive integers $d$ and $n$, we use the notation $[d] = \{1, \ldots, d\}$ and $\textstyle \binom{[d]}{n}$ to denote the set of $n$-element subsets of $[d]$.





\subsection{Matroids}

We first present some preliminary results about matroids; see \cite{Oxley, piff1970vector} for more details.

\begin{definition}\label{def:matroidcircuit}\normalfont
A matroid can be defined from its {\em circuits}. In this formulation, $M$ consists of a ground set $[d]$, together with a collection $\Ccal$ of subsets of $[d]$, called
circuits, satisfying:

\begin{enumerate}[label=(\roman*)]
\item $\emptyset \not\in\Ccal$;
\item if $C_1,C_2 \in \Ccal$ and $C_1\subseteq C_2$, then $C_1=C_2$;
\item 
 if $C_{1}\neq C_{2} \in \Ccal$ then, for any $e\in C_1\cap C_2$, there exists $C_3\in\Ccal$ such that 
 \[
    C_3\; \subseteq \; \left(C_1\cup C_2\right) -\{e\}.
 \]
\end{enumerate}
The set of circuits of $M$ is denoted by $\Ccal(M)$, and $\Ccal_{i}(M)$ consists of those of size $i$.
\end{definition}


There are multiple equivalent ways to define a matroid, including descriptions in terms of independent sets, the rank function, or bases. We now introduce these concepts and refer to \cite{Oxley} for a comprehensive discussion on these equivalent definitions.


\begin{definition}\label{def:dependant}\normalfont
Let $M$ be a matroid on the ground set $[d]$ and $F$ be any subset of $[d]$.\vspace*{-.5em}

\hspace*{-1cm}\parbox{\linewidth}{
\begin{itemize}[label=$\blacktriangleright$]
\item A subset of $[d]$ that contains a circuit is called \emph{dependent}, otherwise it is \emph{independent}. The set of all dependent sets of $M$ is denoted by $\mathcal{D}(M)$.\vs

\item A {\em basis} is a maximal independent subset of $[d]$, with respect to the inclusion.\\ 
The set of all bases of $M$ is denoted by $\mathcal{B}(M)$, and they all have the same size.\vs


\item The {\em rank} of $F$, denoted $\rank(F)$, is the size of the largest independent set contained in $F$. The rank of the matroid, denoted $\rank(M)$, is the size of any basis.\vs

\item The {\em closure} $\closure{F}$ of $F$, is the set of all $x\in [d]$ such that 
    $\rank(F\cup \{x\})=\rank(F)$.
\item $F$ is called a {\em flat} if $F=\closure{F}$, and is a \emph{cyclic flat} if it is also a union of circuits.\vs

\item Let $x\in [d]$, if $\rank(\{x\})=0$ then $x$ is called a {\em loop}. Conversely, if $x$ is a {\em coloop} if it does not belong to any circuit of $M$. 
A subset $\{x,y\}\subset [d]$ is called a {\em double point} if $\rank(\{x,y\})=1$. Finally, a matroid without loops or double points is called {\em simple}.
\end{itemize}
}
\end{definition}


\begin{proposition}[\textup{\cite[Lemma~1.3.1]{Oxley}}]\label{prop:submodularity}
The rank function of a matroid is submodular, meaning that for any subsets $A$ and $B$ of the ground set, the following inequality holds:
\[\rank(A)+\rank(B)\geq \rank(A\cup B)+\rank(A\cap B).\]
\end{proposition}







We now review the concepts of {\em restriction}, {\em deletion}, {\em truncation}, and {\em erection}:

\begin{definition}
\normalfont \label{subm}
Let $M$ be a matroid of rank $n$ on the ground set $[d]$ and $S\subseteq [d]$. 

{
\begin{itemize}[label=$\blacktriangleright$]
\item The {\em restriction of $M$ to $S$} is the matroid 
 on $S$ whose rank function is given by

 \[
  \rank(A)=\rank_{M}(A) \text{\quad for any $A\subset S$},
\] 
where $\rank_{M}$ is the rank function on $M$. This matroid is called a {\em submatroid} of $M$ and is denoted by $M|S$, or simply $S$ when the context is clear.\vs
\item The {\em deletion} of $S$, denoted $M\setminus S$, corresponds to the restriction
$M|([d]\setminus S)$.\vs
\item The {\em truncation} of $M$ is the matroid of rank $n-1$, whose independent sets are those of $M$ with size at most $n-1$.\vs
\item A matroid $N$ is called an {\em erection} of $M$, if $M$ is the truncation of $N$. Among all erections of $M$ there exists a unique matroid with the fewest dependent sets, known as the \emph{free erection} of $M$. For further details, see \cite{crapo1970erecting}.
\end{itemize}
}
\end{definition}



\begin{definition}\normalfont\label{uniform 3}
The uniform matroid $U_{n, d}$ on the ground set $[d]$ of rank $n$ is  
the one whose independent sets are the subsets of size at most $n$. See Figure~\ref{figure uniform and fano} (Left).
\end{definition}

\begin{definition}
Let $M$ be a matroid on the ground set $[d]$. The {\em automorphism group} of $M$, denoted $\text{Aut}(M)$, is the subgroup of all permutations $\sigma\in \mathbb{S}_{d}$ that preserve dependent sets of $M$, meaning that $X\in \mathcal{D}(M)$ if and only if $\sigma(X)\in \mathcal{D}(M)$.
\end{definition}



\begin{definition}\normalfont\label{general}
Let $M$ be a matroid of rank $n$ on $[d]$, with elements, referred to as points. We define an equivalence relation on the circuits of $M$ of size less than $n+1$: 
\begin{equation}\label{equiv}C_{1}\sim C_{2} \Longleftrightarrow \closure{C_{1}}=\closure{C_{2}}.\end{equation}
We adopt the following terminology and notation.\vspace*{-.5em}

\hspace*{-1cm}\parbox{\linewidth}{
\begin{itemize}[label=$\blacktriangleright$] 
\item A {\em subspace} of $M$ is an equivalence class $l$. We say that $\rank(l)=k$ if $\rank(C)=k$ for any circuit $C\in l$. We denote by $\mathcal{L}_{M}$ the set of all subspaces of $M$.\vs
\item A point $p\in [d]$ is said to belong to the subspace $l$, if $p\in C$ for some circuit $C\in l$. For each $p\in [d]$, let $\mathcal{L}_{p}$ denote the set of all the subspaces of $M$ containing $p$. 
The {\em degree} of $p$, is defined as $\deg(p) = \size{\mathcal{L}_{p}}$. 
\end{itemize} 
}
\end{definition}


\begin{example}
Consider the quadrilateral set configuration $\text{QS}$ shown in Figure~\ref{fig:combined} (Left). This represents a rank-$3$ matroid on $[6]$, with the following circuits of size at most three: 
\[\Ccal = \{\{1,2,3\}, \{1,5,6\}, \{3,4,5\}, \{2,4,6\}\}.\]
The subspaces of $\text{QS}$ coincide with $\Ccal$, and each point has degree two.
\end{example}

