\end{lemma}


Let $\ABCD{i}$ for $i\in [4]$ denote the collections of matroids defined as in Subsection~\ref{abcd}. We will need the following lemma:

\begin{lemma}\label{prop}
Let $M$ be a simple matroid of rank four. Then
\[V_{\Ccal(M)}=V_{M}\bigcup_{N\in \minposet{\cup_{i=1}^{3}\ABCD{i}}}V_{\Ccal(N)}\bigcup_{N\rq \in \ABCD{4}}V_{N\rq}.\]
\end{lemma}


By applying Lemma~\ref{prop} to $M_{\textup{V\'{a}mos}}$, we obtain
\begin{equation}\label{union}
V_{\Ccal(M_{\textup{V\'{a}mos}})}=\bigcup_{N\in \minposet{\cup_{i=1}^{3}\mathcal{S}_{i}(M_{\text{V\'{a}mos}})}}V_{\Ccal(N)}\bigcup_{N\rq \in \mathcal{S}_{4}(M_{\text{V\'{a}mos}})}V_{N\rq},
\end{equation}
Note that in this expression we are using the non-realizability of $M_{\textup{V\'{a}mos}}$. 
Furthermore, by applying Algorithm~\ref{algo 2}, we deduce that all the minimal matroids in $\cup_{i=1}^{3}\mathcal{S}_{i}(M_{\text{V\'{a}mos}})$ are greater than or equal to some matroid from the set $\{B_{i},C_{i},D_{i},E_{i},F_{i}\}$. Using this, along with Equation~\eqref{union} and Lemma~\ref{lema red}, we obtain that
\begin{equation}\label{sec eq}
V_{\Ccal(M_{\textup{V\'{a}mos}})}=V_{A}\cup V_{U_{3,8}}\bigcup_{i=1}^{2}V_{C_{i}}\bigcup_{j=1}^{2}V_{D_{j}}\bigcup_{N \in \mathcal{S}_{4}(M_{\text{V\'{a}mos}})}V_{N}.
\end{equation}
Moreover, we have the following lemma:
\begin{lemma}\label{sec lem}
The matroid varieties $V_{N}$ for $N \in \mathcal{S}_{4}(M_{\textup{V\'{a}mos}})$ are redundant in~\eqref{sec eq}.
\end{lemma}

\begin{proposition}
The irreducible decomposition of the circuit variety of $M_{\textup{V\'{a}mos}}$ is 
\[V_{\Ccal(M_{\textup{V\'{a}mos}})}=V_{A}\cup V_{U_{3,8}}\bigcup_{i=1}^{2}V_{C_{i}}\bigcup_{j=1}^{2}V_{D_{j}}.\]
\end{proposition}

\begin{proof}
Using Lemma~\ref{sec lem}, Equation~\eqref{sec eq} directly leads to the above decomposition.
We know that $V_{A}$ is irreducible, as indicated in \textup{\cite[Table~5.1]{corey2023singular}}. Since all matroids in this decomposition, except for $A$, are inductively connected, Theorem~\ref{teo ir} implies that their associated varieties are all irreducible. Moreover, it is easy to verify the non-redundancy of this decomposition. Thus, we have the irreducible decomposition of $V_{M_{\textup{V\'{a}mos}}}$. 
\end{proof}

