\subsection{Training and inference algorithm pseudocode}
\label{Training and inference algorithm pseudocode}

We introduce the transition distribution~\cite{bond2023infty} in the forward process:
\begin{equation}
q(x_t \mid x_0) = \mathcal{N}\left(x_t; \sqrt{\bar{\alpha}_t} \,L x_0, (1 - \bar{\alpha}_t) L L^*\right),
\end{equation}
where \( L \) denotes the mollification operator and  constant coefficient \( \bar{\alpha}_t \in [0,1] \) controls the balance between signal preservation and noise injection. The corresponding posterior distribution can be derived analytically~\cite{song2020score, bond2023infty}:
\begin{equation}
q(x_{t-1} \mid x_t, x_0) = \mathcal{N}\left(x_{t-1}; \tilde{\mu}_t(x_t, x_0), \tilde{\beta}_t L L^*\right),
\end{equation}
where the mean and variance are given by
\begin{align}
\tilde{\mu}_t(x_t, x_0) 
&= \frac{1}{\sqrt{\alpha_{t}}} \left( x_{t} - \frac{1 - \alpha_{t}}{\sqrt{1 - \bar{\alpha}_{t}}} \xi \right), \quad \xi \sim \mathcal{N}(0, L L^*), \\
\tilde{\beta}_t 
&= \frac{1 - \bar{\alpha}_{t-1}}{1 - \bar{\alpha}_t} \beta_t.
\end{align}

We use a neural network \( f_\theta \) to predict $\xi$. The reverse transition is defined as~\cite{song2020score, bond2023infty}:
\begin{equation}
p_\theta(x_{t-1} \mid x_t) = \mathcal{N}\left(x_{t-1}; \mu_\theta(x_t, t), \tilde{\beta}_t L L^*\right),
\label{p_theta}
\end{equation}
with the predicted mean given by
\begin{equation}
\mu_{\theta}(x_t, t) = \frac{1}{\sqrt{\alpha_{t}}} \left[x_{t} - \frac{1 - \alpha_{t}}{\sqrt{1 - \bar{\alpha}_{t}}} f_{\theta}(x_t, t)\right].
\end{equation}

Thus, PRIMER is trained by minimizing the following simplified objective~\cite{ho2020denoising, song2020score, bond2023infty}:
\begin{equation}
\mathcal{L}_{\text{simple}} =  \mathbb{E}_{t} \left[\|\mu_{\theta}(x_t, t) - \tilde{\mu}_t(x_t, x_0) \|_{\mathcal{H}}^2\right] = \mathbb{E}_{t} \left[\|f_\theta(x_t, t) - \xi\|_{\mathcal{H}}^2\right].
\end{equation}


\begin{algorithm}[htbp]
\caption{Training Procedure of PRIMER}
\label{alg:primer_training}
\begin{algorithmic}[1]
\Require Gauge observations \( x_0 \in \mathbb{R}^{M \times d} \) (\( M \) gauges, each with a state vector in \( \mathbb{R}^d \)), gauge coordinates \( C \in \mathbb{R}^{M \times n} \) (spatial locations in \( \mathbb{R}^n \)), Gaussian mollifier kernel \( k \), diffusion schedule \( \bar{\alpha}_t \)

\State Sample white noise \( \varepsilon : \mathbb{R}^n \to \mathbb{R}^d \sim \mathcal{N}(0, I) \)

\ForAll{coordinates \( c \in C \)}
    \State Compute mollified noise: \( \xi(c) \gets (L\varepsilon)(c) = \int_{\mathbb{R}^n} k(c - c') \varepsilon(c') \, dc' \)
    \State Compute mollified data: \( (Lx_0)(c) = \int_{\mathbb{R}^n} k(c - c') x_0(c') \, dc' \)
    \State Compute diffused sample at time \( t \): 
    \(
    x_t(c) \gets \sqrt{\bar{\alpha}_t} \cdot (Lx_0)(c) + \sqrt{1 - \bar{\alpha}_t} \cdot \xi(c)
    \)
\EndFor

\State Predict mollified noise using neural network: \( \hat{\xi} \gets f_{\theta}(x_t, t) \)

\State Compute loss: \( \mathcal{L} \gets \| \hat{\xi} - \xi \|_{C}^2 \)

\State Update model parameters \( \theta \) using gradient descent on \( \mathcal{L} \)

\end{algorithmic}
\end{algorithm}




\begin{algorithm}[htbp]
\caption{Inference Procedure of PRIMER}
\label{alg:inference}
\begin{algorithmic}[1]
\Require Coordinates \( C \in \mathbb{R}^{M \times n} \)  (\( M \) gauges, each are located in \( \mathbb{R}^n \)), mollifier kernel \( k \), trained network \( f_{\theta} \), diffusion schedule \( \bar{\alpha}_t \), inverse signal-noise-ratio \( \epsilon \)
\State Sample Gaussian white noise \( \varepsilon \sim \mathcal{N}(0, I) \) 

\ForAll{coordinates \( c \in C \)}
    \State Set initial sample:
    \[
    x_T(c) \gets \int_{\mathbb{R}^n} k(c - c') \varepsilon(c') \, dc'
    \]
\EndFor

\For{\( t = T, T-1, \ldots, 1 \)}
    \State Predict mollified noise: \( \hat{\xi} \gets f_{\theta}(x_t, t) \)
    \State Estimate denoised state:
    \[
    \hat{x}_0 \gets \frac{x_t - \sqrt{1 - \bar{\alpha}_t} \cdot \hat{\xi}}{\sqrt{\bar{\alpha}_t}}
    \]
    \If{\( t > 1 \)}
        \State Sample new noise: \( \varepsilon \sim \mathcal{N}(0, I) \)
        \ForAll{coordinates \( c \in C \)}
            \State Compute mollified noise:
            \[
            \xi_{t-1}(c) \gets \int_{\mathbb{R}^n} k(c - c') \varepsilon(c') \, dc'
            \]
        \EndFor
        \State Update sample:
        \[
        x_{t-1} \gets \sqrt{\bar{\alpha}_{t-1}} \cdot \hat{x}_0 + \sqrt{1 - \bar{\alpha}_{t-1}} \cdot \xi_{t-1}
        \]
    \EndIf
\EndFor

\State Apply Wiener filtering:
\[
x_0(\omega) \gets \frac{e^{-\omega^2 t}}{e^{-2\omega^2 t} + \epsilon^2} \cdot \hat{x}_0(\omega)
\]
\State \Return \( x_0(c) \)

\end{algorithmic}
\end{algorithm}


\subsection{Network architecture}
\label{SI_Network_architecture}
The overall network architecture is designed to flexibly handle sparse and irregularly distributed observations, such as those from in-situ rain gauges, while maintaining strong representational capacity across heterogeneous data sources. As detailed in Section \ref{Network architecture}, the key distinction from a standard U-Net lies in the inclusion of multiple stacked \textit{SparseConvResBlock} modules at both the input and output stages of the network. These modules are specifically designed to process inputs with sparse spatial distributions. The input to the model consists of feature representations $x \in \mathbb{R}^{B \times L \times C}$ along with their corresponding spatial coordinates in $\mathbb{R}^{B \times L \times 2}$, where $B$ is the batch size, $L$ is the number of gauge locations, and $C$ is the number of feature channels. 
After being processed by a series of \textit{SparseConvResBlock} modules, the features retain their shape while being adapted to the sparsity of the input. These processed features are then transformed onto a coarser, structured grid, which facilitates subsequent processing using a conventional U-Net. See Supplementary Information, Listing~\ref{SI_code}, for the PyTorch implementation of the sparse-to-grid transformation.

\clearpage 
\begin{lstlisting}[language=Python, caption={Transform sparse gauge representation to a structured coarse grid.}, label={SI_code}]
from pytorch3d.ops import knn_points, knn_gather

def knn_interpolate_to_grid(x, coords, uno_coords, knn_neighbours):
    """
    Interpolates sparse features to a structured grid using KNN.

    Args:
        x: Tensor of shape (B, L, C), input features at irregular locations
        coords: Tensor of shape (B, L, 2), spatial coordinates of x
        uno_coords: Tensor of shape (y_length, 2), coordinates of target structured grid
        knn_neighbours: int, number of nearest neighbors to use
    Returns:
        Tensor of shape (B, y_length, C), interpolated features
    """

    B = x.size(0)
    target_coords = uno_coords.unsqueeze(0).repeat(B, 1, 1)  # (B, y_length, 2)

    with torch.no_grad():
        _, assign_index, neighbour_coords = knn_points(
            target_coords, coords, K=knn_neighbours, return_nn=True
        )

        # neighbour_coords: (B, y_length, K, 2)
        diff = neighbour_coords - target_coords.unsqueeze(2)
        squared_distance = (diff * diff).sum(dim=-1, keepdim=True)
        weights = 1.0 / torch.clamp(squared_distance, min=1e-15)

    neighbours = knn_gather(x, assign_index)  # (B, y_length, K, C)
    out = (neighbours * weights).sum(2) / weights.sum(2)

    return out.to(x.dtype)

\end{lstlisting}


Upon completion of the U-Net forward pass, the resulting features are bilinearly interpolated (using torch.nn.functional.grid\_sample function) back to the original set of irregular input coordinates. Finally, multiple \textit{SparseConvResBlock} modules are applied to further refine the outputs at target spatial locations $\mathbb{R}^{B \times L \times 2}$. The architecture of the \textit{SparseConvResBlock} module is shown in Figure~\ref{fig:SI_SparseConvResBlock}, highlighting its ability to integrate conditioning on both diffusion timestep and dataset source labels, enabling the model to operate seamlessly across multi-source inputs with varying spatial coverage.


\begin{figure}[htbp]
    \centering
    \includegraphics[width=\textwidth]{./images/SI_SparseConvResBlock.pdf}
    \caption{\textbf{Architecture of the SparseConvResBlock and its modulation mechanism.} 
