		\end{eqnarray*}
	}

	Algorithm \ref{alg:gh_intersection} describes the modified algorithm.

	\begin{algorithm}[!h]
		\caption{Approximation algorithm for \symsubdmcp}\label{alg:gh_intersection}
		\begin{algorithmic}[1]
			\Statex \textbf{Input:} A symmetric, submodular function $f\colon 2^V\to \bR_+$ and rank-$k$ matroids $ \cM_1 $ and $\cM_2$.
			\Statex \textbf{Output:} A feasible partition $\cP$. 
			\State Compute the Gomory-Hu tree $ H=(V,E) $ of $ f $ and its weight function $w_H$.
