We will now study the action of analytically continued operators $\widetilde V_\tau$ on $\cP_\cX(I_+)\Omega$, which is a dense subspace $\cD$ by Lemma~\ref{lem: X dense} and the Reeh-Schlieder property \cite[App. A]{CarpiRaymondTanimotoTener24ax}.
\begin{defn}
If $F \in \cX$ and $\tau \in \bbS := \{0 \le \Im(\tau) \le \pi\}$, we write $\beta_d(v_\tau)F|_{I_+}$ for the function
\begin{align}\label{eqn: beta d F on I}
(\beta_d(v_\tau)F)(z) &= X_{v_\tau}(v_{-\tau}(z))^{d-1} F(v_{-\tau}(z)) \\
&= (\cosh(\tau) + \Re(z)\sinh(\tau))^{d-1}F(v_{-\tau}(z)), & z \in I_+. \nonumber
\end{align}
\end{defn}
The requirement that $\tau \in \bbS$ ensures that $v_{-\tau}(I_+) \subset \bbO$, which is the domain of definition of $F$.
If $f = F|_{I_+} \in C^\infty(S^1)$ and $t \in \bbR$ then $\beta_d(v_t)F|_{I_+} = \beta_d(v_t)f$, which is to say that the above notation is consistent with our usual definition of $\beta_d(v_t)$.
Since $F$ vanishes to all orders at $\pm 1$ we have $\beta_d(v_\tau)F|_{I_+} \in C_0^\infty(I_+)$, which as previously mentioned we typically extend to a function in $C^\infty_0(S^1)$ by extending to be the zero function on $I_-$.
As expected we have
\begin{equation}\label{eqn: compatibility beta d tau and t}
\beta_d(v_t)\big[\beta_d(v_\tau)F|_{I_+}\big] = \beta_d(v_{\tau+t})F|_{I_+}.
\end{equation}

\begin{lem}\label{lem: vector valued holo map on strip}
Let $\bbS = \{ \tau \in \bbC \, : \, 0 \le \Im(\tau) \le \pi\}$.
\begin{enumerate}[(i)]
\item Let $F \in \cX$. Then the map $\bbS \to C_0^\infty(I_+)$ given by $\tau \mapsto \beta_d(v_\tau)F|_{I_+}$ is continuous and holomorphic in the interior.

\item Let $F_1, \ldots, F_k \in \cX$ and let $\varphi_1, \ldots \varphi_k \in \cF$.
Then the map $\bbS \to \cD$ given by
\[
\tau \mapsto \varphi_1(\beta_{d_1}(v_\tau)F_1|_{I_+}) \cdots \varphi_k(\beta_{d_k}(v_\tau)F_k|_{I_+})\Omega
\]
is continuous and holomorphic in the interior.
\end{enumerate}
\end{lem}
\begin{proof}
From inspection of the formula \eqref{eqn: beta d F on I} we can see that the map $\bbS \times I_+ \to \bbC$ given by $(\tau,z) \mapsto (\beta_d(v_\tau)F)(z)$ is smooth.
Hence the associated map $\bbS \to C^\infty_0(I_+)$ is smooth, and again from the formula \eqref{eqn: beta d F on I} we see that the derivative $\partial_{\overline{\tau}}$ vanishes on $\mathring{\bbS}$, establishing claim (i).

By the definition of the topology on $\cD$, expressions $\varphi_1(f_1) \cdots \varphi_k(f_k)\Omega$ are jointly continuous in the $f_j$, and combined with part (i) we have that 
\[
\varphi_1(\beta_{d_1}(v_\tau)F_1|_{I_+}) \cdots \varphi_k(\beta_{d_k}(v_\tau)F_k|_{I_+})\Omega
\]
depends continuously on $\tau$.
The usual proof of the product rule shows that this dependence is holomorphic on $\mathring{\bbS}$.
\end{proof}


As a straightforward consequence of Lemma~\ref{lem: vector valued holo map on strip} we have the following, which implies that for all $\tau \in \bbS$ we have that $D(\widetilde V_\tau)$ contains $\cP_{\cX}(I_+)\Omega$, and in particular is densely defined (by Lemma~\ref{lem: X dense}).
The proof of the following lemma is adapted from \cite[p.42-43]{Henriques2014CFTNotes}.
\begin{lem}\label{lem: Vtau action}
Let $\varphi_1,\ldots, \varphi_k \in \cF$, let $F_1, \ldots, F_k \in \cX$, and let $\bbS = \{ 0 \le \Im(\tau) \le \pi\}$.
Let 
$
\Phi = \varphi_1(F_1|_{I_+}) \cdots \varphi_k(F_k|_{I_+})\Omega.
$
Then we have the following.
\begin{enumerate}[(i)]
\item For any $\tau \in \bbS$ we have $\Phi \in D(\widetilde V_\tau)$ and
\begin{equation}\label{eqn: Vtau action}
\widetilde V_\tau\Phi = \varphi_1(\beta_{d_1}(v_\tau)F_1|_{I_+}) \cdots \varphi_k(\beta_{d_k}(v_\tau)F_k|_{I_+})\Omega.
\end{equation}
\item If $d=\sum d_j$ then
\begin{equation}\label{eqn: Vipi action}
\widetilde V_{i\pi}\Phi =  (-1)^d \varphi_k(F_k|_{I_+} \circ z^{-1}) \cdots \varphi_1(F_1|_{I_+} \circ z^{-1})\Omega. 
\end{equation}
\end{enumerate}
\end{lem}
\begin{proof}
Fix $\tau_0 \in \bbS$ and $\lambda \in \cD_\cF^*$.
By Lemma~\ref{lem: vector valued holo map on strip}, the map 
\[
G_{\lambda}(\tau) := \lambda\big(\varphi_1(\beta_{d_1}(v_\tau)F_1|_{I_+}) \cdots \varphi_k(\beta_{d_k}(v_\tau)F_k|_{I_+})\Omega\big)
\]
is continuous on the closed strip bounded by $\bbR$ and $\tau_0 + \bbR$ and holomorphic on the interior, with
\[
G_{\lambda}(t) = \lambda\big(V_t \varphi_1(F_1|_{I_+}) \cdots \varphi_k(F_k|_{I_+})\Omega\big), \qquad t \in \bbR.
\]
In light of \eqref{eqn: compatibility beta d tau and t}, for $t \in \bbR$ we have
\[
G_{\lambda}(t+\tau_0) = \lambda\big(V_t \varphi_1(\beta_{d_1}(v_{\tau_0})F_1|_{I_+}) \cdots \varphi_k(\beta_{d_k}(v_{\tau_0})F_k|_{I_+})\Omega\big), \qquad t \in \bbR.
\]
Hence by Definition~\ref{def: Vs}, $\varphi_1(F_1|_{I_+}) \cdots \varphi_k(F_k|_{I_+})\Omega \in D(\widetilde V_{\tau_0})$ and 
\[
\widetilde V_{\tau_0}\big[\varphi_1(F_1|_{I_+}) \cdots \varphi_k(F_k|_{I_+})\Omega\big] = \varphi_1(\beta_{d_1}(v_{\tau_0})F_1|_{I_+}) \cdots \varphi_k(\beta_{d_k}(v_{\tau_0})F_k|_{I_+})\Omega.
\]
This completes the first part of the proof.

It remains to show that the action of $\widetilde V_{i \pi}$ agrees with \eqref{eqn: Vipi action}.
To that end, note that $v_{i\pi}(z) = z^{-1}$, and so by definition  for $F \in \cX$ we have 
\[
\beta_{d_j}(v_{i\pi})F|_{I_+} = (-1)^{d_j-1} \cdot (F \circ z^{-1})|_{I_+} = (-1)^{d_j-1} \cdot F|_{I_-} \circ z^{-1}
\]
Hence from the formula for $\widetilde V_{\tau}$ above we have
\begin{equation}\label{eqn: vipi intermediate step}
\widetilde V_{i\pi} \Phi = (-1)^{d+k} \varphi_1(F_1 \circ z^{-1}|_{I_+}) \cdots \varphi_k(F_k \circ z^{-1}|_{I_+})\Omega.
\end{equation}

We next claim that if $F \in \cX$ then we have
\begin{equation}\label{eqn: claim value on vacuum}
\varphi(F \circ z^{-1}|_{I_+})\Omega = - \varphi(F \circ z^{-1}|_{I_-})\Omega.
\end{equation}
Indeed $F \circ z^{-1}$ is holomorphic on the disk $\mathring{\bbD}$ and vanishes at the origin, and thus $\varphi(F \circ z^{-1}|_{S^1})$ strictly lowers conformal dimension.
In particular,
\[
\varphi(F \circ z^{-1}|_{S^1})\Omega = 0.
\]
Since $\varphi(F \circ z^{-1}|_{S^1}) = \varphi(F \circ z^{-1}|_{I_+}) + \varphi(F \circ z^{-1}|_{I_-})$, the claim \eqref{eqn: claim value on vacuum} follows.

Following \cite[p.43]{Henriques2014CFTNotes}, we set $g_j = F_j \circ z^{-1}|_{I_+}$ and $h_j = F_j \circ z^{-1}|_{I_-} = F_j|_{I_+} \circ z^{-1}$ and compute
\begin{align*}
\varphi_1(g_1) \cdots \varphi_k(g_k)\Omega & = 
 - \varphi_1(g_1) \cdots \varphi_{k-1}(g_{k-1})\varphi_k(h_k)\Omega\\
 & = -\varphi_k(h_k)\varphi_1(g_1) \cdots \varphi_{k-1}(g_{k-1})\Omega, 
\end{align*}
where the first equality is \eqref{eqn: claim value on vacuum} and the second equality is due to locality.
Repeating this argument yields
\[
\varphi_1(g_1) \cdots \varphi_k(g_k)\Omega 
= (-1)^k\varphi_k(h_k) \cdots \varphi_1(h_1)\Omega.
\]
Combining this identity with \eqref{eqn: vipi intermediate step} yields the desired expression \eqref{eqn: Vipi action}.
\end{proof}

We have thus shown that for $\tau \in \bbS$ the domain $D(\widetilde V_\tau)$ contains $\cP_\cX(I_+)\Omega$, where we recall $\cP_\cX(I_+) \subset \cP(I_-)$ is generated by operators $\varphi(F|_{I_+})$ with $F \in \cX$.
We would like to extend this result to $\cP(I_+)\Omega$ via a limiting argument, approximating $f \in C^\infty_0(I_+)$ by functions of the form $F|_{I_+}$.
We will begin by examining the growth rate of the function $\lambda(V_t\Phi)$.

\begin{lem}\label{lem: growth estimate on R}
Let $\varphi_1, \ldots, \varphi_k \in \cF$ and let $\lambda \in \cD_\cF^*$.
Then there exists a positive integer $N$ and function $C:\bbR \to \bbR_{> 0}$ such that:
\begin{enumerate}[(i)]
\item  there exist constants $k_1,k_2>0$ such that $C(t) \le k_1 e^{k_2\abs{t}}$ for all $t \in \bbR$
\item for all $f_j,g_j \in C^\infty(S^1)$ and all $t \in \bbR$ we have
\begin{align*}
%\abs{&\ip{V_t\big[\varphi_1(f_1) \cdots \varphi_k(f_k) - \varphi_1(g_1) \cdots \varphi_k(g_k)\big] \Omega,\Phi'}} \le\\
&\abs{\lambda\big(\big[V_t\varphi_1(f_1) \cdots \varphi_k(f_k) \Omega\big]-\big[V_t\varphi_1(g_1) \cdots \varphi_k(g_k) \Omega\big]\big)} \le\\
&\qquad C(t)\left[\prod_{j=1}^k \big(1+\norm{f_j}_{C^N}+\norm{g_j}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_j-g_j}_{C^N},
\end{align*}
where $\norm{f}_{C^N} = \sum_{j=1}^N \big\|\tfrac{d^j}{d\theta^j} f\big\|_\infty$.
\end{enumerate}
\end{lem}
\begin{proof}

The map
\[
(h_1, \ldots, h_k) \mapsto \lambda\big(\varphi_1(h_1) \cdots \varphi_k(h_k)\Omega\big)
\]
is jointly continuous on $C^\infty(S^1)^k$.
Thus by standard results (c.f. the beginning of \cite[\S41]{Treves67}) there exists a positive integer $N$ such that
\[
\abs{\lambda\big(\varphi_1(h_1) \cdots \varphi_k(h_k)\Omega\big)} \le \norm{h_1}_{C^N} \cdots \norm{h_k}_{C^N}, \qquad h_j \in C^\infty(S^1),
\]
after potentially rescaling $\lambda$ for notational convenience.
Observe that
\begin{align*}
\varphi_1(f_1) \cdots \varphi_k(f_k) - \varphi_1(g_1) \cdots \varphi_k(g_k) = 
\sum_{j=1}^k \left[ \prod_{\ell=1}^{j-1} \varphi_\ell(f_\ell) \right ]\varphi_j(f_j-g_j) \left[ \prod_{\ell=j+1}^{k} \varphi_\ell(g_\ell) \right ],
\end{align*}
where we take the convention that the (non-commuting) products are ordered left-to-right.
Hence
\begin{align*}
&\abs{\lambda\big(\big[V_t\varphi_1(f_1) \cdots \varphi_k(f_k) \Omega\big]-\big[V_t\varphi_1(g_1) \cdots \varphi_k(g_k) \Omega\big]\big)} \le\\
&\qquad \le \sum_{j=1}^k \abs{\lambda\left( \left[ \prod_{\ell=1}^{j-1} \varphi_\ell(\beta_{d_j}(v_t) f_\ell) \right ]\varphi_j(\beta_{d_j}(v_t)[f_j-g_j]) \left[ \prod_{\ell=j+1}^{k} \varphi_\ell(\beta_{d_j}(v_t)g_\ell) \right]\Omega\right)} \le\\
&\qquad \le k \left[\prod_{j=1}^k \big(1+\norm{\beta_{d_j}(v_t)f_j}_{C^N}+\norm{\beta_{d_j}(v_t)g_j}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{\beta_{d_j}(v_t)[f_j-g_j]}_{C^N}.
\end{align*}
Thus it suffices to show that for any $f \in C^\infty(S^1)$ the function $\norm{\beta_d(v_t)f}_{C^N}$ satisfies
\begin{equation}\label{eqn: exp growth bound CN norm}
\norm{\beta_d(v_t)f}_{C^N} \le C(t) \norm{f}_{C^N}
\end{equation}
for a function $C:\bbR \to \bbR_{> 0}$ satisfying the growth condition (i).
We say that a function $\bbR \to \bbR_{> 0}$ satisfying (i) has `at most exponential growth,' and we note that the class of such functions is closed under addition and products.

We first consider $\norm{\beta_d(v_t)f}_\infty$, i.e. the case $N=0$.
Recall that
\[
(\beta_d(v_t)f)(z) = (\cosh(t) + \Re(z) \sinh(t))^{d-1} \cdot f(v_{-t}(z)).
\]
Hence
\[
\norm{\beta_d(v_t)f}_\infty \le \left( \sup_{z \in S^1} \abs{\cosh(t) + \Re(z) \sinh(t)} \right)^{d-1} \norm{f}_\infty
\]
and the function $t \mapsto \sup_{z \in S^1} \abs{\cosh(t) + \Re(z) \sinh(t)}$ evidently has at most exponential growth (it is, in fact, exactly $e^{\abs{t}}$).
This establishes the necessary estimate in the case $N=0$.

More generally, the derivative $\tfrac{d^j}{d\theta^j} \beta_d(v_t)f$ is a linear combination of products of functions of the form 
\[
\tfrac{d^k}{d\theta^k}\big[\cosh(t) + \Re(z) \sinh(t)\big], \quad \tfrac{d^k}{d\theta^k} v_{-t}(z), \quad f^{(k)}(v_{-t}(z)), \qquad 0 \le k \le j,
\]
with exactly one term of the last type in each product.
Explicit calculation shows that the sup norms of functions of the first two types are bounded by functions of $t$ with at most exponential growth as above, and we conclude that \eqref{eqn: exp growth bound CN norm} holds for all $N$ with a function $C$ with at most exponential growth.
\end{proof}

The next lemma establishes an analogous growth bound on the analytic continuation $\lambda(\widetilde V_\tau\Phi)$ on the strip $\bbS$ when $\Phi \in \cP_{\cX}(I_+)\Omega$.
Of particular note is that the estimate only involves data related to the vector $\Phi$ (and the function $V_t\Phi$ on one boundary of the strip), and does not reference $\widetilde V_{i\pi}\Phi$.

\begin{lem}\label{lem: growth estimate on S}
Let $\varphi_1, \ldots, \varphi_k \in \cF$ and let $\lambda \in \cD_\cF^*$.
Then there exists a positive integer $N$ and positive constant $M$ with the following property.
Let $F_j,G_j \in \cX$ and let $f_j = F_j|_{I_+}$ and $g_j = G_j|_{I_+}$.
Then for all $\tau \in \bbS = \{0 \le \Im(\tau) \le \pi\}$ we have
\begin{align*}
%\abs{&\ip{V_t\big[\varphi_1(f_1) \cdots \varphi_k(f_k) - \varphi_1(g_1) \cdots \varphi_k(g_k)\big] \Omega,\Phi'}} \le\\
&\abs{\lambda\big(\big[\widetilde V_\tau\varphi_1(f_1) \cdots \varphi_k(f_k) \Omega\big]-\big[\widetilde V_\tau\varphi_1(g_1) \cdots \varphi_k(g_k) \Omega\big]\big)} \le\\
&\qquad M e^{\Re(\tau)^2} \left[\prod_{j=1}^k \big(1+\norm{f_j}_{C^N}+\norm{g_j}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_j-g_j}_{C^N}.
\end{align*}
\end{lem}
\begin{proof}
Let us temporarily fix $F_j,G_j \in \cX$ along with the corresponding $f_j=F_j|_{I_+}$ and $g_j=G_j|_{I_+}$. 
Let $\mathfrak{F},\mathfrak{G}:\bbS \to \bbC$ be the functions
\[
\mathfrak{F}(\tau) = \lambda\big(\widetilde V_\tau\varphi_1(f_1) \cdots \varphi_k(f_k) \Omega\big), \quad \mathfrak{G}(\tau) = \lambda\big(\widetilde V_\tau\varphi_1(g_1) \cdots \varphi_k(g_k) \Omega\big)
\]
and let $\mathfrak{H} = \mathfrak{F}-\mathfrak{G}$.
By Lemma~\ref{lem: vector valued holo map on strip}, the functions $\mathfrak{F},\mathfrak{G}$ and $\mathfrak{H}$ are continuous on the closed strip $\bbS = \{0 \le \Im(\tau) \le \pi\}$ and holomorphic on the interior.
Write $\tau = t + i s$ with $0 \le s \le \pi$, and let 
\begin{equation}\label{eqn: fjs}
f_{j,s} = \beta_{d_j}(v_{is})F_j|_{I_+}, \qquad g_{j,s} = \beta_{d_j}(v_{is})G_j|_{I_+},
\end{equation}
so that 
\[
\widetilde V_{is} \varphi_1(f_1)\cdots\varphi_k(f_k)\Omega = \varphi_1(f_{1,s}) \cdots \varphi_k(f_{k,s})\Omega
\]
by \eqref{eqn: Vtau action}, and similarly for the $g_j$.
By Lemma~\ref{lem: growth estimate on R} applied to the functions $f_{j,s}$ and $g_{j,s}$ (along with the fact that $\widetilde V_{t+is} = V_t \widetilde V_{is}$) we have 
\begin{align*}
\abs{\mathfrak{H}(t+is)} \le C(t)\left[\prod_{j=1}^k \big(1+\norm{f_{j,s}}_{C^N}+\norm{g_{j,s}}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_{j,s}-g_{j,s}}_{C^N}
\end{align*}
for some positive integer $N$ and some function $C$ with at most exponential growth that does not depend on the functions $F_j$ and $G_j$.
Since $F$ and $G$ are smooth on $\bbO$, the maximum
\[
\max_{0 \le s \le \pi} \left[\prod_{j=1}^k \big(1+\norm{f_{j,s}}_{C^N}+\norm{g_{j,s}}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_{j,s}-g_{j,s}}_{C^N}
\]
is achieved.
Hence there is a constant $K > 0$ (depending on the $F_j$ and $G_j$) such that
\[
\abs{\mathfrak{H}(\tau)} \le K \, C(\Re \tau).
\]
Since $\big|e^{-\tau^2}\big| \le e^{\pi^2} e^{-\Re(\tau)^2}$ on $\bbS$ and $C$ has exponential growth, we see that $e^{-\tau^2} \mathfrak{H}(\tau)$ is bounded, and in fact vanishes at $\infty$.
A straightforward application of the (strong) maximum principle yields that $\big|e^{-\tau^2}\mathfrak{H}(\tau) \big|$ achieves its maximum on $\partial \bbS = \bbR \cup \bbR + i\pi$.

We first investigate the dependence of this maximum on the functions $F_j$ and $G_j$, although we still suppress this dependence from the notation $\mathfrak{H}(\tau)$.
For $t \in \bbR$ we have
\begin{equation}\label{eqn: H bound on R}
\big| e^{-t^2}\mathfrak{H}(t)\big| \le M \left[\prod_{j=1}^k \big(1+\norm{f_{j}}_{C^N}+\norm{g_{j}}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_{j}-g_{j}}_{C^N}
\end{equation}
where $M = \max_t e^{-t^2} C(t)$ does not depend on the functions $F_j$,$G_j$.

We now consider the behavior of $e^{-\tau^2} \mathfrak{H}(\tau)$ on $\bbR + i \pi$.
Recall from Lemma~\ref{lem: Vtau action} that
\[
\widetilde V_{i\pi}\varphi_1(f_1) \cdots \varphi_k(f_k)\Omega = (-1)^d \varphi_k(\hat f_k) \cdots \varphi_1(\hat f_1)\Omega
\]
where $\hat f_j = f_j \circ z^{-1}$ and $d = \sum d_j$.
Crucially, $\|\hat f_j\|_{C^N} = \norm{f_j}_{C^N}$.
We have similar computations for the functions $g_j$, so by Lemma~\ref{lem: growth estimate on R}
\begin{align*}
\abs{\mathfrak{H}(t+i\pi)} &= \abs{\lambda \big( \big[ \widetilde V_{t+i\pi}\varphi_1(f_1) \cdots \varphi_k(f_k)\Omega\big] - \big[\widetilde V_{t+i\pi}\varphi_1(g_1) \cdots \varphi_k(g_k)\Omega\big]\big)}\\
&= \abs{\lambda\big(\big[V_{t}\varphi_k(\hat f_k) \cdots \varphi_1(\hat f_1)\Omega\big] - \big[V_{t}\varphi_k(\hat g_k) \cdots \varphi_1(\hat g_1)\Omega\big]\big)}\\
&\le D(t) \left[\prod_{j=1}^k \big(1+\|\hat f_j\|_{C^{N'}}+\norm{\hat g_j}_{C^{N'}}\big) \right]\max_{1 \le j \le k} \|\hat f_j- \hat g_j\|_{C^{N'}}\\
&= D(t) \left[\prod_{j=1}^k \big(1+\norm{f_j}_{C^{N'}}+\norm{g_j}_{C^{N'}}\big) \right]\max_{1 \le j \le k} \norm{f_j- g_j}_{C^{N'}}.
\end{align*}
The function $D(t)$ and integer $N'$ may differ from the previous computation because of the reordering of the fields $\varphi_j$, but by replacing $N$ or $N'$ with $\max \{N,N'\}$ we may assume without loss of generality that $N=N'$.
Arguing as before we have
\[
\abs{e^{-(t+i\pi)^2} \mathfrak{H}(t+i\pi)} \le M' \left[\prod_{j=1}^k \big(1+\norm{f_{j}}_{C^N}+\norm{g_{j}}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_{j}-g_{j}}_{C^N}
\]
where $M' = \max e^{\pi^2} e^{-t^2}D(t)$ does not depend on the functions.
Combined with \eqref{eqn: H bound on R}, we have for all $\tau \in \partial\bbS = \bbR \cup \bbR + i \pi$
\[
\abs{e^{-\tau^2} \mathfrak{H}(\tau)} \le M'' \left[\prod_{j=1}^k \big(1+\norm{f_{j}}_{C^N}+\norm{g_{j}}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_{j}-g_{j}}_{C^N}
\]
where $M''=\max\{M,M'\}$.
As discussed previously, $\abs{\mathfrak{H}(\tau)}$ is maximized on $\partial \bbS$, so as required we have for all $\tau \in \bbS$
\begin{align*}
\abs{\mathfrak{H}(\tau)} \le M'' \big| e^{\tau^2}\big| \left[\prod_{j=1}^k \big(1+\norm{f_{j}}_{C^N}+\norm{g_{j}}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_{j}-g_{j}}_{C^N}\\
\le M'' e^{\Re(\tau)^2} \left[\prod_{j=1}^k \big(1+\norm{f_{j}}_{C^N}+\norm{g_{j}}_{C^N}\big) \right]\max_{1 \le j \le k} \norm{f_{j}-g_{j}}_{C^N}.
\end{align*}
\end{proof}

We can now give the main result of Section~\ref{sec: general nonunitary}, computing $\widetilde V_{\pm i\pi} x\Omega$ for $x \in \cP(I_\pm)$.

\begin{thm}\label{thm: nonunitary Vipi}
Let $(\cF,\cD,U,\Omega)$ be a non-unitary Wightman CFT on $S^1$.
Let $\cP(I_+) \subset \End(\cD)$ be the algebra generated by operators $\varphi(f)$ with $\varphi \in \cF$ and $\supp(f) \subset I_+$.
Let $\widetilde V_{\pm i\pi}$ be the densely defined operators from Definition~\ref{def: Vs} with domains $D(\widetilde V_{\pm i\pi})$.
\begin{enumerate}[(i)]
    \item $\cP(I_+)\Omega \subset D(\widetilde V_{i\pi})$ and $\cP(I_-)\Omega \subset D(\widetilde V_{-i\pi})$
    \item Let $\varphi_1, \ldots, \varphi_k \in \cF$ with conformal dimensions $d_j$, and let $f_1, \ldots, f_k \in C^\infty(S^1)$ with $\operatorname{supp} f_j \subset I_+$. Let $d= \sum d_j$. Then we have
    \[
    \widetilde V_{i\pi}\varphi_1(f_1)\cdots \varphi_k(f_k)\Omega = (-1)^d \varphi_k(f_k \circ z^{-1}) \cdots \varphi_1(f_1 \circ z^{-1})\Omega.
    \]
    \item The analogous formula holds for $\widetilde V_{-i\pi}$ and $\operatorname{supp} f_j \subset I_-$.
\end{enumerate}
\end{thm}
\begin{proof}
Without loss of generality, we only consider $I_+$.
If for all $j$ we have $f_j = F_j|_{I_+}$ for some $F_j \in \cX$ then by Lemma~\ref{lem: Vtau action} we have
\[
\widetilde V_{i\pi}x\Omega = (-1)^d \varphi_k(F_k|_{I_+} \circ z^{-1}) \cdots \varphi_1(F_1|_{I_+} \circ z^{-1})\Omega
\]
as required.
We now consider general $f_j \in C^\infty(S^1)$ with $\supp f_j \subset I_+$.
By Lemma~\ref{lem: X dense}, for each $j=1,\ldots, k$ there exists a sequence $F_{j,n} \in \cX$ such that $\lim_{n \to \infty} F_{j,n}|_{I_+} = f_j$ in the $C^\infty$ topology.
Let $f_{j,n} = F_{j,n}|_{I_+}$ and fix $\lambda \in \cD_\cF^*$.
Note that $\norm{f_{j,n}}_{C^N}$ is bounded for every positive integer $N$, so by Lemma~\ref{lem: growth estimate on S} we have for all $\tau \in \bbS=\{0 \le \Im(\tau) \le \pi\}$ 
\begin{align*}
\big|\lambda\big(\big[\widetilde V_\tau &\varphi_1(f_{1,n}) \cdots \varphi_k(f_{k,n})\Omega\big] - \big[V_\tau \varphi_1(f_{1,m}) \cdots \varphi_k(f_{k,m})\Omega\big]\big)\big| \\
&\le Me^{\Re(\tau)^2} \max_{1 \le j \le k} \norm{f_{j,n}-f_{j,m}}_{C^N}.
\end{align*}
for some $M>0$ that does not depend on $m$ and $n$.
Thus we see that the sequence of holomorphic functions
\[
G_{\lambda,n}(\tau) = \lambda\big(V_\tau \varphi_1(f_{1,n}) \cdots \varphi_k(f_{k,n})\Omega\big)
\]
is locally uniformly Cauchy on $\bbS$, and thus converges locally uniformly to a function $G_{\lambda}$.
Since each $G_{\lambda,n}$ is continuous on $\bbS$ and holomorphic on the interior (by Lemma~\ref{lem: vector valued holo map on strip}), so is $G_{\lambda}$.
Taking pointwise limits, we see that for $t \in \bbR$
\[
G_{\lambda}(t) = \lambda\big(V_t \varphi_1(f_1) \cdots \varphi_k(f_k)\Omega\big).
\]
Again invoking the formula for $\widetilde V_{i\pi}$ from Lemma~\ref{lem: Vtau action} and the fact that $\widetilde V_{t+i\pi} = V_t \widetilde V_{i\pi}$, we have
\begin{align*}
G_{\lambda}(t+i\pi) & = \lim_{n \to \infty} (-1)^d \lambda\big(V_t \varphi_k(f_{k,n} \circ z^{-1}) \cdots \varphi_1(f_{1,n} \circ z^{-1})\Omega\big)\\
& = (-1)^d \lambda\big(V_t \varphi_k(f_k \circ z^{-1}) \cdots \varphi_1(f_1 \circ z^{-1})\Omega\big).
\end{align*}
Thus by Definition~\ref{def: Vs} we have $\varphi_1(f_1) \cdots \varphi_k(f_k)\Omega \in D(\widetilde V_{i\pi})$ and 
\[
\widetilde V_{i\pi}\varphi_1(f_1) \cdots \varphi_k(f_k)\Omega = (-1)^d \varphi_k(f_k \circ z^{-1}) \cdots \varphi_1(f_1 \circ z^{-1})\Omega. \qedhere
\] 
\end{proof}

\section{Invariant Hermitian forms, Bisognano-Wichmann, and the KMS condition}\label{sec: sesquilinear}

In this section, we  assume that our Wightman CFT $(\cF,\cD,U,\Omega)$ has an invariant nondegenerate sesquilinear form $\ip{\, \cdot \, , \, \cdot \,}$, along with an antiunitary PCT involution $\theta:\cD \to \cD$ which fixes $\Omega$.
Such a theory is called \textbf{involutive}.
In an involutive Wightman CFT, we have
\begin{equation}\label{eqn: invariant sesquilinear}
\ip{\varphi(f)\Phi,\Psi} = \ip{\Phi,\varphi^\dagger(\overline{f})\Psi}, \qquad \Phi,\Psi \in \cD, \, \varphi \in \cF, \, f \in C^\infty(S^1)
\end{equation}
where $\varphi^\dagger$ is the operator-valued distribution 
\[
\varphi^\dagger(f) =(-1)^{d_\varphi} \theta \varphi (\overline{f} \circ z^{-1}) \theta,
\]
and moreover we have $(-1)^{d_\varphi} \varphi^\dagger \in \cF$.
We also have
\[
\ip{U(\gamma)\Phi,U(\gamma)\Psi} = \ip{\Phi,\Psi}, \qquad \Phi,\Psi \in \cD, \, \gamma \in \Mob.
\]
The sesquilinear form is assumed to be jointly $\cF$-strong continuous and is automatically Hermitian symmetric, meaning $\ip{\Phi,\Psi}=\overline{\ip{\Psi,\Phi}}$ for all $\Phi,\Psi \in \cD$.
Given $\theta$, the existence of a unique sesquilinear form on $\cD$ with these properties is equivalent to $\ip{ \, \cdot \, , \theta \, \cdot \,}$ being a nondegenerate invariant bilinear form on the M\"obius vertex algebra underlying $\cF$.
The theory is called \textbf{unitary} if the Hermitian form is an inner product (normalized so that $\norm{\Omega} = 1$).
In terms of the correspondence between Wightman CFTs and vertex algebras, an involutive Wightman CFT corresponds to a M\"obius vertex algebra with a sesquilinear form and antiunitary operator $\theta$ such that $\ip{\, \cdot \, \theta \, \cdot \,}$ is an invariant bilinear form in the sense of \cite{FHL93,Li94}.
See \cite[Def. 4.9]{CarpiRaymondTanimotoTener24ax} and the surrounding discussion for more detail.

Given a continuous map $x \in \End(\cD)$, we say that $x$ has an adjoint if there exists $x^* \in \End(\cD)$ such that $\ip{x\Phi,\Psi}=\ip{\Phi,x^*\Psi}$ for all $\Phi,\Psi \in \cD$\footnote{See also the discussion following Corollary~\ref{cor: KMS} regarding the partially defined adjoint of a partially defined (and not necessarily continuous) linear map.}, and write $\End_*(\cD)$ for the collection of continuous operators $x \in \End(\cD)$ that have an adjoint $x^* \in \End(\cD)$.
In light of \eqref{eqn: invariant sesquilinear} we see that $\varphi(f) \in \End_*(\cD)$, and moreover the algebras $\cP(I)$ are $*$-algebras, i.e., they are closed under taking adjoints.
We have $\theta \cP(I) \theta = \cP(\overline{I})$, where $\overline{I}$ is the complex conjugate interval, and $\theta$ commutes with $V_t$.


Since the Hermitian form is continuous, each map $\ip{ \, \cdot \, , \Phi}$ lies in $\cD_\cF^*$. 
The collection of such functionals separates points in $\cD$ because the form is nondegenerate, although it is generally a proper subspace of $\cD_\cF^*$.
In Definition~\ref{def: Vs}, we defined the domain of $\widetilde V_\tau$ to consist of vectors $\Phi \in \cD$ such that the functions $\lambda(V_t\Phi)$ have appropriate analytic continuations.
In the context of an involutive theory, where we are interested in the adjoints of operators, it is more appropriate to work on an (a priori) larger domain where we only require analytic continuation of the functions $\ip{V_t\Phi,\Phi'}$.

\begin{defn}\label{defn: Vs involutive}
For $\tau \in \bbC$, the operator $V_\tau$ has domain $D(V_\tau) \subset \cD$ consisting of vectors $\Phi \in \cD$ such that for every $\Phi' \in \cD$ the function $\bbR \to \bbC$ given by
\[
t \mapsto \ip{V_t\Phi,\Phi'}
\]
extends to a (necessarily unique) function $G_{\Phi'}$ on the closed strip $\bbS_\tau$ bounded by $\bbR$ and $\bbR + \tau$ such that $G_{\Phi'}$ is continuous on $\bbS_\tau$ and holomorphic in the interior $\mathring{\bbS_\tau}$. Moreover, we require that there exist $\Psi \in \cD$ such that $G_{\Phi'}(\tau+t) = \ip{V_t\Psi,\Phi'}$ for all $t \in \bbR$ and $\Phi' \in \cD$.
The operator $V_\tau$ is defined on $\Phi \in D(V_\tau)$ by $V_\tau\Phi = \Psi$.
\end{defn}

It is immediate that $D(\widetilde V_\tau) \subset D(V_\tau)$ and 
\begin{equation}\label{eqn: Vtau extension}
V_\tau|_{D(\widetilde V_\tau)} = \widetilde V_\tau.
\end{equation}
As a corollary of Theorem~\ref{thm: nonunitary Vipi} we obtain the Bisognano-Wichmann property \cite[Thm. 1(d)]{BisognanoWichmann75} for involutive Wightman CFTs on $S^1$.

\begin{thm}\label{thm: involutive BW}
Let $(\cF,\cD,U,\Omega)$ be an involutive Wightman CFT on $S^1$ with PCT involution $\theta$.
Let $\cP(I_+) \subset \End_*(\cD)$ be the unital algebra generated by operators $\varphi(f)$ with $\varphi \in \cF$ and $\supp f  \subset I_+$.
Let $V_{\pm i\pi}$ be the densely defined operators from Definition~\ref{defn: Vs involutive} with domains $D(V_{\pm i\pi})$.
\begin{enumerate}[(i)]
    \item We have $\cP(I_+)\Omega \subset D(V_{i\pi})$  and if $x \in \cP(I_+)$ then
    \[V_{i\pi}x\Omega = \theta x^* \Omega.\]
    \item We have $\cP(I_-)\Omega \subset D(V_{-i\pi})$  and if $x \in \cP(I_-)$ then
    \[V_{-i\pi}x\Omega = \theta x^* \Omega.\]
\end{enumerate}
\end{thm}
\begin{proof}
We only consider the first item and the second is similar.
By Theorem~\ref{thm: nonunitary Vipi} and \eqref{eqn: Vtau extension} we have $\cP(I_+)\Omega \subset D(V_{i\pi})$.
Consider $x = \varphi_1(f_1) \cdots \varphi_k(f_k)$, where $\varphi_j \in \cF$ with conformal dimension $d_j$ and $\operatorname{supp} f_j \subset I_+$.
 By the same Theorem, we have
\[
V_{i\pi}x\Omega =V_{i \pi} \varphi_1(f_1) \cdots \varphi_k(f_k)\Omega = (-1)^d \varphi_k(f_k \circ z^{-1}) \cdots \varphi_1(f_1 \circ z^{-1})\Omega
\]
where $d = \sum d_j$.
On the other hand, $\theta \Omega = \Omega$ and by \eqref{eqn: invariant sesquilinear} we have
\[
\theta \varphi_j(f_j) \theta = (-1)^{d_j} \varphi_j(f_j \circ z^{-1})^*.
\]
Hence 
\[
\theta x^*\Omega = (-1)^d \varphi_k(f_k \circ z^{-1}) \cdots \varphi_1(f_1 \circ z^{-1})\Omega = V_{i\pi} x \Omega
\]
as required.
\end{proof}

\begin{cor}[KMS condition] \label{cor: KMS}
Let $\phi:\cP(I_+) \to \bbC$ be the linear functional 
\[
\phi(x)=\ip{x\Omega,\Omega}
\]
and let $\alpha_t = \operatorname{Ad} V_t \in \operatorname{Aut}(\cP(I_+))$.
Let $\bbS_{2\pi i} = \{\tau \in \bbC \, : \, 0 \le \Im(\tau) \le 2\pi\}$.
Then for every $x,y \in \cP(I_+)$, there exists a function $F:\bbS_{2\pi i} \to \bbC$ that is continuous on $\bbS_{2\pi i}$, holomorphic on $\mathring{\bbS}_{2 \pi i}$, and satisfies for all $t \in \bbR$
\[
F(t) = \phi(x\alpha_t(y)), \qquad F(t+2\pi i) = \phi(\alpha_t(y)x).
\]
\end{cor}
\begin{proof}
    Let $x,y \in \cP(I_+)$.
    By Theorem~\ref{thm: involutive BW}, there is a function $F_1:\bbS_{i\pi} \to \bbC$ that is continuous and holomorphic on the interior such that
    \[
    F_1(t) = \ip{V_t y\Omega, x^*\Omega}, \qquad F_1(t+i\pi) = \ip{V_tV_{i\pi}y\Omega, x^*\Omega} = \ip{V_t\theta y^*\Omega, x^*\Omega}.
    \]
    Similarly, since $\theta x^* \theta \in \cP(I_-)$, there exists a function $F_2:\bbS_{-i\pi} \to \bbC$ such that
    \[
F_2(t) = \ip{V_t \theta x^* \Omega, y^*\Omega}, \qquad 
    F_2(t-i\pi) = \ip{V_t x\Omega, y^*\Omega}.
\]
The function $G(\tau) = F_2(-\tau+i\pi)$ is defined on the strip $\{\pi \le \Im(\tau) \le 2\pi\}$, and $G(t+i\pi) = F_1(t+i\pi)$ for all $t \in \bbR$.
Hence $F_1$ and $G$ assemble to a function $F$ continuous on $\bbS_{2\pi i}$ and holomorphic in the interior such that
\[
F(t) = F_1(t) = \phi(x\alpha_t(y)), \qquad F(t + 2\pi i) = F_2(-t-\pi i) = \phi(\alpha_t(y)x),
\]
as required.
\end{proof}

We briefly digress on the subject of partially defined operators in the present context.
For the most part, the definitions and results are identical to the situation of unbounded operators on a Hilbert space.
We give a brief summary of the aspects of the theory which persist into the present context.

A partially defined operator $X$ on $\cD$ consists of a subspace $D(X) \subset \cD$ and a linear map $X:D(X) \to \cD$.
We typically require that $D(X)$ be dense.
We say that $X_1$ is an extension of $X_2$ if $D(X_2) \subseteq D(X_1)$ and $X_1|_{D(X_2)} = X_2$, in which case we write $X_2 \subset X_1$.
If $X$ is densely defined, then the adjoint $X^*$ has domain consisting of vectors $\Psi \in \cD$ such that there exists $\Psi' \in \cD$ for which 
\[
\ip{X\Phi, \Psi} = \ip{\Phi,\Psi'}, \qquad \Phi \in D(X).
\]
In this case $X^*\Psi = \Psi'$.
If $X_2 \subset X_1$ then $X_1^* \subset X_2^*$.
A densely defined operator is called symmetric if $X \subset X^*$, and self-adjoint if $X=X^*$ as partially defined operators (i.e. including having the same domain).
A densely defined operator is called closed if its graph is a closed subset of $\cD \times \cD$, and called closable if the closure of its graph is the graph of a (closed) linear map.
We write $\overline{X}$ for the closure of a closable operator $X$.
A core for a closed operator $X$ is a subspace $W \subset D(X)$ such that $\overline{X|_W} = X$.
The adjoint of a densely defined operator is necessarily closed, and if $X$ has a densely defined adjoint, then it is closable.

It is at this point that we encounter a key difference from the theory of unbounded operators on Hilbert spaces.
If $X$ is closable, then $\overline{X} \subseteq X^{**}$, but equality may fail.
In order to understand this phenomenon, one should recall that the graph of $X^*$ is essentially the orthogonal complement of the graph of $X$.
Thus this is a manifestation of another fundamental departure, which is that if $W \subset \cD$ then $\overline{W} \subset W^{\perp\perp}$, but again equality may fail.
This is a consequence of the fact that $W^\perp$ may be `surprisingly small,' even when the Hermitian form is positive definite\footnote{Consider the case where $\cD$ is the subspace of $L^2[0,1]$ spanned by $L^2[0,\tfrac12]$ and polynomials. The orthogonal complement of $W=L^2[0,\tfrac12]$ in $\cD$ consists of only the zero function.}.

The challenges described above can make it difficult to study duality phenomena in the present context, which in turn increases the difficulty in precisely identifying the domains of various operators.
For example, a key question that we do not resolve in this article is the following.

\begin{ques}\label{ques: core}
    Is $\cP(I_+)\Omega$ a core for $V_{i\pi}$?
\end{ques}

We will see below (Corollary~\ref{cor: haag dual subspace net} and Proposition~\ref{prop: algebra haag duality}) that the answer to Question~\ref{ques: core} has meaningful consequences for our present study.

In light of the above discussion, it is particularly satisfying that we will now be able to establish (`by hand') that the operators $V_{\pm i\pi}$ are self-adjoint on their given domain.
We first give the following straightforward lemma, which shows that they are symmetric.
\begin{lem}
If $\Phi \in D(V_\tau)$ and $\Phi' \in D(V_{-\overline{\tau}})$, then
\[
\ip{V_\tau\Phi,\Phi'} = \ip{\Phi,V_{-\overline{\tau}}\Phi'}.
\]
\end{lem}
\begin{proof}
Fix $\tau_0 \in \bbC$.
For notational clarity, we assume without loss of generality that $\Im(\tau_0) \ge 0$.
Fix $\Phi \in D(V_{\tau_0})$ and $\Phi' \in D(V_{-\overline{\tau_0}})$.
As $\Phi \in D(V_\tau)$, there is a map $G$ continuous on the strip $\{0 \le \Im(\tau) \le \Im(\tau_0)\}$ and holomorphic on the interior, satisfying
\[
G(t) = \ip{V_t\Phi,\Phi'}, \qquad G(t+\tau_0) = \ip{V_{\tau_0}\Phi,V_{-t}\Phi'}.
\]
Similarly, since $\Phi' \in D(V_{\tau_0})$ we have a map $H$ on the same strip (continuous on the closure and holomorphic on the interior) such that
\[
H(t) = \ip{V_t\Phi',\Phi}, \qquad H(t-\overline{\tau_0}) = \ip{V_{-\overline{\tau_0}}\Phi',V_{-t}\Phi}.
\]
By inspection, $\tau \mapsto \overline{H(-\overline{\tau})}$ is again continuous on the strip, holomorphic on the interior, and agrees with $G(\tau)$ on $\bbR$. 
Hence the two functions agree identically, and evaluating at $\tau_0$ yields the desired identity.
\end{proof}

We now give a careful analysis of the domain $D(V_{\pm i\pi}^*)$ in order to show that these operators are self-adjoint.

\begin{thm}\label{thm: Vipi selfadjoint}
On the domain $D(V_{i\pi})$ introduced in Definition~\ref{defn: Vs involutive}, $V_{i\pi}^* = V_{i\pi}$. Similarly, $V_{-i\pi}^* = V_{-i\pi}$.
\end{thm}
\begin{proof}
We only consider $V_{i\pi}$.
Fix $\Phi' \in D(V_{i\pi}^*)$, and we must show that $\Phi' \in D(V_{i\pi})$. 
Let $\Phi \in D(V_{i\pi})$, and let $G:\bbS \to \bbC$ be the continuous function (holomorphic in the interior) such that for all $t \in \bbR$ we have
\[
G(t) = \ip{V_t\Phi,\Phi'}, \qquad G(t+i\pi) = \ip{V_t V_{i\pi}\Phi, \Phi'},
\]
where as usual $\bbS=\{ \tau \in \bbC \, : \, 0 \le \Im(\tau) \le \pi\}$.
Note that $V_t$ leaves $D(V_{i\pi})$ invariant and commutes with $V_{i\pi}$, so for $t \in \bbR$
\[
G(t+i\pi)=\ip{V_{t}V_{i\pi}\Phi,\Phi'} = \ip{\Phi, V_{-t}V_{i\pi}^*\Phi'} .
\]
Define $H_\Phi:\bbS \to \bbC$ by $H_\Phi(\tau) = \overline{G(-\overline{\tau})}$, and note that $H_\Phi$ is again continuous on $\bbS$ and holomorphic in the interior.
We have for $t \in \bbR$
\begin{equation}\label{eqn: H boundary}
H_\Phi(t) = \ip{V_t \Phi', \Phi}, \qquad H_\Phi(t+i\pi) = \ip{V_t V_{i\pi}^*\Phi',\Phi}.
\end{equation}
In order to show that $\Phi' \in D(V_{i\pi})$, we must establish the existence of such a function $H_\Phi$ for all $\Phi \in \cD$, and we have done this so far when $\Phi \in D(V_{i\pi})$.

By Lemma~\ref{lem: X dense}, the closure of $\cP_\cX(I_+)\Omega$ contains $\cP(I_+)\Omega$, and thus $\cP_\cX(I_+)\Omega$ is dense by the Reeh-Schlieder theorem \cite[App. A]{CarpiRaymondTanimotoTener24ax}.
Given arbitrary $\Phi \in \cD$, choose a net $\Phi_n \in \cP_\cX(I_+)\Omega$ such that $\Phi_n \to \Phi$.
We will show that the net $H_{\Phi_n}$ converges locally uniformly on $\bbS$ to the required function $H_\Phi$.
Our first step is to show that this net is locally uniformly Cauchy.

Note that $\overline{H_{\Phi_n}(-\overline{\tau})}$ is a function of the form $G$ considered above, and so by Lemma~\ref{lem: growth estimate on S} (and the fact that $\Phi_n \in \cP_\cX(I_+)\Omega$) we can infer that $e^{-2\tau^2}H_{\Phi_n}$ vanishes at infinity.
It follows that $e^{-2\tau^2}H_{\Phi_n} - e^{-2\tau^2}H_{\Phi_m}(\tau)$ vanishes at infinity as well, and 
so 
\begin{equation}\label{eqn: H Cauchy}
\abs{e^{-2\tau^2}H_{\Phi_n}(\tau) - e^{-2\tau^2}H_{\Phi_m}(\tau)}
\end{equation}
is maximized on $\partial \bbS = \bbR \cup i\pi + \bbR$.
From \eqref{eqn: H boundary}, we see that the restriction of \eqref{eqn: H Cauchy} to each boundary component is a function $\bbR \to \bbC$ of the form
\[
t \mapsto C e^{-2t^2} \ip{V_t\Psi,\Phi_n-\Phi_m}
\]
for some $\Psi \in \cD$.
We will show that functions of the above form converge uniformly to zero as $n,m \to \infty$.

It suffices to consider $\Psi=\varphi_1(f_1) \cdots \varphi_k(f_k)\Omega$ for $f_j \in C^\infty(S^1)$.
We have
\[
e^{-2t^2} V_t\Psi = \varphi_1(e^{-2t^2/k}\beta_{d_1}(v_t)f_1) \cdots \varphi_k(e^{-2t^2/k}\beta_{d_k}(v_t)f_k)\Omega.
\]
From the proof of Lemma~\ref{lem: growth estimate on R} (specifically \eqref{eqn: exp growth bound CN norm}), we have $e^{-2t^2/k}\beta_d(v_t)f \to 0$ in $C^\infty(S^1)$ as $t \to \pm \infty$.
Hence $e^{-2t^2}V_t\Psi \to 0$ in $\cD$, or in other words $e^{-t^2}V_t \Psi$ extends to a continuous function $[-\infty,\infty] \to \cD$ which vanishes at infinity.
Since $[-\infty,\infty]$ is compact, the image of this map is a bounded subset of $\cD$, which means that for any open neighborhood $U$ of $0$ in $\cD$ there exists a scalar $M > 0$ such that $e^{-t^2}V_t \Psi \in M U$ for all $t$.

Since the Hermitian form is jointly continuous, given $\epsilon > 0 $ we may choose a neighborhood $U$ of $0$ in $\cD$ such that $\abs{\ip{\Phi_1,\Phi_2}} < \epsilon$ when $\Phi_j \in U$.
Choose $M > 0$ as above so that $V_t\Psi \in MU$ for all $t$, and note that $\abs{\ip{\Phi_1,\Phi_2}} < \epsilon$ when $\Phi_1 \in MU$ and $\Phi_2 \in M^{-1} U$.
Since $\Phi_n \to \Phi$, we may choose $n_0$ such that when $n,m \ge n_0$ we have $\Phi_n-\Phi_m \in M^{-1} U$.
We then have for all $t \in \bbR$
\[
\abs{e^{-2t^2} \ip{V_t\Psi,\Phi_n-\Phi_m} } < \epsilon,
\]
and so the sequence of functions $e^{-2t^2} \ip{V_t\Psi,\Phi_n-\Phi_m}$ converges uniformly to zero, as claimed.
As described above, it follows that $e^{-\tau^2}(H_{\Phi_n} - H_{\Phi_m})$ converges uniformly to zero.
Hence $H_{\Phi_n}$ is a locally uniformly Cauchy net of functions, which therefore converges locally uniformly to a function $H_{\Phi}$ that is continuous on $\bbS$ and holomorphic in the interior.
Taking pointwise limits on the boundary we see that $H_{\Phi}$ satisfies \eqref{eqn: H boundary}.
Since $\Phi$ was arbitrary, we conclude that $\Phi' \in D(V_{i \pi})$, as claimed.
\end{proof}

As an aside, we remark that the above proof of Theorem~\ref{thm: Vipi selfadjoint} does not go through verbatim for the operator $\widetilde V_{i\pi}$, with the key obstruction being that linear functionals of the form $\ip{\, \cdot \, , \Phi}$ may not be dense in $\cD_\cF^*$ in the strong dual topology (i.e. the topology of uniform convergence on bounded sets), although they are dense in the weak-$*$ topology (i.e. the topology of pointwise convergence).

\section{Haag duality for Wightman CFTs with invariant Hermitian forms}\label{sec: nonunitary duality}

In this section we continue the notation of Section~\ref{sec: sesquilinear}, fixing an involutive Wightman CFT. 
We will now study the notion of `Haag duality' for nets of algebras, which is a key application of Tomita-Takesaki theory in the unitary setting. Our first step will be to make contact with the theory of standard subspaces, which have proven to be very powerful in analyzing duality phenomena in algebraic quantum field theory \cite{LongoLectureNotesI,LongoLectureNotesII} (see also Section~\ref{sec: background unitary} for the unitary case).
The results in this section on Haag duality for non-unitary theories are exploratory at this stage, with the main result being some sufficient conditions for Haag duality of the double commutant net $\cP(I)''$, albeit conditions that may not be practical to check.
However, given how crucial Haag duality is in the study of nets of operator algebras, it is worthwhile to initiate the study in this non-unitary setting.
Furthermore, the results of this section will be applied in Section~\ref{sec: unitary} to gain insight into unitary models.

We first require a brief digression on topological notions.

\begin{defn}\label{defn: standard topologies}
    Let $\cD$ be a locally convex space with a nondegenerate Hermitian form.
    Then we refer to the given topology on $\cD$ as the \textbf{strong} topology, the weak topology on $\cD$ induced by the continuous dual $\cD^*$ as the \textbf{weak} topology, and the weak topology induced by the functionals $\{\ip{\, \cdot \, , \Phi} \, : \, \Phi \in \cD\}$ as the \textbf{$\cD$-weak} topology.
    We refer to these topologies as the \textbf{standard topologies} on $\cD$.
\end{defn}


In the context of an involutive Wightman theory, the strong topology is also known as the $\cF$-strong topology and the weak topology is also known as the $\cF$-weak topology.
The strong topology is stronger than the weak topology, which is stronger than the $\cD$-weak topology.
By the Hahn-Banach theorem, a convex subset of $\cD$ is strong closed if and only if it is weakly closed, but a strongly closed subspace of $\cD$ may not be $\cD$-weakly closed.
However, the results we will obtain below hold for any choice of standard topology.

\begin{defn}
    Let $\cD$ be a locally convex space with nondegenerate Hermitian form, equipped with one of its standard topologies.
    A closed real subspace $K \subset \cD$ is called \textbf{cyclic} (with respect to the topology) if $K + iK$ is dense in $\cD$, and called \textbf{separating} if $K \cap iK =\{0\}$.
    A closed real subspace is called \textbf{standard} if it is both cyclic and separating.
\end{defn}

To a standard subspace $K$, we can associate a densely defined conjugate-linear involution $S_K$ with domain $D(S_K) = K+iK$ given by $S_K(\Phi_1+i\Phi_2) = \Phi_1 - i \Phi_2$ for $\Phi_j \in K$.
The term involution here means that $S_K^2 = \mathrm{Id}_{D(S_K)}$.
The subspace $K$ is recovered as the fixed points of $S_K$.
The following is standard, although we include a proof to emphasize that unitarity is not required.

\begin{lem}\label{lem: std subspace vs involution}
    Let $\cD$ be a locally convex space with nondegenerate Hermitian form, equipped with one of its standard topologies.
Then the correspondence $K \leftrightarrow S_K$ induces a bijection between i) standard subspaces $K$ of $\cD$, and 2) closed conjugate-linear involutions $S$
\end{lem}
\begin{proof}
We need to check that $S_K$ is closed, and that every closed conjugate linear involution $S$ is of the form $S_K$.
To the first end, suppose that $\Phi_n \in D(S_K)=K+iK$, that $\Phi_n \to \Phi$ in $\cD$, and that $S_K\Phi_n \to \Psi$.
Let $\Phi_{1,n} = \frac{\Phi_n + S_K\Phi_n}{2}$ and $\Phi_{2,n} = \frac{\Phi_n - S_K \Phi_n}{2i}$, and note that $\Phi_n = \Phi_{1,n} + i \Phi_{2,n}$.
We then have $S_K \Phi_{j,n} = \Phi_{j,n}$, so that $\Phi_{j,n} \in K$.
Moreover $\Phi_{1,n} \to \frac{\Phi + \Psi}{2}$ and $\Phi_{2,n} \to \frac{\Phi - \Psi}{2i}$, and these vectors lie in $K$ since $K$ is closed.
Hence 
\[
\Phi = \lim \Phi_{1,n} + i \lim \Phi_{2,n} \in K + i K = D(S_K),
\]
and 
\[
S_K\Phi = \Psi = \lim \Phi_{1,n} - i \lim \Phi_{2,n} = \lim S_K \Phi_n.
\]
We conclude that $S_K$ is closed.

To complete the proof, we must show that given a closed densely-defined conjugate-linear involution $S$, the fixed points $K=\operatorname{Ker}(S-1)$ are a standard subspace such that $D(S)=K+iK$.
The argument is routine.
If $\Phi \in K \cap iK$, then applying $S$ yields $\Phi = - \Phi$ and so $\Phi = 0$ and $K$ is separating.
Moreover if $\Phi \in D(S)$ then $\frac{\Phi+S\Phi}{2}, \frac{\Phi-S\Phi}{2i} \in K$.
Hence $\Phi \in K + iK$, so $D(S) \subset K+iK$.
Since $D(S)$ is assumed dense, $K$ is cyclic.
Moreover $K$, and thus $K+iK$ are contained in $D(S)$ by construction, so we evidently have $D(S)=K+iK$ as required.
\end{proof}

\begin{defn}
    If $K \subset \cD$ is a real subspace, the \textbf{complementary subspace} $K'$ is defined by
    \[
    K' = \{ \Phi \in \cD \, : \ip{\Phi,\Psi} \in \bbR \, \text{ for all } \Psi \in K\}.
    \]
    This is the same as the perpendicular subspace to $iK$ with respect to the real form $\Re \ip{\, \cdot \, , \, \cdot \,}$.
\end{defn}

As described before Question~\ref{ques: core}, taking complements does not behave the same as in the Hilbert space case, as even when the form on $\cD$ is positive definite, the complement could be `unexpectedly small.'
For this reason, even when $K$ is standard the space $K'$ may fail to be cyclic, and even if $K'$ is standard we may have $K \subsetneq K''$.
We can, however, establish some basic results below in Lemma~\ref{lem: SK adjoint}.
First, the reader is reminded that the relation between a conjugate-linear operator $X$ and its adjoint $X^*$ is
\[
\ip{X\Phi,\Psi} = \ip{X^*\Psi,\Phi},
\]
and the definition of the domain $D(X^*)$ is adjusted accordingly.

\begin{lem}\label{lem: SK adjoint}
Let $\cD$ be a locally convex space with nondegenerate Hermitian form, equipped with one of its standard topologies.
Let $K \subset \cD$ be a closed real subspace.
\begin{enumerate}[(i)]
\item If $K$ is cyclic then $K'$ is separating, and if $K'$ is cyclic then $K$ is separating.
\item If $K$ is standard, then $K'$ is standard if and only if $S_K^*$ is densely defined, in which case $S_{K'} = S_K^*$.
\end{enumerate}
\end{lem}
\begin{proof}
    We first prove (i). Suppose $K$ is cyclic and $\Phi \in K' \cap iK'$.
    It follows that $\ip{\Phi,\Psi} \in \bbR \cap i \bbR$ for all $\Psi \in K$.
    Hence $\ip{\Phi,\Psi} = 0$ for all $\Psi \in K$, and indeed for all $\Psi \in K + i K$.
    Since $K$ is cyclic and the form is nondegenerate, we conclude that $\Phi=0$ and $K'$ is separating.
    On the other hand, if $K'$ is cyclic, then $K''$ is separating by the previous work, and so $K \subseteq K''$ is separating as well.

    We now prove (ii).
    Assume $K$ is standard, so by part (i) $K'$ is separating.
    Since $S_K$ is an involution, $D(S_K^*)$ is invariant under $S_K^*$ and $S_K^*$ is an involution as well.
    Let $\tilde K = \operatorname{ker}(S_K^*-1)$, and arguing as before yields $D(S_K^*) = \tilde K + i \tilde K$.
    Thus to prove (ii) it suffices to prove that $\tilde K = K'$.
    Indeed for $\Phi \in K$ and $\Psi \in \cD$ we have
    \[
    \ip{S_K\Phi,\Psi} = \ip{\Phi,\Psi} = \overline{\ip{\Psi,\Phi}}.
    \]
    Hence if $\Psi \in K'$ we see $\ip{S_K\Phi,\Psi} = \ip{\Psi,\Phi}$, which shows that $\Psi \in D(S_K)^*$ and $S_K^*\Psi = 1$, i.e., $\Psi \in \tilde K$.
    Conversly, if $\Psi \in \tilde K$ then $\ip{S_K\Phi,\Psi} = \ip{\Psi,\Phi}$, and we see that $\ip{\Psi,\Phi} \in \bbR$, so that $\Psi \in K'$.
    We conclude $K' = \tilde K$, completing the proof of (ii).
\end{proof}

We note that even when $K$ and $K'$ are both standard, we have not ruled out the possibility that $K \subsetneq K''$ and $S_K \subsetneq S_K^{**}$.
Typically one would expect this if $K$ were a standard subspace for the strong topology on $\cD$ but not $\cD$-weakly closed, as $K''$ would contain the $\cD$-weak closure.

We now return to our study of involutive Wightman CFTs $(\cF,\cD,U,\Omega)$.
\begin{defn}
    Given an interval $I$, we denote by $\cP(I)_{sa} \subset \cP(I)$ the real subspace of self-adjoint elements, and the corresponding real subspace of $\cD$ is denoted $\cK(I) := \overline{\cP(I)_{sa}\Omega}$, where the closure is taken in the strong (or equivalently weak) topology.
    We denote by $\cK_w(I)$ the closure of $\cK(I)$ in the $\cD$-weak topology.
\end{defn}

The reader is reminded that if $I \subset S^1$ is an interval, then $I'$ denotes the complementary interval.

\begin{lem}\label{lem: KI standard}
    For each interval $I$, the subspaces $\cK(I)$ and $\cK(I)'$ are standard subspaces of $\cD$, and $\cK(I') \subset \cK(I)'$.
    The same holds for the subspaces $\cK_w(I)$ and $\cK_w(I')$.
\end{lem}
\begin{proof}
    Observe that $\cK(I)$ contains $\cP(I)\Omega$, which is dense by the Reeh-Schlieder theorem, and so each $\cK(I)$ is cyclic.
    If $x \in \cP(I)_{sa}$ and $y \in \cP(I')_{sa}$, then locality for the net $\cP(I)$ implies that 
    \[
    \ip{x\Omega, y\Omega} = \ip{yx\Omega,\Omega} = \ip{xy\Omega,\Omega} = \ip{y\Omega,x\Omega} = \overline{\ip{x\Omega,y\Omega}}.
    \]
    Hence $\ip{x\Omega,y\Omega} \in \bbR$, and we see that $\cK(I') \subseteq \cK(I)'$.
    Since $\cK(I')$ is cyclic, so is $\cK(I)'$ whence $\cK(I)$ is separating by Lemma~\ref{lem: SK adjoint}.
    We have shown that $\cK(I)$ is standard and that $\cK(I)'$ is cyclic, and the fact that $\cK(I)'$ is separating again follows from Lemma~\ref{lem: SK adjoint}.

    In the case of $\cK_w$, note that $\cK(I)' = \cK_w(I)'$ and $\cK(I) \subset \cK_w(I)$.
    It immediately follows from the above that $\cK_w(I)'$ is standard, that $\cK_w(I') \subset \cK_w(I)'$, and that $\cK_w(I)$ is cyclic.
    The fact that $\cK_w(I)$ is separating follows again from Lemma~\ref{lem: SK adjoint}.
\end{proof}

From here it is straightforward to see that the spaces $\cK(I)$ and $\cK_w(I)$ each enjoy the following structure:

\begin{defn}\label{def: mob covariant net nonunitary}
    Let $\cD$ be a locally convex space equipped with a jointly continuous nondegenerate Hermitian form and a strongly continuous untiary representation $U:\Mob \to \End(\cD)$.
    A \textbf{(non-unitary) M\"obius-covariant net of standard subspaces} is a collection of standard subspaces $\cK(I) \subset \cD$ such that the following holds:
    \begin{enumerate}[1)]
        \item Isotony: If $I_1 \subseteq I_2$, then $\cK(I_1) \subseteq \cK(I_2)$.
        \item M\"obius covariance: $U(\gamma)\cK(I) = \cK(\gamma(I))$.
        \item Locality: $\cK(I') \subset \cK(I)'$.
    \end{enumerate}
\end{defn}

\begin{rem}
    Note that if the subspaces $\cK(I)$ are only assumed cyclic then standardness follows from locality, as in the proof of Lemma~\ref{lem: KI standard}.
    One could hope to replace cyclicity of each $\cK(I)$ with a weaker condition of being jointly cyclic. The question of whether this a priori weaker definition is equivalent is asking whether the Reeh-Schlieder phenomenon occurs, but we do not pursue this question.
    Without any positive energy assumption on $U$, one should not expect to deduce too much from axioms presented in Definition~\ref{def: mob covariant net nonunitary}; we include the definition to capture the structure we observe in our example.
\end{rem}

We have thus proven:

\begin{prop}
Let $(\cF,\cD,U,\Omega)$ be an involutive Wightman CFT on $S^1$.
Then the family of subspaces $\cK(I)=\overline{\cP(I)_{sa}\Omega}$ is a M\"obius-covariant net of standard subspaces of $\cD$ with respect to the representation $U$ of $\Mob$.
The same holds for the $\cD$-weak closures $\cK_w(I)$ of $\cK(I)$.
\end{prop}
\begin{proof}
    The standardness of the subspaces $\cK(I)$ and the locality axiom are Lemma~\ref{lem: KI standard}, and the other requirements are immediate from properties of the algebras $\cP(I)$.
\end{proof}

A key question which arises in this context, and has been extensively studied in various guises, is that of duality.

\begin{defn}
    Let $\cD$ be a locally convex space with nondegenerate Hermitian form.
    A M\"obius-covariant net of standard subspaces satisfies \textbf{Haag duality} if $\cK(I')=\cK(I)'$ for all intervals $I$.
    We call the net \textbf{weakly Haag dual} if the $\cD$-weak closures $\cK_w(I) = \overline{\cK(I)}$  are Haag dual.
\end{defn}

In the context of positive energy nets of standard subspaces of a Hilbert space, Haag duality is automatic \cite[Thm. 3.3.1]{LongoLectureNotesI}.
We now investigate the question of Haag duality for the nets of standard subspaces arising from a Wightman CFT.

\begin{lem}\label{lem: dual standard subspaces}
\text{}

    \begin{enumerate}[(i)]
    \item As unbounded operators, $\theta V_{\pm i\pi} \theta = V_{\mp i \pi}$ and $V_{i\pi}^{-1} = V_{-i\pi}$.
    \item The operators $S_\pm = \theta V_{\pm i \pi}$ are closed conjugate-linear involutions (with respect to every standard topology) and $S_{\pm}^* = S_{\mp}$.
    \item If $\cL_{\pm}$ is the standard subspace corresponding to $S_{\pm}$, then $\cL_{\pm}' = \cL_{\mp}$, $\cK(I_\pm) \subset \cK_w(I_\pm) \subset \cL_{\pm}$, and $V_t\cL_{\pm} = \cL_{\pm}$ for all $t \in \bbR$.
    \end{enumerate}
\end{lem}
\begin{proof}
    We first show that $\theta$ maps $D(V_{i \pi})$ into $D(V_{-i\pi})$.
    Indeed if $\Phi \in D(V_{i\pi})$ and $\Phi' \in \cD$, then we have a map $G_{\Phi'}:\bbS_\pi \to \bbC$ that is continuous and holomorphic in the interior, and
    \[
    G_{\Phi'}(t) = \ip{V_t\Phi, \Phi'}, \qquad G_{\Phi'}(t+i\pi) = \ip{V_tV_{i\pi} \Phi,\Phi'}.
    \]
    Define $H_{\Phi'}:\bbS_{-\pi} \to \bbC$ by $H_{\Phi'}(\tau) = \overline{G_{\theta \Phi'}(\overline{\tau})}$.
    Since $\theta$ commutes with $V_t$, we have
    \[
    H_{\Phi'}(t) = \overline{\ip{V_t\Phi,\theta\Phi'}} = \ip{V_t\theta\Phi,\Phi'}
    \]
    and similarly
    \[
    H_{\Phi'}(t-i\pi) = \overline{\ip{V_tV_{i\pi}\Phi,\theta \Phi'}} = \ip{V_t\theta V_{i\pi} \Phi,\Phi'}.
    \]
    Hence $\theta\Phi \in D(V_{-i\pi})$ and $V_{-i\pi}\theta\Phi = \theta V_{i\pi}\Phi$.
    The same argument shows that if $\Phi \in D(V_{-i\pi})$ then $\theta \Phi \in D(V_{i\pi})$ and $\theta V_{-i\pi}\Phi = V_{i\pi}\theta \Phi$.
    Since $\theta$ is an involution and maps $D(V_{\pm i \pi})$ into $D(V_{\mp i \pi})$, we actually must have $\theta D(V_{\pm i \pi}) = D(V_{\mp i \pi})$, and so from our previous calculations $\theta V_{\pm i \pi} \theta = V_{\mp i \pi}$.
    A very similar calculation, this time defining $H_{\Phi'}(\tau) = G_{\Phi'}(\tau - i\pi)$, shows that $V_{\pm i\pi} V_{\mp i\pi} = \mathrm{Id}_{D(V_{\mp i\pi})}$, completing (i).

    From part (i), we see that $S_{\pm}^2 = V_{\mp i \pi} V_{\pm i \pi} = \mathrm{Id}_{D(\pm i \pi)} = \mathrm{Id}_{D(S_{\pm})}$, and so $S_{\pm}$ are conjugate-linear involutions.
    The maps $V_{\pm i\pi}$ are closed for the $\cD$-weak topology (and so for every standard topology) since adjoints are automatically $\cD$-weakly closed and $V_{\pm i\pi}$ are self-adjoint. 
    Hence $S_{\pm}$ are closed as well, and we have
    \[
    S_{\pm}^* = V_{\pm i \pi}\theta = \theta V_{\mp i \pi} = S_{\mp}
    \]
    where we note that the first equality is not immediate but easy to verify. This completes (ii).

    The identity $\cL_{\pm}' = \cL_{\mp}$ now follows from Lemma~\ref{lem: SK adjoint}.
    By definition $\cL_{\pm}$ consists of fixed points of $S_{\pm}$, and so $\cP(I_{\pm})_{sa}\Omega \subset \cL_{\pm}$ by Theorem~\ref{thm: involutive BW}.
    Taking closures yields $\cK(I_{\pm}) \subset \cL_{\pm}$.
    Finally note that $V_t$ commutes with both $\theta$ and $V_{\pm i \pi}$, and so with $S_{\pm}$.
    Hence $V_t$ leaves $\cL_{\pm}$ invariant for all $t$, which implies that $V_t\cL_{\pm} = \cL_{\pm}$.
\end{proof}

\begin{cor}\label{cor: haag dual subspace net}
The net of standard subspaces $\cK(I) = \overline{\cP(I)_{sa}\Omega}$ satisfies Haag duality if and only if $\cP(I_+)\Omega$ is a core for $V_{i\pi}$ for the $\cF$-strong topology.
Similarly $\cK_w(I)$ satisfies Haag duality if and only if $\cP(I_+)\Omega$ is a core for $V_{i\pi}$ for the $\cD$-weak topology.
\end{cor}
\begin{proof}
If $\cP(I_+)\Omega$ is a $\cF$-strong core for $V_{i\pi}$ then $\cK(I_+) = \cL_+$, and applying $\theta$ yields $\cK(I_-) = \cL_-$.
Hence by Lemma~\ref{lem: dual standard subspaces} we have $\cK(I_{\pm})' = \cK(I_{\mp})$.
Haag duality then follows from M\"obius covariance.
For the converse, suppose the net is Haag dual, which is to say $\cK(I_\pm)' = \cK(I_\mp)$.
By Lemma~\ref{lem: dual standard subspaces} we have 
\[
\cK(I_\pm) \subset \cL_{\pm} = \cL_{\mp}' \subset \cK(I_{\mp})' = \cK(I_{\pm}).
\]
As the first and last terms coincide, we have $\cK(I_{\pm}) = \cL_{\pm}$ and so $\cP(I_+)$ is a $\cF$-strong core for $V_{i\pi}$.
The proof for the $\cD$-weak topology is similar.
\end{proof}

\begin{rem}\label{rem: inclusion of standard subspaces}
We see from the proof of Corollary~\ref{cor: haag dual subspace net} that the key question for (weak) Haag duality is whether the inclusion $\cK(I_\pm) \subset \cL_{\pm}$ is an equality.
This is an inclusion of standard subspaces, the involution $S_{\pm}$ satisfies $S_{\pm} = \theta V_{\pm i\pi}$, and $\cK(I_{\pm})$ is invariant under $V_t$.
In the unitary setting the identity $\cK(I_{\pm}) = \cL_{\pm}$ would follow (see e.g. \cite[Prop. 2.1.10]{LongoLectureNotesI}), but we do not see an immediate generalization to our context.
\end{rem}

\begin{rem}\label{rem: not isotone}
In light of Lemma~\ref{lem: dual standard subspaces}, one could alternatively try to construct a Haag dual M\"obius covariant net of standard subspaces as follows.
    Given an interval $I$, choose $\gamma \in \Mob$ such that $\gamma(I_+) = I$, and set $\cL(I) = U(\gamma)\cL_+$.
Since $\gamma(I_+) = I_+$ exactly when $\gamma=v_t$ for some $t$, and $V_t \cL_+ = \cL_+$, the subspace $\cL(I)$ does not depend on the choice of $\gamma$, and in particular $\cL(I_+) = \cL_+$.
If $r_\pi \in \Mob$ is rotation by $\pi$, then $U(r_\pi)V_t U(r_\pi)^{-1} = V_{-t}$ and it is then straightforward to check that $U(r_\pi)V_{i\pi}U(r_{\pi})^{-1} = V_{-i\pi}$. Hence $\cL(I_-)=\cL_-$ as well.
This collection of standard subspaces is Haag dual (in particular, local) and M\"obius covariant, but does not visibly satisfy isotony.
\end{rem}

We conclude this section with a discussion of Haag duality for nets of algebras.
As with standard subspaces, we have a preliminary definition of a local net of algebras (for which one does not expect a robust general theory, in part because of the lack of a positive energy condition).


\begin{defn}\label{def: mob covariant net algebras nonunitary}
    Let $\cD$ be a locally convex space equipped with a jointly continuous nondegenerate Hermitian form, a strongly continuous untiary representation $U:\Mob \to \End(\cD)$, and a choice of non-zero vector $\Omega \in \cD$.
    A \textbf{(non-unitary) M\"obius-covariant net of algebras} is a collection of unital $*$-subalgebras $\cQ(I) \subset \End_*(\cD)$ such that the following holds:
    \begin{enumerate}[1)]
        \item Isotony: If $I_1 \subseteq I_2$, then $\cQ(I_1) \subseteq \cQ(I_2)$.
        \item M\"obius covariance: $U(\gamma)\cQ(I)U(\gamma)^{-1} = \cQ(\gamma(I))$.
        \item Locality: $\cQ(I)$ and $\cQ(I')$ commute for all intervals $I$.
        \item Vacuum: the vector $\Omega$ is fixed by $\Mob$ and is cyclic for each algebra $\cQ(I)$. 
    \end{enumerate}
    The net is called \textbf{Haag dual} if $\cQ(I)' = \cQ(I')$.
    Here we have used the notation that if $S \subset \End_*(\cD)$, then $S'$ denotes the commutant, consisting of all operators in $\End_*(\cD)$ which commute with $S$ elementwise.
\end{defn}

It is straightforward to check that if $\cQ(I)$ is a net of algebras as above, then $\cK(I) = \overline{\cQ(I)_{sa}\Omega}$ is a net of standard subspaces as in Definition~\ref{def: mob covariant net nonunitary}.

Returning to our Wightman CFT, the net of algebras $\cP(I)$ evidently satisfies the conditions of Definition~\ref{def: mob covariant net nonunitary}.
Indeed, the net $\cQ(I):=\cP(I)''$ is also a M\"obius-covariant  net of algebras (the only condition to check is locality, which follows formally from taking  two commutants of the inclusion $\cP(I) \subset \cP(I')'$).

We will verify that Haag duality occurs under a pair of reasonable-looking (but presumably difficult to verify) conditions.
The two arguments share an important technical (but standard) step, which we distil into the following lemma. 

\begin{lem}\label{lem: algebra commutant inclusion}
Let $\cD$ be a locally convex vector space equipped with a jointly continuous nondegenerate Hermitian form and let $\Omega \in \cD$.
Let $A,B \subset \End_*(\cD)$ be unital $*$-subalgebras, and let $\theta$ be an antiunitary involution on $\cD$ such that $\theta \Omega = \Omega$.
Suppose that the following hold:
\begin{enumerate}[(i)]
\item Suppose that for all $X,Y \in A_{sa}$ we have $\ip{\theta X\Omega,Y\Omega} \in \bbR$.
\item Suppose $B\Omega$ is $\cD$-weakly dense in $\cD$,  that $B$ commutes with $A$, and that $\theta B \theta \subset A$.
\end{enumerate}
Then we have $\theta A\theta \subset A'$.
\end{lem}
\begin{proof}
    Let $X,Y \in A_{sa}$, so that by assumption we have $\ip{\theta X\Omega, Y\Omega} = \ip{Y\Omega, \theta X\Omega}.$
Since $\theta\Omega = \Omega$, this becomes
\[
\ip{\theta X \theta Y \Omega, \Omega} = \ip{Y\theta X \theta \Omega, \Omega}.
\]
Both sides of the above identity are conjugate linear in $X$ and linear in $Y$, so it extends to all $X,Y \in A$.
If $S,T \in B$, then $\theta S \theta, \theta T \theta \in A$.
Thus we apply the above identity with $X$ replaced by $\theta T \theta X\theta S \theta$ to obtain
\[
\ip{T \theta X \theta S Y \Omega, \Omega} = \ip{YT\theta X \theta S \Omega, \Omega}
\]
for all $X,Y \in A$ and $S,T \in B$.
Since $S$ and $T$ commute with $Y$, this becomes
\[
\ip{(\theta X \theta)Y S\Omega, T^*\Omega} = \ip{Y(\theta X \theta)S\Omega, T^*\Omega}.
\]
Now for arbitrary $\Phi' \in \cD$ choose a net $T_m^*\Omega \in B\Omega$ such that $T_m^*\Omega \to \Phi'$ in the $\cD$-weak topology.
Taking the limit of the identity
\[
\ip{(\theta X \theta)Y S\Omega, T^*_m\Omega} = \ip{Y(\theta X \theta)S\Omega, T^*_m\Omega}.
\]
yields 
\[
\ip{(\theta X \theta)Y S\Omega, \Phi'} = \ip{Y(\theta X \theta)S\Omega, \Phi'}.
\]
Now for arbitrary $\Phi \in \cD$ choose a net $S_n\Omega \in B\Omega$ such that $S_n\Omega \to \Phi$.
We now have
\[
\ip{ S_n\Omega, [(\theta X \theta)Y]^*\Phi'} = \ip{(\theta X \theta)Y S_n\Omega, \Phi'} = \ip{Y(\theta X \theta)S_n\Omega, \Phi'} = \ip{S_n\Omega, [Y(\theta X \theta)]^*\Phi'}.
\]
Taking the limit yields
\[
\ip{(\theta X \theta)Y \Phi, \Phi'} = \ip{Y(\theta X \theta)\Phi, \Phi'}.
\]
Since $\Phi,\Phi' \in \cD$ were arbitrary, we see that $\theta X \theta$ and $Y$ commute.
Hence $\theta X \theta \in A'$, which completes the proof.
\end{proof}

We can now give sufficient conditions for Haag duality of the net $\cQ(I)$:

\begin{prop}\label{prop: algebra haag duality}
    Let $\cQ(I)$ be the M\"obius-covariant net of algebras $\cQ(I)=\cP(I)''$.
    Then any one of the following conditions individually implies that $\cQ$ is Haag dual:
    \begin{enumerate}[(a)]
        \item The net of standard subspaces $\cK(I)$ is weakly Haag dual, i.e. $\cK_w(I') = \cK_w(I)'$ 
        \item $\cP(I_+)\Omega$ is a core for $V_{i\pi}$ for any standard topology
        \item $\cP(I_+)'' = \overline{\cP(I_+)}$ where the closure is taken in the $\cD$-weak operator topology\footnote{That is, the topology of $\cD$-weak pointwise convergence.}.
    \end{enumerate}
\end{prop}
\begin{proof}
First consider assumption (a).
We know that $\theta \cP(I_+) \theta = \cP(I_-)$, and taking double commutants yields $\theta \cQ(I_+) \theta = \cQ(I_-)$.
Thus to establish Haag duality, we must show $\theta \cQ(I_+) \theta = \cQ(I_+)'$.
The locality axiom implies that $\theta \cQ(I_+) \theta \subset \cQ(I_+)'$, so we need only show the reverse inclusion. Plugging in $\cQ(I)=\cP(I)''$, we wish to show $\cP(I_+)'''  \subset \theta \cP(I_+)'' \theta $.
It suffices to show that $\theta \cP(I_+)' \theta \subset \cP(I_+)''$, and then take commutants.

We will establish this last inclusion by invoking Lemma~\ref{lem: algebra commutant inclusion} with $A=\cP(I_+)'$ and $B = \cP(I_+)$.
The conclusion of the lemma is exactly the required inclusion, so we just verify that the two hypotheses hold.
We first consider hypothesis (i) of the Lemma.
Note that if $X \in \cP(I_+)'$ and $X=X^*$, then for all $Y \in \cP(I_+)_{sa}$ we have $\ip{X\Omega,Y\Omega} \in \bbR$, and so $X\Omega \in \cK(I_+)' = \cK_w(I_-)$ by assumption (a).
Similarly $(\cP(I_-)')_{sa}\Omega \subset \cK_w(I_+)$, and so $(\cP(I_+)')_{sa}\Omega$ and $(\cP(I_-)')_{sa}\Omega$ are in particular local.
If $X,Y \in (\cP(I_+)')_{sa}$, then $\theta X \theta \in \cP(I_-)'$ so
\[
\ip{\theta X\Omega, Y\Omega} \in \bbR
\]
which establishes condition (i) of the Lemma.
Condition (ii) is straightforward, so the Lemma says that $\theta \cP(I_+)'\theta \subset \cP(I_+)''$, as was required to complete the proof in case (a).

Assumption (b) implies (a) by Corollary~\ref{cor: haag dual subspace net}, so we move on to assumption (c).
As above, we need to show $\theta \cQ(I_+) \theta \subset \cQ(I_+)'$.
We will invoke Lemma~\ref{lem: algebra commutant inclusion} with $A=\cQ(I_+)=\cP(I_+)''$ and $B= \cP(I_-)$.
We first verify condition (i) of the Lemma.
Let $X,Y \in \cQ(I_+)_{sa}$.
By assumption (c), we may choose nets $X_n$ and $Y_m$ in $\cP(I_+)$ such that $X_n \to X$ and $Y_m \to Y$ in the weak operator topology.
Replacing $X_n$ by $\tfrac12(X_n+X_n^*)$, and similarly for $Y_n$, we may assume that $X_n=X_n^*$ and $Y_n=Y_n^*$.
Then $\theta X_n\Omega \in \cK(I_-)$ and $Y_n\Omega \in \cK(I_+)$, so we have
\[
\ip{\theta X_n\Omega, Y_m\Omega} \in \bbR.
\]
Taking limits first in $n$ and then in $m$ yields $\ip{\theta X\Omega, Y\Omega} \in \bbR$, establishing (i).
Condition (ii) is straightforward, and we conclude that $\theta \cQ(I_+) \theta \subset \cQ(I_+)'$, completing the proof.
\end{proof}


\section{Applications for unitary CFTs}\label{sec: unitary}

A \textbf{unitary} Wightman CFT $(\cF,\cD,U,\Omega)$ is an involutive Wightman CFT with antiunitary PCT operator $\theta$ (see the opening of Section~\ref{sec: sesquilinear}) for which the invariant Hermitian form is positive definite, i.e. an inner product, and normalized so that $\norm{\Omega}=1$.
In this case $\cD$ embeds continuously in its Hilbert space completion $\cH$ (see \cite[\S2.3]{RaymondTanimotoTener22}).

In addition to the standard topologies ($\cF$-strong, $\cF$-weak, and $\cD$-weak; see Definition~\ref{defn: standard topologies}), the space $\cD$ has a norm topology.
The relative strength of these topologies is summarized in the diagram below, with arrows going from stronger topologies to weaker topologies: 
\[
\begin{tikzpicture}[arrow/.style={-{Latex}, thick}]
  % Nodes 
  \node (E) at (0,0) {$\cF$-strong};
  \node (C) at (-1.5,-1.2) {norm};
  \node (D) at (1.5,-1.2) {$\cF$-weak};
  %\node (B) at (0,-2.4) {weak norm};
  %\node (A) at (0,-3.6) {$\cD$-weak};
  \node (B) at (0,-2.4) {$\cD$-weak};

  % Arrows 
  \draw[arrow] (E) -- (C);
  \draw[arrow] (E) -- (D);
  \draw[arrow] (C) -- (B);
  \draw[arrow] (D) -- (B);
  %\draw[arrow] (B) -- (A);
\end{tikzpicture}
\]
As usual, let $\cP(I) \subset \End_*(\cD)$ be the unital $*$-algebra generated by $\varphi(f)$ with $\operatorname{supp} f \subset I$, and let $\cP(I)_{sa}$ be the real subspace of self-adjoint elements.
In Section~\ref{sec: nonunitary duality} we defined $\cK(I)$ and $\cK_w(I)$ to be the closure of $\cP(I)_{sa}\Omega$ in the $\cF$-strong and $\cD$-weak topologies, respectively.
Let $\cK_n(I)$ be the closure in $\cD$ of $\cP(I)_{sa}\Omega$ in the norm topology, and let $\hat \cK_n(I)$ be the closure of $\cP(I)_{sa}\Omega$ in $\cH$.
We have
\[
\cK(I) \subset \cK_n(I) \subset \cK_w(I), \qquad \cK_n(I) \subset \hat \cK_n(I).
\]

\begin{prop}\label{prop: unitary K weakly haag dual}
    The net $\hat \cK_n(I)$ is a Haag dual M\"obius covariant net of standard subspaces of $\cH$.
    The net $\cK_n(I)$ is a Haag dual M\"obius covariant net of standard subspaces of $\cD$, and $\cK_n(I)=\cK_w(I)=\cK(I)''$.
\end{prop}
\begin{proof}
    The locality, M\"obius covariance, and isotony of the net $\hat \cK_n$ is inherited from $\cK$.
    Haag duality for this net then follows by general theory \cite[Thm. 3.3.1]{LongoLectureNotesI}.
    Haag duality for $\cK_n$ then follows from the fact that $\cK_n(I) = \hat \cK_n(I) \cap \cD$ and that $\cK_n(I)$ is dense in $\hat \cK_n(I)$ for each interval $I$.
    Since $\cK_n(I)$ is $\cD$-weakly dense in $\cK_w(I)$, we have $\cK_w(I)' = \cK_n(I)' = \cK_n(I') \subseteq \cK_w(I')$. Locality for $\cK_w$ furnishes the opposite inclusion $\cK_w(I') \subset \cK_w(I)'$, and we conclude that $\cK_w$ is Haag dual and $\cK_n = \cK_w$.
    Since $\cK(I)$ is $\cD$-weakly dense in $\cK_w(I)$, we have $\cK(I)' = \cK_w(I)' = \cK_w(I')$, and by Haag duality for $\cK_w$ it follows that $\cK(I)'' = \cK_w(I)$.
\end{proof}

Recall that we considered the nets of algebras $\cQ(I) = \cP(I)''$, where the commutant is taken in $\End_*(\cD)$.
This is a local M\"obius covariant net of $*$-algebras, and we obtained in Section~\ref{sec: nonunitary duality} several conditions which implied Haag duality for this net of algebras.
As a result, we can show the following.

\begin{cor}\label{cor: unitary algebra haag duality}
Let $(\cF,\cD,U,\Omega)$ be a unitary Wightman CFT.
    Let $\cP(I) \subset \End_*(\cD)$ be the unital algebra generated by operators $\varphi(f)$ with $\varphi \in \cF$ and $\operatorname{supp} f \subset I$, and let $\cQ(I) = \cP(I)''$.
    Then $\cQ(I)$ is a Haag dual M\"obius covariant net of algebras.
\end{cor}
\begin{proof}
    The net $\cK_w(I)$ is Haag dual by Proposition~\ref{prop: unitary K weakly haag dual}, and so $\cQ$ is Haag dual by Proposition~\ref{prop: algebra haag duality}.
\end{proof}

Recall from Section~\ref{sec: background unitary} that given a standard subspace $K$ of a Hilbert space $\cH$, we have a corresponding conjugate linear closed involution $S_K$ with polar decomposition $S_K = J\Delta^{1/2}$.
Given a M\'obius covariant net of standard subspaces $\cK(I) \subset \cH$, covariant with respect to the unitary representation $U$ of $\Mob$ on $\cH$, then the Bisognano-Wichmann property for $\cK$ \cite[Thm. 3.3.1]{LongoLectureNotesI} states that the modular automorphisms $\Delta_\pm^{it}$ for $\cK(I_\pm)$ are given by
\begin{equation}\label{eqn: Delta pm it}
\Delta_{\pm}^{it} = U(v_{\mp 2\pi t}),
\end{equation}
where $v_t$ is the one-parameter subgroup of $\Mob$ fixing $I_{\pm}$ defined in Section~\ref{sec: background unitary}.
In Definition~\ref{defn: Vs involutive}, we considered densely defined operators $V_{\pm i \pi}$ on $\cD$ which were analytic continuations of the group $U(v_{t})|_{\cD}$.
It is therefore not surprising that the modular operator $\Delta_{\pm}^{1/2}$ is connected to $V_{\pm i\pi}$, and in fact we have an identity of unbounded operators.

\begin{thm}\label{thm: modular for unitary}
    Let $(\cF,\cD,U,\Omega)$ be a unitary Wightman CFT with PCT operator $\theta$, and let $\cH$ be the Hilbert space completion of $\cD$.
    Let $\hat \cK_n(I) \subset \cH$ be the corresponding net of standard subspaces defined as the closure of $\cP(I)_{sa}\Omega$.
    Let $V_{\pm i\pi}$ be the densely defined operators on $\cD$ defined in Definition~\ref{defn: Vs involutive}.
    Let 
    \[
    \cE_\pm = \{ \Phi \in D(\Delta^{1/2}_{\pm}) \, : \, \Phi \in \cD \text{ and } \Delta_{\pm}^{1/2}\Phi \in \cD\}.
    \]
    Then the modular operator and conjugation for $\hat \cK_n(I_{\pm})$ satisfy
    \[
    \Delta_{\pm}^{1/2}|_{\cE_{\pm}} = V_{\pm i\pi}, \qquad J_{\pm} = \theta.
    \]
\end{thm}
\begin{proof}
    We first show that $\cE_{\pm}$ is contained in the domain of $V_{i\pi}$, and that $V_{i\pi}$ and $\Delta_+^{1/2}$ agree on this space.
    Without loss of generality we only consider $\cE_+$.
    Given $\Phi \in D(\Delta_+^{1/2})$, the map $F:\bbS \to \cH$ given by
    \[
    F(\tau) = \Delta^{\tfrac{\tau}{2\pi i}} \Phi
    \]
    is continuous on the closed strip and holomorphic on the interior.
    Hence for each $\Phi' \in \cD$, the map $F_{\Phi'}:\bbS \to \bbC$ given by $F_{\Phi'}(\tau) = \ip{F(\tau),\Phi'}$ is again continuous on the closed strip and holomorphic in the interior.
    Since $\Delta^{it}_+ = V_{-2\pi t}$ by \eqref{eqn: Delta pm it}, it follows that
    \[
    F_{\Phi'}(t) = \ip{V_t \Phi, \Phi'}, \qquad F_{\Phi'}(t + i \pi) = \ip{V_t \Delta^{1/2}\Phi,\Phi'}.
    \]
    Hence if $\Phi, \Delta^{1/2}_+\Phi \in \cD$, then it follows that $\Phi \in D(V_{i\pi})$ and $V_{i\pi}\Phi = \Delta^{1/2}\Phi$.

    It remains to check that $\cE_{\pm} = D(V_{\pm i\pi})$, and since we have shown $\cE_{\pm} \subset D(V_{\pm i \pi})$, it only remains to check the opposite inclusion.
    As in Lemma~\ref{lem: dual standard subspaces}, let $\cL_{\pm} \subset \cD$ be the standard subspace corresponding to the involution $S_{\pm} = \theta V_{\pm i \pi}$, so that $D(V_{\pm i \pi}) = \cL_{\pm} + i \cL_{\pm}$.
    By the same lemma, $\cL_{\pm}' = \cL_{\mp}$ and $\cK_w(I_{\pm}) \subset \cL_{\pm}$.
    By Proposition~\ref{prop: unitary K weakly haag dual}, the net $\cK_w(I_{\pm})$ is Haag dual, so taking complements yields $\cL_{\mp} \subset \cK_w(I_{\mp})$.
    Thus we have shown $\cL_{\pm} = \cK_w(I_{\pm})$.
    By Proposition~\ref{prop: unitary K weakly haag dual} we have $\cK_w(I_{\pm}) = \cK_n(I_{\pm}) = \hat \cK_n(I_{\pm}) \cap \cD$.
    Putting it all together, we conclude that $\cL_{\pm} = \hat \cK_n(I_{\pm}) \cap \cD$.
    We thus have:
    \[
    D(V_{\pm i\pi}) = \cL_{\pm} + i \cL_{\pm} \subset \hat \cK_n(I_{\pm}) + i \hat \cK_n(I_{\pm}) = D(\Delta^{1/2}_{\pm}).
    \]
    Arguing as in the first half of the proof, we see that if $\Phi \in D(V_{\pm i\pi})$ then $\Delta^{1/2}_{\pm}\Phi = V_{\pm i\pi}\Phi \in \cD$.
    Hence we have that $D(V_{\pm i\pi}) \subset \cE_{\pm}$, completing our proof that $D(V_{\pm i\pi}) = \cE_{\pm}$.

    We finally compute the modular conjugation $J_+=J_-$. Let $\hat S_+$ be the involution corresponding to $\hat \cK_n(I_+)$, so that $\hat S_+ = J_+ \Delta_+^{1/2}$.
    If $x \in \cP(I_+)_{sa}$, then since $x\Omega \in \cK(I_+) \subset \hat \cK_n(I_+)$ we have
    \[
    J_+ \Delta_+^{1/2} x\Omega = \hat S_+ x\Omega = x\Omega = \theta V_{i\pi} x \Omega = \theta \Delta_+^{1/2} x\Omega.
    \]
    The first equality is the definition of $J_+$ and $\Delta_+^{1/2}$, the second is the fact that $x\Omega \in \hat \cK_n(I_+)$, the third is Theorem~\ref{thm: involutive BW}, and the fourth follows from the previous part of this proof.
    Hence $J_+$ and $\theta$ agree on $\Delta^{1/2}_+ x\Omega$ when $x=x^*$, and by antilinearity this holds for all $x \in \cP(I_+)$.
    Hence $\theta$ and $J_+$ agree on $\cP(I_-)\Omega$, which is dense by Reeh-Schlieder.
    Since both are antiunitary, we conclude $\theta = J_+$.
\end{proof}

We now turn our attention to the correspondence between vertex algebras (i.e. Wightman CFTs) and conformal nets, which were introduced in Section~\ref{sec: background unitary}.
Given a unitary M\"obius vertex algebra $\cV$, we embed $\cV$ in its Hilbert space completion $\cH$, and for $v \in \cV$ with conformal dimension $d$ and $f \in C^\infty(S^1)$ we define the smeared field operator $Y(v,f)$ to be the closure of the operator $Y^0(v,f)$ defined on $\cV$ by
\[
Y^0(v,f)u = \sum_{n \in \bbZ} \hat f(n) v_{(n+d-1)}u, \qquad u \in \cV.
\]
For analytic details, see \cite[\S2.4]{RaymondTanimotoTener22} (and also \cite{CKLW18,CarpiRaymondTanimotoTener24ax}).
We now let $\cF$ be the Wightman CFT associated with the generating set of \emph{all} quasiprimary vectors $v$, i.e. 
\[
\cF = \{ Y(v, \cdot) \, : \, v \text{ quasiprimary} \},
\]
whose domain $\cD$ embeds continuously in the Hilbert space completion $\cH$ of $\cV$.
Since $\cV$ is unitary, it is semisimple as a representation of $\mathfrak{sl}_2(\bbC)$ and therefore generated by quasiprimary fields.
Following \cite{RaymondTanimotoTener22} (and, more generally, \cite{CKLW18} when the vertex algebra is energy bounded) we have the following notion of integrability for $\cV$.
Recall that if $S$ is a set of closed operators on a Hilbert space $\cH$, the von Neumann algebra  generated by $S$ is the von Neumann algebra generated by the polar partial isometries and spectral projections of all operators $X \in S$.

\begin{defn}\label{defn: AQFT-local]}
    Let $\cV$ be a unitary M\"obius vertex algebra with Hilbert space completion $\cH$.
    The local algebra $\cA_\cV(I)$ associated with an interval $I \subset S^1$ is the von Neumann algebra generated by all operators $Y(v,f)$ with $v$ quasiprimary and $f \in C^\infty(S^1)$ with $\operatorname{supp} f \subset I$.
    We say that $\cV$ is \textbf{AQFT-local} if $\cA_\cV(I)$ and $\cA_\cV(J)$ commute element-wise when $I$ and $J$ are disjoint.
\end{defn}

We use the term AQFT-local rather than the term `strongly local' from \cite{CKLW18} as the latter definition also assumes `energy bounds,' which are not required here.
It is reasonably straightforward to show that if $\cV$ is AQFT-local, then $\cA_\cV$ is a M\"obius-covariant Haag-Kastler net \cite[Prop. 4.8]{RaymondTanimotoTener22} (which is a reproof of a result of \cite[Thm. 6.8]{CKLW18}, without energy bounds).

It is believed that every unitary M\"obius vertex algebra is AQFT-local \cite[Conj. 8.18]{CKLW18}.
There is no criterion for determining when the von Neumann algebras generated by two families of closed operators commute which is general enough to cover this situation, and this kind of commutativity can fail even under very nice circumstances (see \cite{Nelson59} for a famous example).
This challenge has presented itself from the early days of Haag-Kastler's algebraic approach to QFT, and we do not offer a general solution.
However, we can use the standard subspace approach to vertex algebra nets $\cP(I)$ to give a conceptual proof that a simpler-looking statement is equivalent AQFT-locality.
Similar results were shown by Bisognano-Wichmann in the context considered in their original article \cite[Thm. 3(f)]{BisognanoWichmann75}.

Define a family of von Neumann subalgebras $\cC^\cH(I) \subset \cB(\cH)$ by $\cC^\cH(I) = \cA_\cV(I')'$.
Let $\cH_\cC \subset \cH$ be the Hilbert space
\[
\cH_\cC = \overline{\left(\bigvee_{I \subset S^1} \cC(I)\right)\Omega},
\]
where $\bigvee_I \cC^\cH(I)$ is the von Neumann algebra generated by the algebras $\cC(I)$.
Let $p_\cC$ be the projection of $\cH$ onto $\cH_\cC$, and let $\cC(I) = \cC^\cH(I)p_\cC$, the cutdown of the net of algebras $\cC^\cH$ to its vacuum Hilbert space $\cH_\cC$.

We will show that the algebras $\cC(I)$ form a Haag-Kastler net on $\cH_\cC$, but it is convenient to first check the `one-particle' version.

\begin{lem}\label{lem: standard subspace net for dual net}
    The real subspaces $\overline{\cC(I)_{sa}\Omega}$ are a M\"obius-covariant net of standard subspaces of the Hilbert space $\cH_\cC$.
    The modular conjugation corresponding to the upper semicircle is $\theta|_{\cH_\cC}$.
\end{lem}
\begin{proof}
    We verify that these subspaces satisfy Definition~\ref{defn: unitary net of subspaces}.
    Isotony of the net is clear, as is the spectrum condition.
    The algebras $\cC^\cH(I)$ are M\"obius covariant with respect to the given unitary representation on $\cH$. It follows that $\cH_\cC$ is invariant under the M\"obius group, and that the algebras $\cC(I)$ are M\"obius covariant, and indeed that the subspaces $\overline{\cC(I)_{sa}\Omega}$ are as well.
    It remains to check the cyclicity condition.
    Let $\tilde \cH_\cC \subset \cH_\cC$ be the closed span of the subspaces $\cC(I)\Omega$.
    Then evidently the given subspaces form a M\"obius-covariant net of subspaces of $\tilde \cH_\cC$.
    Then by the Reeh-Schlieder property \cite[Thm. 3.2.1]{LongoLectureNotesI} we have $\tilde \cH_\cC = \overline{\cC(I)\Omega}$ for each interval $I$.
    Hence $\tilde \cH_\cC$ is invariant under each algebra $\cC(I)$.
    It follows that $\tilde \cH_\cC$ is invariant under $\bigvee_I \cC(I)$, from which it follows that $\cH_\cC \subset \tilde \cH_\cC$.
    Hence $\cH_\cC = \tilde \cH_\cC$, which completes the proof of the locality axiom.
\end{proof}

\begin{thm}\label{thm: commutant net locality}
Let $\cV$ be a unitary M\"obius vertex algebra with PCT operator $\theta$, let $\cC^\cH(I) = \cA_\cV(I')'$ be the dual net of von Neumann algebras, and let $\cC(I)$ be the cutdown of $\cC^\cH(I)$ to the vacuum Hilbert space $\cH_\cC$, as described above.
Then $\cC$ is a a M\"obius-covariant Haag-Kastler net on $\cH_\cC$.
The modular conjugation associated with $\cC(I_+)$ and $\Omega$ is $\theta|_{\cH_\cC}$.
\end{thm}
\begin{proof}
The only axiom which needs to be checked is locality.
This will follow from the assertion regarding the modular conjugation, which we now verify.
Let $\cN = \overline{\cC(I_+)_{sa}\Omega}$, which is a standard subspace of $\cH_\cC$ by Lemma~\ref{lem: standard subspace net for dual net}.
We note that it follows that $\Omega$ is cyclic and separating for $\cC(I_+)$.
By definition $\cC^\cH(I_+)$ commutes with $\cP(I_-)$, and therefore $\cC(I_+)_{sa}\Omega \subset \hat \cK_n(I_-)' = \hat \cK_n(I_+)$.
It follows that $\cN \subset \hat \cK_n(I_+)$.

From the theory of M\"obius covariant nets of subspaces we know that the modular automorphism group of $\hat \cK_n(I_+)$ is $\Delta_+^{it} = U(v_{-2 \pi t})$ \cite[Thm. 3.3.1]{LongoLectureNotesI}.
As $\cN$ is invariant under $\Delta_+^{it}$, the modular automorphism group for $\cN$ is $\Delta_+^{it}|_{\cH_\cN}$ \cite[Cor. 2.1.8]{LongoLectureNotesI}.
Let $S_\cN$ be the involution on $\cH_\cN$ corresponding to $\cN$, and let $S_\cN = J_\cN\Delta_\cN^{1/2}$ be the polar decomposition.
For $\xi \in D(\Delta_\cN^{1/2})$, the map $\Delta_\cN^{it}\xi$ extends to a continuous function on the strip $\{-\tfrac12 \le \Im(\tau) \le 0\}$, holomorphic on the interior, mapping $\tau=-i/2$ to $\Delta^{1/2}_\cN\xi$.
As the same holds for $\Delta_+^{it}$, we have $\Delta^{1/2}_\cN\xi = \Delta^{1/2}_+\xi$ for $\xi \in \cN + i \cN$, and in particular for $\xi$ of the form $x\Omega$ with $x \in \cC(I_+)$.
Thus if $x \in \cC(I_+)$ we have
\[
J_\cN x^*\Omega = \Delta_\cN^{1/2} x \Omega = \Delta_+^{1/2}x\Omega = \theta x^* \Omega
\]
with the last equality by Theorem~\ref{thm: modular for unitary}.
Hence by Reeh-Schlieder (which in this case follows from Lemma~\ref{lem: standard subspace net for dual net}) we have $J_\cN = \theta|_{\cH_\cN}$, proving our claim about the modular conjugation for $\cC(I_+)$.

We now complete the proof of locality, for which it suffices to show that $\cC(I_+)$ and $\cC(I_-)$ commute.
By the main theorem of Tomita-Takesaki theory, we have $\theta \cC(I_+) \theta = \cC(I_+)'$.
On the other hand, since $\theta \cA_\cV(I_{\pm}) \theta = \cA_\cV(I_\mp)$, it follows that $\theta \cC^\cH(I_+) \theta = \cC^\cH(I_-)$.
Since $\theta$ leaves $\cH_\cN$ invariant we have $\theta \cC(I_+) \theta = \cC(I_-)$.
Hence $\cC(I_+)' = \cC(I_-)$, completing the proof of locality.
\end{proof}

\begin{cor}\label{cor: separating implies local}
    Let $\cV$ be a unitary M\"obius vertex algebra with vacuum vector $\Omega$ and PCT operator $\theta$. Then the following are equivalent:
    \begin{enumerate}[1)]
        \item $\cV$ is AQFT-local
        \item $\Omega$ is separating for $\cA_V(I)$, for some (or any) interval $I$
    \end{enumerate}
    If the above hold, then $\theta$ is the modular conjugation for $\cA(I_+)$ with respect to the vacuum state.
\end{cor}
\begin{proof}
    If $\cV$ is AQFT-local, then $\cA_\cV(I)$ is a M\"obius-covariant Haag-Kastler net, and $\Omega$ is separating for $\cA_\cV(I)$ by the Reeh-Schlieder property.
    Conversely, if $\Omega$ is separating, then it is cyclic for $\cC^\cH(I) = \cA_\cV(I')'$, and $\cH_\cC = \cH$.
    Hence by Theorem~\ref{thm: commutant net locality} , $\cC(I)$ is a M\"obius-covariant Haag Kastler net on $\cH$, and by Haag duality for that net we have $\cC(I)=\cA_\cV(I)$, completing the proof.
    The computation of the modular conjugation follows from Theorem~\ref{thm: commutant net locality} as well.
\end{proof}
We note that the claim about the modular conjugation  could have alternatively been proven directly from \cite[Thm. B.6]{CKLW18}, under the assumption of energy bounds.



