\section{Distributing Three-body Graphs}
\label{sec: threebody}
Algorithm \ref{alg:bond_graph} depicts the method in which to distribute three-body graphs (also known as bond graphs) as well as calculating the necessary information to perform data transfer between various partitions at each convolution of the three-body graph.

\begin{algorithm}[H]
   \caption{Distributed Bond Line Graph Construction}
   \label{alg:bond_graph}
\begin{algorithmic}
   \STATE \textbf{Input:} Global edges $E$, partitions $\{P_i\}$, bond cutoff $r$, tolerance $\tau$
   \STATE \textbf{Output:} Line graphs $\{L_i\}$ for partitions $\{P_i\}$

   \FOR{each partition $P_i$}
      \STATE Initialize TO/FROM/PURE arrays for bond graph nodes (edges within atom graph)
      \STATE Initialize edge tables $T_i$ for each partition
      \STATE \textbf{Build Edge Table $T_i$}:
      \FOR{each edge $e \in E$ with $\text{dist}(e) \leq r + \tau$}
          \IF{$\text{dst}(e)$ in $P_i$}
            \STATE append $e$ to $T_i[e.src]$
              \IF{$e$ is border edge for $P_i$}
                  \STATE add $e$ to $\text{FROM}_{p_i}[\text{which\_partition(e.src)}]$
              \ELSIF{$e$ is border edge for another partition $P_j$}
                  \STATE add $e$ to $\text{TO}_{\text{which\_partition(e.src)}}[P_i]$
              \ENDIF
          \ENDIF
      \ENDFOR

      \FOR{each edge $e \in E$ with $\text{dist}(e) \leq r + \tau$}
          \IF{$e$ is pure edge assigned to $P_i$}
              \STATE Append $e$ to $T_i[e.src]$
              \STATE add $e$ to $\text{PURE}[\text{which\_partition(e.dst)}]$
          \ENDIF
      \ENDFOR

      \STATE \textbf{Localize Edges}
      \FOR{each $e \in T_i$}
          \STATE Create mappings between global and local bond graph node indices
          \STATE Assign local node indices to each $e$ in $T_i$ $\forall i$
      \ENDFOR

      \STATE \textbf{Build Line Graph $L_i$}
      \FOR{each partition $P_i$}
          \FOR{each $v \in T_i$}
              \FOR{each $e \in T_i[v]$}
                  \FOR{each $e' \in T_i[\text{e.dst}]$}
                     \IF{\text{needs\_in\_line($e'$)}}
                        \STATE Draw an edge in bond graph from $e$ to $e'$ using local node indices
                     \ENDIF
                  \ENDFOR
              \ENDFOR
          \ENDFOR
      \ENDFOR
   \ENDFOR
\end{algorithmic}
\end{algorithm}

