\section{Assign to Partitions}
\label{sec: assign_to_partitions}
Algorithm \ref{alg:assign_partitions} is the method used to determine assign individual nodes to the PURE/TO/FROM buckets of each partition. It is used extensively in both atom graph creation (algorithm \ref{alg:atom_subgraph}) and three-body graph creation (algorithm \ref{alg:bond_graph}).

\begin{algorithm}[H]
\caption{assign\_to\_partitions Subroutine}
\label{alg:assign_partitions}
\begin{algorithmic}
\STATE \textbf{Input:} Nodes, edges, partitions
\STATE \textbf{Output:} PURE, TO, FROM arrays for each partition

\STATE \textbf{1. Initialize node tracking:}
    \STATE Create table \texttt{node\_to\_partition[node\_id]} $\gets$ -1 $\forall$ nodes

\STATE \textbf{2. Populating} \texttt{node\_to\_partition}
    \FOR{each edge e}
        \STATE \texttt{node\_to\_partition} $[\text{which\_partition}(e.src)] =$
        \STATE \quad $\text{which\_partition}(e.dst)$
    \ENDFOR

\STATE \textbf{3. Assigning nodes to partition buckets}
    \FOR {each node n}
        \IF{\texttt{node\_to\_partition}[n] $= -1$}
            \STATE add n to PURE array of which\_partition(n)
        \ELSE
            \STATE add n to $\text{TO}_{\text{which\_partition}(n)}[\texttt{node\_to\_partition}[n]]$
            \STATE add n to $\text{FROM}_{\texttt{node\_to\_partition}[n]}[\text{which\_partition(n)}]$
        \ENDIF

    \ENDFOR
\end{algorithmic}
\end{algorithm}

