  \centering
  \includegraphics[width=1\linewidth, trim=0cm 7cm 0cm 3cm, clip]{fig7.pdf}
  \caption{Energy (meV/atom) discrepancy between DistMLIP's multi-GPU inference and baseline single-GPU inference for \textbf{(a)} MACE-3.8M, \textbf{(b)} TensorNet-0.8M, and \textbf{(c)} CHGNet-2.7M on multiple chemical systems. Note that DistMLIP's graph partitioning and distribution algorithms are exact, and these non-perfect discrepancies are a result of non-deterministic matrix multiplication operations on different devices.}
  \label{fig:force_discrepancy}
\end{figure}

\section{Parallelizing a Model in DistMLIP}
DistMLIP is designed to be both high-performant as well as easily usable. Parallelizing new MLIPs using DistMLIP is a straightforward process that can be done purely in Python. A few key points of DistMLIP are outlined in \ref{sec:parallelization_usage}.
\newpage

\subsection{Model Parallelization Example}
\label{sec:parallelization_usage}
\begin{lstlisting}[style=pytorch]
# Creating a DistMLIP distributed object
dist = Distributed.create_distributed(...)
# Distributed edge information
dist.src_nodes, dist.dst_nodes # List of src and dist node pairs for each partition
# Distributing node/edge features
node_features_dist = dist.distribute_node_features(node_features)
edge_features_dist = dist.distribute_edge_features(edge_features)
# Exchanging node information
dist.atom_transfer(node_features_dist)
# Aggregating node features
node_features = dist.aggregate(node_features_dist)
\end{lstlisting}
