\subsection{Nondimensionalisation}

\temp{In order to simplify the subsequent analysis, we perform a standard nondimensionalisation to reduce the overall number of parameters in the model.} We substitute scalings of each variable given by
\begin{equation}
    E = E_0u, \quad T = T_0v, \quad I_L = I_{L_0}w, \quad \overline{t} = t_s t, \quad \bm{x} = X\bm{\overline{x}}
\end{equation}
into \eqref{effectoreq}-\eqref{ILeq} to arrive at
\begin{align}
    \frac{\partial u}{\partial {t}} =&\frac{t_s d_E}{X^2}{\nabla}^2u  +\frac{t_s T_0c}{E_0}v -t_sm_E u + \frac{p_Et_s I_{L_0}uw}{g_E + I_{L_0}w} + \frac{t_s s_E}{E_0},
    \\ 
    \frac{\partial v}{\partial {t}} =& \frac{t_s d_T}{X^2}{\nabla}^2 v + r_Tt_s v(1-bT_0v) -\frac{p_TE_0t_s uv}{g_T + T_0v},
    \\ 
    \frac{\partial w}{\partial {t}} =&\frac{t_s d_{I_L}}{X^2}{\nabla}^2 w + \frac{p_{I_L}t_sE_0T_0uv}{I_{L_0}g_{I_L} + I_{L_0}T_0v} - t_sm_{I_L} w  + \frac{t_s s_{I_L}}{I_{L_0}}.
\end{align}
We can hence simplify the system slightly by setting,
\begin{equation}
    t_s = \frac{1}{r_T}, \quad E_0 = \frac{r_T}{bp_T}\quad  T_0 = \frac{1}{b}, \quad I_{L_0} = g_E, \quad X = \sqrt{\frac{d_T}{r_T}},
\end{equation}
finally leading to the system,
\begin{align}
    \frac{\partial u}{\partial {t}} =&\delta_u{\nabla}^2u  +\alpha v -\mu_u u + \frac{\rho_u uw}{1 + w} + \sigma_u, \label{u_nondim_eq}\\ 
    \frac{\partial v}{\partial {t}} =& {\nabla}^2 v +  v(1-v) -\frac{uv}{\gamma_v + v}, \label{v_nondim_eq}\\ 
    \frac{\partial w}{\partial {t}} =&\delta_w{\nabla}^2 w + \frac{\rho_w uv}{\gamma_w + v} - \mu_w w  +\sigma_w,\label{w_nondim_eq}
\end{align}
where the nondimensional parameters are given by,
\begin{equation}\begin{aligned}
   &\delta_u = \frac{d_E}{d_T}, \quad \alpha = \frac{p_T c}{r_T^2}\quad  \mu_u = \frac{m_E}{r_T}, \quad \rho_u = \frac{p_E}{r_T}, \quad \sigma_u = \frac{bp_T s_E}{r_T^2}, \quad \gamma_v = g_T b,\\
   &\delta_w = \frac{d_{I_L}}{d_T}, \quad \rho_w = \frac{p_{I_L}}{bp_Tg_E}, \quad \gamma_w = g_{I_L}b, \quad \mu_w = \frac{m_{I_L}}{r_T}, \quad \sigma_w = \frac{ s_{I_L}}{g_E r_T}.
\end{aligned}\end{equation}

