\section{Analytical expressions of $S(\beta)$ and $H(\beta)$}

\noindent It was found by Lee \cite{lee10} that $S(\beta)$ can be expressed in terms of hypergeometric functions $_2F_3$ and $_3F_4$:  

\begin{eqnarray}\label{nc}
S(\beta)&=&\frac{\mathrm{\Gamma}(5/3)}{\pi}~_2F_3
\left(
\begin{array}{c}
\frac{5}{12}, \frac{11}{12}\\
\frac{1}{3}, \frac{1}{2}, \frac{5}{6}\\
\end{array};-\frac{4\beta^6}{3^6}
\right)\nonumber\\
& &-\frac{\beta^2}{3\pi}~_3F_4
\left(
\begin{array}{c}
\frac{3}{4}, 1, \frac{5}{4}\\
\frac{2}{3}, \frac{5}{6}, \frac{7}{6}, \frac{4}{3}\\
\end{array}; -\frac{4\beta^6}{3^6}
\right)
\nonumber\\
& &+\frac{7\beta^4\mathrm{\Gamma}(4/3)}{3^4\pi}~_2F_3
\left(
\begin{array}{c}
\frac{13}{12}, \frac{19}{12}\\
\frac{7}{6}, \frac{3}{2}, \frac{5}{3}\\
\end{array}; -\frac{4\beta^6}{3^6}
\right).
\end{eqnarray}

\noindent Such an expression was also mentioned by $\mathrm{\c{C}}$opuro$\mathrm{\check{g}}$lu \cite{copuroglu19} and Mehmeto$\mathrm{\check{g}}$lu. We provide an expression which is simpler than Eq. (\ref{nc}), in the sense that it involves hypergeometric functions with lower indices (lower numbers of parameters) and Airy (or Bessel) functions. We give below the main steps of two different ways to obtain the new formula. The first one consists in using inverse Fourier transform of $\exp(-|\tau|^{3/2})$ \cite{stam08,stam12,stam13}:

\begin{equation}\label{inv}
S(\beta)=\frac{1}{2\pi}\int_{-\infty}^{\infty}\exp\left(-|\xi|^{3/2}-i\beta\xi\right)d\xi
\end{equation}

\noindent and splitting the integral in two parts (one from $-\infty$ to 0 and the other one from 0 to $\infty$). For instance, considering

\begin{equation}
I(\beta)=\int_0^{\infty}e^{-t^{3/2}}e^{-i\beta t}dt,
\end{equation}

\noindent we find, with the change of variable $v=t^{3/2}$:

\begin{equation}
I(\beta)=\frac{2}{3}\int_0^{\infty}e^{-v}v^{-1/3}e^{-i\beta v^{2/3}}dv,
\end{equation}

\noindent which yields, after expanding $e^{-i\beta v^{2/3}}$ in series:

\begin{equation}
I(\beta)=\frac{2}{3}\sum_{k=0}^{\infty}\frac{(-i\beta)^k}{k!}\int_0^{\infty}v^{\frac{(2k-1)}{3}}e^{-v}dv=\frac{2}{3}\sum_{k=0}^{\infty}\frac{(-i\beta)^k}{k!}\mathrm{\Gamma}\left(\frac{2(k+1)}{3}\right).
\end{equation}

\noindent Then, knowing that the general form of a generalized hypergeometric series $_pF_q$ is

\begin{eqnarray}\label{def_fpq}
_pF_q\left[\begin{array}{c}
\alpha_1\cdots\alpha_p\\
\gamma_1,\cdots,\gamma_q
\end{array};z\right]&=&\sum_{n=0}^{\infty}\frac{\prod_{i=1}^p(\alpha_i)_n}{\prod_{j=1}^q(\gamma_j)_n}\frac{z^n}{n!},
\end{eqnarray}

\noindent where $(\lambda)_n$ represents the Pochhammer symbol

\begin{equation}
(\lambda)_n=\lambda(\lambda+1)\cdots(\lambda+n-1)=\frac{\mathrm{\Gamma}(\lambda+n)}{\mathrm{\Gamma}(\lambda)},
\end{equation}

\noindent one gets, using a computer algebra system \cite{mathematica}:

\begin{eqnarray}
I(\beta)&=&\frac{2}{3}\mathrm{\Gamma}\left(\frac{2}{3}\right)~_1F_1\left(\begin{array}{c}
\frac{5}{6}\\
\frac{2}{3}
\end{array}; \frac{4i\beta^3}{27}\right)-\frac{2i\beta}{9}\mathrm{\Gamma}\left(\frac{1}{3}\right)~_1F_1\left(\begin{array}{c}
\frac{7}{6}\\
\frac{4}{3}
\end{array}; \frac{4i\beta^3}{27}\right)\nonumber\\
& &-\frac{\beta^2}{3}~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; \frac{4i\beta^3}{27}\right).
\end{eqnarray}

\noindent In the same way, we have

\begin{eqnarray}
J(\beta)&=&\int_{-\infty}^{0}e^{-|t|^{3/2}}e^{-i\beta t}dt\nonumber\\
&=&\frac{2}{3}\mathrm{\Gamma}\left(\frac{2}{3}\right)~_1F_1\left(\begin{array}{c}
\frac{5}{6}\\
\frac{2}{3}
\end{array};-\frac{4i\beta^3}{27}\right)+\frac{2i\beta}{9}\mathrm{\Gamma}\left(\frac{1}{3}\right)~_1F_1\left(\begin{array}{c}
\frac{7}{6}\\
\frac{4}{3}
\end{array};-\frac{4i\beta^3}{27}\right)\nonumber\\
& &-\frac{\beta^2}{3}~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array};-\frac{4i\beta^3}{27}\right).
\end{eqnarray}

\noindent In the present case, $\beta$ is real, the argument of the $_1F_1$ and $_2F_2$ functions is pure imaginary and the sum of two $_1F_1$ (or two $_2F_2$) functions with opposite imaginary arguments is real. Therefore, $I(\beta)$ and $J(\beta)$ are complex conjugates, and their sum is real. Since Airy function $\mathrm{Bi}$ and its derivative $\mathrm{Bi}'$ \cite{abramowitz,ghatak91} can be expressed using confluent hypergeometric functions $_1F_1$ \cite{dmlf}:

\begin{eqnarray}
\mathrm{Bi}(x)&=&\frac{1}{3^{1/6}\mathrm{\Gamma}\left(\frac{2}{3}\right)}\exp\left(-\frac{2}{3}x^{3/2}\right)~_1F_1\left(\begin{array}{c}
\frac{1}{6}\\
\frac{1}{3}
\end{array};\frac{4}{3}x^{3/2}\right)\nonumber\\
& &+\frac{3^{5/6}}{2^{2/3}\mathrm{\Gamma}\left(\frac{1}{3}\right)}\left(\frac{2}{3}\right)^{2/3}x\exp\left(-\frac{2}{3}x^{3/2}\right)~_1F_1\left(\begin{array}{c}
\frac{5}{6}\\
\frac{5}{3}
\end{array};\frac{4}{3}x^{3/2}\right)
\end{eqnarray}

\noindent and

\begin{eqnarray}
\mathrm{Bi}'(x)&=&\frac{3^{1/6}}{\mathrm{\Gamma}\left(\frac{1}{3}\right)}\exp\left(-\frac{2}{3}x^{3/2}\right)~_1F_1\left(\begin{array}{c}
-\frac{1}{6}\\
-\frac{1}{3}
\end{array};\frac{4}{3}x^{3/2}\right)\nonumber\\
& &+\frac{1}{2\times 3^{1/6}\mathrm{\Gamma}\left(\frac{2}{3}\right)}x^2\exp\left(-\frac{2}{3}x^{3/2}\right)~_1F_1\left(\begin{array}{c}
\frac{7}{6}\\
\frac{7}{3}
\end{array};\frac{4}{3}x^{3/2}\right),
\end{eqnarray}

\noindent it is possible, with the help of a computer algebra system \cite{mathematica}, to recognize

\begin{eqnarray}\label{final}
S(\beta)&=&\frac{-\beta^2}{6\pi}\left[~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; -\frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; \frac{4i\beta^3}{27}\right)\right]\nonumber\\
& &+\frac{4}{3\times 3^{2/3}}\left[\mathrm{Bi}'\left(-\frac{\beta^2}{3\times 3^{1/3}}\right)\cos\left(\frac{2\beta^3}{27}\right)\right.\nonumber\\
& &\left.+\frac{\beta}{3^{2/3}}~\mathrm{Bi}\left(-\frac{\beta^2}{3\times 3^{1/3}}\right)\sin\left(\frac{2\beta^3}{27}\right)\right].
\end{eqnarray}

\noindent The arguments of the $_2F_2$ functions are pure imaginary complex numbers, but the sum of the two functions is real. For $x$ positive, the function $\mathrm{Bi}(-x)$ is related to the Bessel functions of fractional order $J_{-1/3}$ and $J_{1/3}$ and its derivative to the Bessel functions of fractional order $J_{-2/3}$ and $J_{2/3}$ \cite{abramowitz,prudnikov}. One has therefore 

\begin{eqnarray}
S(\beta)&=&\frac{4\beta^2}{27\sqrt{3}}\left\{\cos\left(\frac{2\beta^3}{27}\right)\left[J_{-2/3}\left(\frac{2\beta^3}{27}\right)+J_{2/3}\left(\frac{2\beta^3}{27}\right)\right]\right.\nonumber\\
& &\left.+\sin\left(\frac{2\beta^3}{27}\right)\left[J_{-1/3}\left(\frac{2\beta^3}{27}\right)-J_{1/3}\left(\frac{2\beta^3}{27}\right)\right]\right\}\nonumber\\
& &-\frac{\beta^2}{6\pi}\left[~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; -\frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; \frac{4i\beta^3}{27}\right)\right].
\end{eqnarray}

\noindent Another way to derive Eq. (\ref{final}) is to start from Eq. (\ref{smallarg}), which reads equivalently

\begin{equation}
S(\beta)=\frac{2}{3\pi\beta}\sum_{m=0}^{\infty}(-1)^m\beta^{2m+1}\frac{\mathrm{\Gamma}\left(\frac{2(2m+1)}{3}\right)}{\mathrm{\Gamma}(2m+1)},
\end{equation}

\noindent and setting $m=3p+q$, we get

\begin{equation}
S(\beta)=\frac{2}{3\pi\beta}\sum_{p=0}^{\infty}\sum_{q=0}^2(-1)^{3p+q}\beta^{6p+2q+1}\frac{\mathrm{\Gamma}\left(4p+\frac{2(2q+1)}{3}\right)}{\mathrm{\Gamma}(6p+2q+1)},
\end{equation}

\noindent which becomes, with $r=2p$:

\begin{equation}
S(\beta)=\frac{2}{3\pi\beta}\sum_{r=0}^{\infty}\sum_{q=0}^2\left[\frac{1+(-1)^r}{2}\right]e^{i\pi\frac{3r}{2}}(-1)^q\beta^{3r+2q+1}\frac{\mathrm{\Gamma}\left(2r+\frac{2(2q+1)}{3}\right)}{\mathrm{\Gamma}(3r+2q+1)}.
\end{equation}

\noindent Using Gauss' multiplication formula, it is possible to write

\begin{equation}
\frac{\mathrm{\Gamma}\left(2r+\frac{2(2q+1)}{3}\right)}{\mathrm{\Gamma}(3r+2q+1)}=\sqrt{2\pi}\frac{2^{2r+\frac{4q}{3}+\frac{1}{6}}}{3^{3r+2q+\frac{1}{2}}}\frac{\mathrm{\Gamma}\left(\frac{2q}{3}+\frac{5}{6}\right)\left(\frac{2q}{3}+\frac{5}{6}\right)_r}{\prod_{k=1}^2\mathrm{\Gamma}\left(\frac{2q+1+k}{3}\right)\left(\frac{2q+1+k}{3}\right)_r},
\end{equation}

\noindent which leads to

\begin{eqnarray}
S(\beta)&=&\frac{2^{7/6}}{3\sqrt{6\pi}}\sum_{q=0}^2(-1)^q\left(\frac{4\beta^3}{27}\right)^{\frac{2q}{3}}\frac{\mathrm{\Gamma}\left(\frac{4q+5}{6}\right)}{\prod_{k=1}^2\mathrm{\Gamma}\left(\frac{2q+1+k}{3}\right)}\nonumber\\
& &\times\left\{~_2F_2\left(\begin{array}{c}
1,\frac{4q+5}{6}\\
\frac{2q+2}{3}, \frac{2q+3}{3}
\end{array}; \frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{4q+5}{6}\\
\frac{2q+2}{3}, \frac{2q+3}{3}
\end{array}; -\frac{4i\beta^3}{27}\right)\right\}.\nonumber\\
& &
\end{eqnarray}

\noindent The latter expression can be simplified into

\begin{eqnarray}
S(\beta)&=&\frac{2^{7/6}}{3\sqrt{6\pi}}\left\{\frac{\mathrm{\Gamma}\left(\frac{5}{6}\right)}{\mathrm{\Gamma}\left(\frac{2}{3}\right)}\left[~_2F_2\left(\begin{array}{c}
1,\frac{5}{6}\\
\frac{2}{3}, 1
\end{array};-\frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{5}{6}\\
\frac{2}{3}, 1
\end{array};\frac{4i\beta^3}{27}\right)\right]\right.\nonumber\\
& &-\left(\frac{4\beta^3}{27}\right)^{2/3}\frac{\mathrm{\Gamma}\left(\frac{3}{2}\right)}{\mathrm{\Gamma}\left(\frac{4}{3}\right)\mathrm{\Gamma}\left(\frac{5}{3}\right)}\left[~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array};-\frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array};\frac{4i\beta^3}{27}\right)\right]\nonumber\\
& &+\left.\left(\frac{4\beta^3}{27}\right)^{2/3}\frac{\mathrm{\Gamma}\left(\frac{13}{6}\right)}{\mathrm{\Gamma}\left(\frac{7}{3}\right)}\left[~_2F_2\left(\begin{array}{c}
1,\frac{13}{6}\\
2, \frac{7}{3}
\end{array};-\frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{13}{6}\\
2, \frac{7}{3}
\end{array};\frac{4i\beta^3}{27}\right)\right]\right\}\nonumber\\
& &
\end{eqnarray}

\noindent and since

\begin{equation}
~_2F_2\left(\begin{array}{c}
1, \frac{5}{6}\\
\frac{2}{3}, 1
\end{array};x\right)=~_1F_1\left(\begin{array}{c}
\frac{5}{6}\\
\frac{2}{3}
\end{array};x\right)
\end{equation}

\noindent as well as

\begin{equation}
~_2F_2\left(\begin{array}{c}
1,\frac{13}{6}\\
2, \frac{7}{3}
\end{array};x\right)=\frac{8}{7x}\left[~_1F_1\left(\begin{array}{c}
\frac{7}{6}\\
\frac{4}{3}
\end{array};x\right)-1\right],
\end{equation}

\noindent we obtain, with the help of a computer algeba system \cite{mathematica}, Eq. (\ref{final}). Using the relations 

\begin{equation}
\frac{\partial}{\partial x}~_2F_2(a_1,a_2;b_1,b_2;x)=\frac{a_1a_2}{b_1b_2}~_2F_2(a_1+1,a_2+1;b_1+1,b_2+1;x)
\end{equation}

\noindent and $\mathrm{Bi}''(x)=x~\mathrm{Bi}(x)$, we find for the Holtsmark distribution

\begin{eqnarray}
H(\beta)&=&\frac{2\beta^2}{3\pi}\left[~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; -\frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; \frac{4i\beta^3}{27}\right)\right]\nonumber\\
& &-\frac{i\beta^5}{10\pi}\left[~_2F_2\left(\begin{array}{c}
2,\frac{5}{2}\\
\frac{7}{3}, \frac{8}{3}
\end{array}; -\frac{4i\beta^3}{27}\right)-~_2F_2\left(\begin{array}{c}
2,\frac{5}{2}\\
\frac{7}{3}, \frac{8}{3}
\end{array}; \frac{4i\beta^3}{27}\right)\right]\nonumber\\
& &-\frac{8\beta}{3^4\times 3^{2/3}}\left\{3^{1/3}\mathrm{Bi}\left(-\frac{\beta^2}{3\times 3^{1/3}}\right)\left[4\beta^3\cos\left(\frac{2\beta^3}{27}\right)+9\sin\left(\frac{2\beta^3}{27}\right)\right]\right.\nonumber\\
& &\left.-12\beta^2\mathrm{Bi'}\left(-\frac{\beta^2}{3\times 3^{1/3}}\right)\sin\left(\frac{2\beta^3}{27}\right)\right\},
\end{eqnarray}

\noindent or, in terms of Bessel functions:

\begin{eqnarray}
H(\beta)&=&\frac{2\beta^2}{3\pi}\left[~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; -\frac{4i\beta^3}{27}\right)+~_2F_2\left(\begin{array}{c}
1,\frac{3}{2}\\
\frac{4}{3}, \frac{5}{3}
\end{array}; \frac{4i\beta^3}{27}\right)\right]\nonumber\\
& &-\frac{i\beta^5}{10\pi}\left[~_2F_2\left(\begin{array}{c}
2,\frac{5}{2}\\
\frac{7}{3}, \frac{8}{3}
\end{array}; -\frac{4i\beta^3}{27}\right)-~_2F_2\left(\begin{array}{c}
2,\frac{5}{2}\\
\frac{7}{3}, \frac{8}{3}
\end{array}; \frac{4i\beta^3}{27}\right)\right]\nonumber\\
& &-\frac{8\beta^2}{3^5\times \sqrt{3}}\left\{\left[J_{-1/3}\left(\frac{2\beta^3}{27}\right)-J_{1/3}\left(\frac{2\beta^3}{27}\right)\right]\right.\nonumber\\
& &\times\left[4\beta^3\cos\left(\frac{2\beta^3}{27}\right)+9\sin\left(\frac{2\beta^3}{27}\right)\right]\nonumber\\
& &\left.-4\beta^3\left[J_{-2/3}\left(\frac{2\beta^3}{27}\right)+J_{2/3}\left(\frac{2\beta^3}{27}\right)\right]\sin\left(\frac{2\beta^3}{27}\right)\right\}.
\end{eqnarray}

\section{Conclusion}

We have provided an expression of the Holtsmark probability density function in terms of hypergeometric $_2F_2$ and Airy $\mathrm{Bi}$ and $\mathrm{Bi}'$ functions. The part involving $\mathrm{Bi}$ and $\mathrm{Bi}'$ functions can also be expressed in terms of Bessel functions of fractional order $J_{-2/3}$, $J_{-1/3}$, $J_{1/3}$ and $J_{2/3}$. The interest of the new expression (\ref{final}) for numerical evaluations is not obvious. It seems much more straightforward to base evaluation of the function on its standard series (\ref{smallarg}) and asymptotic expansion (\ref{bigarg}), which have a very simple form. The difficulty of expressing the Holtsmark distribution in terms of standard special functions is only due to the argument of the gamma function being a fraction of the summation index in the expansion (\ref{smallarg}) and (\ref{bigarg}). The new formulation may yield the discovery of further relations, in particular using identities for Airy and $_2F_2$ functions. It may also help to study asymptotic behaviours and derive approximants of the Holtsmark distribution. 

