\section{Introduction} 


\subsection{Enumerating partitions} 

The generating series of partitions, or Young diagrams, admits the following infinite product formula attributed to Euler
$$
\sum_{\pi} q^{|\pi|} = \prod_{n=1}^{\infty} (1-q^n)^{-1},
$$
where $|\pi|$ denotes the size of $\pi$. MacMahon found the following expression for the generating series of plane partitions, i.e.~3-dimensional piles of boxes
$$
\sum_{\pi} q^{|\pi|} = \prod_{n=1}^{\infty} (1-q^n)^{-n}.
$$
In this paper we consider \emph{solid partitions}, where a solid partition $\pi$ is a finite subset of $\mathbb{Z}_{\ge 0}^4$ such that if $(a_1,a_2,a_3,a_4) \in \pi$ and $0 \le b_i \le a_i$ for $i = 1, 2, 3, 4$, then also $(b_1,b_2,b_3,b_4) \in \pi$.

MacMahon initially expected the generating series of solid partitions to satisfy (see \cite{ABMM})
$$
\sum_{\pi} q^{|\pi|} \overset{?}{=} \prod_{n=1}^{\infty} (1-q^n)^{-\frac{1}{2}n(n+1)}.
$$
This formula predicts 141 solid partitions of size 6 -- one too many. As mentioned in \cite[Sect.~11]{Sta}, the study of solid partitions has seen little progress.\footnote{Stanley \cite{Sta} remarks: 
\noindent \emph{``The case $r = 2$ has a well-developed theory --- here 2-dimensional partitions are known as plane
partitions (...) For $r \geq 3$ almost nothing is known, and (...) casts only a faint glimmer of light
on a vast darkness.''}}


\subsection{Magnificent Four}

In his ``Magnificent Four'' paper, Nekrasov \cite{Nek} assigned a weight 
$$
(-1)^{\mu_\pi}[-\mathsf{v}_\pi]  \in \Q(t_1,t_2,t_3,t_4,y^{\frac{1}{2}}) \ \text{with }t_4 = t_1^{-1}t_2^{-1}t_3^{-1}
$$
to any solid partition $\pi$.
Here
$$
\mu_\pi = |\{(i,i,i,j) \in \pi \, : \, j > i\}|
$$
and the term $[-\mathsf{v}_\pi]$ is an explicit rational function determined by the character
\[
Z_\pi = \sum_{(a_1,a_2,a_3,a_4) \in \pi} t_1^{a_1}t_2^{a_2}t_3^{a_3}t_4^{a_4}.
\]
More generally, to an $r$-tuple $\vec{\pi} = (\pi_1, \ldots, \pi_r)$ of solid partitions, Nekrasov--Piazzalunga \cite{NP} assigned a weight
$$
(-1)^{\mu_{\vec{\pi}}} [-\mathsf{v}_{\vec{\pi}}] \in \Q(t_1,t_2,t_3,t_4,w_1, \ldots, w_r,y_1^{\frac{1}{2}}, \ldots, y_r^{\frac{1}{2}})\ \text{with }t_4 = t_1^{-1}t_2^{-1}t_3^{-1},
$$
where $\mu_{\vec{\pi}} = \sum_{\alpha} \mu_{\pi_\alpha}$. We recall the expressions for $[-\mathsf{v}_\pi]$ and $[-\mathsf{v}_{\vec \pi}]$ in Definition \ref{def:NPweight}. Although the sign $\mu_{\vec{\pi}}$ and weight $[-\mathsf{v}_{\vec{\pi}}]$ are not invariant with respect to permutations of $\{1,2,3,4\}$, the product $(-1)^{\mu_{\vec{\pi}}} [-\mathsf{v}_{\vec{\pi}}]$ is invariant under such permutations \cite[Thm.~2.9]{Mon}.

Having defined these weights, one may consider the formal power series
\begin{equation} \label{NPZ}
\mathsf{Z}_{r}^{\NP} = \sum_{\vec{\pi} = (\pi_1, \ldots, \pi_r)}  (-1)^{\mu_{\vec{\pi}}} [ -\mathsf{v}_{\vec{\pi}} ]  \, ((-1)^{r} q)^{|\vec{\pi}|},
\end{equation}
where $|\vec{\pi}| = \sum_{\alpha} |\pi_\alpha|$.
Nekrasov and Piazzalunga give a conjectural formula for $\mathsf{Z}_r^{\NP}$, and the main goal of this paper is to give a proof of this formula.

To describe the formula, recall that the \emph{plethystic exponential} of a Laurent series $F(z_1, \ldots, z_n)$ is defined by
\begin{equation}
\mathrm{Exp}(F(z_1, \ldots, z_n)) = \exp\Big( \sum_{m=1}^{\infty} \frac{1}{m} F(z_1^m, \ldots, z_n^m) \Big), \label{eqn:DefinitionOfPlethystic}
\end{equation}
where we assume that the coefficients of $F$ are such that this is well defined algebraically (i.e.~such that no infinite sums occur in the computation of any one coefficient of $\mathrm{Exp}(F)$).
%More precisely, below, one could consider the exponent of Exp as a \emph{formal} power series in $t_1,t_2,t_3,q,a:=y^{\frac{1}{2}}, b:=y^{-\frac{1}{2}}$. This formal power series is zero when putting $t_1,t_2,t_3,q,a,b$ all to zero.
For any monomial $z_1^{i_1} \cdots z_n^{i_n}$, we define 
$$
[z_1^{i_1} \cdots z_n^{i_n}] = z_1^{\frac{i_1}{2}} \cdots z_n^{\frac{i_n}{2}} - z_1^{-\frac{i_1}{2}} \cdots z_n^{-\frac{i_n}{2}}.
$$
\begin{theorem}[Nekrasov--Piazzalunga's conjecture] 
	\label{mainthm}
	We have
$$
\mathsf{Z}_{r}^{\NP} = \mathrm{Exp}\Bigg(\frac{[t_1t_2][t_1t_3][t_2t_3][y]}{[t_1][t_2][t_3][t_4][y^{\frac{1}{2}} q ]   [y^{\frac{1}{2}} q^{-1} ]}\Bigg),
$$
where $y=y_1 \cdots y_r$ and $t_1t_2t_3t_4 = 1$. In particular, $\mathsf{Z}^{\NP}_{r}$ is independent of $w_1, \ldots, w_r$.
\end{theorem}

\begin{remark}
After eliminating $t_4 = (t_1t_2t_3)^{-1}$, the argument of the plethystic exponential in the conjecture is a rational function in $t_1,t_2,t_3,y^{\frac{1}{2}},q$. 
This rational function can be expanded as a formal power series in positive powers of $q$, whose coefficients are rational functions in $t_i, y^{\frac{1}{2}}$.
One can then apply the plethystic exponential, because only positive powers of $q$ appear in the plethystic exponent.
\end{remark}

\begin{remark}
The $r=1$ case of Theorem \ref{mainthm} was conjectured by Nekrasov in \cite{Nek}.
A special limit of the $r = 1$ case, namely taking $t_i = \exp(b \lambda_i)$ and $y = \exp(- b (d_1\lambda_1 + d_2 \lambda_2 + d_3 \lambda_3 + d_4 \lambda_4))$ with $b \to 0$, was conjectured in \cite{CK}.\footnote{In \cite[Conj.~1.10(c)]{CK}, the authors also give a conjectural formula for the further specialization $d_1=d_2=d_3=0$ and $\lambda_4 = 0$. Though true for solid partitions of size $\leq 6$, it fails for solid partitions of size 8.} This specialization was recently proved using novel degeneration methods by Cao--Zhao--Zhou \cite{CZZ} (relying on this paper's proof of Nekrasov's sign formula  for the localisation, see \cite[Sect.~6.4]{CZZ}).

The motivation in \cite{CK} comes from a parallel conjecture on tautological integrals on Hilbert schemes of points on \emph{compact} Calabi--Yau 4-folds. 
This conjecture was proved in the very ample case by H.~Park \cite{Par} using virtual pull-back.
% (see also \cite{CQ}). 
The general case was shown by Bojko \cite{Boj} to follow from a conjectural virtual 4-fold wall-crossing formula along the lines of \cite{GJT}. 
%This conjecture was recently settled in the ``very ample case'' by Cao and F.~Qu \cite{CQ}. The general case was established by A.~Bojko \cite{Boj} using a conjectural virtual 4-fold wall-crossing formula along the lines of \cite{GJT}. Moreover, using the same conjectural wall-crossing formula, he derives the analog of Theorem \ref{mainthm} for Hilbert schemes of points on compact Calabi--Yau 4-folds.
\end{remark}


\subsection{Three dimensions} 

The Hilbert scheme parametrizing 0-dimensional subschemes of length $n$ on $\C^d$, denoted by $\Hilb^n(\C^d)$, is only smooth if $d\le 2$ or $n\le 3$. In general, even its dimension is unknown. 

For $d=3$, $\Hilb^n(\C^3)$ is the critical locus of a superpotential on a smooth ambient space. This structure was exploited by Behrend--Bryan--Szendr\H{o}i \cite{BBS} in their study of \emph{motivic} Donaldson--Thomas invariants and by Okounkov \cite{Oko} in his proof of the Nekrasov conjecture for \emph{$K$-theoretic} Donaldson--Thomas invariants. Denoting the twisted virtual structure sheaf $\O^{\vir} \otimes (\det T^{\vir})^{-1/2}$ of $\Hilb^n(\C^3)$ (and later the Quot scheme) by $\widehat{\O}^{\vir}$ we have:
\begin{theorem}[{\cite[Thm.~3.3.6]{Oko}}] \label{Okounkovthm}
$$
\sum_{n=0}^{\infty} \chi(\Hilb^n(\C^3), \widehat{\O}^{\vir}) \, (-q)^n = \mathrm{Exp}\Bigg(\frac{[t_1t_2][t_1t_3][t_2t_3]}{[t_1][t_2][t_3][\kappa^{\frac{1}{2}} q ]   [\kappa^{\frac{1}{2}} q^{-1} ]}\Bigg), \quad \kappa=t_1t_2t_3.
$$
\end{theorem}

As noted by Beentjes--Ricolfi \cite{BR}, the Quot scheme $\Quot^{n}_{r}(\C^3)$ parametrizing 0-dimensional quotients $\O_{\C^3}^{\oplus r} \twoheadrightarrow Q$ of length $n$ is also the critical locus of a superpotential. This has been used by Fasola--Monavari--Ricolfi \cite{FMR} and Arbesfeld--Kononov \cite{AK1} to establish the Awata--Kanno conjecture \cite{AK2}:

\begin{theorem}[Fasola--Monavari--Ricolfi, Arbesfeld--Kononov] \label{FMRthm}
$$
\sum_{n=0}^{\infty} \chi(\Quot^{n}_{r}(\C^3), \widehat{\O}^{\vir}) \, ((-1)^r q)^n = \mathrm{Exp}\Bigg(\frac{[t_1t_2][t_1t_3][t_2t_3][\kappa^r]}{[t_1][t_2][t_3][\kappa][\kappa^{\frac{r}{2}} q ]   [\kappa^{\frac{r}{2}} q^{-1} ]}\Bigg).
$$
\end{theorem}

In four dimensions, $\Hilb^n(\C^4)$ and $\Quot^{n}_{r}(\C^4)$ are not critical loci, but instead they can be realized as the zero locus of an isotropic section of an orthogonal bundle on a smooth ambient space. 
Using the $K$-theoretic sheaf counting theory for Calabi--Yau 4-folds defined by Oh--Thomas \cite{OT}, this allows us to give a global definition of Nekrasov--Piazzalunga's invariants and prove their conjecture.
The invariants defined by Oh--Thomas are generalizations and refinements of the sheaf counting invariants on Calabi--Yau 4-folds previously defined by Borisov--Joyce \cite{BJ}, and in special cases by Cao--Leung \cite{CL}.


\subsection{Oh--Thomas theory} \label{sec:OTtheory}

In this paper, we only need what we will call the \textit{standard model} version of Oh--Thomas's invariants \cite{OT}, which we now discuss. 
Let $A$ be a connected smooth quasi-projective variety and $(E,q)$ an orthogonal bundle of even rank $m$ on $A$, i.e.~$E$ is a rank $m$ vector bundle and $q \colon E \otimes E \rightarrow \O_A$ is a non-degenerate symmetric bilinear form. 
Suppose $\Lambda \subset E$ is a maximal isotropic subbundle of $E$.
%, i.e.~$\Lambda$ is a rank $r/2$ subbundle such that $q|_{\Lambda \otimes \Lambda} \equiv 0$. 
This gives a short exact sequence of vector bundles
\begin{equation} \label{splitting}
0 \to  \Lambda \to E \to \Lambda^\vee \to 0.
\end{equation}
Suppose we have an isotropic section $s \in \Gamma(A,E)$, i.e.~$q(s,s)=0$, and let $M = Z(s) \subset A$. This gives rise to the following commutative diagram of sheaves on $M$
\begin{displaymath}
\xymatrix
{
T_A|_M \ar^<<<<{ds}[r] &E|_M \stackrel{q}{\cong} E^\vee|_M  \ar^<<<<<{(ds)^\vee}[r] \ar@{->>}^{s^\vee}[d] & \Omega_A|_M \ar@{=}[d] \\
& I/I^2|_M \ar^{d}[r] & \Omega_A|_M
}
\end{displaymath}
where $I = s^\vee(E) \subset \O_A$ is the ideal cutting out $M$.
We view the top row as a complex $E^\mdot$ of locally free sheaves concentrated in degrees $-2,-1,0$ satisfying $E^{\mdot} \cong (E^{\mdot})^{\vee}[2]$. The bottom row is the truncated cotangent complex $\tau^{\geq -1} \mathbb{L}_M$, and this diagram provides an obstruction theory $E^\mdot \to \tau^{\geq -1} \mathbb{L}_M$. Since $E^\mdot$ is \emph{not} 2-term, we cannot use the classical theory of virtual classes and virtual structure sheaves \cite{BF, LT}.

To get a well-defined virtual class, we must first choose an \textit{orientation} of $E$.
We refer to \cite[Sec.~2]{OT} for a more precise discussion of orientations and the subtle sign choices involved, and we only recall a few basic facts here.
Note that $\Lambda^{m} q$ induces an isomorphism $\det(E) \cong \det(E^\vee)$. An \emph{orientation} of $(E,q)$ is a map $o \colon \O_A \to \det(E)$ such that
the composed map
\[
\O_A \overset{o \otimes o}{\to} \det(E) \otimes \det(E) \overset{\id \otimes \Lambda^{m}q}\to \det(E) \otimes \det(E^\vee) \to \O_A
\]
equals $(-1)^{m/2}\id_{\O_A}$.\footnote{The homomorphism $\det(E) \otimes \det(E^\vee) \to \O_A$ is defined by $a_1\wedge \dots \wedge a_n \otimes a_n^\vee \wedge \dots \wedge a_1^\vee \mapsto 1$.} Under our assumption \eqref{splitting}, we get a canonical isomorphism 
\[
\pi_\Lambda \colon \det(E) \cong \det(\Lambda) \otimes \det(\Lambda^\vee) \cong \O_A,
\]
and, by \cite[Def. 2.2]{OT}, the orientation \textit{induced by} $\Lambda$ is
\[
o_\Lambda = (-i)^{m/2} \pi_{\Lambda}^{-1}.
\]
For a given orientation $o$ of $(E,q)$, we say that $\Lambda$ is \emph{positive} with respect to $o$, if $o_\Lambda = o$.
For our purposes, it is usually more convenient to specify an orientation through a choice of positive maximal isotropic subbundle $\Lambda$ rather than through a trivialisation of $\det(E)$. 
%For the cases of interest to us, we may additionally assume that we have a splitting $E = \Lambda \oplus \Lambda^\vee$.

Oh and Thomas construct a \emph{virtual class} $[M]^{\mathrm{vir}} \in A_n(M,\Z[\tfrac{1}{2}])$ and a \emph{twisted virtual structure sheaf} $\widehat{\mathcal{O}}_M^{\mathrm{vir}} \in K_0(M,\Z[\tfrac{1}{2}])$, which depend on the choice of orientation of $(E,q)$.
Here $A_n(M,\Z[\tfrac{1}{2}])$ is the Chow group of degree $n=\tfrac{1}{2}\rk(E^\mdot)$ with coefficients in  $\Z[\tfrac{1}{2}] = \{\frac{a}{2^b} \, : \, a, b \in \Z\}$, and $K_0(M,\Z[\tfrac{1}{2}]) = K_0(M) \otimes \mathbb Z[\tfrac12]$ denotes the Grothendieck group of coherent sheaves on $M$ ``with coefficients in $\Z[\tfrac{1}{2}]$''.

In the case of interest to us, $M$ is non-compact, but there is an action of an algebraic torus $T$ on $M$, induced by a $T$-action on $A$, with compact fixed locus $M^T$. 
If $E$ and $s$ are $T$-equivariant and $q$ is $T$-invariant, then Oh--Thomas also define the $T$-equivariant versions of these classes $[M]^{\vir} \in A_n^T(M,\Z[\frac12])$ and $\widehat{\O}^{\vir}_M \in K_0^T(M)_{\mathrm{loc}}$. Here $K_0^T(M)_{\mathrm{loc}}$ is defined by \cite[Sect.~7]{OT}
\[
K_0^T(M)_{\mathrm{loc}} := K_0(M) \otimes_{\Z[t,t^{-1}]} \Q(t^{\frac{1}{2}}),
\]
where $t = (t_1, \dots, t_{\dim T})$ is the tuple of $T$-equivariant parameters and furthermore $t^a = (t_1^a,\dots,t_{\dim T}^a)$. 

\begin{remark}
Note that the geometric setup described above is adapted to our concrete problem and is more restrictive than what \cite{OT} require, even locally.

Oh--Thomas also work in a global setting, where $M$ is a quasi-projective scheme with a $(-2)$-shifted symplectic structure (in the sense of \cite{PTVV}) and an orientation. From this data, one obtains an obstruction theory $E^\mdot \to \tau^{\geq -1} \mathbb{L}_M$, where $E^\mdot$ is a self-dual
%\footnote{Self-duality of a complex is defined in \cite[Sect.~4.1]{OT}.} 
3-term complex of locally free sheaves, and a choice of orientation for $E^\mdot$, i.e.~an appropriate trivialisation of $\det(E^\mdot)$.
Oh--Thomas define a virtual class and virtual structure sheaf in this general setting as well.
\end{remark}

\begin{remark} At various points in this text we will be taking square roots of an equivariant line bundle $L$.
In the ring $K^0_T(M)_{\mathrm{loc}}$, a square root of the class of $L$ exists and is unique (see \cite[Sect.~5.1]{OT}), and so we may write $L^{\frac12}$ without further comment.

In Section \ref{sec:global}, where we prove that the generating function $\sfZ^{\NP}_1$ is factorizable, the problem of taking square roots becomes more subtle.
This is because the definition of factorizable sequence requires that certain sheaves are isomorphic, and so we are forced to specify square roots as line bundles rather than just $K$-theory classes, and in particular neither existence or uniqueness of such square roots is automatic.
\end{remark}

In the setting of the standard model, and using the orientation induced by $\Lambda$, we use two facts from \cite{OT}:\ \\

\noindent \textbf{Virtual structure sheaf.}
 Let $\iota \colon M \hookrightarrow A$ denote the inclusion. 
 Then 
$$
\iota_* \widehat{\mathcal{O}}^{\vir}_M = \widehat{\Lambda}^\mdot \Lambda^\vee \otimes \det(T_A)^{-\frac{1}{2}} \in K_0^T(A)_{\loc},
$$
where, for any vector bundle $V$, we define
\begin{equation} \label{eqn:lambdahat}
\Lambda^{\mdot} V = \sum_{i = 0}^{\rk V} (-1)^i \Lambda^i V, \quad \widehat{\Lambda}^{\mdot} V = \frac{\Lambda^\mdot V}{\det(V)^{\frac{1}{2}}}.
\end{equation}

\noindent \textbf{Virtual localization.} Let $T$ be an algebraic torus acting on $A$. Suppose $E,\Lambda, s$ are $T$-equivariant, $q$ is $T$-invariant, and $M^T$ consists of isolated reduced points. Denote the fixed and moving part of a $T$-equivariant complex $V^\mdot$ at a fixed point $P$ by $(V^\mdot|_P)^f$ and $(V^\mdot|_P)^m$. Suppose $\dim( (T_{A} - \Lambda)|_P^f) = 0$ for all $\iota_P \colon \{P\} \subset M^T$, i.e.~all fixed points have virtual dimension 0. 
Then tracking the signs in the localization formula of \cite{OT}, we prove (Section \ref{sec:localfixisolated})
\begin{equation} \label{virloc1}
\widehat{\O}_M^{\vir} = \sum_{P \in M^T} (-1)^{n_P^\Lambda} \, \iota_{P*} \Bigg( \frac{1}{\widehat{\Lambda}^{\mdot} (\Omega_{A} - \Lambda^\vee)|_{P}} \Bigg)
\end{equation}
with
\begin{equation}
\label{eqn:CohomologicalFormulaForLocalisationSign}
n_P^\Lambda \equiv \dim  \mathrm{coker}(p_{\Lambda} \circ ds|_P)^f  \pmod 2,
\end{equation}
where $p_{\Lambda} \circ ds|_P$ is the composition
$$
T_{A}|_P \stackrel{ds|_P}{\to} E|_P  \stackrel{p_{\Lambda}}{\to} \Lambda|_P
$$
and $p_{\Lambda}$ is the projection onto $\Lambda|_P$ for any splitting $E|_P = \Lambda|_P \oplus \Lambda^\vee|_P$.

\subsection{Outline}

In Section \ref{sec:tools} we review and develop some of the general tools used in our proof, i.e.~factorizability, Clifford algebras, spin modules, and torus localization. In Section \ref{sec:global}, we show that $M=\Quot^n_r(\C^4)$ satisfies the ``standard model'' setup by embedding it into a non-commutative Quot scheme $A$. We define $K$-theoretic virtual invariants
$$
N_{r,n}^{\mathrm{glob}} = \chi(M, \widehat{\O}^{\vir}_M \otimes \widehat{\Lambda}^\mdot \hom(\cV,\cW)), 
$$
for a certain bundle $\hom(\cV,\cW)$ on $M$, and consider the generating function
\[
\mathsf{G}_{r} = \sum_{n=0}^{\infty} N_{r,n}^{\mathrm{glob}} \, q^n.
\]

For $r=1$, we use the Hilbert--Chow morphism 
$$
\nu_n \colon \Hilb^n(\C^4) \rightarrow \Sym^n(\C^4)
$$
and consider the $K$-theory classes 
\begin{equation} \label{KclassCh}
R\nu_{n*}( \widehat{\O}^{\vir} \otimes \widehat{\Lambda}^\mdot \hom(\cV,\cW) ).
\end{equation}
We refine these classes to actual equivariant $\Z/2$-graded coherent sheaves, and we show that these sheaves form a factorizable sequence in the sense of Okounkov (\cite[Sect.~5.3]{Oko}, \cite{Ren}). 
The refinement of \eqref{KclassCh} to a sheaf involves describing $\widehat{\O}^{\vir}_M$ in terms of spin modules. 
The fact that the sheaves refining \eqref{KclassCh} form a factorizable sequence implies, as in \cite{Oko}, that the generating function $\mathsf{G}_1$ has the form
\[
\mathrm{Exp}\Bigg(\frac{G_1}{[t_1][t_2][t_3][t_4]}\Bigg),
\]
where $G_1$ is a power series in $q$ whose coefficients are \emph{Laurent polynomials} in the variables $t_i, y^{\frac{1}{2}}$.

In Section \ref{sec:local}, we apply the Oh--Thomas localization formula \eqref{virloc1} to show that our global invariants recover Nekrasov--Piazzalunga's invariants i.e.~$\mathsf{G}_r = \sfZ_r^{\NP}$. The main difficulty is the computation of the parity of $n_P^\Lambda$ in \eqref{virloc1}, which we establish by determining the dimensions of certain Ext groups.

In Section \ref{sec:limits}, we apply Okounkov's rigidity principle to further examine the power series $G_1$ appearing above.
We first show that it is divisible by $[t_1t_2][t_2t_3][t_1t_3]$.
A simple formal argument allows us to then determine $\sfZ^{\NP}_1$ by using the fact that for $y=t_4$, $\sfZ_1^{\NP}$ reduces to the known generating series of $K$-theoretic Donaldson--Thomas invariants of $\C^3$ (Theorem \ref{Okounkovthm}). 
%This dimensional reduction was previously studied in \cite{Nek,CKM}. 
For general $r>1$, we take suitable limits of the framing parameters, which allows us to reduce to the $r=1$ case.%\footnote{In fact, Theorem \ref{FMRthm} is implied by the Nekrasov--Piazzalunga conjecture (Remark \ref{FMRrmk}).} \\ %, much like in \cite{FMR}.\footnote{In fact, Theorem \ref{FMRthm} is implied by the Nekrasov--Piazzalunga conjecture (Remark \ref{FMRrmk}).} This establishes Theorem \ref{mainthm}.


\subsection{Conventions}

The torus $(\C^*)^4 = \Spec \C[t_1^{\pm1}, t_2^{\pm1}, t_3^{\pm1}, t_4^{\pm1}]$ acts on closed points $(p_1,p_2,p_3,p_4) \in \C^4$ via
\[
(t_1, t_2, t_3, t_4) \cdot (p_1,p_2,p_3,p_4) = (t_1^{-1}p_1,t_2^{-1}p_2,t_3^{-1}p_3,t_4^{-1}p_4),
\]
so that the character of $H^0(\C^4, \O_{\C^4})$ is $\prod_{i=1}^4 (1-t_i)^{-1}$, and not $\prod_{i=1}^4 (1-t_i^{-1})^{-1}$.
This convention agrees with roughly half of the relevant literature.

For a quasi-projective scheme $Y$ with action by an algebraic torus $T$, we define $K_0^T(Y)_{\loc} := K_0^T(Y) \otimes_{K^T_0(\pt)} \Q(t^{\frac{1}{2}})$, where $K^T_0(\pt) = \Z[t^{\pm 1}]$ and  $t = (t_1, \ldots, t_{\dim T})$ is the tuple of $T$-equivariant parameters. By the $K$-theoretic localization formula \cite{Tho}, push-forward along the inclusion $Y^T \hookrightarrow Y$ gives $K^T_0(Y^T)_{\loc} \cong K_0^T(Y)_{\loc}$.

We use the phrase ``$\Z/2$-graded coherent sheaf'' to mean a sheaf $\F = \F_0 \oplus \F_1$ where the grading is to be interpreted as a cohomological grading.
In $K$-theory we have $[\F] = [\F_0] - [\F_1]$.
If $\F$ and $\G$ are $\Z/2$-graded sheaves, then in the isomorphism $\F \otimes \G \cong \G \otimes \F$ we apply the Koszul sign rule.

Given a 2-periodic complex $\F$, we write $\cH(\F) := H^{-1}(\F)[1] \oplus H^0(\F)$ for its $\Z/2$-graded cohomology sheaf.

