The relevance of spin geometry in the Donaldson--Thomas theory of Calabi--Yau 4-folds was recently worked out by N.~Kuhn \cite{Kuh}.
\begin{definition}
	A \emph{spin module} for $(E,q)$ is a left $C(E)$-module $S$, locally free of finite rank as $\O_X$-module, such that there exists an isomorphism of $\cO_X$-modules
	\begin{equation}
		\label{eqn:spinModuleStructure}
		\phi \colon S^\dagger \otimes_{C(E)} S \cong \cO_X.
	\end{equation}
\end{definition}
For given $(E,q)$, the natural category of pairs $(S,\phi)$, where $S$ is a spin module and $\phi$ an isomorphism, is equivalent to the category of $\text{Spin}(2n)$-structures on the $SO(2n)$-bundle $E$; see \cite[Sec.~A.6]{Kuh} for a parallel discussion of $\text{Spin}^{\mathbb C}(2n)$-structures.

Let $S$ be a spin module, and let $S^\vee = \sHom(S, \cO_X)$, which is a right $C(E)$-module.
We have that the homomorphism 
\[
C(E) \to \sHom(S, S) = S \otimes S^\vee
\]
is an isomorphism of $C(E)$-bimodules.
The isomorphism \eqref{eqn:spinModuleStructure} induces an isomorphism of right $C(E)$-modules $S^\dagger \cong S^\vee$, and so we get an isomorphism of $C(E)$-bimodules
\[
S \otimes S^\dagger \cong C(E).
\]

\begin{example} \label{ex:sqrtdetgivesspin}
	Assume that $E$ has a maximal isotropic subbundle $\Lambda$, and that $L$ is a square root of $\det \Lambda$.
	Then $C(E)\Lambda \otimes L^{-1}$ is a spin module for $E$, since
	\begin{align*}
	(C(E)\Lambda \otimes L^{-1})^\dagger \otimes_{C(E)} (C(E)\Lambda \otimes L^{-1}) &\cong L^{-2} \otimes \Lambda C(E) \otimes_{C(E)} C(E)\Lambda \\
	&\cong \det(\Lambda)^{-1} \otimes \det(\Lambda) \cong \cO_X,
	\end{align*}
using the isomorphisms from \eqref{eqn:lambdaOpposite} and Lemma \ref{thm:detIsomorphism}.
\end{example}

Conversely, if $\Lambda$ is a maximal isotropic subbundle of $E$ and $S$ is a spin module, then we have an isomorphism
\begin{align*}
	(S^\dagger \otimes_{C(E)} C(E)\Lambda)^{\dagger} \otimes S^\dagger \otimes_{C(E)} C(E)\Lambda &\cong \Lambda C(E) \otimes_{C(E)} S \otimes S^\dagger \otimes_{C(E)} C(E)\Lambda \\
	&\cong \Lambda C(E) \otimes_{C(E)} C(E) \Lambda \cong \det \Lambda.
\end{align*}
It follows that
\begin{equation}
	\label{eqn:squarerootDefinition}
(\det \Lambda)_S^{1/2} :=  \Lambda C(E) \otimes_{C(E)} S
\end{equation}
is a square root of $\det \Lambda$.
We have have an inclusion of $\cO_X$-modules
\begin{equation}
	\label{eqn:inclusionOfSquareRoot}
(\det \Lambda)^{1/2}_S = \Lambda C(E) \otimes_{C(E)} S \to C(E) \otimes_{C(E)} S \to S.
\end{equation}
\begin{remark}
	\label{rmk:imageOfLambdaSquareRoot}
If $S = C(E)\Lambda \otimes L^{-1}$, with $L$ a square root of $\det(\Lambda)$, then a simple computation shows that the image of $(\det \Lambda)^{1/2}_S \to S$ is the submodule spanned by $e_1\cdots e_n \otimes t$, for some local basis $e_1,\dots, e_n$ of $\Lambda$ and trivializing section $t$ of $L^{-1}$. We note that \'etale locally, any spin module $S$ can be expressed as $S \cong C(E)\Lambda$ for some maximal isotropic subbundle $\Lambda$. Indeed, étale locally such a $\Lambda$ exists, and the Picard group of $X$ is trivial. The Morita equivalence between $C(E)$ and $\cO_X$ must then send both $S$ and $C(E)\Lambda$ to $\cO_X$.
\end{remark}

So far, we have not used the orientation $o$ on $(E,q)$. The orientation allows us to endow each left $C(E)$-module with a $\Z/2$-grading.
\begin{definition}
	The orientation $o$ of $E$ induces a \textit{volume element} $\omega_o$ in the Clifford algebra, see \cite[Def.~A.11]{Kuh}.
	Working \'etale locally, we may choose $\Lambda$ and $\Lambda'$ to be dual maximal isotropic subbundles of $E$, with $e_1,\dots, e_n$ a basis of $\Lambda$ and $f_1, \dots f_n$ a dual basis of $\Lambda'$ such that $q(e_i,e_j) = q(f_i,f_j) = 0$ and $q(e_i,f_j) = \delta_{ij}$ for all $i,j=1, \ldots, n$, and moreover such that $\Lambda$ is positive.
	Then
	\[
	\omega_o = (e_1f_1 -1)\cdots(e_n f_n -1).
	\]
\end{definition}
We have $\omega_o^2 = 1$, and for every section $s$ of $E$, that 
\begin{equation}
	\label{eqn:commutatorOmega}
	\omega_o s + s\omega_o = 0.
\end{equation}
If $M$ is a left $C(E)$-module, then the action of $\omega_o$ on $M$ induces a splitting $M = M_0 \oplus M_1$ of $\cO_X$-modules, where sections of $M_j$ satisfy $\omega_o m = (-1)^jm$.
By \eqref{eqn:commutatorOmega}, if $m \in M$ is such that $\omega_o m = \pm m$ and $s$ is a section of $E$, then $\omega_o sm = \mp sm$.
It follows that the splitting $M_0 \oplus M_1$ gives $M$ a structure of $\ZZ/2$-graded $C(E)$-module with respect to the $\ZZ/2$-grading of $C(E)$.

\begin{definition} \label{def:complex}
	Let $s$ be an isotropic section of $E$, and let $S$ be a spin module.
	Define $(S,s)$ to be the $\ZZ/2$-graded complex whose underlying sheaf is the $\ZZ/2$-graded $\cO_X$-module $S$, and with differential given by $d(m) = sm$.
\end{definition}
It follows from the fact that $s$ is isotropic that $s^2 = 0$, so that $d^2(m) = s^2m = 0$, i.e., $d$ is a differential.

\begin{example} \label{ex:reltoperiodcx}
	Suppose $\Lambda \subset E$ is positive maximal isotropic, $E = \Lambda \oplus \Lambda^\vee$, and $s$ is an isotropic section. Suppose furthermore that $L$ is a square root of $\det(\Lambda)$. Then $S := L^{-1} \otimes C(E) \Lambda $ is a spin module (Example \ref{ex:sqrtdetgivesspin}) and
	\[
	L \otimes \Lambda^\mdot \Lambda^\vee \cong S
	\]
	as $\Z/2$-graded $C(E)$-modules, where the map, in the usual local basis, and with $t$ a section of $L$ squaring to $e_1 \wedge \dots \wedge e_n$, is induced by 
    \[
    t \otimes f_{i_1} \wedge \cdots \wedge f_{i_k} \mapsto t^\vee \otimes f_{i_1} \cdots f_{i_k} e_1 \cdots e_n.
    \]
    The differential $s = (s_{\Lambda},s_{\Lambda^\vee})$ then corresponds to $s_{\Lambda^\vee} \wedge (-) + s_{\Lambda}\intprod (-)$ on $L \otimes \Lambda^\mdot \Lambda^\vee$ and we obtain a 2-periodic complex
	\[
	\cdots \stackrel{s_{\Lambda^\vee} \wedge + s_{\Lambda}\intprod}{\xrightarrow{\hspace*{1.5cm}}} L \otimes \Lambda^{\mathrm{even}} \Lambda^\vee \stackrel{s_{\Lambda^\vee} \wedge + s_{\Lambda}\intprod}{\xrightarrow{\hspace*{1.5cm}}} L \otimes \Lambda^{\mathrm{odd}} \Lambda^\vee \stackrel{s_{\Lambda^\vee} \wedge + s_{\Lambda}\intprod}{\xrightarrow{\hspace*{1.5cm}}} \cdots 
	\]
\end{example}

It is well-known that the cohomology sheaves of the 2-periodic complex of the previous example are supported on $Z(s) = Z(s_{\Lambda}) \cap Z(s_{\Lambda^\vee})$ \cite[Rem.~3.2]{OS}. Since any spin module is \'etale locally of the above form, we deduce the following lemma.

\begin{lemma} \label{lem:suppZ(s)}
For any spin module $S$ and isotropic section $s$ of $(E,q)$, the sheaf $\mathcal{H}(S,s) = H^{-1}(S,s)[1] \oplus H^{0}(S,s)$ is supported on $Z(s)$.
\end{lemma}

We now turn our attention to tensor products of spin modules.
%\begin{definition}
%	\label{defn:orientationOfSum}
	Given oriented quadratic vector bundles $(E_1,q_1,o_1), (E_2,q_2,o_2)$ of even rank on $X$, the quadratic bundle $(E_1 \oplus E_2,q_1 \oplus q_2)$ has an induced orientation $o_1 \otimes o_2$. %From now on, we sometimes drop $q_i, o_i$ from the notation and simply speak of an oriented quadratic vector bundle --- always of even rank. \textcolor{orange}{we could make this convention earlier on}
%\end{definition}

\begin{definition}
	If $A, B$ are two $\ZZ/2$-graded sheaves of $\O_X$-algebras, then we write $A \, \widehat{\otimes} \, B$ for the algebra $A \otimes B$, equipped with the natural tensor product grading, and with the product for homogeneous sections $a,a'$ of $A$ and $b, b'$ of $B$ determined by
	\[
	(a \otimes b)(a' \otimes b') = (-1)^{|b||a'|}aa' \otimes bb'.
	\]
\end{definition}

The following lemma is straightforward.
\begin{lemma} \label{lem:tensorCliff}
	Given oriented quadratic bundles $(E_1,q_1,o_1), (E_2,q_2,o_2)$ on $X$, we have an isomorphism
	\[
	C(E_1) \, \widehat{\otimes} \, C(E_2) \cong C(E_1 \oplus E_2),
	\]
	defined by
	\[
	s_1 \otimes 1 \mapsto (s_1,0)
	\]
	and 
	\[
	1 \otimes s_2 \mapsto (0,s_2).
	\]
	This satisfies
	\[
	\omega_{o_1} \otimes \omega_{o_2} \mapsto \omega_{o},
	\]
	where $o$ is the orientation $o_1 \otimes o_2$ of $(E_1 \oplus E_2,q_1 \oplus q_2)$.
\end{lemma}
Going forward, we will implicitly identify $C(E_1 \oplus E_2)$ and $C(E_1) \, \widehat{\otimes} \, C(E_2)$.
If $M_1$ and $M_2$ are $\ZZ/2$-graded modules for $C(E_1)$ and $C(E_2)$ respectively, the sheaf $M_1 \otimes M_2$ is a $C(E_1) \, \widehat{\otimes} \, C(E_2)$-module by
\[
(a \otimes b)(m \otimes m') = (-1)^{|b||m|} am \otimes bm'.
\]

\begin{lemma}
	\label{thm:tensorProduct}
	Let $M_1, N_1, M_2, N_2$ be $\ZZ/2$-graded modules of $C(E_1)$ and $C(E_2)$ respectively.
	We have an isomorphism of $\cO_X$-modules
	\[
	(M_1 \otimes M_2)^\dagger \otimes_{C(E_1 \oplus E_2)} (N_1 \otimes N_2) \cong (M_1^\dagger \otimes_{C(E_1)} N_1) \otimes (M_2^\dagger \otimes_{C(E_2)} N_2).
	\]
\end{lemma}
\begin{proof}
	The isomorphism is given on $\ZZ/2$-homogeneous sections by
	\[
	a \otimes b \otimes c \otimes d \mapsto (-1)^{(|a| + |c|)|b|} a\otimes c \otimes b \otimes d.
	\]
	It is straightforward to check that this gives a well-defined homomorphism (that is, respects the relations defining the tensor product), and that the obvious inverse is also well-defined.
\end{proof}

\begin{corollary}
	Given oriented quadratic vector bundles $E_1, E_2$ on $X$, with spin modules $S_1, S_2$ for $E_1, E_2$ respectively, the $C(E_1) \, \widehat{\otimes} \, C(E_2)$-module $S_1 \otimes S_2$ is a spin module for $E_1 \oplus E_2$.\footnote{Note that the tensor product grading of $S_1 \otimes S_2$ coincides with the one coming from the orientation on $E_1 \oplus E_2$ by Lemma \ref{lem:tensorCliff}.}
\end{corollary}
\begin{proof}
	By Lemma \ref{thm:tensorProduct}, we get
	\[
	(S_1 \otimes S_2)^\dagger \otimes_{C(E_1 \oplus E_2)} (S_1 \otimes S_2) \cong (S_1^\dagger \otimes_{C(E_1)} S_1) \otimes (S_2^\dagger \otimes_{C(E_2)} S_2) \cong \cO_X \otimes \cO_X \cong \cO_X.
	\]
\end{proof}

Let $E_1, E_2$ be oriented quadratic vector bundles on $X$, let $S$ be a spin module for $E_1 \oplus E_2$ and $S_1$ a spin module for $E_1$.
Give $S_1^\vee$ a $\ZZ/2$-grading as a right $C(E_1)$-module such that the homomorphism $m \colon S_1 \otimes S_1^\vee \to C(E_1)$ is homogeneous.
Let 
\[
S \setminus S_1 = S_1^\vee \otimes_{C(E_1)} S,
\]
considered as a $C(E_2)$-module by, for a section $s_2$ of $E_2$ and homogeneous sections $a$ of $S_1^\vee$ and $b$ of $S$
\[
s_2(a \otimes b) = (-1)^{|a|} a \otimes s_2b.
\]
\begin{lemma}
	\label{thm:subtractingSpinModules}
	The $C(E_2)$-module $S \setminus S_1$ defined above is a spin module for $E_2$.
\end{lemma}
\begin{proof}
	We have an isomorphism of $C(E_1)$-modules
	\[
	S_1 \otimes (S \setminus S_1) = S_1 \otimes S_1^\vee \otimes_{C(E_1)} S \overset{m \otimes \id_S}{\cong} C(E_1) \otimes_{C(E_1)} S \cong S,
	\]
	and we claim this is also an isomorphism of $C(E_1) \, \widehat{\otimes} \, C(E_2)$-modules.
	It is enough to check that the homomorphism commutes with multiplication by a section $s_2$ of $E_2$.
	So let $a, b, c$, be homogeneous sections of $S_1, S_1^\vee$ and $S$, respectively, then we have
	\[
	s_2(a \otimes (b \otimes c)) = (-1)^{|a|} a \otimes s_2(b\otimes c)  = (-1)^{|a| + |b|} a \otimes b \otimes s_2c.
	\]
	It follows that
	\begin{align*}
	m \otimes \id_S(s_2(a \otimes b \otimes c)) &= (-1)^{|a| + |b|} m(a \otimes b) \otimes s_2 c \\
	&= (-1)^{|m(a \otimes b)|} m(a \otimes b) \otimes s_2 c = s_2(m(a \otimes b) \otimes c).
	\end{align*}
We now have, by Lemma \ref{thm:tensorProduct}, that
\begin{align*}
\cO_X &\cong S^{\dagger} \otimes_{C(E_1 \oplus E_2)} S \cong (S_1 \otimes (S\setminus S_1))^\dagger \otimes_{C(E_1 \oplus E_2)} (S_1 \otimes (S\setminus S_1)) \\
&\cong (S_1^\dagger \otimes_{C(E_1)} S_1) \otimes ((S\setminus S_1)^\dagger \otimes_{C(E_2)} (S\setminus S_1)) \cong (S\setminus S_1)^\dagger \otimes_{C(E_2)} (S\setminus S_1). \qedhere
\end{align*}
\end{proof}
If $\Lambda_1$ and $\Lambda_2$ are maximal isotropic subbundles of quadratic bundles $E_1$ and $E_2$ on $X$, then from \eqref{eqn:inclusionOfSquareRoot} we get inclusions
\begin{gather*}
\det(\Lambda_1)^{1/2}_{S_1} \otimes \det(\Lambda_2)^{1/2}_{S_2} \to S_1 \otimes S_2 \\
\det(\Lambda_1 \oplus \Lambda_2)^{1/2}_{S_1 \otimes S_2} \to S_1 \otimes S_2.
\end{gather*}
These have the same image, and so give an isomorphism 
\begin{equation} \label{eqn:sqrtdetdirectsum}
\det(\Lambda_1)^{1/2}_{S_1} \otimes \det(\Lambda_2)^{1/2}_{S_2} \cong \det(\Lambda_1 \oplus \Lambda_2)^{1/2}_{S_1 \otimes S_2}.
\end{equation}


\subsection{Pull-back of spin modules} \label{sec:pullbackspin}
In this section, we consider the following setup.
Let $A$ be a smooth variety of dimension $d$, let $E$ be an oriented quadratic vector bundle of rank $2n$ on $A$ with quadratic form $q$, let $s$ be an isotropic section of $E$, and let $S$ be a spin module for $C(E)$.
Let $A_0$ be a smooth variety of dimension $d_0$, and let $f \colon A_0 \to A$ be an unramified morphism.
Let $E_0$ be an oriented quadratic vector bundle of rank $2n_0$, with quadratic form $q_0$, which embeds as a subbundle of $E|_{A_0}$ compatibly with the quadratic forms. 
Let $S_0$ be a spin module for $C(E_0)$.
Assume that the section $s$ lies in $E_0$ after restriction to $A_0$, and let $s_0 = s|_{A_0}$ be the resulting section of $E_0$.
We further assume that $d - d_0 = n - n_0$.
As $E_0$ is a quadratic subbundle of $E|_{A_0}$, we have a quadratic bundle $E' = E_0^\perp$ of rank $2n - 2n_0$ with quadratic form $q'$ such that $(E|_{A_0},q) = (E_0 \oplus E', q_0 + q')$. 

We are interested in relating $f^*(S,s)$ (or rather its cohomology sheaves) to $(S_0,s_0)$.
This will be possible under the following assumption, which will be satisfied in the setting we explore in Section \ref{sec:global}.
Let $N = N_{A_0/A} = f^*T_{A}/T_{A_0}$.
\begin{assumption}
\label{assume:LocalForm}
Working on $Z(s_0)$, define $\phi$ by the commutative diagram
\[
\begin{tikzcd}
    0\arrow[r]&T_{A_0}\arrow[r]\arrow[d,"ds_0"] &f^*T_A\arrow[r]\arrow[d, "ds"] &N\arrow[r]\arrow[d, "\phi"] &0 \\
    0\arrow[r]&E_0\arrow[r] &f^*E\arrow[r] &E'\arrow[r] &0
\end{tikzcd}
\]
Then $\phi$ is an injective map of vector bundles, embedding $N|_{Z(s_0)}$ as a maximal isotropic subbundle of $E'|_{Z(s_0)}$.

Let $p \in Z(s_0)$, and let $\widehat{\cO}_{A,f(p)}$ be the completion of the local ring at $f(p)$, isomorphic to a formal power series ring in $d$ variables.
We assume that formally locally, i.e.~after base changing the whole setup along $\Spec \widehat{\cO}_{A,f(p)} \to A$, the following hold:
\begin{itemize}
	\item We have an isomorphism $\widehat{\cO}_{A,f(p)} \cong \CC[[x_1,\dots, x_{d_0}, y_1,\dots y_{d-d_0}]]$, and $A_0$ is defined by the vanishing of the $y_i$.
	\item We have an isomorphism $E \cong \cO_A^{2n}$, with quadratic form
	\begin{equation} \label{eqn:standardquadraticform}
q(a_1,\dots, a_{2n_0}, b_1, \dots, b_{2n-2n_0}) = \sum_{i=1}^{n_0}a_ia_{i+n_0} + \sum_{i=1}^{n-n_0}b_ib_{i+n-n_0}.
	\end{equation}
	%oriented so that the maximal isotropic subspace spanned by unit vectors corresponding to $a_1,\dots, a_{n_0}$ and $b_1,\dots, b_{n-n_0}$ is positive.
	\item The subbundle $E_0 \to E|_{A_0}$ is identified with the inclusion $\cO_{A_0}^{2n_0} \to \cO_A^{2n}|_{A_0}$ in the first $2n_0$ coordinates.
    %, oriented so that the maximal isotropic subspace spanned by the first $n_0$ unit vectors is positive.
	\item The section $s$ of $E$ has the form
	\begin{equation}
		\label{eqn:specialFormOfS}
	(g_1,\dots, g_{2n_0}, h_1,\dots, h_{2d-2d_0}),
	\end{equation}
	where each $g_i$ lies in $(x_1,\dots, x_{d_0}) + (y_1,\dots, y_{d-d_0})^2$ and each $h_i$ lies in $(y_1,\dots, y_{d-d_0})$.
\end{itemize}
\end{assumption}

With the above normalizations, we (formally locally) have $E' \cong \cO_{A_0}^{2n-2n_0} \subseteq \cO_{A_0}^{2n}$, consisting of the last $2n - 2n_0$ factors.
In the above choice of coordinates, $N$ embeds in $E' \cong \cO_{A_0}^{2n-2n_0}$ as the subbundle spanned by the first $n-n_0$ unit vectors.

\begin{lemma}
\label{thm:strongerLocalForm}
% Let $x_1,\dots, x_M, y_1, \dots, y_N$ be formal local coordinates around a point of a closed embedding of smooth varieties $A_0 \hookrightarrow A$, and let $R = \CC[[x_1, \ldots, x_M,y_1, \ldots, y_N]]$, equipped with the bigrading of monomials such that $x_i^ay_j^b$ has degree $(a,b)$.
% Let $E_1 = \cO^{2r}$ and $E_2 = \cO^{2N}$, with the standard quadratic forms \eqref{eqn:standardquadraticform}.
% Assume we are given sections $s_1$ and $s_2$ of $E_1, E_2$ such that: 
% \begin{itemize}
% 	\item $s_1$ and $s_2$ vanish at $0$.
% 	\item the components of $s_1$ have no terms of degree $(0,1)$;
% 	\item the components of $s_2$ are contained in and generate $(y_1,\dots, y_N)$;
% 	\item the section $(s_1,s_2)$ is isotropic.
% \end{itemize}
% Then there exist $y_1',\dots, y_N' \in R$ such that $R = \CC[[x_1, \ldots, x_M,y_1', \ldots, y'_N]]$, such that $(y'_1,\dots, y_N') = (y_1,\dots, y_N)$, and a new splitting $E_1' \oplus E'_2 = E_1 \oplus E_2$ such that $E'_1 =E_1$ after restricting to $Z(y_1, \ldots, y_N)$).
% Moreover there exist trivializations of $E_1'$ and $E_2'$ such that the induced sections $s'_1$ and $s'_2$ satisfy
% \begin{itemize}
% 	\item $s'_1$ has no $y'_i$-dependence;
% 	\item $s'_2 = (y_1',\dots, y_N', 0, \dots, 0)$.
% \end{itemize}

If Assumption \ref{assume:LocalForm} holds, we may find local coordinates $x_i, y_i$ and a trivialization of $E$ such that the section $s$ has the form
\[
(g_1,\dots, g_{2n_0}, y_1,\dots, y_{d-d_0},\overbrace{0,\dots, 0}^{d-d_0}),
\]
where each $g_i$ lies in $\C[[x_1,\dots, x_{d_0}]]$, that is, it is independent of the $y_j$.
\end{lemma}
\begin{proof}
    Consider the bigrading on monomials of $R = \C[[x_1,\dots, x_{d_0}, y_1,\dots y_{d-d_0}]]$ where $x_i^ay_j^b$ has degree $(a,b)$.
    Write $I_{a,b}$ for the ideal of $R$ generated by all monomials of degree $(a,b)$.

    Let $s'$ be the section of $E$ defined by the terms of $s$ of degree $(0,1)$.
	Since $s$ has no constant term, the degree $(0,2)$ part of the relation $q(s,s) = 0$ is the same as that in $q(s',s')$.
    This implies that $s'$ is also isotropic.
    By assumption, the $g_i$ have no terms of degree $(0,1)$, so $s'$ is of the form
    \[
    (0,\dots, 0, h_1',\dots, h_{2d-2d_0}').
    \]
    The constant sections $\frac{\partial}{\partial y_i}(s')$ of $E'$ are isotropic and mutually orthogonal since $s'$ is, and they are all non-zero by the assumption that $\phi$ is injective.

    We may therefore choose a new trivialization of $E'$ where the first $d-d_0$ component vectors are the vectors $\frac{\partial}{\partial y_i}(s')$.
	It follows that $s$ has the form
	\[
	(g_1,\dots, g_{2n_0}, y_1 + h_1'', \dots, y_{d-d_0} + h_{d-d_0}'', h_{d-d_0+1}'', \dots, h_{2d-2d_0}''),
	\]
	where each $h_i'' \in I_{1,1} + I_{0,2}$.
    We make the variable change setting $y_i$ to $y_i + h_i''$, and so $s$ has the form
	\[
	(g_1',\dots, g_{2n_0}', y_1, \dots, y_{d-d_0}, h_{d-d_0+1}''', \dots, h_{2d-2d_0}'''),
	\]
    where $g_i' \in I_{1,0} + I_{0,2}$ and $h_i''' \in I_{1,1} + I_{0,2}$.

	Let us write the local frame for $E$ as 
    \[
    (v_1,\dots, v_{n_0}, v'_1, \dots, v'_{n_0},w_1,\dots, w_{d-d_0}, w_1',\dots, w_{d-d_0}').
    \]
	We now iteratively change these trivial sections to obtain each of the conditions claimed.

    By assumption, $q(s,v_1) = g'_{n_0+1}$ has no terms of degree $(0,1)$, so we can write
	\[
	q(s,v_1) = F(x) + \sum_{i=1}^{d-d_0}y_iF_i(x,y),
	\]
	where $F_i(x,y) \in I_{0,1}$ and $F(x)$ has no $y_i$-dependence.
	Now replace $v_1$ by $v_1 - \sum_{i=1}^{d-d_0} F_iw'_i$ and replace each $w_i$ by $w_i + F_iv'_1$.
    We then have that $q(s, v_1)$ has no $y_i$-dependence.
	Iterating this over $v_2,\dots, v_{n_0}$, and next similarly over $v'_1, \dots, v'_{n_0}$, we end up with no $y_i$-dependence in $q(s,v_i)$ and $q(s,v'_i)$.
    In other words, with respect to the new trivialization of $E$, the section $s$ has the form
    \[
    (g_1'',\dots, g_{2n_0}'', y_1,\dots y_{d-d_0},h_{d-d_0+1}'''',\dots, h_{2d-2d_0}''''),
    \]
    where the $g_i''$ have no $y_i$-dependence and the $h_i''''$ lie in $I_{1,1} + I_{0,2}$.
	Note that as the frame is unchanged modulo the $y_i$, it is still true that $E_0$ is identified with the subbundle spanned by the first $n_0$ factors of $E$ over $A_0$.

    Now for $i \ge 2$, write $h_i'''' = y_1G_i(x,y) + F_i(x,y)$, where $F_i$ has no $y_1$-dependence.
    Replacing $w_1$ by $w_1 + \sum_{i=2}^{d-d_0} G_iw'_i$, and for all $i \ge 2$, replacing $w_i$ by $w_i - G_iw'_1$, we get instead that for all $i \ge 2$
    \[
    q(s,w_i) = F_i(x,y),
    \]
    so has no $y_1$-dependence.
    Since $s$ is isotropic, we then have
    \[
    0 = q(s,s) = \sum_{i=1}^{n_0} g_i''g_{i + n_0}'' + \sum_{i=1}^{d-d_0}y_iq(s,w_i).
    \]
    Since the only term of this sum which has $y_1$-dependence is $y_1q(s,w_1)$, we must have $q(s,w_1) = 0$.

    Iterating this argument to redefine $w_i$ for all $i \ge 2$, we find a normalization such that $q(s,w_i) = 0$ for all $i$, which is what we wanted.
\end{proof}

Let $S' = S_0^{\vee} \otimes_{C(E_0)} S|_{A_0}$, the spin module of $C(E')$ from Lemma \ref{thm:subtractingSpinModules}.
Recall that from \eqref{eqn:inclusionOfSquareRoot} we have an inclusion of $\cO_{Z(s_0)}$-modules $(\det N)^{1/2}_{S'}|_{Z(s_0)} \to S'|_{Z(s_0)}$.
\begin{lemma}
	\label{thm:comparisonHomomorphismExists}
	Suppose $N$ is positive. Under Assumption \ref{assume:LocalForm}, the homomorphisms of $\ZZ/2$-graded sheaves
	\[
	f^*(\cH(S,s)) \to \cH(f^*(S,s)) \cong \cH((S_0,s_0) \otimes (S',0)) \cong \cH(S_0,s_0) \otimes (S',0)|_{Z(s_0)}
	\]
	and
	\[
	\cH(S_0,s_0) \otimes (\det N)^{1/2}_{S'} \to \cH(S_0,s_0) \otimes (S',0)|_{Z(s_0)}
	\]
    are both injective and have the same image. In particular, we have an induced isomorphism of $\Z/2$-graded sheaves
	\[
	f^*(\cH(S,s)) \stackrel{\cong}{\to} \cH(S_0,s_0) \otimes (\det N )_{S'}^{1/2}.
	\]
\end{lemma}
\begin{proof}
	The claim can be verified formally locally at a point $p \in Z(s_0)$, so we may assume that we have made a choice of coordinates $x_i, y_i$ and trivialization $E \cong \cO_A^{2n}$ satisfying Assumption \ref{assume:LocalForm}, as well as the stronger assumption on $s$ granted by Lemma \ref{thm:strongerLocalForm}.
	We let $\overline E_0$ and $\overline E'$ be the subbundle of $\cO_A^{2n}$ spanned by the first $2n_0$ and last $2n - 2n_0$ unit vectors respectively, and so $E = \overline E_0 \oplus \overline E'$, while $\overline E_0|_{A_0} = E_0$ and $\overline E'|_{A_0} = E'$.

	Let $\Lambda_0 \subseteq \overline E_0$ and $\Lambda' \subseteq \overline E'$ be the maximal isotropic subbundles spanned by the first $n_0$ and first $n - n_0$ unit vectors, respectively, and let $\Lambda = \Lambda_0 \oplus \Lambda' \subseteq E$. Accordingly, we can split the section $s = (\overline{s}_0, \overline{s}')$.
	%These maximal isotropic subbundles are all positive, and we have 
    Note that $\Lambda'|_{A_0} = N$ as subbundles of $E'$.

	We may choose isomorphisms $S \cong C(E)\Lambda$ and $S_0 \cong C(E_0) \Lambda_0|_{A_0}$ (see Remark \ref{rmk:imageOfLambdaSquareRoot}).
	We also have an isomorphism
	\[
	S \cong C(E)\Lambda \cong C(\overline E_0)\Lambda_0 \otimes C(\overline E')\Lambda',
	\]
	which moreover agrees with differentials, so we have an isomorphism of complexes
	\[
	(S,s) \cong (C(\overline E_0)\Lambda_0, \overline s_0) \otimes (C(\overline E')\Lambda', \overline s').
	\]

	By the assumption on the $g_i$ in \eqref{eqn:specialFormOfS}, the complex $(C(\overline E_0), \overline s_0)$ is a free $\cO_A$-module with differential only depending on the $x_i$ and $(C(\overline E'), \overline s')$ is a free $\cO_A$-module with differential only depending only on the $y_i$.

	The first homomorphism in the lemma factors through a sequence of isomorphisms (we suppress differentials from the notation)
	\begin{align*}
	&f^*\cH(S) \cong f^*(\cH(\overline S_0 \otimes \overline S')) \overset{(1)}{\cong}f^*(\cH(\overline S_0) \otimes \cH(\overline S')) \cong f^*(\cH(\overline S_0))\otimes f^*(\cH(\overline S')) \\ &\overset{(2)}{\cong} \cH(f^*\overline S_0) \otimes f^*(\cH(\overline S')) \cong \cH(S_0) \otimes f^*(\cH(\overline S')) \to \cH(S_0) \otimes \cH(f^*(\overline S')) \cong \cH(S_0) \otimes S'.
	\end{align*}
	Here the isomorphism (1) follows from the fact that $\overline S_0$ and $\overline S'$ have differentials depending on $x_i$ and $y_i$ respectively.
	The isomorphism (2) follows from the differential of $\overline S_0$ depending only on $x_i$, and $f \colon A_0 \to A$ being the inclusion of the vanishing locus of the $y_i$.

	Our claim now follows from showing that the homomorphisms $f^*(\cH(\overline S')) \to \cH(f^*(\overline S')) \cong S'$ and $(\det N)^{1/2}_{S'} \to S'$ are injective with the same image.
	Under the isomorphisms $\overline S' = C(\overline E')\Lambda'$ and $S' = C(E')\Lambda'|_{A_0}$, we find that $\overline S'$ is the Koszul complex associated with $y_1,\dots, y_{d-d_0}$, and that the first homomorphism is injective with image $\det (\Lambda')|_{A_0} \subseteq C(E')\Lambda'|_{A_0}$.
	As $N = \Lambda'|_{A_0}$, the image of the second homomorphism is the same $\det(\Lambda')|_{A_0}$, by Remark \ref{rmk:imageOfLambdaSquareRoot}. Finally, since $N$ is positive, the isomorphism obtained this way is $\Z/2$-graded.
\end{proof}
From Lemma \ref{thm:comparisonHomomorphismExists}, we get an isomorphism 
\begin{equation}
	\label{eqn:comparisonHomomorphism}
f^*(\cH(S,s)) \overset{\cong}{\to} \cH(S_0,s_0) \otimes (\det N)_{S'}^{1/2}.
\end{equation}

\subsubsection*{Associativity} We now assume that $A_0 \overset{f_1}{\to} A_1 \overset{f_2}{\to} A_2$ are unramified morphisms of smooth varieties, and that for $i = 0, 1, 2$, we have an oriented quadratic vector bundle $E_i$ on $A_i$ of rank $2n_i$ with an isotropic section $s_i$ and a spin module $S_i$ for $E_i$.
We further assume that for $i=0, 1$, we have an inclusion $E_i \subseteq f_{i+1}^*E_{i+1}$, such that the assumptions above Lemma \ref{thm:comparisonHomomorphismExists} hold.
It follows from this that we also have an inclusion $E_0 \subseteq (f_2 \circ f_1)^*E_2$ such that the assumptions hold.
For $0 \le i < j \le 2$, write $N_{ij}$ for the normal bundle of $A_i$ in $A_j$, and write 
\[
S_{j} \setminus S_i = S_i^\vee \otimes_{C(E_i)} S_j|_{A_i},
\]
for the spin module of $C(E_j|_{A_i}/E_i)$ from Lemma \ref{thm:subtractingSpinModules}.
Suppose that, over $Z(s_i)$, the maximal isotropic subbundles $N_{ij}$ of $E_{j}|_{A_i}/E_i$ are positive. By \eqref{eqn:inclusionOfSquareRoot} we have an inclusion
\[
\det(N_{ij})_{S_{j} \setminus S_i}^{1/2} |_{Z(s_i)} \to S_{j} \setminus S_i |_{Z(s_i)}.
\]
After restricting all modules to $A_0$, we have an isomorphism
\begin{align*}
(S_1 \setminus S_0) \otimes (S_2 \setminus S_1) &= S_0^\vee \otimes_{C(E_0)} S_1 \otimes S_1^\vee \otimes_{C(E_1)} S_2 \cong S_0^\vee \otimes_{C(E_0)} C(E_1) \otimes_{C(E_1)} S_2 \\ 
&\cong S_0^\vee \otimes_{C(E_0)} S_2 = S_2 \setminus S_0,
\end{align*}
and this gives an isomorphism on $A_0$ of 
\begin{equation} \label{eqn:eqn:sqrtdetdirectsumN}
(\det N_{01})_{S_1 \setminus S_0}^{1/2} \otimes (\det N_{12})_{S_2 \setminus S_1}^{1/2}|_{Z(s_0)} \cong (\det N_{02})_{S_2 \setminus S_0}^{1/2}|_{Z(s_0)}
\end{equation}
by \eqref{eqn:sqrtdetdirectsum}.
\begin{lemma} \label{lem:associativity}
	The isomorphisms
	\[
	f_1^*(\cH(S_1,s_1)) \to \cH(S_0,s_0) \otimes (\det N_{01})^{1/2}_{S_1\setminus S_0}
	\]
	and
	\[
	f_2^*(\cH(S_2,s_2)) \to \cH(S_1,s_1) \otimes (\det N_{12})^{1/2}_{S_2 \setminus S_1}
	\]
	induce an isomorphism
	\[
	\cH(S_2,s_2)|_{A_0} \cong \cH(S_0,s_0) \otimes (\det N_{01})^{1/2}_{S_1 \setminus S_0} \otimes (\det N_{12})^{1/2}_{S_2 \setminus S_1}|_{A_0}.
	\]
	Under the isomorphism \eqref{eqn:eqn:sqrtdetdirectsumN}, this agrees with the isomorphism
	\[
	\cH(S_2,s_2)|_{A_0} \to \cH(S_0,s_0) \otimes (\det N_{02})^{1/2}_{S_2\setminus S_0}.
	\]
\end{lemma}
\begin{proof}
	Working on $Z(s_0) \subset A_0$, we have a commutative diagram
	\[
	\begin{tikzcd}
		S_0 \otimes (S_2 \setminus S_0) \arrow[rrr, bend left] & \arrow[l] S_2 \arrow[r] & \arrow[r] S_1 \otimes (S_2 \setminus S_1) & S_0 \otimes (S_1 \setminus S_0) \otimes (S_2 \setminus S_1) \\
		S_0 \otimes (\det N_{02})^{1/2}_{S_2 \setminus S_0} \arrow[u] \arrow[rrrd] & & \arrow[u] S_1 \otimes (\det N_{12})^{1/2}_{S_2 \setminus S_1} \arrow[r] & \arrow[u] S_0 \otimes (S_1 \setminus S_0) \otimes (\det N_{12})^{1/2}_{S_2 \setminus S_1} \\
		& & & \arrow[u] S_0 \otimes (\det N_{01})^{1/2}_{S_1 \setminus S_0} \otimes (\det N_{12})^{1/2}_{S_2 \setminus S_1}
	\end{tikzcd}
	\]
	Up to taking cohomology sheaves and inserting pullbacks, the two maps to compare are obtained starting from $S_2$ and going ``left, down'' and ``right, down, right, down'', respectively.
	Commutativity of the diagram gives the claim.
\end{proof}

\subsubsection{Commutativity}
Assume now that we have an unramified morphism of smooth varieties $f \colon A_0 \to A$, with oriented quadratic vector bundles $E_0$ and $E$, and isotropic sections as at the start of this section.
Suppose that, on $Z(s_0)$, the normal bundle $N$ of $A_0$ in $A$ is positive.
Assume further that we have oriented quadratic vector bundles $F_1, F_2$ on $A_0$ equipped with corresponding spin modules $S_1, S_2$, such that $E_0 = F_1 \oplus F_2$.
Accordingly, we write $s_0 = (s_1,s_2)$ for the isotropic section. Then $S_1 \otimes S_2$ and $S_2 \otimes S_1$ are both spin modules for $C(E_0)$ with corresponding differentials $s_1 \otimes 1 + 1 \otimes s_2$ and $s_2 \otimes 1 + 1 \otimes s_1$, and by Lemma \ref{thm:comparisonHomomorphismExists}, we get isomorphisms
\[
\cH(S,s)|_{A_0} \cong \cH((S_1,s_1) \otimes (S_2,s_2)) \otimes (\det N)^{1/2}_{S \setminus S_1 \otimes S_2}
\]
and
\[
\cH(S,s)|_{A_0} \cong \cH((S_2,s_2) \otimes (S_1,s_1)) \otimes (\det N)^{1/2}_{S \setminus S_2 \otimes S_1}.
\]
The isomorphism
\[
S_1 \otimes S_2 \cong S_2 \otimes S_1
\]
given by $a \otimes b \mapsto (-1)^{|a||b|} b \otimes a$ of $C(E_0)$-modules induces an isomorphism $S \setminus (S_1 \otimes S_2) \cong S \setminus (S_2 \otimes S_1)$ of $C(E|_{A_0}/E_0)$-modules, and so an isomorphism
\[
(\det N)^{1/2}_{S \setminus S_1 \otimes S_2}|_{Z(s_0)} \cong (\det N)^{1/2}_{S \setminus S_2 \otimes S_1}|_{Z(s_0)}.
\]
\begin{lemma} \label{lem:commutativity}
The diagram of isomorphisms
\[
\begin{tikzcd}
\cH(S,s)|_{A_0} \arrow[r] \arrow[dr] & \cH((S_1,s_1) \otimes (S_2,s_2)) \otimes (\det N)^{1/2}_{S \setminus S_1 \otimes S_2} \arrow[d] \\
& \cH((S_2,s_2) \otimes (S_1,s_1)) \otimes (\det N)^{1/2}_{S \setminus S_2 \otimes S_1}
\end{tikzcd}
\]
commutes.
\end{lemma}
\begin{proof}
	Let $E' = E|_{A_0}/E_0$.
	Working over $Z(s_0)$, the claim follows from the commutativity of the diagram
	\[
	\begin{tikzcd}
		S|_{A_0} \arrow[d] \arrow[dr] & \\
		(S_1 \otimes S_2) \otimes (S \setminus (S_1 \otimes S_2)) \arrow[r] & (S_2 \otimes S_1) \otimes (S \setminus (S_2 \otimes S_1)) \\
		(S_1 \otimes S_2) \otimes C(E') \otimes_{C(E')} S \setminus (S_1 \otimes S_2) \arrow[r] \arrow[u] & (S_2 \otimes S_1) \otimes C(E') \otimes_{C(E')} S \setminus (S_2 \otimes S_1) \arrow[u] \\
				(S_1 \otimes S_2) \otimes (\det N)^{1/2}_{S \setminus (S_1 \otimes S_2)}\arrow[r] \arrow[u] & (S_2 \otimes S_1) \otimes (\det N)^{1/2}_{S \setminus (S_2 \otimes S_1)}  \arrow[u]
	\end{tikzcd}
	\]
\end{proof}


\subsection{Torus localization} \label{sec:localfixisolated}

Let $M$ be a quasi-projective scheme with 3-term symmetric obstruction theory $\phi \colon E^\mdot \to \tau^{\geq -1} \LL_M$ coming from a $(-2)$-shifted derived scheme (so that the intrinsic normal cone is isotropic \cite{OT}). Then, by \cite[Prop.~4.1]{OT}, $E^\mdot$ is quasi-isomorphic to a self-dual complex 
\begin{equation} \label{eqn:sdres}
[F \stackrel{a}{\to} E \cong E^\vee \stackrel{a^\vee}{\to} F^\vee]
\end{equation}
in degrees $-2,-1,0$ where $F$ is a vector bundle and $(E,q)$ is a quadratic vector bundle, which we assume to be of even rank. Suppose $M$ has an action by an algebraic torus $T$, $\phi$ is $T$-equivariant, and $E^\mdot$ is $T$-equivariantly symmetric. 
Then the above self-dual complex can be chosen $T$-equivariantly \cite[Sec.~7]{OT}. On the fixed locus $\iota \colon M^T \subset M$, which we assume to be compact, we can decompose $E^\mdot|_{M^T}$ into a fixed and moving part 
$$
E^\mdot|_{M^T} = E^\mdot|_{M^T}^f \oplus E^\mdot|_{M^T}^m.
$$
Then $N^{\vir} := (E^\mdot|_{M^T}^m)^\vee$ is the virtual normal bundle. The complex $E^\mdot|_{M^T}^f$ maps to $(\tau^{\geq -1} \mathbb{L}_{M})
|_{M^T}^f$ and we can compose with the natural map $(\tau^{\geq -1} \mathbb{L}_{M})|_{M^T}^f \to \tau^{\geq -1} \mathbb{L}_{M^T}$.
This gives a 3-term symmetric obstruction theory on $M^T$. Suppose we have orientations $o \colon \O_M \cong \det(E^\mdot)$, $o^f \colon \O_{M^T} \cong \det(E^\mdot|_{M^T}^f)$, and $o^m \colon \O_{M^T} \cong \det(E^\mdot|_{M^T}^m)$. Then there are classes
\begin{align*}
[M]^{\vir} &\in A_*^T(M, \Z[\tfrac{1}{2}]), \quad \widehat{\O}_{M}^{\vir} \in K_0^T(M)_{\loc}, \\
[M^T]^{\vir} &\in A_*(M^T, \Z[\tfrac{1}{2}]), \quad \widehat{\O}_{M^T}^{\vir} \in K_0(M^T,\Z[\tfrac{1}{2}]).
\end{align*}
Supposing that the orientations are compatible, i.e., $o|_{M^T} = o^f \otimes o^m$, the Oh--Thomas localization formulae are \cite[Sect.~7]{OT}
\begin{equation} \label{eqn:OTlocgeneral}
[M]^{\vir} = \iota_* \Bigg( \frac{1}{\sqrt{e}(N^{\vir})} \cap [M^T]^{\vir} \Bigg), \quad \widehat{\O}_{M}^{\vir} = \iota_* \Bigg(\frac{1}{\sqrt{\mathfrak{e}}(N^{\vir})} \cdot \widehat{\O}_{M^T}^{\vir} \Bigg),
\end{equation}
where the square root Euler class $\sqrt{e}(-)$ and its $K$-theoretic analog $\sqrt{\mathfrak{e}}(-)$ were defined in \cite{OT}. Suppose we have a $T$-equivariant maximal isotropic subbundle $\Lambda \subset E$ of the self-dual resolution \eqref{eqn:sdres}. Then there are induced maximal isotropic subbundles
$$
\Lambda|_{M^T}^m \subset E|_{M^T}^m, \quad \Lambda|_{M^T}^f \subset E|_{M^T}^f,
$$
which induce (compatible) orientations on the complexes $E^\mdot|_{M^T}^f, N^{\vir}$. We are interested in making \eqref{eqn:OTlocgeneral} explicit under the following assumption: \\

\noindent \textbf{Assumption.} The fixed locus $M^T$ is 0-dimensional and reduced. \\

% This implies $h^0(E^\mdot|_P^f) = 0$, for all $P \in M^T$, and thus the map
% $$
% a|_P^f \colon F|_P^f \hookrightarrow E|_P^f
% $$
%in the self-dual resolution \eqref{eqn:sdres} is injective. Therefore $F|_P^f \hookrightarrow E|_P^f$ is isotropic and $2 \vd \{P\} := \rk (E^\mdot|_P^f) \leq 0$. If $\vd \{P\} < 0$, then obviously $\{P\}^{\vir} = 0$, so we may assume $\vd \{P\} = 0$. Then $a(F|_P^f) \subset E|_P^f$ is \emph{maximal} isotropic and the complex $E^\mdot|_P^f$ is \emph{acyclic}. 
With this assumption, on each fixed point $P \in M^T$ we get a 3-term symmetric obstruction theory $E^\bullet|_P^f$.
The invariants associated with such are described by the following lemma, which follows easily from the definitions in \cite{OT}.
\begin{lemma}
Let $P = \Spec \CC$ be endowed with a 3-term symmetric obstruction theory $E^\mdot$ with self-dual resolution $[F \stackrel{a}{\to} E \cong E^\vee \stackrel{a^\vee}{\to} F^\vee]$ with $\rk(E)$ even. Then $a$ is injective and $\vd P \leq 0$. 

We have $\vd P = 0$ if and only if $E^\mdot$ is acyclic if and only if $a(F) \subset E$ is maximal isotropic. 
If this holds, then with the orientation induced by $a(F)$, we have $[P]^{\vir} = [P]$ and $\widehat{\O}_{P}^{\vir} = \O_P$.

If $\vd P < 0$, $[P]^{\vir} = 0$ and $\widehat{\O}^{\vir}_P = 0$.
\end{lemma}

Denoting the inclusion of $P$ in $M^T$ by $\iota_P$, from the lemma we obtain
$$
[M]^{\vir} = \sum_{P \in M^T \atop \vd P = 0} (-1)^{n_P^\Lambda} \iota_{P*} \Bigg(\frac{1}{e((F-\Lambda)|_P)} \Bigg), \quad \widehat{\O}_{M}^{\vir} = \sum_{P \in M^T \atop \vd P = 0} (-1)^{n_P^\Lambda} \iota_{P*} \Bigg(\frac{1}{ \widehat{\Lambda}^{\mdot} (F^\vee-\Lambda^\vee)|_P} \Bigg),
$$
where 
\begin{equation} \label{defn}
(-1)^{n^\Lambda_P} = \left\{ \begin{array}{cc} 1 & \textrm{if } a(F|_P^f) \textrm{ is positively oriented \, } \\ -1 & \textrm{otherwise.} \end{array}\right.
\end{equation}

%\noindent \textbf{Assumption.} $M^T$ consists of isolated reduced points. \\
We want to make this sign more explicit. We will repeatedly use the following fact \cite[Sect.~6.1, p.~735]{GH}: for any even-dimensional quadratic vector space $(E,q)$ and maximal isotropic subspaces $\Lambda, \Lambda' \subset E$, we have that $\Lambda, \Lambda'$ induce the same orientation if and only if 
$$
\dim(\Lambda \cap \Lambda') \equiv \tfrac{1}{2} \dim(E) \pmod 2.
$$

We start with the following lemma.
% about the compositions
%\begin{align*}
%T_A|_P \stackrel{ds}{ \longrightarrow} E|_P \stackrel{p_\Lambda}{\longrightarrow} \Lambda|_P,  \quad T_A|_P \stackrel{ds}{ \longrightarrow} E|_P \stackrel{p_{\Lambda^\vee}}{\longrightarrow} \Lambda^\vee|_P.
%\end{align*}
\begin{lemma} \label{lem:nnprime}
Let $P \in M^T$ have $\vd P= 0$, and let $E|_P = \Lambda|_P \oplus  \Lambda^\vee|_P$ be a splitting into maximal isotropic subspaces with projection maps $p_\Lambda$ and $p_{\Lambda^\vee}$.
We then have
 $$
\dim \coker (p_{\Lambda} \circ a|_P)^f \equiv  \dim \coker (p_{\Lambda^\vee} \circ a|_P)^f + \dim(\Lambda^\vee|_P^f) \pmod 2.
 $$
\end{lemma}
 \begin{proof}
 Let $l = \dim(\Lambda|_P^f) = \dim (F|_P^f)$.
 It is easy to see that $\dim \coker (p_{\Lambda^\vee} \circ a|_P)^f = \dim (a(F|_P^f) \cap \Lambda|_P^f)$.
 If $l$ is even, then $\Lambda|_P^f$ and $\Lambda^\vee|_P^f$ are deformation equivalent as maximal isotropic subspaces of $E|_P^f$, and so \cite[Sect.~6.1, p.~735]{GH} 
 \[
 \dim(\Lambda|_P^f \cap a(F|_P^f)) \equiv \dim(\Lambda^\vee|_P^f \cap a(F|_P^f)) \pmod 2.
 \]
 If $l$ is odd, then $\Lambda|_P^f$ and $\Lambda^\vee|_P^f$ are not deformation equivalent as maximal isotropic subspaces of $E|_P^f$, and so
 \[
\dim(\Lambda|_P^f \cap a(F|_P^f)) \not\equiv \dim(\Lambda^\vee|_P^f \cap a(F|_P^f)) \pmod 2. \qedhere
 \]
 \end{proof}

We obtain the following formula for $n_P^\Lambda$. 
\begin{proposition} \label{prop:nP}
For any isolated reduced $P \in M^T$ with $\vd P = 0$, we have
$$
n_P^\Lambda \equiv \dim  \mathrm{coker}(p_{\Lambda} \circ a|_P)^f \pmod 2,
$$
where $p_\Lambda \colon E|_P \to \Lambda|_P$ is the projection for any splitting $E|_P = \Lambda|_P \oplus  \Lambda^\vee|_P$.
\end{proposition}
\begin{proof}
We have that $\Lambda|_P^f$, $a(F|_P^f)$ determine the same orientation if and only if
$$
\dim(a(F|_P^f ) \cap \Lambda|_P^f) \equiv \tfrac{1}{2} \dim(E|_P^f) = \dim(\Lambda^\vee|_P^f) \pmod 2.
$$
In the proof of Lemma \ref{lem:nnprime}, we saw that 
\begin{align*}
\dim \coker (p_{\Lambda^\vee} \circ a|_P)^f &= \dim (a(F|_P^f) \cap \Lambda|_P^f) \\
\dim \coker (p_{\Lambda} \circ a|_P)^f &\equiv  \dim \coker (p_{\Lambda^\vee} \circ a|_P)^f + \dim(\Lambda^\vee|_P^f) \pmod 2.
\end{align*}
From \eqref{defn}, we deduce
\begin{align*}
n_P^{\Lambda} &\equiv \dim(a(F|_P^f ) \cap \Lambda|_P^f) - \dim(\Lambda^\vee|_P^f) \\
&=\dim \coker (p_{\Lambda^\vee} \circ a|_P)^f - \dim(\Lambda^\vee|_P^f)  \\
&\equiv \dim \coker (p_{\Lambda} \circ a|_P)^f  \pmod 2. \qedhere 
\end{align*}
\end{proof}


\section{Global} \label{sec:global}

In this section we describe $\Quot_r^n(\C^4)$, the Quot scheme parametrizing 0-dimensional quotients of length $n$ of $\O_{\C^4}^{\oplus r}$, as the vanishing locus of an isotropic section of a quadratic vector bundle over a smooth variety.
This leads to a definition of the twisted virtual structure sheaf on the Quot scheme, to the $K$-theory class
\[
\cN^\glob_{r,n} \in K_0^{\mathbb{T}'}(\Quot_r^n(\C^4)),
\]
for some algebraic torus $\TT'$ acting on $\Quot_r^n(\C^4)$, and to 
\[
N^{\glob}_{r,n} = \chi(\Quot_r^n(\C^4), \cN^\glob_{r,n}).
% \in \Q(t_1, t_2, t_3, t_4, w_1, \ldots, w_r, y_1^{\frac{1}{2}}, \ldots, y_r^{\frac{1}{2}}) / (t_1t_2t_3t_4-1).
\]
Using spin modules, we show that the classes $\cN_{r,n}^{\glob}$ lift to sheaves and give rise to a factorizable sequence.


\subsection{Isotropic zero locus} \label{sec:zeroloc} 

 Let $n \in \Z_{\geq 0}$ and let $V$ be an $n$-dimensional complex vector space. Let $r \in \Z_{>0}$ and consider the following quiver:
