  \matrix [matrix of math nodes,
           column sep={3cm,between origins},
           row sep={3cm,between origins},
           nodes={circle, draw, minimum size=7.5mm}]
{ 
|(A)| \infty & |(B)| 0 \\         
};
\tikzstyle{every node}=[font=\small\itshape]
\path[->] (B) edge [loop above] node {$X_1$} ()
              edge [loop left] node {$X_2$} ()
              edge [loop right] node {$X_4$} ()
              edge [loop below] node {$X_3$} ();

\node [anchor=west,right] at (-0.5,0.1) {$\vdots$};
\node [anchor=west,right] at (-0.3,0.95) {$u_1$};              
\node [anchor=west,right] at (-0.3,-0.85) {$u_r$};              
%\draw (A) to [bend left=25,looseness=1] (B) node [midway,above] {};
\draw (A) to [bend left=40,looseness=1] (B) node [midway] {};
\draw (A) to [bend right=35,looseness=1] (B) node [midway,below] {};
\end{tikzpicture}
%\caption{}
\end{figure}

We consider representations of this quiver with dimension vector $(1,n)$, i.e.~we put the vector space $\C$ at the node $\infty$ and $V$ at the node $0$. 
Representations with this dimension vector correspond to elements of 
\[
W = \C^4 \otimes \End(V) \oplus \Hom(\C^r,V).
\]
The group $\GL(V)$ acts on $W$ by
\begin{align*}
&g \cdot (X_1,\ldots,X_4, u_1, \ldots, u_r) = (g X_1 g^{-1},\ldots,g X_4 g^{-1},g u_1, \ldots, g u_r),\\ 
&X_i \in \End(V), \quad u_i \in V.
\end{align*}
Let $U \subset W$ be the open subset consisting of representations satisfying
$$
\C\langle X_1,\ldots,X_4\rangle \cdot \langle u_1, \ldots , u_r \rangle = V,
$$ 
i.e.~acting with polynomial expressions on the span of the vectors $u_i$ generates $V$.
Then $\GL(V)$ acts freely on $U$ and the \emph{non-commutative Quot scheme} is defined as the open substack
$$
\ncQuot_{r}^{n}(\C^4) = [U / \GL(V)] \subset [W / \GL(V)].
$$
In fact, $\ncQuot_{r}^{n}(\C^4)$ is a smooth variety of dimension $3n^2+rn$ (see also \cite{BR}).
%Its analog exists in any dimension $d$ (replacing $X_1, \ldots, X_4$ by $X_1, \ldots, X_d$). For $d=3$, it famously has a superpotential $\Phi := \tr(X_1[X_2,X_3])$ and $\Quot_{r}^{n}(\C^3) = Z(d\Phi)$ \cite{BBS, Oko, BR}. 

On $U$, we have the trivial vector bundle
$$
E = \Lambda^2 \C^4 \otimes \End(V) \otimes \O_U
$$
with quadratic form $q$ determined (after fixing a non-zero $\omega \in \Lambda^4 \C^4$) by
\begin{align*}
&(\Lambda^2 \C^4 \otimes \End(V)) \otimes (\Lambda^2 \C^4 \otimes \End(V)) \rightarrow \Lambda^4 \C^4  \overset{\omega^\vee(-)}{\cong} \C \\
&\quad\quad (\omega_1 \otimes f_1) \otimes (\omega_2 \otimes f_2) \mapsto \omega_1 \wedge \omega_2 \cdot \tr(f_1 \circ f_2).
\end{align*}
We let $(e_1,e_2,e_3,e_4)$ be the standard basis of $\C^4$.
Then $E$ has a section
$$
s \in H^0(U,E), \quad \Big(\sum_{i=1}^{4} e_i \otimes f_i , u_1, \ldots, u_r \Big) \mapsto \sum_{i,j=1}^{4} (e_i \wedge e_j) \otimes (f_i \circ f_j),\ \ f_i \in \End(V).
$$

Letting $\C^3=\langle e_1,e_2,e_3 \rangle$, we define the subbundle $\Lambda \subset E$ by
\begin{equation} \label{defLambda}
\Lambda = (\langle e_4 \rangle \wedge \C^3) \otimes \End(V) \otimes \O_U.
\end{equation}
Since $E, \Lambda, s$ are naturally $\GL(V)$-equivariant and $q$ is $\GL(V)$-invariant, they descend to $\ncQuot_r^n(\C^4)$, where we use the same notation.
\begin{lemma}
The section $s$ is isotropic and $Z(s) \cong \Quot_r^n(\C^4)$. Furthermore $\Lambda \subset E$ is a maximal isotropic subbundle.
\end{lemma}
\begin{proof}
The section $s$ vanishes at a point $(\sum_i e_i \otimes f_i , u_1, \ldots, u_r)$ if and only if
$$
[f_i,f_j] = f_i \circ f_j - f_j \circ f_i = 0, \quad \forall i,j=1,\ldots, 4.
$$
This induces a (scheme theoretic) isomorphism $Z(s) \cong \Quot_r^n(\C^4)$. Moreover
\begin{align*}
&q\Big( \sum_{i,j=1}^{4} (e_i \wedge e_j) \otimes (f_i \circ f_j), \sum_{i,j=1}^{4} (e_i \wedge e_j) \otimes (f_i \circ f_j)\Big) \\
&\quad \quad  \quad \quad = e_1 \wedge e_2 \wedge e_3 \wedge e_4 \otimes \tr(\sum_{\sigma \in S_4} (-1)^{|\sigma|} f_{\sigma(1)} \circ f_{\sigma(2)} \circ f_{\sigma(3)} \circ f_{\sigma(4)}) = 0.
\end{align*}
Any element of the form $\lambda = \sum_{i=1}^{3} (e_4 \wedge e_i) \otimes f_{i} \in  (\langle e_4 \rangle \wedge \C^3) \otimes \End(V)$ satisfies $q(\lambda,\lambda) = 0$, so $\Lambda$ is isotropic.
\end{proof}


\subsection{Definition of invariants} \label{sec:definv}

We introduce three tori acting on $\ncQuot^n_r(\C^4)$, denoted $T_t, T_w$ and $T_y$.
The torus $(\C^*)^4$ acts naturally on $\C^4$, and we let $T_t$ be the subtorus preserving the volume form on $\C^4$.
We denote its coordinates by $t_1,t_2,t_3,t_4$, these are subject to the relation $t_1t_2t_3t_4 = 1$.

The tori $T_w$ and $T_y$ are $r$-dimensional tori with coordinates $w_1, \ldots, w_r$ and $y_1, \ldots, y_r$, respectively.
The parameters $w_i$ are referred to as \textit{framing parameters}.
The parameters $y_i$ are referred to as \textit{mass parameters}.
There is an action of $\mathbb{T} = T_t \times T_w \times T_y$ on $A = \ncQuot_{r}^{n}(\C^4)$ given by
\begin{align*}
&(t_1, \ldots, t_4, w_1, \ldots, w_r, y_1, \ldots, y_r) \cdot (X_1, \ldots, X_4, u_1, \ldots, u_r) \\
 &= (t_1^{-1} X_1, \ldots, t_4^{-1} X_4, w_1^{-1} u_1, \ldots, w_r^{-1} u_r).
\end{align*}

The $\GL(V)$-equivariant vector bundle $V \otimes \O_U$ descends to a tautological rank $n$ vector bundle $\cV$ on $\ncQuot_r^n(\C^4)$. Note that
$$
\cV|_{\Quot_r^n(\C^4)} \cong \pi_* \cQ
$$
where $\cQ$ denotes the universal quotient sheaf on $\Quot_r^n(\C^4) \times \C^4$ and $\pi$ denotes projection onto the first factor. We give the quadratic vector bundle $E = \Lambda^2\C^4 \otimes \cEnd(\cV)$ the $\mathbb T$-equivariant structure coming from the $\mathbb T$-action on $\C^4$. Then $\Lambda$ and the quadratic form $q$ are $\mathbb{T}$-invariant and $s$ is $\mathbb T$-equivariant.\footnote{This gives one reason for why we restrict to the subtorus $T_t$ of $(\C^*)^4$: there is no way to lift the $T_t$-equivariant structure on $E$ to a $(\C^*)^4$-equivariant one in such a way that $s$ is $(\C^*)^4$-equivariant and $q$ is $(\CC^*)^4$-invariant.} 

As we discuss in Section \ref{sec:local}, the natural $\mathbb{T}$-action on $\Quot_r^n(\C^4)$ has isolated reduced fixed points, and we are therefore in the setting of the ``standard model'' of Oh--Thomas discussed in the introduction. 
%We define $\widetilde{\mathbb T}$ to be the $2^{2r +3}$-fold cover of $\T$ so that every character in the original torus has a square root.
Thus we obtain a $\mathbb{T}$-equivariant virtual class and virtual structure sheaf for $M=\Quot_r^n(\C^4)$
\begin{align*}
[M]^{\vir} \in A_{rn}^{\mathbb{T}}(M,\Z[\tfrac{1}{2}]), \quad \widehat{\O}^{\vir}_M &\in K_0^{\T}(M)_{\loc}. 
%:= K_0^{\T}(M) \otimes_{K_0^{\TT}(\pt)} \Q(t_1^{\frac{1}{2}}, \ldots, t_3^{\frac{1}{2}}, w_1^{\frac{1}{2}}, \ldots, w_r^{\frac{1}{2}},y_1^{\frac{1}{2}}, \ldots, y_r^{\frac{1}{2}}),
\end{align*}
%where $K_0^{\TT}(\pt) = \Z[t_1^{\pm 1}, \ldots, t_3^{\pm 1}, w_1^{\pm 1}, \ldots, w_r^{\pm 1},y_1^{\pm 1}, \ldots, y_r^{\pm 1}]$ and we eliminated the variable $t_4$ by the relation $t_1t_2t_3t_4=1$.

We consider also the $\mathbb T$-equivariant vector bundle
\[
\cW = \bigoplus_{i=1}^{r} \O_A \otimes w_i \otimes y_i,
\]
where $\O_A$ has its natural $\TT$-equivariant structure which, in the $i$th summand, we tensorize by the weight one characters $w_i$, $y_i$ of $T_w, T_y$. 

\begin{definition} \label{defNgenus}
We define $K$-theory classes
\[
\cN^\glob_{r,n} = \widehat{\O}^{\vir} \otimes \widehat{\Lambda}^\mdot \hom(\cV,\cW) \in K_0^{\mathbb T}(\Quot^n_r(\C^4))_{\loc}
\]
and invariants 
$$
N_{r,n}^\glob = \chi(\Quot_r^n(\C^4), \cN^\glob_{r,n}) \in \Q(t_1^{\frac{1}{2}}, \ldots , t_4^{\frac12}, w_1^{\frac{1}{2}}, \ldots, w_r^{\frac{1}{2}}, y_1^{\frac{1}{2}}, \ldots, y_r^{\frac{1}{2}}), \ t_4 = t_1^{-1}t_2^{-1}t_3^{-1}.
$$
Here $\widehat{\Lambda}^\mdot$ was defined in \eqref{eqn:lambdahat} and we interpret $\chi$ via the general $K$-theoretic localization formula, that is we let
\[
\chi(\Quot_r^n(\C^4), \cN^\glob_{r,n}) = \chi(\Quot_r^n(\C^4)^{\T}, \widetilde{\cN}^\glob_{r,n}),
\]
where $\widetilde{\cN}^\glob_{r,n}$ is the unique class in 
$K_0^{\T}(\Quot_r^n(\C^4)^{\T})_{\mathrm{loc}}$
which under pushforward along $\Quot_r^n(\C^4)^{\T} \into \Quot_r^n(\C^4)$ maps to $\cN^\glob_{r,n}$, see \cite{Tho}, \cite[Sect.~2.3]{Oko}.
Furthermore, we define the generating series
\begin{align}
\begin{split} \label{defG}
\mathsf{G}_{r} &= \sum_{n=0}^{\infty} N_{r,n}^\glob \, q^n,
\end{split}
\end{align}
which has leading term 1.
\end{definition}

\begin{remark} \label{def:Tprime}
Let $\mathbb{T}' = T_t \times T_w \times \widetilde{T}_y$, where $\widetilde{T}_y$ is the $2^r$-fold cover of $T_y$ such that all characters of $T_y$ have a square root defined on $\widetilde T_y$. At the end of this section, we will in fact see that $\cN^\glob_{r,n} \in K_0^{\mathbb T}(\Quot^n_r(\C^4))_{\loc}$ admits a lift to $K_0^{{\mathbb T}'}(\Quot^n_r(\C^4))$.
Consequently, $N_{r,n}^\glob \in \Q(t_1, \ldots, t_4, w_1, \ldots, w_r, y_1^{\frac{1}{2}}, \ldots, y_r^{\frac{1}{2}})$ with $t_4 = t_1^{-1}t_2^{-1}t_3^{-1}$. 
In Section \ref{sec:limits}, we will show that $N_{r,n}^\glob \in \Q(t_1, \ldots , t_4, (y_1 \cdots y_r)^{\frac{1}{2}})$ with $t_4 = t_1^{-1}t_2^{-1}t_3^{-1}$.
\end{remark}

\begin{remark} \label{dualVW}
We note the identity
$$
\widehat{\Lambda}^\mdot \hom(\cV,\cW) = (-1)^{rn} \widehat{\Lambda}^\mdot \hom(\cW,\cV). 
$$
In Section \ref{sec:local}, we prefer to work with the representation on the right hand side in order to match existing conventions for the vertex formalism in the literature. 
\end{remark}

In the ``standard model'' for 2-term perfect obstruction theories, where $M$ is the zero locus of a section $s$ of a vector bundle $E$ on a smooth ambient space $A$, the virtual structure sheaf $\O_M^{\mathrm{vir}} \in K_0(M)$ lifts to a $\Z/2$-graded coherent sheaf on $M$ as follows. The Koszul complex $(\Lambda^\mdot E^\vee,s \intprod)$ gives rise to the following $K$-theory class
%an element of the derived category $D^b(A) = D^b(\mathsf{coh}(A))$. More precisely, the cohomology of the Koszul complex $(\Lambda^\mdot E^*,(-) \intprod s)$ is supported on $M$, so it defines a $K$-theory class on $M$, which is precisely the virtual structure sheaf
\begin{equation}
\label{eqn:koszul}
\sum_{i \geq 0} (-1)^i \Lambda^i E^\vee = \sum_{i \geq 0} (-1)^i H^i(\Lambda^\mdot E^\vee, s\intprod) \in K_0(A).
\end{equation}
The Koszul complex is a sheaf of differential graded $\O_A$-algebras and, by the Leibniz rule, we see that the cohomology sheaves $H^i(\Lambda^\mdot E^\vee, s\intprod)$ are sheaves of $\O_M$-modules. 
Therefore, the right hand side of \eqref{eqn:koszul} gives a class in $K_0(M)$ known as the virtual structure sheaf $\O_M^{\mathrm{vir}}$. In this ``standard model'' setting, we can view $\O_M^{\mathrm{vir}}$ as the class of the $\Z/2$-graded coherent sheaf $H^{\mathrm{odd}}(\Lambda^\mdot E^\vee)[1] \oplus H^{\mathrm{even}}(\Lambda^\mdot E^\vee)$.
Note that $\O_M^{\vir} = \O_M$ when $s$ is regular.

In the case $E = \Omega_A$ and $s = dw$, for a regular function $w \colon A \to \mathbb{A}^1$, the perfect obstruction theory is symmetric, $K_M^{\mathrm{vir}}$ has the square root $(K_M^{\mathrm{vir}})^{\frac12}=K_A$, and one obtains the twisted (or \textit{symmetrized}) virtual structure sheaf \cite[3.2.8]{Oko}
$$
\widehat{\O}_M^{\mathrm{vir}} = \O_M^{\mathrm{vir}} \otimes (K_M^{\mathrm{vir}})^{\frac{1}{2}} \in K_0(M). 
$$

Suppose we are in the setting of the ``standard model'' of Section \ref{sec:OTtheory}, i.e.~we have a quadratic vector bundle $(E,q)$ of even rank over a smooth quasi-projective scheme $A$, an isotropic section $s$ of $E$ such that $M=Z(s)$, and a maximal isotropic subbundle $\Lambda \subset E$. Recall that $\Lambda$ induces an orientation on $(E,q)$. Now suppose additionally that $\det(\Lambda)$ has a square root $L$ (as a line bundle) and suppose the entire setup is $T$-equivariant with respect to the action of an algebraic torus $T$ on $A$ as before. By Example \ref{ex:sqrtdetgivesspin}, we then obtain a spin module
\[
S := C(E)\Lambda \otimes L^{-1}.  
\]
Furthermore, the isotropic section $s$ gives rise to a complex $(S,s)$ (Definition \ref{def:complex}). In the case $E = \Lambda \oplus \Lambda^\vee$ splits, we can write $s = (s_{\Lambda},s_{\Lambda^\vee})$ and we have an isomorphism (of $T$-equivariant $\Z/2$-graded left $C(E)$-modules)
\begin{equation} \label{eqn:isototwoperiodic}
S \cong L \otimes \Lambda^\mdot \Lambda^\vee,
\end{equation}
where multiplication by $s$ corresponds to $s_{\Lambda^\vee} \wedge + s_{\Lambda} \intprod$ (Example \ref{ex:reltoperiodcx}). 
Note that the $\Z/2$-graded sheaf $\cH(S,s)$ is supported on $M$ (Lemma \ref{lem:suppZ(s)}) and therefore defines a class in $K_0(M)$.
As shown by Oh--Sreedhar \cite{OS}, this class agrees with the one defined via Kiem--Li cosection localisation for the section and cosection $s_\Lambda$ and $s_{\Lambda^\vee}^\vee$ of $\Lambda$.
It follows from this that the Oh--Thomas virtual structure sheaf in this ``standard model'' setup can be expressed using \eqref{eqn:isototwoperiodic}, and we have:
\begin{proposition} \label{Kcompare}
In the above setup, we have
$$
\cH(S,s) \cdot \det(T_A|_M)^{-\frac{1}{2}} = \widehat{\mathcal{O}}^{\vir}_M \in K^T_0(M)_{\mathrm{loc}}.
$$
\end{proposition}

We now return to the setting of Section \ref{sec:zeroloc} with $A = \ncQuot_{r}^n(\C^4)$, and the data $(E,q)$, $s$ and $\Lambda$ as defined there with $Z(s) = \Quot_r^n(\C^4)$. Note that we have a $\TT$-equivariant splitting $E =\Lambda \oplus \Lambda^\vee$. In $K^0_{\TT}(A)$, we have the identity
\[
\Lambda = \langle e_4 \rangle \wedge \C^3 \cdot \mathcal{E}{\it{nd}}(\cV),
\]
where $\cV$ is naturally a $\TT$-equivariant vector bundle as described above and $\langle e_4 \rangle \wedge \C^3$ denotes the $\TT$-representation $t_1^{-1}t_4^{-1}+t_2^{-1}t_4^{-1}+t_3^{-1}t_4^{-1}$. Since the determinant map factors through $K$-theory, we obtain
\begin{equation} \label{eqn:detLambda}
\det(\Lambda) = t_4^{-2n^2} \otimes \O_A.
\end{equation}
Therefore, we can choose the square root $L = t_4^{-n^2} \otimes \O_A$ and we are in the setting described in Proposition \ref{Kcompare}. 

We next define a $\Z/2$-graded sheaf $\cN^{\text{sheaf}}_{r,n}$ by
\[
\cN^{\text{sheaf}}_{r,n} = \cH(S,s) \otimes \Lambda^\mdot \hom(\cV,\cW) \otimes (\det(T_A) \otimes \det(\hom(\cV,\cW)))^{-\frac12},
\]
which, by Lemma \ref{lem:suppZ(s)}, is supported on $\Quot_r^n(\C^4)$.
The quotient description of $A$ gives a short exact sequence of sheaves
\begin{equation}
\label{eqn:tangentBundleExactSequence}
0 \to \mathcal{E}{\it{nd}}(\cV) \to \C^4 \otimes \mathcal{E}{\it{nd}}(\cV) \oplus \bigoplus_{i=1}^{r} \cV \otimes w_i^{-1} \to T_A \to 0.
\end{equation}
In $K^0_{\TT}(A)$, we have the identity
\begin{equation} \label{eqn:TAinKtheory}
T_A = (\C^4 - 1) \mathcal{E}{\it{nd}}(\cV) + \sum_{i=1}^{r} \cV \otimes w_i^{-1},
\end{equation}
where $\cV$ is naturally a $\TT$-equivariant vector bundle as described above and $\C^4 =t_1^{-1}+ \cdots + t_4^{-1}$ is the $\TT$-representation generated by the tangent vectors $\frac{\partial}{\partial x_i}$. We obtain
\[
\det(T_A) = (w_1\cdots w_r)^{-n}\det(\cV)^{\otimes r}
\]
and
\[
\det(\hom(\cV,\cW)) = (y_1 w_1 \cdots y_r w_r)^{n}\det(\cV)^{-\otimes r}.
\]
The line bundle 
\begin{equation} \label{eqn:cancel}
\det(T_A) \otimes \det(\hom(\cV,\cW)) \cong (y_1 \cdots y_r)^{n} \otimes \O_A
\end{equation}
admits a $\mathbb T'$-equivariant square root $(y_1\cdots y_r)^{\frac n2}\otimes \O_A$. Thus, $\cN^{\text{sheaf}}_{r,n}$ is $\TT'$-equivariant for the torus $\TT'$ defined in Remark \ref{def:Tprime}.

By Proposition \ref{Kcompare} we then have 
\[
\cN^{\mathrm{glob}}_{r,n} = [\cN^{\mathrm{sheaf}}_{r,n}] \in K_0^{\mathbb{T}}(\ncQuot_r^n(\C^4))_{\loc},
\]
so $\cN^{\mathrm{sheaf}}_{r,n}$ is indeed a refinement of $\cN^{\mathrm{glob}}_{r,n}$ as claimed. In fact, our analysis shows 
\[
\cN^{\mathrm{glob}}_{r,n}  \in K_0^{\mathbb{T}'}(\ncQuot_r^n(\C^4)),
\]
which establishes the claim in Remark \ref{def:Tprime}.


\subsection{Factorization data} \label{sec:factorforNek}

In this section, we construct a factorizable sequence $\{\F_n\}_{n=1}^{\infty}$ for $\Sym^n(\C^4)$ (Definition \ref{def:factorisableSequence}).

Recall the description of $\Quot_1^n(\C^4) = \Hilb^n(\C^4)$ as the zero locus of an isotropic section of a quadratic vector bundle on a smooth ambient space $\mathrm{ncQuot}_1^n(\C^4) = \mathrm{ncHilb}^n(\C^4)$ from Section \ref{sec:zeroloc}. We denote the corresponding data by $A_n, E_n, s_n, \Lambda_n$.
Since the tori $T_w$ and $T_y$ are 1-dimensional, we write $w$ and $y$ instead of $w_1$ and $y_1$.

We will use the notation of Section \ref{sec:factorizability}. From the quotient description of $A_n$, it is clear that for any $m,n \geq 1$ there is a rational map
\begin{equation} \label{eqn:ratmap}
A_m \times A_n \dashrightarrow A_{m+n}.
\end{equation}

Let $O_{m,n} \subseteq A_m \times A_n$ be the open set of pairs
\[
((X_1,\dots,X_4,u), (Y_1,\dots, Y_4,v))
\]
such that there exists a $4$-tuple $(a_1,\dots,a_4) \in \C^4\setminus \{0\}$ such that the spectra of $\sum_{i=1}^4 a_iX_i$ and $\sum_{i=1}^4 a_i Y_i$ are disjoint.

\begin{lemma}
\label{thm:linearAlgebra}
Let $n_1,n_2 \ge 1$ and let $A_{11}, A_{22}$ be matrices of size $(n_1 \times n_1)$ and $(n_2 \times n_2)$, respectively.
Assume the spectra of $A_{11}$ and $A_{22}$ are disjoint, and let
\[
A = \begin{pmatrix} A_{11} & 0 \\ 0 & A_{22} \end{pmatrix}.
\]
Then
\begin{enumerate}
    \item There are complex polynomials $f_1, f_2$ such that
    \[
    f_1(A) = \begin{pmatrix} I_{n_1} & 0 \\ 0 & 0 \end{pmatrix},\ f_2(A) = \begin{pmatrix} 0 & 0 \\ 0 & I_{n_2} \end{pmatrix}.
    \]
    \item Let $B_{12}$ be an $(n_1 \times n_2)$-matrix, and let $B_{21}$ be an $(n_2 \times n_1)$-matrix, such that
    \[
    A_{11}B_{12}=B_{12}A_{22} \text{ and }A_{22}B_{21} = B_{21}A_{11}.
    \]
    Then $B_{12} = B_{21} = 0$.
\end{enumerate}
\end{lemma}
\begin{proof}
Part (1) follows from the Cayley--Hamilton theorem.
For part (2), we have
\[
\begin{pmatrix} 0 & B_{12} \\
B_{21} & 0
\end{pmatrix} A
= A \begin{pmatrix} 0 & B_{12} \\
B_{21} & 0
\end{pmatrix}.
\]
The same identity holds after replacing $A$ by $f_1(A)$ and $f_2(A)$.
This gives the claim.
\end{proof}


\begin{lemma}
	The map \eqref{eqn:ratmap} is defined on $O_{m,n}$. Moreover $$\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4)|_{U_{m,n}} = (\Hilb^m(\C^4) \times \Hilb^n(\C^4)) \cap O_{m,n}.$$
\end{lemma}
\begin{proof}
Take an element $((X_1, \ldots, X_4,u), (Y_1, \ldots, Y_4,v))$ of $O_{m,n}$ and consider the direct sum
\begin{equation}
\label{eqn:blockDiagonals}
	\left( \begin{pmatrix}
		X_1 & 0 \\
		0 & Y_1
	\end{pmatrix}, \begin{pmatrix}
		X_2 & 0 \\
		0 & Y_2
	\end{pmatrix}, \begin{pmatrix}
		X_3 & 0 \\
		0 & Y_3
	\end{pmatrix}, \begin{pmatrix}
		X_4 & 0 \\
		0 & Y_4
	\end{pmatrix},\begin{pmatrix}
		u \\
		v
	\end{pmatrix} \right),	
\end{equation}
where $\C\langle X_1, \ldots, X_4 \rangle \cdot u = \C^m$ and $\C\langle Y_1, \ldots, Y_4 \rangle \cdot v = \C^n$. We must show that, acting on $(u,v)$, these block diagonal matrices generate $\C^{m+n}$. By assumption, there is an $(a_1, \ldots, a_4) \in \C^4 \setminus 0$ such that $X' := a_1 X_1 + \dots + a_4 X_4$ and $Y' := a_1 Y_1 + \dots + a_4 Y_4$ have disjoint spectra.
Letting
\[
A = \begin{pmatrix} X' & 0 \\ 0 & Y'\end{pmatrix},
\]
then we can find polynomials $f_1, f_2$ as in Lemma \ref{thm:linearAlgebra}.
We then have $(u,0) = f_1(A)(u,v)$ and $(0,v) = f_2(A)(u,v)$.
Thus $(u,0)$ and $(0,v)$ are both in the subspace generated from $(u,v)$, by \eqref{eqn:blockDiagonals}, and it follows that the whole of $\C^{m+n}$ is generated by \eqref{eqn:blockDiagonals}.

For the second part, note that if $((X_1, \ldots, X_4,u), (Y_1, \ldots, Y_4,v))$ lies in $\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4)$, then the $X_i$ (resp.~$Y_i$) commute.
We then have the joint spectra
\[
S(X) = \{(\lambda_1,\lambda_2,\lambda_3,\lambda_4) \in \C^4 \, : \, \exists v \in \C^m \setminus \{0\} \text{ such that }X_i v = \lambda_iv\}
\]
and
\[
S(Y) = \{(\lambda_1,\lambda_2,\lambda_3,\lambda_4) \in \C^4 \, : \, \exists v \in \C^n\setminus\{0\} \text{ such that }Y_i v = \lambda_iv\}.
\]
Letting $l(\lambda_1,\lambda_2,\lambda_3,\lambda_4) = \sum_{i=1}^4 a_i\lambda_i$, the spectrum of $\sum_{i=1}^4a_iX_i$ (resp.~$\sum_{i=1}^4a_iY_i)$ is $l(S(X))$ (resp.~$l(S(Y))$).
It is then easy to see that the pair $((X_i),u),((Y_i),v)$ lies in $O_{m,n}$ if and only if $S(X) \cap S(Y) = \varnothing$.

On the other hand, $S(X)$ and $S(Y)$ can be identified with the set-theoretic support of the associated subschemes of $\Hilb^m(\C^4)$ and $\Hilb^n(\C^4)$, so that $S(X) \cap S(Y) = \varnothing$ if and only if the pair lies over $U_{m,n}$.
This proves the claim.
\end{proof}

We obtain a commutative diagram
\begin{equation} \label{diag:sqrs1}
\begin{tikzcd} 
O_{m,n}  \arrow[r, " "] & A_{m+n} \\
\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4)|_{U_{m,n}} \arrow[r, " "] \arrow[u, hook] \arrow[d, "\nu_{m,n}"] & \Hilb^{m+n}(\C^4) \arrow[u, hook] \arrow[d, "\nu_{m+n}"] \\
 U_{m,n} \arrow[r, "\sigma_{m,n}"] & \Sym^{m+n}(\C^4)
\end{tikzcd}
\end{equation}
where the squares are cartesian, and the bottom map is \'etale. Abusing notation, we denote all horizontal arrows by $\sigma_{m,n}$.

\begin{lemma}
The morphism $O_{m,n} \to A_{m+n}$ is unramified.
\end{lemma}
\begin{proof}
Representing $(P,Q) \in O_{m,n}$ by $(X_1^P, \ldots, X_4^P, u^P)$ and $Q$ by $(X_1^Q, \ldots, X_4^Q, u^Q)$, the image point $P+Q$ is represented by
$$
\Big( \Big(\begin{array}{cc} X_1^P & 0 \\ 0 & X_1^Q \end{array}\Big), \ldots, \Big(\begin{array}{cc} X_4^P & 0 \\ 0 & X_4^Q \end{array}\Big), \Big( \begin{array}{c} u^P \\ u^Q \end{array} \Big) \Big).
$$
Consider the induced map on tangent spaces
\begin{equation} \label{mapontangents}
T_{A_m}|_P \oplus T_{A_n}|_Q \to T_{A_{m+n}}|_{P+Q}, 
\end{equation}
and take a vector in $T_{A_m}|_P$ represented by $\xi_1 = (Y_1, \ldots, Y_4, u)$ and a vector in $T_{A_n}|_Q$ represented by $\xi_2 = (Z_1, \ldots, Z_4, v)$. Using the quotient construction of $A_{m+n}$, we see that if $(\xi_1,\xi_2)$ maps to zero under \eqref{mapontangents} then there exist matrices $g_{11} \in \End(\C^m)$, $g_{12} \in \Hom(\C^n,\C^m)$, $g_{21} \in \Hom(\C^m,\C^n)$, $g_{22} \in \End(\C^n)$ such that
\begin{align*}
[g_{11}, X_i^P] &= Y_i, \quad [g_{22}, X_i^Q] = Z_i, \\ 
g_{12} X_i^Q &= X_i^P g_{12}, \quad g_{21} X_i^P = X_i^Q g_{21}, \\ 
g_{11} u^P + g_{12} u^Q &= u, \quad g_{21} u^P + g_{22} u^Q= v,
\end{align*}
for all $i=1,2,3,4$, and where $[-,-]$ denotes the commutator. By assumption, there exists $(a_1, \ldots, a_4) \in \C^4 \setminus 0$ such that $\sum_i a_i X_i^P$ and $\sum a_i X_i^Q$ have disjoint spectra.
By the second line of equations, we may apply Lemma \ref{thm:linearAlgebra}, with $A_{11} = \sum_i a_iX_i^P, A_{22} = \sum_i a_iX_i^Q$, $B_{12} = g_{12}$, and $B_{21} = g_{21}$. 
We conclude that $g_{12} = 0$ and $g_{21} = 0$. 
The remaining equations then imply $(\xi_1,\xi_2)$ equals  $(0,0)$ as elements of $T_{A_m}|_P \oplus T_{A_n}|_Q$.
\end{proof}

We define the quadratic vector bundle
$$
E_{m,n} := E_m \boxplus E_n \quad \mathrm{on} \quad A_m \times A_n,
$$
which has a maximal isotropic subbundle $\Lambda_{m,n} = \Lambda_m \boxplus \Lambda_n$.
There is a natural inclusion 
$$
E_{m,n} \into \sigma_{m,n}^*E_{m+n}
$$
under which the quadratic forms and sections of $(s_m, s_n)$ and $s_{m+n}$ agree. Recall that on $A_n$, we also have a rank $n$ tautological vector bundle $\cV_n$ and we define 
\[
\cV_{m,n} = \cV_m \boxplus \cV_n \quad \mathrm{on} \quad A_m \times A_n.
\]
We define the bundle
\[
F_{m,n} = \C^4 \otimes (\sHom (\cV_m, \cV_n) \oplus \sHom(\cV_n,\cV_m))
\]
on $A_{m} \times A_n$.
We have a natural identification of $\sigma^*(E_{m+n})/E_{m,n}$ with
\[
\Lambda^2 \C^4 \otimes (\sHom (\cV_m, \cV_n) \oplus \sHom(\cV_n,\cV_m)).
\]
We get a homomorphism of sheaves
\[
\phi \colon F_{m,n} \to \sigma^*(E_{m,n})/E_{m,n}
\]
defined by
\[
\sum_i e_i \otimes Y_i \mapsto \sum_{i < j} (e_i \wedge e_j) \otimes ([X_i,Y_j] + [X_j,Y_i]),
\]
where $X_i \in \cEnd(\cV_m \oplus \cV_n)$ are the tautological endomorphisms.
\begin{lemma}
\label{thm:inclusionOfMaximaIsotropic}
    Restricting to $\Hilb^m(\C^4) \times \Hilb^n(\C^4)|_{U_{m,n}}$, the image $\phi(F_{m,n})$ is an isotropic subsheaf of $\sigma_{m,n}^*(E_{m+n}/E_{m,n})$.
    At any point $p \in \Hilb^m(\C^4) \times \Hilb^n(\C^4)|_{U_{m,n}}$, we have that $\phi(F_{m,n})|_p \subseteq \sigma^*_{m,n}(E_{m+n})/E_{m,n}|_p$ is of dimension $6mn$, so is a maximal isotropic subspace, and this is moreover positively oriented with respect to our chosen orientations of $E_m, E_n$ and $E_{m+n}$.
\end{lemma}
\begin{proof}
The fact that $\phi(F_{m,n})|_p \subseteq \sigma_{m,n}^*(E_{m+n})/E_{m,n}|_p$ is an isotropic subspace follows from the fact that (since the $X_i$ commute),
\[
\sum_{\sigma \in S_4}(-1)^{|\sigma|}\tr(([X_{\sigma(1)}, Y_{\sigma(2)}] + [X_{\sigma(2)}, Y_{\sigma(1)}])([
X_{\sigma(3)},Y_{\sigma(4)}] + [X_{\sigma(4)}, Y_{\sigma(3)}])) = 0.
\]
We now show that $\phi(F_{m,n})|_p$ has the maximal dimension $6mn$.
Let us write $V_i$ for $\cV_i|_p$, and let $W = \Hom(V_m, V_n) \oplus \Hom(V_n, V_m)$.
The image of $\phi|_p$ is identified with the image of a map
\[
\C^4 \otimes W \to \Lambda^2 \C^4 \otimes W.
\]
Letting $\C^3 = \langle e_2,e_3,e_4\rangle$, it is enough to show that the composed homomorphism
\[
\C^3 \otimes W \to \C^4 \otimes W \to \Lambda^2 \C^4 \otimes W \to e_1 \otimes \C^3 \otimes W
\]
has rank $\ge 6mn$.
This homomorphism is explicitly described by
\begin{equation}
\label{eqn:explicitForm}
(Y_2,Y_3,Y_4) \mapsto ([Y_2,X_1], [Y_3,X_1], [Y_4,X_1]).
\end{equation}
After acting by $\mathrm{GL}(4,\C)$, we may assume, since $p \in O_{m,n}$, that the spectrum of $X_1$ acting on $V_m$ is disjoint from the spectrum of $X_1$ acting on $V_n$.
It then follows from Lemma \ref{thm:linearAlgebra} that \eqref{eqn:explicitForm} is injective, i.e.~has rank $6mn$.

We have shown that, on $\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4)|_{U_{m,n}}$, $\im(\phi)$ is an isotropic subbundle of maximal rank. 
It remains to see that it is positively oriented.
By connectedness of $\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4)|_{U_{m,n}}$, this can be checked at any given point, and we may choose a point $(Z_1,Z_2)$ contained in the line $\{x_1 = x_2 = x_3 = 0\} \subset \C^4$.
For our choice of $\Lambda$ in \eqref{defLambda}, here a simple computation shows that in fact $\im(\phi) = \Lambda_{m+n}/ \Lambda_{m,n}$. 
\end{proof}

\begin{lemma} \label{lem:N}
On $\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4)|_{U_{m,n}}$, the section $s_{m+n}$ of $E_{m+n}$ induces an inclusion of vector bundles.
\[
ds_{m+n} \colon N_{A_m \times A_n/A_{m+n}} \into \sigma_{m,n}^*(E_{m+n})/E_{m,n}.
\]
With respect to the orientations on $E_{m,n}$ and $E_{m+n}$ given by $\Lambda_{m,n}$ and $\Lambda_{m+n}$, the bundle $ds_{m+n}(N_{A_m \times A_n/A_{m+n}})$ is a positive maximal isotropic subbundle of the quadratic vector bundle $\sigma^*_{m,n}(E_{m+n})/E_{m,n}$.
\end{lemma}
\begin{proof}
We work on $\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4)|_{U_{m,n}}$, and suppress all pullbacks from the notation.
We first show that the homomorphism $ds_{m+n} \colon N_{A_m \times A_n/A_{m+n}} \to \sigma^*_{m,n}(E_{m+n})/E_{m,n}$ is injective as a map of vector bundles.
Since the sections $s_m,s_n$ and $s_{m+n}$ vanish on $U_{m,n}$, we have a commutative diagram
\begin{equation}
\label{eqn:commDiagT}
\begin{tikzcd}
    T_{A_m \times A_n} \arrow[r] \arrow[d, "ds_m \oplus ds_n"] & T_{A_{m + n}} \arrow[d, "ds_{m+n}"] \\
    E_m \oplus E_n \arrow[r] & E_{m+n}
\end{tikzcd}
\end{equation}
and taking cokernels gives the homomorphism 
\[
N_{A_m \times A_n/A_{m+n}} \to E_{m+n}/(E_m \oplus E_n).
\]
We have a short exact sequence
\[
0 \to \cEnd(\cV_{m+n}) \to \C^4 \otimes \cEnd(\cV_{m+n}) \to T_{A_{m+n}} \to 0.
\]
There is moreover a natural homomorphism $F_{m,n} \to \C^4 \otimes \cEnd(\cV_{m+n})$.
The homomorphism $\phi$ agrees with the composed homomorphism
\[
F_{m,n} \to \C^4 \otimes \cEnd(\cV_{m+n}) \to T_{A_{m+n}} \to N_{A_m \times A_n/A_{m+n}} \to E_{m+n}/(E_m \oplus E_n).
\]
By Lemma \ref{thm:inclusionOfMaximaIsotropic}, our claims follow.
\end{proof}

%We require some information about the determinant of $N_{A_m \times A_n / A_{m+n}}$.
\begin{lemma} \label{lem:detN}
There is a $\TT'$-equivariant isomorphism $\det(N_{A_m \times A_n / A_{m+n}}) \cong \O$.
% Any $\TT$-equivariant square root of $\det(N_{A_m \times A_n / A_{m+n}})$ is also $\TT$-equivariantly trivial. 
\end{lemma}
\begin{proof}
Let $N := N_{A_m \times A_n/A_{m+n}}$. In $K_{\TT'}^0(O_{m,n})$, we have the identity $$N = T_{A_{m+n}}|_{O_{m,n}} - (T_{A_m} \boxplus T_{A_n})|_{O_{m,n}}.$$ Since the determinant map factors through $K$-theory, using \eqref{eqn:TAinKtheory}, we immediately find $\det(N) \cong \O$ ($\TT'$-equivariantly). 
\end{proof}

