We now have an unramified morphism $O_{m,n} \to A_{m+n}$ and quadratic vector bundles $E_{m,n}$, $E_{m+n}$ with maximal isotropic subbundles $\Lambda_{m,n}$, $\Lambda_{m+n}$ (and hence orientations) and compatible sections $(s_m,s_n)$, $s_{m+n}$. By Example \ref{ex:sqrtdetgivesspin}, using the square roots of $\det(\Lambda_{m+n})$, $\det(\Lambda_m)$, $\det(\Lambda_n)$ in Section \ref{sec:definv} (see \eqref{eqn:detLambda}), we thus have spin modules
\[
S_m \otimes S_n, \quad S_{m+n}
\]
for $C(E_{m,n}) \cong C(E_m) \, \widehat{\otimes} \, C(E_n)$ and $C(E_{m+n})$. It remains to verify the local structure described in \eqref{eqn:specialFormOfS}.

\begin{proposition} \label{prop:localstruccheck}
The isotropic section $s_{m+n}$ satisfies \eqref{eqn:specialFormOfS} in suitable local formal coordinates. As a consequence, we have an induced $\TT'$-equivariant isomorphism
\begin{align*}
\sigma_{m,n}^* (\cH(S_{m+n},s_{m+n})) &\cong \cH((S_m,s_m) \otimes (S_n,s_n))|_{O_{m,n}} \\
&\cong \cH(S_m,s_m) \otimes \cH(S_n,s_n) |_{O_{m,n}}.
\end{align*}
\end{proposition}
\begin{proof}
	We may write $A_m$ as a GIT quotient $Z_m/\GL(m,\CC)$, where $Z_m$ is the open semistable locus of $\C^{4m^2 + m}$ denoted $U$ in Section \ref{sec:zeroloc}.
	The map $A_m \times A_n \dashrightarrow A_{m+n}$ arises from the natural map $Z_m \times Z_n \dashrightarrow Z_{m + n}$ along with the group inclusion $\GL(m,\CC) \times \GL(n, \CC) \to \GL(m+n,\CC)$.

	We fix a point $(P,Q) \in \Hilb^m(\C^4) \times \Hilb^n(\C^4)|_{U_{m,n}}$ at which we want to prove the claim.
    Say $(P,Q)$ is the image of $(\widetilde P, \widetilde Q) \in Z_m \times Z_n$, with  $\widetilde P = (\mathbf{A}_1, \ldots, \mathbf{A}_4,u)$ and $\widetilde Q = (\mathbf{D}_1, \ldots, \mathbf{D}_4,v)$.
	After acting by $\GL(4,\CC)$, we may assume that the spectra of $\mathbf{A}_1$ and $\mathbf{D}_1$ are disjoint.

    The map $Z_m \times Z_n \dashrightarrow Z_{m +n}$ sends $(\widetilde{P},\widetilde{Q})$ to 
	\[
	\left( \begin{pmatrix}
		\mathbf{A}_1 & 0 \\
		0 & \mathbf{D}_1
	\end{pmatrix}, \begin{pmatrix}
		\mathbf{A}_2 & 0 \\
		0 & \mathbf{D}_2
	\end{pmatrix}, \begin{pmatrix}
		\mathbf{A}_3 & 0 \\
		0 & \mathbf{D}_3
	\end{pmatrix}, \begin{pmatrix}
		\mathbf{A}_4 & 0 \\
		0 & \mathbf{D}_4
	\end{pmatrix},\begin{pmatrix}
		u \\
		v
	\end{pmatrix} \right).	\]
	Here $\mathbf{A}_i$ has size $m \times m$, $\mathbf{D}_i$ has size $n \times n$, $\C \langle \mathbf{A}_1, \ldots, \mathbf{A}_4 \rangle \cdot u = \C^m$, $\C \langle \mathbf{D}_1, \ldots, \mathbf{D}_4 \rangle \cdot v = \C^n$, and $\mathbf{A}_1, \mathbf{D}_1$ have disjoint spectra.
	We define $\widetilde{Z}_{m,n}$ as the locally closed subvariety of $Z_{m+n}$ of all such tuples satisfying these constraints.
	We next define $\widetilde Z_{m+n}$ to be the closed subvariety of $Z_{m+n}$ of tuples of the form
	\[
	\left( \begin{pmatrix}
		\mathbf{A}_1 & 0 \\
		0 & \mathbf{D}_1
	\end{pmatrix}, \begin{pmatrix}
		\mathbf{A}_2 & \mathbf{B}_2 \\
		\mathbf{C}_2 & \mathbf{D}_2
	\end{pmatrix}, \begin{pmatrix}
		\mathbf{A}_3 & \mathbf{B}_3 \\
		\mathbf{C}_3 & \mathbf{D}_3
	\end{pmatrix}, \begin{pmatrix}
		\mathbf{A}_4 & \mathbf{B}_4 \\
		\mathbf{C}_4 & \mathbf{D}_4
	\end{pmatrix} ,\begin{pmatrix}
		u \\
		v
	\end{pmatrix} \right).	 
	\]
	 The diagram
	\begin{equation}
    \label{eqn:ZTildeDiagram}
	\begin{tikzcd}
		\widetilde{Z}_{m,n} \arrow[hookrightarrow]{r} \arrow[d] & \widetilde Z_{m+n} \arrow[d]\\
		A_{m} \times A_n \arrow[dashed,r] & A_{m + n}
	\end{tikzcd}
	\end{equation}
	is commutative.
	We claim both vertical arrows are submersions locally near $(\widetilde{P},\widetilde{Q})$.
	The left hand morphism is locally a free group quotient, hence a submersion.
	For the right hand morphism, we may describe the tangent space of $A_{m+n}$ at a point by the cokernel in the short exact sequence
	\[
	0 \to \mathfrak{gl}_{m+n} \to \CC^4 \otimes \End(\CC^{m+n}) \oplus \C^{m+n} \to T \to 0.
	\]
	The vertical arrow maps the tangent space $T'$ of $\widetilde Z_{m+n}$ at a point $(\widetilde{P},\widetilde{Q})$ to the corresponding subspace of $\CC^4 \otimes \End(\CC^{m+n}) \oplus \C^{m+n}$, and the claim to be verified is that the composition of this to $T$ is surjective.

	We claim that $T' \cap \mathfrak{gl}_{m+n} \subseteq \mathfrak{gl}_m \times \mathfrak{gl}_n$.
	To see this, note the embedding of $\mathfrak{gl}_{m+n}$ in $\CC^4 \otimes \End(\CC^{m+n}) \oplus \C^{m+n}$ at a point $(X_1, \ldots, X_4,u)$ is given by commutators $g \mapsto ([g,X_1], \dots, [g,X_4],g u)$.
	Writing
	\[
	g = \begin{pmatrix} g_{11} & g_{12} \\ g_{21} & g_{22} \end{pmatrix}, \quad X_1 = \begin{pmatrix} \mathbf{A}_1 & 0 \\ 0 & \mathbf{D}_1 \end{pmatrix},
	\]
	the condition that $[g, X_1]$ is block diagonal means that $\begin{pmatrix} 0 & g_{12} \\ g_{21} & 0 \end{pmatrix}$ commutes with $X_1$.
	Since the spectra of $\mathbf{A}_1$ and $\mathbf{D}_1$ are assumed disjoint, this implies $g_{12}$ and $g_{21}$ are both 0 by Lemma \ref{thm:linearAlgebra}. 
	A dimension count now implies the surjectivity we want.

	Working around the point $(\widetilde{P},\widetilde{Q})  \in \widetilde{Z}_{m,n}$, imposing a general system of $m^2 + n^2$ linear equations on the $\mathbf{A}_i$ and $\mathbf{D}_i$, and $(u,v) \in \CC^{m+n}$, we get transversal slices of the vertical maps in \eqref{eqn:ZTildeDiagram}.
	We therefore obtain a formal local model of $A_m \times A_n \dashrightarrow A_{m +n}$ in this way.
	Letting the $x_i$ be the coordinates arising from the $\mathbf{A}_j$, $\mathbf{D}_j$, $u,v$ and the $y_i$ be the coordinates arising from the $\mathbf{B}_j$ and $\mathbf{C}_j$, we find that $A_{m} \times A_n$ is cut out by the vanishing of the $y_i$. We furthermore shift the coordinates $x_i$ so that the point defined by putting all $x_i$ and $y_i$ equal to zero corresponds to $(\widetilde{P},\widetilde{Q})$.

	On $\widetilde Z_{m + n}$, the bundle $E_{m + n}$ is identified with the trivial vector bundle with fibre $\Lambda^2 \CC^4 \otimes \End(\CC^{m+n})$, and similarly the bundles $E_{m}, E_n$ are identified with the trivial vector bundles with fibre $\Lambda^2 \CC^4 \otimes \End(\CC^m)$ and $\Lambda^2 \CC^4 \otimes \End(\CC^n)$ respectively.
	We let $E_{m,n}'$ correspond to the trivial vector bundle with fibre  $\Lambda^2 \CC^4 \otimes (\Hom(\CC^m, \CC^n) \oplus \Hom(\CC^n, \CC^m))$. 
    We then get a split exact sequence of quadratic vector bundles
	\[
	0 \to E_m \oplus E_n \to E_{m+n} \to E_{m,n}' \to 0.
	\]

	The canonical sections of $E_{m+n}$, $E_m$, and $E_n$ are quadratic in the $x_i$ and $y_i$, have no constant term, and have the following properties:
    \begin{itemize}
    \item the terms of the components of the section in $E_m \oplus E_n$ are of the form $x_i, x_ix_j$ or $y_iy_j$;
    \item the terms of the components of the section in $E_{m,n}'$ are of the form $x_i y_j$ or $y_i$;
    \item the degree 1 terms in the $y_i$ define an inclusion of the normal bundle $N_{\widetilde Z_{m,n}/\widetilde Z_{m+n}}$ in $E_{m,n}'$ (Lemma \ref{lem:N}).
    \end{itemize} 
	%Indeed, if the map were not injective, we would have matrices $b_2, c_2,\dots b_4, c_4$ such that $A_1b_i - b_iD_1 = 0$ and $c_iA_1 - D_1c_i = 0$.
	%By our assumption on $A_1$, this is impossible. \textcolor{orange}{here we also have the old proof using that the map is ramified}

This means that Assumption \ref{assume:LocalForm} holds.
We may therefore apply Lemma \ref{thm:comparisonHomomorphismExists}. 
By Lemma \ref{lem:detN} combined with Proposition \ref{thm:torsionInPicardGroup}, after restricting to $\Hilb^m(\C^4) \times \Hilb^n(\C^4)|_{U_{m,n}}$, any square root of $\det(N_{A_m \times A_n/A_{m+n}})$ is $\TT'$-equivariantly trivial, so we obtain a $\TT'$-equivariant isomorphism
\[
\sigma_{m,n}^* (\cH(S_{m+n},s_{m+n})) \cong \cH((S_m,s_m) \otimes (S_n,s_n))|_{O_{m,n}}.
\]
Finally, since the factors of $(S_m,s_m) \otimes (S_n,s_n)$ pull-back from $A_m$ and $A_n$, they depend on different variables and we have $\cH((S_m,s_m) \otimes (S_n,s_n)) \cong \cH(S_m,s_m) \otimes \cH(S_n,s_n)$ from which the result follows.
\end{proof}

We can now define our factorizable sequences.
\begin{lemma}
	\label{thm:compareSqrtK}
	Let $\F_n := \cH(R \nu_{n*} \cH(S_n,s_n))$ for all $n>0$.\footnote{To a bounded complex $\mathcal{C}\udot$, we associate the $\Z/2$-graded coherent sheaf $\cH(\mathcal{C}\udot) :=  H^{\mathrm{odd}}(\mathcal{C}\udot)[1] \oplus  H^{\mathrm{even}}(\mathcal{C}\udot)$ where $H^i(-)$ denotes the $i$th cohomology sheaf.} Then, for each $m,n >0$, we have a $\TT'$-equivariant isomorphism 
	\[
	\phi_{m,n} \colon \F_m \boxtimes \F_n|_{U_{m,n}} \cong \sigma_{m,n}^* \F_{m+n}.
	\]
\end{lemma}
\begin{proof}
	Pulling back the isomorphism of Proposition \ref{prop:localstruccheck} to $\Hilb^m(\C^4)\times \Hilb^n(\C^4)|_{U_{m,n}}$, applying $R \nu_{m,n*}(-)$, using the fact that the bottom square in \eqref{diag:sqrs1} is cartesian, $\sigma_{m,n}$ is \'etale so in particular flat, and applying the K\"unneth formula for derived push-forward, we obtain 
	\begin{align*}
	\sigma_{m,n}^* R \nu_{m+n*}  \cH(S_{m+n},s_{m+n}) &\cong R \nu_{m,n*}  (\cH(S_m,s_m) \otimes  \cH(S_n,s_n))|_{U_{m,n}} \\
	& \cong R \nu_{m*} \cH(S_m,s_m) \boxtimes^{L} R \nu_{n*} \cH(S_n,s_n)|_{U_{m,n}}.
	\end{align*}
	Applying $\cH(-)$, using again that $\sigma_{m,n}$ is flat, and applying the K\"unneth formula for cohomology sheaves, the result follows. 
\end{proof}

\begin{proposition} \label{prop:factor}
The following are factorizable sequences of $\mathbb T'$-equivariant $\Z/2$-graded coherent sheaves on $\Sym^\mdot(\C^4)$ 
\begin{align*}
\Big\{ \cH(R \nu_{n*}  ( \cH(S_n,s_n) ) \Big\}_{n=1}^{\infty}, \quad \Big\{ \cH(R \nu_{n*} (\Lambda^\mdot (\cV^\vee_n \otimes y))) \Big\}_{n=1}^{\infty}, \quad \Big\{ \cH(R \nu_{n*} (\cN^\sheaf_{1,n})) \Big\}_{n=1}^{\infty}.
\end{align*}
\end{proposition}
\begin{proof}
Let us start with factorizability of the first sequence. Denote by $O_{m,n,p} \subset A_m \times A_n \times A_p$ the open locus representing triples $$((X_1, \ldots, X_4,u), (Y_1, \ldots, Y_4,v), (Z_1, \ldots, Z_4,w),$$ for which there exists an $(a_1, \ldots, a_4) \in \C^4 \setminus 0$ such that $\sum_i a_i X_i$, $\sum_i a_i Y_i$, $\sum_i a_i Z_i$ have mutually disjoint spectra. We then have a commutative diagram
\begin{equation} \label{diag:sqrs}
\begin{tikzcd} 
O_{m,n,p}  \arrow[r, " "] & A_{m+n+p} \\
\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4) \times \Hilb^p(\C^4) |_{U_{m,n,p}} \arrow[r, " "] \arrow[u, hook] \arrow[d, "\nu_{m,n,p}"] & \Hilb^{m+n+p}(\C^4) \arrow[u, hook] \arrow[d, "\nu_{m+n+p}"] \\
 U_{m,n,p} \arrow[r, "\sigma_{m,n,p}"] & \Sym^{m+n+p}(\C^4)
\end{tikzcd}
\end{equation}
in which the squares are cartesian, the top horizontal arrow is unramified and the bottom two horizontal arrows are \'etale. We apply Lemma \ref{lem:associativity} to the two ways of decomposing $\sigma_{m,n,p}$
\begin{displaymath}
\xymatrix
{
& O_{m+n,p} \ar[rd]^{\sigma_{m+n,p}} & \\
O_{m,n,p} \ar[ru]^{\sigma_{m,n} \times \mathrm{id}} \ar[rd]_{\mathrm{id} \times \sigma_{n,p}} \ar^{\sigma_{m,n,p}}[rr] & & A_{m+n+p} \\
& O_{m,n+p} \ar_{\sigma_{m,n+p}}[ru] &
}
\end{displaymath}
We then obtain a diagram (suppressing some obvious pull-backs to open subsets)
\begin{displaymath}
\label{eqn:actualCommutativity}
\xymatrix
{
& \sigma_{m,n}^* \cH(S_{m+n}) \otimes \cH(S_p) \ar[rd] & \\
\sigma_{m,n,p}^* \cH(S_{m+n+p}) \ar[ru] \ar[rd] & & \cH(S_m) \otimes \cH(S_n) \otimes \cH(S_p) \\
& \cH(S_m) \otimes \sigma_{n,p}^* \cH(S_{n+p}) \ar[ru] &
}
\end{displaymath}
however this diagram may \emph{not} commute. The reason for this is that, for each pair $(m,n) \in \Z_{>0}^2$, we pick a $\TT'$-equivariant isomorphism of a square root of $\det(N)$ with $\O$ at the end of the proof of Proposition \ref{prop:localstruccheck}. In particular, going through the previous diagram via the top two arrows requires picking $\TT'$-equivariant isomorphisms of square roots of $\det(N_{A_m \times A_n \times A_p/A_{m+n} \times A_p})$ and $\det(N_{A_{m+n} \times A_p / A_{m+n+p}})$ with $\O$, whereas going through the diagram via the bottom two arrows requires picking $\TT'$-equivariant isomorphisms of square roots of $\det(N_{A_m \times A_n \times A_p/A_{m} \times A_{n+p}})$ and $\det(N_{A_m \times A_{n+p} / A_{m+n+p}})$ with $\O$. Therefore, the diagram is only guaranteed to commute up to an element of 
\[
H^0_{\TT'}(\Hilb^{m}(\C^4) \times \Hilb^{n}(\C^4) \times \Hilb^p(\C^4) |_{U_{m,n,p}}, \O^*).
\]

% By the same codimension arguments as in the proof of Lemma \ref{lem:sqrtdetN}, we easily see that $H^0_{\TT}(O_{m,n,p},\O^*) \cong \C^*$, so the diagram commutes up to a non-zero constant.

The trivializations of $\det(N_\bullet)$ from Lemma \ref{lem:detN} can be made explicit using the exact sequence \eqref{eqn:tangentBundleExactSequence}.
They are compatible up to a global scalar,\footnote{The authors have not ruled out the possibility that this scalar is in fact 1.} in the sense that for all $m,n,p$, the composed homomorphism
\begin{align*}
\O = \O \otimes \O &\cong \det(N_{A_m \times A_n \times A_p/A_{m+n} \times A_p}) \otimes \det(N_{A_{m+n} \times A_p/A_{m+n+p}}) \\
&\cong \det(N_{A_m \times A_n \times A_p/A_{m+n+p}}) \cong \O
\end{align*}
is constant.

Now for each square root line bundle $(\det(N_\bullet))^{1/2}$, we may choose a trivialization such that $1 \otimes 1$ maps to $1$.
As this is done on a connected scheme, there are precisely two such trivializations, differing by a sign.
It follows that the trivializations of the square roots are compatible with the tensor products up to a global scalar, and so the diagram \eqref{eqn:actualCommutativity} commutes up to a scalar.
This is enough by Proposition \ref{prop:uptocst}. 

Similarly, applying Lemma \ref{lem:commutativity}, one verifies the commutativity property of Definition \ref{def:factorisableSequence}. 
Again, commutativity may only hold up to a non-zero constant due to our choices of trivialization of $\det(N_{A_m \times A_n/A_{m + n}})^{1/2}$, arguing as above.
Using Proposition \ref{prop:uptocst}, this constant equals either $1$ or $(-1)^{mn}$, implying that either (case A) $\{\cH(R \nu_{n*}  ( \cH(S_n,s_n))\}$ or (case B) $\{\cH(R \nu_{n*}  ( \cH(S_n,s_n))[n]\}$ is a factorizable sequence.

Leaving the question of whether case A or B holds aside for the moment, note that factorizability of the second sequence is straight-forward by using the fact that $\cV_{m+n}|_{O_{m,n}} \cong \cV_m \oplus \cV_n$ and therefore
\[
\Lambda^\mdot(\cV_{m+n}^\vee \otimes y)|_{O_{m,n}} \cong  \Lambda^\mdot(\cV_m^\vee \otimes y) \otimes \Lambda^\mdot(\cV_n^\vee \otimes y).
\]

Taking the tensor product of the isomorphisms on $\Hilb^m(\C^4) \times \Hilb^n(\C^4)|_{U_{m,n}}$ used to show factorizability of the first two sequences, we get factorizability of either (case A) $\{\cH(R \nu_{n*} (\cN^\sheaf_{1,n}))\}$ or (case B) $\{\cH(R \nu_{n*} (\cN^\sheaf_{1,n}))[n])\}$.
We now prove that case B cannot hold.
Assume for a contradiction that it did.
In Section \ref{sec:local}, we determine $\mathsf{G}_1$ by $\TT'$-localization and in particular, by Proposition \ref{signprop}, we find
\[
\sum_{n=0}^\infty \chi(\Sym^n(\C^4), R \nu_{n*} (\cN^\sheaf_{1,n})[n])q^n = \mathsf{G}_1(-q) = \mathsf{Z}_1^{\NP}(-q).
\]
Moreover, the methods of Section \ref{sec:local} readily determine this generating series explicitly modulo $q^3$. By Lemma \ref{prop:Oko}, we also have
\[
\mathsf{Z}_1^{\NP}(-q) = \Exp\left(\frac{G_1}{[t_1][t_2][t_3][t_4]}\right)
\]
for some $G_1 \in qK_0^{\mathbb T'}(\pt)[[q]]$.
But taking the plethystic logarithm of $\mathsf{Z}_1^{\NP}(-q)$ shows that the $q^2$-term of $G_1$ must then be
\[
-[t_1t_2][t_1t_3][t_2t_3][y^2] - \frac{[t_1^2t_2^2][t_1^2t_3^2][t_2^2t_3^2][y^2]}{(1+t_1)(1+t_2)(1+t_3)(1+t_4)},
\]
which is not a Laurent polynomial.
This gives a contradiction, and so case A holds, proving our claim.
\end{proof}

Recall that $\mathsf{G}_1 = \sum_n N_{1,n}^{\glob} q^n$.
\begin{corollary} \label{Exp}
There exists a unique $G_1 \in q K_0^{\T'}(\pt) [[q]]$ such that
\begin{align*}
\mathsf{G}_{1} = \mathrm{Exp}\Bigg(\frac{G_1}{[t_1][t_2][t_3][t_4]}\Bigg).
\end{align*}
\end{corollary}
\begin{proof}
The coefficients of $\mathsf{G}_1$ are
\[
N^\glob_{1,n} = \chi(\Hilb^n(\C^4),\cN^\sheaf_{1,n}) = \chi(\Sym^n(\C^4), R \nu_{n*} (\cN^\sheaf_{1,n})), 
\]
and by Proposition \ref{prop:factor}, the sequence $\{\cH(R \nu_{n*} (\cN^\sheaf_{1,n}))\}$ is factorizable.
Hence, by Lemma \ref{prop:Oko}, there exist $\mathbb T'$-equivariant $K$-theory classes $\G_{n}$ on $\C^4$ such that
\[
\mathsf{G}_{1} = \mathrm{Exp}\Bigg(\sum_{n=1}^\infty \chi(\C^4, \G_ n) \, q^n\Bigg).
\]
Since $\C^4$ has $0$ as its only fixed point, the $K$-theoretic localization formula implies
$$
\G_n = \frac{\iota_* (\G_n|_0)}{(1-t_1)(1-t_2)(1-t_3)(1-t_4)},
$$
where $\G_n|_0 \in  K_0^{\T'}(\pt)$ and $\iota \colon \{0\} \hookrightarrow \C^4$ is the inclusion of the origin.
\end{proof}

\begin{remark}
Using the localization techniques discussed in Section \ref{sec:local}, one can compute $\chi(\Hilb^n(\C^4),\widehat{\O}^{\vir})$ for $n=1,2$. This reveals that 
$$
\sum_{n=0}^{\infty} \chi(\Hilb^n(\C^4),\widehat{\O}^{\vir}) \, q^n
$$
is \emph{not} of the form stated in Lemma \ref{prop:Oko}. This was observed by Arbesfeld. 
Indeed, in this section, we do \emph{not} take square roots of the line bundles $\det(T_{A_n})$, but only of the product $\det(T_{A_n}) \otimes  \det (\cV_n^\vee \otimes y)$. 
In particular, the  $K$-theory classes $R \nu_{n*} \widehat{\O}^{\vir}$ cannot come from a factorizable sequence.
On the other hand, by Proposition \ref{prop:factor}, factorizability \emph{does} apply to the classes $R \nu_{n*} (\widehat{\O}^{\vir} \otimes  \det(T_{A_n}|_{M_n} )^{\frac{1}{2}} )$.
\end{remark}


\section{Local} \label{sec:local}

In this section, we apply virtual localization (specifically, Proposition \ref{prop:nP}) to show that $\mathsf{G}_r = \mathsf{Z}_r^{\mathrm{NP}}$, i.e., the globally defined invariants on $\Quot_r^n(\C^4)$ from Section \ref{sec:definv} indeed give the weighted generating function of $r$-tuples of solid partitions introduced by Nekrasov--Piazzalunga. This section does not require the factorizability results from Section \ref{sec:factorforNek}.


\subsection{Localization for Quot schemes} \label{sec:vertex}

As before, consider $\Quot_r^n(\C^4)$ on which we have an action of $\T'$ (recall the definition of $\T'$ from Remark \ref{def:Tprime}). 
By \cite{Bif} and \cite[Lem.~3.6]{CK}, the $\T'$-fixed locus of $\Quot_r^n(\C^4)$ is scheme theoretically isomorphic to
$$
\bigsqcup_{n = n_1 + \cdots +n_r} \prod_{\alpha=1}^{r} \Hilb^{n_\alpha}(\C^4)^{(\C^*)^4},
$$
where we use the standard action of $(\C^*)^4$ on $\C^4$ lifted to $\Hilb^m(\C^4)$. Moreover, $\Hilb^{m}(\C^4)^{(\C^*)^4}$ is 0-dimensional reduced and identified with the set of monomial ideals of colength $m$, or equivalently solid partitions of size $m$. 
Therefore, we can index the points $P_{\vec{\pi}}$  of $\Quot_r^n(\C^4)^{\T'}$ by $r$-tuples of solid partitions $\vec{\pi} = (\pi_1, \ldots, \pi_r)$ with total size $n$.

Consider a $\T'$-fixed point
$$
P_{\vec{\pi}} =[\O_{\C^4}^{\oplus r} \twoheadrightarrow Q], \quad  Q = \bigoplus_{\alpha=1}^{r} \O_{Z_\alpha},
$$ 
where $Z_\alpha \subset \C^4$ corresponds to the solid partition $\pi_\alpha$. By the Oh--Thomas localization formula, as discussed in the Section \ref{sec:localfixisolated}, we are interested in 
$$
(T_{A_n} - \Lambda)|_{P_{\vec{\pi}}} \in K_0^{\T'}(\pt),
$$
where $A_n:=\ncQ_{r}^{n}(\C^4)$ denotes the ambient non-commutative Quot scheme. 
Recall our choice of $\Lambda$ \eqref{defLambda}.
For computational reasons, and for easy comparison to Nekrasov--Piazzalunga's work \cite{NP}, it will be more convenient to work with $(T_{A_n} - \Lambda^\vee)|_{P_{\vec{\pi}}}$.
Recall that $A_n$ was described as a quotient of a smooth space by a free action (Section \ref{sec:zeroloc}), from which we obtain a short exact sequence
$$
0 \rightarrow \End(V) \rightarrow \C^4 \otimes \End(V) \oplus \Hom(\C^r,V) \rightarrow T_{A_n}|_{P_{\vec{\pi}}} \rightarrow 0.
$$
Hence, in $K_0^{\T'}(\mathrm{pt})$, we have
\begin{align*}
T_{A_n} |_{P_{\vec{\pi}}} = (\C^4 - 1) \cdot \End(V) + \Hom(\C^r,V), \\  
\Lambda^\vee|_{P_{\vec{\pi}}} = (\langle e_4 \rangle \wedge \C^3)^\vee \cdot \End(V) \cong \Lambda^2 \C^3 \otimes \End(V),
\end{align*}
where
\begin{align*}
\C^4 &= t_1^{-1}+t_2^{-1}+t_3^{-1}+t_4^{-1},  \\
\C^r &= w_1 + \cdots + w_r, \\
V &= Z_1 w_1 + \cdots + Z_r w_r,  \\
\Lambda^2 \C^3 &= t_1^{-1}t_2^{-1} +t_1^{-1} t_3^{-1} + t_2^{-1} t_3^{-1}, \\
Z_\alpha &= \sum_{(i,j,k,l) \in \pi_\alpha} t_1^{i} t_2^j t_3^k t_4^l. 
\end{align*}
Therefore 
\begin{align*}
&(T_{A_n} - \Lambda^\vee)|_{P_{\vec{\pi}}} = \\
&\sum_{\alpha,\beta=1}^{r} \frac{w_\beta}{w_\alpha}\Big( Z_\beta - (1- t_1^{-1} - t_2^{-1} - t_3^{-1} - t_4^{-1} + t_1^{-1}t_2^{-1} + t_1^{-1}t_3^{-1} + t_2^{-1}t_3^{-1}) Z^*_\alpha Z_\beta \Big),
\end{align*}
where $(-)^\vee$ denotes the dual of a class in $K$-theory. 
We add to this the representation 
$$
- \hom(\cW,\cV)|_{P_{\vec{\pi}}}^\vee = \sum_{\alpha,\beta=1}^{r} \frac{w_\beta}{w_\alpha}\Big( - y_\beta Z_\alpha^\vee \Big).
$$
For the class of a line bundle $L = t^a w^b y^c \in K_0^{\T'}(\textrm{pt})$, we define
$$
[t^a w^b y^c] = t^{\frac{a}{2}} w^{\frac{b}{2}} y^{\frac{c}{2}} - t^{-\frac{a}{2}} w^{-\frac{b}{2}} y^{-\frac{c}{2}},
$$
where we use multi-index notation for $t=(t_1,t_2,t_3, t_4)$, $w = (w_1, \ldots, w_r)$, and $y = (y_1, \ldots, y_r)$. This operation extends to any class $V \in K_0^{\T'}(\textrm{pt})$ with $V^f \geq 0$ by
$$
[L_1+L_2] = [L_1][L_2], \quad [L_1-L_2] = \frac{[L_1]}{[L_2]}.
$$

\begin{definition} \label{def:NPweight}
Define
\begin{align*}
\mathsf{v}_{\vec{\pi}, \alpha\beta}^{\textrm{pre}} &= \frac{w_\beta}{w_\alpha}   \Big( Z_\beta  - (1-t_1^{-1})(1-t_2^{-1})(1-t_3^{-1}) Z^\vee_\alpha Z_\beta \Big), \quad \mathsf{v}_{\vec{\pi}}^{\textrm{pre}} = \sum_{\alpha,\beta=1}^{r} \mathsf{v}_{\vec{\pi},\alpha\beta}^{\textrm{pre}}, \\
\mathsf{v}_{\vec{\pi}, \alpha\beta} &= \mathsf{v}_{\vec{\pi}, \alpha\beta}^{\textrm{pre}} + \frac{w_\beta}{w_\alpha}   \Big( - y_\beta Z^\vee_\alpha  \Big), \quad \mathsf{v}_{\vec{\pi}} = \sum_{\alpha,\beta=1}^{r} \mathsf{v}_{\vec{\pi},\alpha\beta}.
\end{align*}
The weight assigned to $\vec{\pi}$ by Nekrasov--Piazzalunga \cite{NP} equals $[-\mathsf{v}_{\vec{\pi}}]$. 
\end{definition}

By \cite[Sect.~2.4.1]{NP}, $\mathsf{v}_{\vec{\pi}, \alpha\beta}^{\textrm{pre}}$ and $\mathsf{v}_{\vec{\pi}}$ have no fixed terms (with respect to the torus $\T'$). By the proposition below, this also implies 
$$
\vd P_{\vec{\pi}} = 0.
$$

\begin{proposition} \label{Ktheorycalc}
We have the following equality in $K_0^{\T'}(\mathrm{pt})$
\begin{align*}
\mathsf{v}_{\vec{\pi}}^{\mathrm{pre}} + (\mathsf{v}_{\vec{\pi}}^{\mathrm{pre}})^\vee = \Big((T_{A_n} - \Lambda^\vee) + (T_{A_n} - \Lambda^\vee)^\vee \Big) \Big|_{P_{\vec{\pi}}}.
\end{align*}
In particular, $(T_{A_n} - \Lambda^\vee)|_{P_{\vec{\pi}}}$ has no fixed term. Denoting the kernel of the quotient $P_{\vec{\pi}} =[\O_{\C^4}^{\oplus r} \twoheadrightarrow Q]$ by $\F$, we have
$$
\mathsf{v}_{\vec{\pi}}^{\mathrm{pre}} + (\mathsf{v}_{\vec{\pi}}^{\mathrm{pre}})^\vee = R\Hom(\O_{\C^4}^{\oplus r}, \O_{\C^4}^{\oplus r}) - R\Hom(\F,\F).
$$
Finally, we have
\begin{align*}
&\Big[ \Big( \hom(\cW,\cV)^\vee + \Lambda^\vee- T_{A_n} \Big) \Big|_{P_{\vec{\pi}}} \Big] = (-1)^{n + k_{\vec{\pi}}} [-\mathsf{v}_{\vec{\pi}}], \\
&k_{\vec{\pi}} = \sum_{\alpha=1}^{r} |\{(i,j,k,l) \in \pi_\alpha \, : \, l \neq \min(i,j,k) \}|.
\end{align*}
\end{proposition}
\begin{proof}
The summand corresponding to $\alpha,\beta$ in $(T_{A_n} - \Lambda^\vee)|_{P_{\vec{\pi}}}$ differs from $\mathsf{v}_{\vec{\pi}, \alpha\beta}^{\textrm{pre}}$ by
\begin{equation} \label{diff}
\frac{w_\beta}{w_\alpha} (t_4^{-1} - t_4) Z_\alpha^\vee Z_\beta,
\end{equation}
from which the first equality follows. 
%Since $[-\mathsf{v}_{\vec{\pi}}]$ has no fixed term \cite[Sect.~2.4.1]{NP} and $\hom(\cW,\cV)|^*_{P_{\vec{\pi}}}$ (obviously) has no fixed term, we conclude that $(T_{\ncQ_r^n(\C^4)} - \Lambda)|_{P_{\vec{\pi}}}$ has no fixed term.

The class $R\Hom(\O_{\C^4}^{\oplus r}, \O_{\C^4}^{\oplus r}) - R\Hom(\F,\F)$ can be determined using a \v{C}ech calculation similar to \cite{MNOP1} and was worked out for $\Quot_r^n(\C^3)$ in \cite{FMR} and for $\Hilb^n(\C^4)$ in \cite{CK}. The result is
$$
\sum_{\alpha,\beta=1}^{r} \frac{w_\beta}{w_\alpha}   \Big( Z_\beta + \frac{Z^\vee_\alpha}{t_1t_2t_3t_4}  - (1-t_1^{-1})(1-t_2^{-1})(1-t_3^{-1})(1-t_4^{-1}) Z^\vee_\alpha Z_\beta \Big).
$$ 
The second equality of the proposition now follows from direct calculation. 

Let $Q = \sum_{\alpha} Z_\alpha w_\alpha$, then 
$$
\dim (t_4^{-1} Q^\vee Q)^m = n^2 - \dim (t_4^{-1} Q^\vee Q)^f = n^2 - \sum_{\alpha = 1}^{r} \dim (t_4^{-1} Z_\alpha^\vee Z_\alpha)^f,
$$
where $(-)^m$ denotes the moving part and $(-)^f$ denotes the fixed part. Thus, by \eqref{diff}, the final equality of the proposition follows from the following combinatorial lemma.
\end{proof}

%\begin{MK} Strictly speaking, we do not need to know the sign $k_{\pi}$ because later it cancels again! But still, I think it is nice to know. It's a cute lemma.\end{MK}
\begin{lemma} \label{induct}
For any solid partition $\pi$ and corresponding 0-dimensional subscheme $Z$ we have
$$
\dim (t_1 t_2 t_3 Z^\vee Z)^f \equiv |\{(i,j,k,l) \in \pi \, : \, l \neq \min(i,j,k) \}| \pmod 2.
$$
\end{lemma}
\begin{proof}
Writing $Z = \sum_{(i,j,k,l) \in \pi} t_1^{i-l} t_2^{j-l} t_3^{k-l}$, the desired dimension equals
$$
|\{((i,j,k,l),(i',j',k',l')) \in \pi \times \pi \, : \, i'-i = j' - j = k' - k = l' - l-1\}|.
$$
The lemma can now be proved by induction on $|\pi|$. We order the elements $(i,j,k,l) \in \pi$ of a solid partition $\pi$ using the lexicographic order $x_4 > x_3 > x_2 > x_1$. Let $\pi$ be a solid partition of size $n$. Then $\pi$ is obtained from a solid partition $\xi$ of size $n-1$ by adding a box $b$ with bigger order than any box in $\xi$. Suppose the coordinates of $b$ are $(i_0,j_0,k_0,l_0)$. By the induction hypothesis, it suffices to show that 
$$
|\{ (i,j,k,l) \in \xi \, : \, i_0 - i = j_0 - j = k_0 - k = l_0 - l \pm 1\}| \equiv \left\{ \begin{array}{cc} 1 \pmod 2 & \mathrm{if \, }  l_0 \neq \min(i_0,j_0,k_0) \\ 0 \pmod 2 & \mathrm{otherwise.} \end{array} \right.
$$
Since $b$ has maximal order, we only need to compare it to boxes $(i,j,k,l) \in \xi$ with $i \leq i_0$, $j \leq j_0$, $k \leq k_0$, and $l \leq l_0$. In other words, we may assume $\pi$ is of the form $[0,A-1] \times [0,B-1] \times [0,C-1] \times [0,D-1]$ in which case the above claim easily follows.
\end{proof}

We will now apply the Oh--Thomas localization formula as discussed in Section \ref{sec:localfixisolated} and Proposition \ref{prop:nP}
\begin{align}
\begin{split} \label{virloc2} 
\widehat{\O}_M^{\vir} &= \sum_{P \in M^T} (-1)^{n_P^\Lambda} \, \iota_{P*} \Bigg( \frac{1}{\widehat{\Lambda}^{\mdot} (\Omega_{A} - \Lambda^\vee)|_P } \Bigg), \\
n_P^\Lambda &\equiv  \dim  \mathrm{coker}(p_{\Lambda} \circ ds|_P)^f  \pmod 2,
\end{split}
\end{align}
where $s$ is the isotropic section in Section \ref{sec:zeroloc}.
Note that
$$
\widehat{\Lambda}^{\mdot} \Lambda^\vee|_{P}^m = (-1)^{\rk \Lambda|_{P}^m} \widehat{\Lambda}^{\mdot} \Lambda|_{P}^m.
$$
By Lemma \ref{lem:nnprime}, equation \eqref{virloc2} can be rewritten as (keeping the orientation on $(E,q)$ induced by $\Lambda$)
\begin{align}
\begin{split} \label{virloc3} 
\widehat{\O}_M^{\vir} &= (-1)^{\rk \Lambda} \sum_{P \in M^T} (-1)^{n_P^{\Lambda^\vee}} \,  \iota_{P*} \Bigg( \frac{1}{\widehat{\Lambda}^{\mdot} (\Omega_{A} - \Lambda)|_P } \Bigg), \\
n_P^{\Lambda^\vee} &\equiv  \dim  \mathrm{coker}(p_{\Lambda^\vee} \circ ds|_P)^f  \pmod 2.
\end{split}
\end{align}
We prefer using \eqref{virloc3} over \eqref{virloc2} in order to match existing conventions for the vertex formalism in the literature. Moreover, with our current choice of $\Lambda$ in \eqref{defLambda}, it is easier to calculate the parity of $n_{P}^{\Lambda^\vee}$ as opposed to $n_{P}^{\Lambda}$. The calculation of the parity of $n_{P}^{\Lambda^\vee}$ will occupy the next section. 

\begin{proposition} \label{globaltolocal}
We have
\begin{align*}
N_{r,n}^\glob = (-1)^{rn} \sum_{\vec{\pi}} (-1)^{n_{P_{\vec{\pi}}}^{\Lambda^\vee} + k_{\vec{\pi}}} [-\mathsf{v}_{\vec{\pi}}],
\end{align*}
where the sum is over all $r$-tuples $\vec{\pi} = (\pi_1, \ldots, \pi_r)$ of total size $n$.
\end{proposition}
\begin{proof}
By the virtual localization formula, Proposition \ref{Ktheorycalc} (and Remark \ref{dualVW}), the desired invariant equals 
\begin{align*}
N_{r,n}^\glob &= \sum_{\vec{\pi}} (-1)^{n^{\Lambda}_{P_{\vec{\pi}}}} \cdot \widehat{\Lambda}^{\mdot} \hom(\cV,\cW)|_{P_{\vec{\pi}}} \cdot \widehat{\Lambda}^{\mdot} (\Lambda^\vee - \Omega_{A_n})|_{P_{\vec{\pi}}} \\
&=(-1)^{(r-1)n} \sum_{\vec{\pi}} (-1)^{n^{\Lambda^\vee}_{P_{\vec{\pi}}}} \cdot \widehat{\Lambda}^{\mdot} \hom(\cW,\cV)|_{P_{\vec{\pi}}} \cdot \widehat{\Lambda}^{\mdot} (\Lambda - \Omega_{A_n})|_{P_{\vec{\pi}}},
\end{align*}
where we suppress equivariant push-forward to a point. For the class of a line bundle $L$ in $K_0^{\T'}(\mathrm{pt})$, we have $\ch(\widehat{\Lambda}^{\mdot} L^\vee) = [L]$. Since $\widehat{\Lambda}^{\mdot} (V_1 + V_2) = \widehat{\Lambda}^{\mdot} V_1 \cdot  \widehat{\Lambda}^{\mdot} V_2$, the above reduces to
$$
(-1)^{(r-1)n} \sum_{\vec{\pi}} (-1)^{n^{\Lambda^\vee}_{P_{\vec{\pi}}}}   \Big[ \Big( \hom(\cW,\cV)^\vee + \Lambda^\vee - T_{A_n} \Big) \Big|_{P_{\vec{\pi}}} \Big].
$$
The result now follows from Proposition \ref{Ktheorycalc}.
\end{proof}


\subsection{Sign rule}

As in the previous section, we consider a $\T'$-fixed point of $\Quot_r^n(\C^4)$
$$
P_{\vec{\pi}}=[\O_{\C^4}^{\oplus r} \twoheadrightarrow Q], \quad  Q = \bigoplus_{\alpha=1}^{r} \O_{Z_\alpha},
$$ 
where $Z_\alpha \subset \C^4$ corresponds to a solid partition $\pi_\alpha$. In terms of the ``standard model'' $M:=Z(s) \subset A$, $s \in \Gamma(A,E)$ discussed in the introduction and Section \ref{sec:global}, we want to determine the sign \eqref{virloc3}
$$
(-1)^{n^{\Lambda^\vee}_{P_{\vec{\pi}}}}, \quad n_P^{\Lambda^\vee} \equiv  \dim  \mathrm{coker}(p_{\Lambda^\vee} \circ ds|_P)^f  \pmod 2.
$$

% \begin{remark}
% \textcolor{orange}{Delete this remark?} Often in mathematics, a computation is complete if you can carry it out ``up to signs''. However, for the Nekrasov--Piazzalunga conjecture, the signs are perhaps the most striking and important aspect. Up to solid partitions of size $\leq 6$, it is verified in \cite{CK} that there is a \emph{unique} choice of signs for which the Nekrasov--Piazzalunga conjecture holds. E.g.~for the 140 solid partitions of size 6, there are $2^{140} \approx 10^{42}$ choices.\footnote{The uniqueness verification in loc.~cit.~is not via a brute force check. Rather, a special limit of the conjecture turns $[-\mathsf{v}_\pi]$ into a polynomial, which can be exploited to verify uniqueness up to size $\leq 6$ \cite[Rem.~3.24]{CK}.}
% \end{remark}

Recall the definitions of $\mathsf{G}_r$ and  $\sfZ_r^{\NP}$ in \eqref{defG} and \eqref{NPZ}.

\begin{proposition} \label{signprop}
We have
$$
n^{\Lambda^\vee}_{P_{\vec{\pi}}} + k_{\vec{\pi}} \equiv \mu_{\vec{\pi}} \pmod 2, \quad \mu_{\vec{\pi}} := \sum_{\alpha=1}^{r}  |\{(i,i,i,j) \in \pi_\alpha \, : \, j > i\}|.
$$
In particular, $\mathsf{G}_r = \sfZ_r^{\NP}$.
\end{proposition}
\begin{proof}
For any $P = [\O_{\C^4}^{\oplus r} \twoheadrightarrow Q] \in A_n:=\ncQ_{r}^{n}(\C^4)$, we have a short exact sequence (Section \ref{sec:zeroloc})
$$
0 \rightarrow \End(V) \rightarrow \C^4 \otimes \End(V) \oplus \Hom(\C^r,V) \rightarrow T_{A_n}|_P \rightarrow 0.
$$
Consider the composition 
$$
\C^4 \otimes \End(V) \oplus \Hom(\C^r,V) \twoheadrightarrow T_{A_n}|_P \stackrel{ds}{\rightarrow} E|_P = \Lambda^2 \C^4 \otimes \End(V).
$$
Let $(\sum_i e_i \otimes f_i^P, u_1^P, \ldots, u_r^P)$ be a representative of $P \in A_n = U / \GL(V)$. Then the above composition is given by
$$
 \Big(\sum_{i=1}^{4} e_i \otimes f_i , u_1, \ldots, u_r \Big) \mapsto \sum_{i,j=1}^{4} e_i \wedge e_j \cdot (f^P_i \circ f_j - f_j \circ f^P_i).
$$
Recall that $\Lambda^\vee|_P  = (\langle e_4 \rangle \wedge \C^3)^\vee \otimes \End(V) \cong \Lambda^2 \C^3 \otimes \End(V)$, where $\C^3 = \langle e_1, e_2, e_3 \rangle \subset \C^4$, so the image of $T_{A_n}|_{P} \to  \Lambda^\vee|_{P}$ equals the image of 
\begin{align}
\begin{split} \label{impds}
\C^3 \otimes \End(V)  &\rightarrow  \Lambda^2 \C^3 \otimes \End(V) \\
 \sum_{i=1}^{3} e_i \otimes f_i  &\mapsto \sum_{i,j=1}^{3} e_i \wedge e_j \cdot (f^P_i \circ f_j - f_j \circ f^P_i).
\end{split}
\end{align}

Consider the projection $p \colon \C^4 \rightarrow \C^3$ onto the first three coordinates. Then the cohomology of $R \Hom(p_* Q, p_* Q)$ is computed by the cohomology of a ($\T'$-equivariant) complex of $\O_{\C^3}$-modules
$$
\End(V) \rightarrow \C^3 \otimes \End(V) \stackrel{\theta_1}{\rightarrow} \Lambda^2 \C^3 \otimes \End(V) \stackrel{\theta_2}{\rightarrow} \Lambda^3 \C^3 \otimes \End(V), 
$$
where the map $\theta_1$ coincides with \eqref{impds}. 

Let $\vec{\pi}$ be the $r$-tuple corresponding to $P = P_{\vec{\pi}}$. Furthermore, we write $Q = \bigoplus_\alpha \O_{Z_\alpha}$, where $Z_\alpha$ corresponds to a solid partition $\pi_\alpha$. Then
$$
\Ext^2(p_* Q, p_* Q)^f = \bigoplus_{\alpha=1}^{r} \Ext^2(p_* \O_{Z_\alpha}, p_* \O_{Z_\alpha})^f = 0,
$$
where the second equality follows from the lemma below. Therefore
\begin{align*}
\mathrm{coker}(\theta_1)^f \cong \Bigg( \frac{\Lambda^2 \C^3 \otimes \End(V)}{\ker(\theta_2)} \Bigg)^f \cong \mathrm{im}(\theta_2)^f,
\end{align*}
and
\begin{align*}
\dim \mathrm{im}(\theta_2)^f &= \dim (\Lambda^3 \C^3 \otimes \End(V))^f - \dim \Ext^3(p_* Q, p_* Q)^f \\
&=\sum_{\alpha=1}^{r} \Big\{ \dim (t_1^{-1}t_2^{-1}t_3^{-1} Z_\alpha^\vee Z_\alpha)^f - \dim \Ext^3(p_* \O_{Z_\alpha}, p_* \O_{Z_\alpha})^f \Big\}.
\end{align*}
By Lemma \ref{induct} and the lemma below, this equals
$$
\sum_{\alpha=1}^{r} (k_{\pi_\alpha} - \mu_{\pi_\alpha}) \pmod 2
$$
as desired. The proposition now follows from the definitions of $\mathsf{G}_r$ \eqref{defG}, $\mathsf{Z}_r^{\NP}$ \eqref{NPZ}, and Proposition \ref{globaltolocal}.
\end{proof}

\begin{lemma}
Denote by $p \colon \C^4 \rightarrow \C^3$ the projection onto the first three coordinates. For any $T_t$-fixed $0$-dimensional subscheme $Z \subset \C^4$ corresponding to a solid partition $\pi$ we have
\begin{align*}
&\dim \Hom(p_* \O_Z, p_* \O_Z)^f = |\{(i,i,i,j) \in \pi \, : \, j \geq i\}|, \\
&\dim \Ext^1(p_* \O_Z, p_* \O_Z)^f = \dim \Ext^2(p_* \O_Z, p_* \O_Z)^f  = 0, \\
&\dim \Ext^3(p_* \O_Z, p_* \O_Z)^f = |\{(i,i,i,j) \in \pi \, : \, j > i\}|. 
\end{align*}
\end{lemma}
\begin{proof}
Let $Z \subset Z' \subset \C^3$ be $T_t$-fixed 0-dimensional subschemes corresponding to \emph{plane} partitions $\pi,\pi'$ and let $(w_1,w_2,w_3) \in \Z^3$.\footnote{Recall that the torus $T_t \subset (\C^*)^4$ is defined by the relation $t_1t_2t_3t_4=1$. Projecting onto the first three coordinates $T_t \cong (\C^*)^3$, which acts in the standard way on $\C^3$.} We first establish the following basic building blocks
\begin{align*}
\Hom(\O_{Z'}, \O_Z \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3})^f &= \C, \quad \mathrm{if \ } (w_1,w_2,w_3) \in \pi \\
\Hom(\O_{Z'}, \O_Z \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3})^f &= 0, \quad \mathrm{if \ } (w_1,w_2,w_3) \notin \pi \\
\Ext^k(\O_{Z'}, \O_Z \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3})^f &= 0, \quad \mathrm{if \ } w_1,w_2,w_3 \geq 0, \, k>0 \\
\Ext^3(\O_{Z}, \O_{Z'} \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3})^f &= \C, \quad \mathrm{if \ } (-w_1-1,-w_2-1,-w_3-1) \in \pi \\ 
\Ext^3(\O_{Z}, \O_{Z'} \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3})^f &= 0, \quad \mathrm{if \ } (-w_1-1,-w_2-1,-w_3-1) \notin \pi \\ 
\Ext^k(\O_{Z}, \O_{Z'} \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3})^f &= 0, \quad \mathrm{if \ } w_1,w_2,w_3 \leq -1, \, k<3.
\end{align*}
The last three statements follow from the first three by using $(\C^*)^3$-equivariant Serre duality and $K_{\C^3} = \O_{\C^3} \otimes t_1t_2t_3$. For the first two statements, we use the short exact sequence
$0 \to I_{Z'} \to \O_{\C^3} \to \O_{Z'} \to 0$, which gives an exact sequence
\begin{align*}
0 \to \Hom(\O_{Z'},\O_Z  \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3}) &\to \Hom(\O_{\C^3},\O_Z  \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3}) \\
&\to \Hom(I_{Z'},\O_Z  \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3}).
\end{align*}
Since $Z \subset Z'$, the third map is zero and we obtain
$$
\Hom(\O_{Z'},\O_Z  \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3}) \cong \Hom(\O_{\C^3},\O_Z  \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3}),
$$
which has 1-dimensional fixed part if and only if $(w_1,w_2,w_3) \in \pi$ and 0-dimensional fixed part otherwise. For the third statement, we use the Taylor resolution \cite{Tay}
$$
0 \to R_t \to \cdots \to R_1 \to \O_{\C^3} \to \O_{Z'} \to 0,
$$
which is a $(\C^{*})^3$-equivariant resolution where each $R_i$ is a direct sum of $(\C^{*})^3$-equivariant line bundles $\O_{\C^3} \otimes t_1^{a_1}t_2^{a_2}t_3^{a_3}$ with $(a_1,a_2,a_3) \in \Z_{\geq 0}^3 \setminus \pi'$. For any such line bundle and $w_1,w_2,w_3 \geq 0$, we have 
$$
\Hom(\O_{\C^3} \otimes t_1^{a_1}t_2^{a_2}t_3^{a_3}, \O_Z \otimes t_1^{-w_1}t_2^{-w_2}t_3^{-w_3})^f =0,
$$
because $(a_1+w_1,a_2+w_2,a_3+w_3) \in \Z_{\geq 0}^3 \setminus \pi' \subset \Z_{\geq 0}^3 \setminus \pi$. This establishes the third statement.

To prove the lemma, we take $Z \subset \C^4$ a $T_t$-fixed $0$-dimensional subscheme corresponding to a \emph{solid} partition $\pi$. Then 
$$
p_* \O_Z = \bigoplus_{i \geq 0} \O_{Z_i} \otimes t_4^{i} = \bigoplus_{i \geq 0} \O_{Z_i} \otimes (t_1t_2t_3)^{-i},
$$
where $Z_0 \supset Z_1 \supset \cdots$ is a finite flag of $(\C^*)^3$-invariant 0-dimensional subschemes of $\C^3$. We denote the corresponding plane partitions by $\pi_0 \supset \pi_1 \supset \cdots$. For the first statement of the lemma, we consider
$$
\Hom(\O_{Z_i} \otimes (t_1t_2t_3)^{-i}, \O_{Z_j} \otimes (t_1t_2t_3)^{-j})^f.
$$
When $i \leq j$, this is 1-dimensional if and only if $(j-i,j-i,j-i) \in \pi_j$ and 0-dimensional otherwise. When $i > j$, this is 0-dimensional. The first statement of the lemma follows. For the second statement of the lemma, we note that for $k=1,2$ we have
$$
\Ext^k(\O_{Z_i}, \O_{Z_j} \otimes (t_1t_2t_3)^{i-j})^f = 0,
$$
for all $i,j$. For the final statement of the lemma, we consider
$$
\Ext^3(\O_{Z_i}, \O_{Z_j} \otimes (t_1t_2t_3)^{i-j})^f. 
$$
When $i \leq j$, this is 0-dimensional. When $i>j$, this is 1-dimensional if and only if $(i-j-1,i-j-1,i-j-1) \in \pi_i$ and 0-dimensional otherwise. The third statement of the lemma follows.
\end{proof}


\section{Limits} \label{sec:limits}

We have established equality of the following power series (Proposition \ref{signprop})
\begin{align*}
\mathsf{G}_{r} = \sum_{n=0}^{\infty} N_{r,n}^\glob \, q^n, \quad \mathsf{Z}_{r}^{\NP} = \sum_{\vec{\pi} = (\pi_1, \ldots, \pi_r)}  (-1)^{ \mu_{\vec{\pi}}} [ -\mathsf{v}_{\vec{\pi}} ]  \, ((-1)^{r} q)^{|\vec{\pi}|}.
\end{align*}
For $r=1$, combining with factorizability (Proposition \ref{Exp}) gives
$$
\mathsf{Z}_{1}^{\NP} = \mathrm{Exp}\Bigg(\frac{G_1}{[t_1][t_2][t_3][t_4]}\Bigg),
$$
for some $G_1 \in qK_0^{\T'}(\pt)[[q]]$. As we will show in this section, this is enough information to first determine $G_1$ and then complete the proof of the Nekrasov--Piazzalunga conjecture for all $r>0$.


\subsection{Rigidity and boundedness}

In this section, we consider $\mathsf{Z}_{1}^{\NP}$, i.e., $r=1$.  
From Section \ref{sec:vertex}, it is clear that $\mathsf{Z}_{1}^{\NP}$ is independent of $w:=w_1$ and we will write $y:=y_1$. 
We first proceed in a similar fashion to Okounkov's proof of Nekrasov's conjecture on $\C^3$ \cite[Sect.~3.5]{Oko}. The first result is the 4-fold analog of \cite[Sect.~3.5.8]{Oko} and \cite[Lem.~5]{MNOP2}.
\begin{proposition} \label{H}
There exists  $H_1 \in q K_0^{\T'}(\pt) [[q]]$ such that
\begin{align*}
\mathsf{Z}_{1}^{\NP} = \mathrm{Exp}\Bigg(\frac{[t_1t_2][t_1t_3][t_2t_3]H_1}{[t_1][t_2][t_3][t_4]}\Bigg).
\end{align*}
\end{proposition}
\begin{proof}
Let $\pi$ be a non-empty solid partition.
It suffices to show that, for all $1 \leq i < j \leq 3$, the numerator of $[-\mathsf{v}_{\pi}]$ is divisible by $t_i^n t_j^n-1$ for some $n>0$ (and no such terms appear in the denominator). By symmetry, we may take $i=1$ and $j=2$. We write
$$
\mathsf{v}_{\pi} = \sum_{i,j,k,l \in \Z} c^{\pi}_{ijkl} \, t_1^i t_2^j t_3^k y^l.
$$
Then the claim is equivalent to 
$$
\sum_{i \in \Z} c^{\pi}_{ii00} < 0.
$$
Let $t_1 = u$, $t_2 = u^{-1}$, and $t_3 = v$. We define coefficients $a_{ij}^{\pi}, b_{ijk}^{\pi}$ by
\begin{align*}
Z_\pi &=  \sum_{(i,j,k,l) \in \pi} t_1^i t_2^j t_3^k t_4^l = \sum_{(i,j,k,l) \in \pi} u^{i-j} v^{k-l} = \sum_{i,j \in \Z} a^{\pi}_{ij} \, u^i v^ j, \\ 
\mathsf{v}_{\pi} &= \sum_{i,j,k \in \Z} b^{\pi}_{ijk} \, u^i v^ j y^k,
\end{align*}
and we have to show $b^{\pi}_{000}<0$. Concretely
$$
a_{ij}^{\pi} = |\{(a+i,a,b+j,b) \in \pi \, : \, a,b \geq 0\}|.
$$

By the same calculation as in \cite[Lem.~5]{MNOP2}, we find
\begin{align*}
b^{\pi}_{000} &= a^{\pi}_{00} + \sum_{i,j \in \Z} \Big\{ (2a^{\pi}_{i,j+1}a^{\pi}_{ij} - a^{\pi}_{i,j+1}a^{\pi}_{i+1,j} - a^{\pi}_{i+1,j+1} a^{\pi}_{ij}) - (2(a^{\pi}_{ij})^2 - 2a^{\pi}_{ij} a^{\pi}_{i+1,j}) \Big\} \\
&= a^\pi_{00} - \frac{1}{2}\sum_{i,j \in \Z}(a_{ij}^\pi - a_{i+1,j}^\pi - a_{i,j+1}^\pi + a_{i+1,j+1}^\pi)^2.
\end{align*}
Now let $s(i,j) = 1$ if $i \ge 0$  and $j \ge 0$, or if $i<0$ and $j < 0$. Otherwise let $s(i,j) = -1$.
Then
\begin{align*}
\sum_{i,j \in \Z}(a_{ij}^\pi - a_{i+1,j}^\pi - a_{i,j+1}^\pi + a_{i+1,j+1}^\pi)^2 &\ge \sum_{i,j \in \Z}|a_{ij}^\pi - a_{i+1,j}^\pi - a_{i,j+1}^\pi + a_{i+1,j+1}^{\pi}| \\
&\ge \sum_{i,j \in \Z} s(i,j)(a_{ij}^\pi - a_{i+1,j}^\pi - a_{i,j+1}^\pi + a_{i+1,j+1}^{\pi}) \\
&= 4a^\pi_{00},
\end{align*}
since the sum over each quadrant $\{(i,j) : i,j \geq 0\}$, $\{(i,j) : i,j < 0\}$, $\{(i,j) : i \geq 0, j < 0\}$, $\{(i,j) : i < 0, j \geq 0\}$ in $\Z^2$ equals $a^\pi_{00}$.
Thus we get $b^{\pi}_{000} \le -a^{\pi}_{00} < 0$, since $\pi$ is non-empty.
