Our next result is the 4-fold analog of \cite[Prop.~3.5.11]{Oko}.
\begin{proposition} \label{tindep}
The class $H_1 \in q K_0^{\T'}(\pt) [[q]]$ is independent of $t_1,t_2,t_3$, i.e., only depends on $y$.
\end{proposition}
\begin{proof}
We expand $H_1$ in $q$ 
$$
H_1 = \sum_{n=1}^{\infty} H_{1,n}(t_1,t_2,t_3,y) \, q^n.
$$ 
We argue, by induction on $n$, that $H_{1,n}$ is independent of the $t_i$. For $n=1$, this is obvious by direct calculation. For $n>1$, expanding the plethystic exponential gives 
\begin{align} 
\begin{split} \label{nthterm}
N_{1,n}^\glob  = \frac{[t_1t_2][t_1t_3][t_2t_3]}{[t_1][t_2][t_3][t_4]} H_{1,n}(t_1,t_2,t_3,y) + C,
\end{split}
\end{align}
where $C$ is a polynomial combination of terms of the form
$$
\frac{[t_1^{\ell}t_2^{\ell}][t_1^{\ell}t_3^{\ell}][t_2^{\ell}t_3^{\ell}]}{[t_1^{\ell}][t_2^{\ell}][t_3^{\ell}][t_4^{\ell}]} H_{1,m}(y^{\ell}),
$$
for various $\ell \geq 1$ and $m<n$. Here we used the induction hypothesis to conclude that $H_{1,m}$ is independent of $t_1,t_2,t_3$. Since $H_{1,n}$ is (a priori) a Laurent polynomial in the variables $t_i^{\pm 1}$ and $y^{\pm \frac{1}{2}}$, it suffices to show that its limits for $t_i^{\pm 1} \to \infty$ exist, i.e.~$H_{1,n}$ is bounded as $t_i^{\pm 1} \to \infty$. This is known as \emph{Okounkov's rigidity principle}. 

Without loss of generality, let $i=1$. Clearly 
$$
 \frac{[t_1^{\ell}t_2^{\ell}][t_1^{\ell}t_3^{\ell}][t_2^{\ell}t_3^{\ell}]}{[t_1^{\ell}][t_2^{\ell}][t_3^{\ell}][t_4^{\ell}]} =  \frac{[t_1^{\ell}t_2^{\ell}][t_1^{\ell}t_3^{\ell}][t_2^{\ell}t_3^{\ell}]}{[t_1^{\ell}][t_2^{\ell}][t_3^{\ell}][(t_1t_2t_3)^{-\ell}]} 
$$
is bounded as $t_1^{\pm 1} \to \infty$. By the lemma below, the left hand side of \eqref{nthterm} is also bounded as $t_1^{\pm 1} \to \infty$. The result follows.
\end{proof}

\begin{lemma}
Let $i=1,2,3$. The limit
$$
\lim_{t_i^{\pm 1} \to \infty} N_{1,n}^\glob
$$
exists, i.e., $N_{1,n}^\glob$ is bounded as $t_i^{\pm 1} \to \infty$.
\end{lemma}
\begin{proof}
Without loss of generality, we consider the $i=1$ case. 
Let $\pi$ be a solid partition of size $n$. We consider the Laurent monomials $t_1^{i_1}t_2^{i_2}t_3^{i_3} y^j$ appearing in $\mathsf{v}_{\pi}$ (where $t_4$ is eliminated by $t_4 = (t_1t_2t_3)^{-1}$). 
It is known that $\mathsf{v}_{\pi}$ has no fixed terms by \cite[Sect.~2.4.1]{NP}.
We also note that the class $\mathsf{v}_{\pi}$ has rank zero (Definition \ref{def:NPweight}). 

For any Laurent monomial $t_1^{i_1}t_2^{i_2}t_3^{i_3} \neq 1$ appearing in $Z$, there is a corresponding term $- y t_1^{-i_1}t_2^{-i_2}t_3^{-i_3}$ in $- y Z^\vee$.
Taken together, their contribution to $[-\mathsf{v}_{\pi}]$ is
$$
\frac{    t_1^{-\frac{i_1}{2}} t_2^{-\frac{i_2}{2}} t_3^{-\frac{i_3}{2}}  y^{\frac{1}{2}} - t_1^{\frac{i_1}{2}} t_2^{\frac{i_2}{2}} t_3^{\frac{i_3}{2}}  y^{-\frac{1}{2}}   }{ t_1^{\frac{i_1}{2}} t_2^{\frac{i_2}{2}} t_3^{\frac{i_3}{2}}  - t_1^{-\frac{i_1}{2}} t_2^{-\frac{i_2}{2}} t_3^{-\frac{i_3}{2}}   }.
$$
As $t_1^{\pm 1} \to \infty$, either $i_1=0$ and this is constant, or $i_1 \neq 0$ and this is $-y^{\pm \frac{1}{2}}$. 

Consider a Laurent monomial $t_1^{i_1}t_2^{i_2}t_3^{i_3}$ appearing in $Z Z^\vee$.
Suppose, after multiplying $t_1^{i_1}t_2^{i_2}t_3^{i_3}$ by $(1-t_1^{-1})(1-t_2^{-1})(1-t_3^{-1})$, there are no $T_t$-fixed terms.
Then its contribution to $\mathsf{v}_{\pi}$ is
\begin{align*}
&\frac{   (t_1^{\frac{i_1}{2}} t_2^{\frac{i_2}{2}} t_3^{\frac{i_3}{2}}  -   t_1^{-\frac{i_1}{2}} t_2^{-\frac{i_2}{2}} t_3^{-\frac{i_3}{2}}  )    (t_1^{\frac{i_1-1}{2}} t_2^{\frac{i_2-1}{2}} t_3^{\frac{i_3}{2}}  - t_1^{-\frac{i_1-1}{2}} t_2^{-\frac{i_2-1}{2}} t_3^{-\frac{i_3}{2}} ) }{ (t_1^{\frac{i_1-1}{2}} t_2^{\frac{i_2}{2}} t_3^{\frac{i_3}{2}}  -   t_1^{-\frac{i_1-1}{2}} t_2^{-\frac{i_2}{2}} t_3^{-\frac{i_3}{2}}  )   (t_1^{\frac{i_1}{2}} t_2^{\frac{i_2-1}{2}} t_3^{\frac{i_3}{2}}  -   t_1^{-\frac{i_1}{2}} t_2^{-\frac{i_2-1}{2}} t_3^{-\frac{i_3}{2}}  )      } \\
&\times \frac{     (t_1^{\frac{i_1-1}{2}} t_2^{\frac{i_2}{2}} t_3^{\frac{i_3-1}{2}}  - t_1^{-\frac{i_1-1}{2}} t_2^{-\frac{i_2}{2}} t_3^{-\frac{i_3-1}{2}} )        (t_1^{\frac{i_1}{2}} t_2^{\frac{i_2-1}{2}} t_3^{\frac{i_3-1}{2}}  - t_1^{-\frac{i_1}{2}} t_2^{-\frac{i_2-1}{2}} t_3^{-\frac{i_3-1}{2}} )}{  (t_1^{\frac{i_1}{2}} t_2^{\frac{i_2}{2}} t_3^{\frac{i_3-1}{2}}  -   t_1^{-\frac{i_1}{2}} t_2^{-\frac{i_2}{2}} t_3^{-\frac{i_3-1}{2}}  )   (t_1^{\frac{i_1-1}{2}} t_2^{\frac{i_2-1}{2}} t_3^{\frac{i_3-1}{2}}  -   t_1^{-\frac{i_1-1}{2}} t_2^{-\frac{i_2-1}{2}} t_3^{-\frac{i_3-1}{2}}  )     }.
\end{align*}
The terms involving $t_1^{\pm \frac{i_1}{2}}$ (respectively $t_1^{\pm \frac{i_1-1}{2}}$) in the numerator and denominator come in pairs so this product is bounded for $t_1^{\pm 1} \to \infty$ as well. Since the $T_t$-fixed terms of  $(1-t_1^{-1})(1-t_2^{-1})(1-t_3^{-1})Z^\vee Z$ cancel the $T_t$-fixed term of $Z$, the result follows. 
\end{proof}


\subsection{Rank one} \label{sec:rk1}

We start with the following observation, which is a special case of \cite[Prop.~2.1]{CKM} (which also deals with subschemes of dimension 1). For completeness, we include the proof.
\begin{proposition} \label{dimred}
Let $Z \subset \C^4$ be a $T_t$-fixed 0-dimensional subscheme corresponding to a solid partition $\pi$. Then 
$[-\mathsf{v}_\pi] |_{y=t_4} = 0$ unless $Z \subset \C^3 = \{x_4=0\}$. For $Z \subset \C^3 = \{x_4=0\}$, $\mathsf{v}_\pi |_{y=t_4}$ is identical to the (fully equivariant) Donaldson--Thomas vertex $\mathsf{V}_{\pi}^{\mathrm{DT}}$ in \cite[Sect.~4.7]{MNOP1}. In particular
$$
\mathsf{Z}_1^{\NP} |_{y=t_4} = \sum_{n=0}^{\infty} \chi(\Hilb^n(\C^3), \widehat{\O}^{\vir}) \, (-q)^n.
$$
\end{proposition}
\begin{proof}
For $Z \subset \{x_4=0\}$, the statement follows at once by comparing Definition \ref{def:NPweight} to \cite[Sect.~4.7]{MNOP1}. 
Suppose $Z$ is not scheme theoretically supported in $\{x_4=0\}$. The vertex $\mathsf{v}_{\pi}$ does not have a $T_t$-fixed part by \cite[Sect.~2.4.1]{NP}. Therefore, it suffices to consider the $T_t$-fixed terms arising from setting $y=t_4 = (t_1t_2t_3)^{-1}$ in the $y$-dependent part of $\mathsf{v}_{\pi}$, i.e.~$-y Z^\vee$. Since $Z$ contains the term $t_4$, setting $y=t_4$, it contributes $-yt_4^{-1}=-1$, so $\mathsf{v}_\pi |_{y=t_4} = 0$.

The 0-dimensional $(\C^*)^3$-fixed subschemes $Z \subset \C^3$ correspond to \emph{plane} partitions $\pi$. By \cite[Sect.~3]{Oko}, we have
$$
\sum_{n=0}^{\infty} \chi(\Hilb^n(\C^3), \widehat{\O}^{\vir}) \, q^n = \sum_{\pi} [-\mathsf{V}_{\pi}^{\mathrm{DT}}] \, q^{|\pi|}.
$$
The result of the proposition follows by noting that $(-1)^{n + \mu_\pi} = (-1)^n$ for all plane partitions $\pi$ (Propositions \ref{globaltolocal} and \ref{signprop}).
\end{proof}

The proof of Theorem \ref{mainthm} for $r=1$ can now be completed as follows. 
\begin{proof}[Proof of Theorem \ref{mainthm} for $r=1$]
By Propositions \ref{H} and \ref{tindep}, taking plethystic log yields
$$
H_1(y) = \frac{[t_1][t_2][t_3][t_4]}{[t_1t_2][t_1t_3][t_2t_3]} \, \mathrm{Log}\big(\mathsf{Z}_1^{\NP} \big),
$$
where we stress that $H_1(y)$ only depends on $y:=y_1$ and the formal variable $q$. By Proposition \ref{dimred} and Okounkov's Theorem \ref{Okounkovthm} 
$$
 \mathrm{Log} \big( \mathsf{Z}_1^{\NP} \big) \Big|_{y=t_4} = \frac{[t_1t_2][t_1t_3][t_2t_3]}{[t_1][t_2][t_3][\kappa^{\frac{1}{2}} q ]   [\kappa^{\frac{1}{2}} q^{-1} ]},
$$
where $\kappa = t_1t_2t_3 = t_4^{-1}$. Hence 
$$
H_1(t_4) = \frac{[t_4]}{ [t_4^{-\frac{1}{2}} q ]   [t_4^{-\frac{1}{2}} q^{-1} ] } = \frac{[t_4]}{[t_4^{\frac{1}{2}} q ]   [t_4^{\frac{1}{2}} q^{-1} ] },
$$
and the proof is complete.
\end{proof}


\subsection{Higher rank} \label{sec:higherrk}

In this section, we complete the proof of Theorem \ref{mainthm} for $r>1$. It will follow from showing independence of the framing parameters $w_1, \ldots, w_r$ and reducing to the $r=1$ case. We learned this strategy from \cite{FMR}. The rank reduction in this section does not require factorizability.
We start with the following analog of \cite[Lem.~6.7]{FMR}. Recall the definition of $\mathsf{v}_{\vec{\pi},\alpha\beta}$ from Definition \ref{def:NPweight}.
\begin{proposition} \label{offdiag}
Let $\vec{\pi} = (\pi_1, \ldots, \pi_r)$ be an $r$-tuple of solid partitions. For any $\alpha < \beta$, we have
$$
\lim_{L \rightarrow \infty} [-\mathsf{v}_{\vec{\pi},\alpha\beta}] [-\mathsf{v}_{\vec{\pi},\beta\alpha}]\Big|_{(w_1 = L, w_2 = L^2, \ldots, w_r = L^r)} = \frac{(-y_\beta^{\frac{1}{2}})^{|\pi_\alpha|}}{(-y_\alpha^{\frac{1}{2}})^{|\pi_\beta|}}.
$$
\end{proposition}
\begin{proof}
Eliminating $t_4 = (t_1t_2t_3)^{-1}$, we write
\begin{align*}
Z_\alpha = \sum_{(i_1,i_2,i_3)} t_1^{i_1}t_2^{i_2}t_3^{i_3}, \quad Z_\beta = \sum_{(j_1,j_2,j_3)} t_1^{j_1}t_2^{j_2}t_3^{j_3},
\end{align*}
for certain finite sums with possibly repeated terms. The first sum has $|\pi_\alpha|$ terms and the second has $|\pi_\beta|$ terms. For any monomial $\pm w_\beta w_\alpha^{-1} t_1^{k_1} t_2^{k_2} t_3^{k_3}$ appearing in $-\mathsf{v}_{\vec{\pi},\alpha\beta}$, we have
$$
[\pm w_\beta w_\alpha^{-1} t_1^{k_1} t_2^{k_2} t_3^{k_3}] = \Big( (L^{\beta-\alpha} t_1^{k_1} t_2^{k_2} t_3^{k_3})^{\frac{1}{2}}(1-(L^{\beta-\alpha} t_1^{k_1} t_2^{k_2} t_3^{k_3})^{-1}) \Big)^{\pm 1}, \quad \beta - \alpha>0.
$$
In the limit $L \to \infty$, the contributions from $Z_\alpha^\vee Z_\beta$ to $[-\mathsf{v}_{\vec{\pi},\alpha\beta}]$ cancel and contribute 1 (and similarly for $Z_\beta^\vee Z_\alpha$ and $[-\mathsf{v}_{\vec{\pi},\beta\alpha}]$). Therefore, the desired limit equals the limit of $L \to \infty$ of
$$
\Bigg\{ L^{\frac{\beta-\alpha}{2}( - |\pi_\beta| + |\pi_\alpha|) } \frac{\prod_{(i_1,i_2,i_3)}  t_1^{-\frac{i_1}{2}}t_2^{-\frac{i_2}{2}}t_3^{-\frac{i_3}{2}} y_\beta^{\frac{1}{2}}}{\prod_{(j_1,j_2,j_3)}  t_1^{\frac{j_1}{2}}t_2^{\frac{j_2}{2}}t_3^{\frac{j_3}{2}}} \Bigg\}    \Bigg\{  (-1)^{|\pi_\alpha| + |\pi_\beta|} L^{\frac{\beta-\alpha}{2}( |\pi_\beta| - |\pi_\alpha|) } \frac{\prod_{(j_1,j_2,j_3)}  t_1^{\frac{j_1}{2}}t_2^{\frac{j_2}{2}}t_3^{\frac{j_3}{2}} y_\alpha^{-\frac{1}{2}}}{\prod_{(i_1,i_2,i_3)}  t_1^{-\frac{i_1}{2}}t_2^{-\frac{i_2}{2}}t_3^{-\frac{i_3}{2}}} \Bigg\},
$$
which gives the answer.
\end{proof}

\begin{proposition} \label{windep}
The generating series $\sfZ_r^{\NP}$ is independent of $w_1, \ldots, w_r$.
\end{proposition}
\begin{proof}
We endow $\Sym^n(\C^4)$ with the trivial $(T_w \times \widetilde{T}_y)$-action. Then the Quot-Chow morphism \cite[Cor.~7.15]{Ryd}
$$
\nu_n \colon \Quot_r^n(\C^4) \to \Sym^n(\C^4)
$$
is proper, $\T'$-equivariant, and we have
\begin{align} \label{pushtoChow}
N_{r,n}^\glob = \chi( \Sym^n(\C^4), R \nu_{n*}(\cN_{r,n}^\glob)). 
\end{align}
Since $\Sym^n(\C^4)$ has a trivial $T_w$-action, the class
$$
R \nu_{n*}(\cN_{r,n}^\glob) \in K_0^{\T'}(\Sym^n(\C^4))
$$
is a finite sum 
$$
\sum_{(i_1, \ldots, i_r)} V_{i_1, \ldots, i_r} \, w_1^{i_1} \cdots w_r^{i_r}, \quad V_{i_1, \ldots, i_r} \in K_0^{T_t \times \widetilde{T}_y}(\Sym^n(\C^4)).
$$
Hence, the right hand side of \eqref{pushtoChow} is a \emph{Laurent polynomial} in the variables $w_i$.

By Proposition \ref{offdiag}, we know that \eqref{pushtoChow} is bounded for 
$$
(w_1, \ldots, w_r) = (L, \ldots, L^r), \quad \textrm{as \ } L \to \infty.
$$ 
The proof of Proposition \ref{offdiag} also shows that, for any choice of $0 < n_1 < \cdots < n_r$, we have that \eqref{pushtoChow} is bounded for 
$$
(w_1, \ldots, w_r) = (L^{n_1}, \ldots, L^{n_r}), \quad L^{\pm 1} \to \infty.
$$
Therefore \eqref{pushtoChow} is independent of the $w_i$.
\end{proof}

Before we finish the proof of Theorem \ref{mainthm}, we note the following identity 
\begin{equation} \label{funid}
\frac{[a]}{[a^{\frac{1}{2}} b^{\frac{1}{2}} c] [a^{\frac{1}{2}} b^{-\frac{1}{2}} c^{-1}]} + \frac{[b]}{[a^{-\frac{1}{2}} b^{\frac{1}{2}} c] [a^{\frac{1}{2}} b^{\frac{1}{2}} c^{-1}]} = \frac{[ab]}{[(ab)^{\frac{1}{2}} c] [(ab)^{\frac{1}{2}} c^{-1}]}.
\end{equation}

\begin{proof}[Proof of Theorem \ref{mainthm} for $r>1$]
By Propositions \ref{globaltolocal} and \ref{signprop}, we have
$$
\sfZ_r^{\NP} = \sum_{\vec{\pi} = (\pi_1, \ldots, \pi_r)} ((-1)^{r}q)^{|\vec{\pi}|} (-1)^{\mu_{\vec{\pi}}} \prod_{\alpha=1}^{r} [-\mathsf{v}_{\vec{\pi},\alpha \alpha}] \cdot \prod_{1 \leq \alpha < \beta \leq r} [-\mathsf{v}_{\vec{\pi},\alpha\beta}] [-\mathsf{v}_{\vec{\pi},\beta\alpha}].
$$
By Proposition \ref{windep}, we may specialize $(w_1 = L, w_2 = L^2, \ldots, w_r = L^r)$ and take the limit $L \to \infty$. Consider the rank 1 generating series
$$
\sfZ_1^{\NP} = \sfZ_1^{\NP}(t_1,t_2,t_3,y,q),
$$
and recall that we proved the rank 1 case of Theorem \ref{mainthm} in Section \ref{sec:rk1}. Using Proposition \ref{offdiag}, we obtain
\begin{align*}
\sfZ_r^{\NP} &=\sum_{\vec{\pi} = (\pi_1, \ldots, \pi_r)} ((-1)^{r}q)^{|\vec{\pi}|}  \cdot \prod_{\alpha=1}^{r} (-1)^{\mu_{\pi_\alpha}} [-\mathsf{v}_{\pi_\alpha}] \cdot \prod_{1 \leq \alpha < \beta \leq r}\frac{(-y_\beta^{\frac{1}{2}})^{|\pi_\alpha|}}{(-y_\alpha^{\frac{1}{2}})^{|\pi_\beta|}} \\
&= \prod_{\alpha=1}^{r} \sfZ_1^{\NP}\big( t_1,t_2,t_3,y_\alpha,q \prod_{\beta \neq \alpha} y_\beta^{\frac{1}{2} \mathrm{sgn}(\beta-\alpha)} \big).
\end{align*}
Now write $\sfZ_r^{\NP} = \mathrm{Exp}(\cdots)$ and consider the exponent, i.e.,
\begin{equation} \label{eqn:summingExp}
\frac{[t_1t_2][t_1t_3][t_2t_3]}{[t_1][t_2][t_3][t_4]  } \sum_{\alpha = 1}^{r} \frac{[y]}{[y^{\frac{1}{2}} q ]   [y^{\frac{1}{2}} q^{-1} ] } \Bigg|_{\big(  y_\alpha, q \prod_{\beta \neq \alpha} y_\beta^{\frac{1}{2} \mathrm{sgn}(\beta-\alpha)} \big)}.
\end{equation}
Next, we apply \eqref{funid} to $a= y_1$, $b = y_2$, $c =  y_3 \cdots y_r q$. We deduce that the first two terms of the sum in \eqref{eqn:summingExp} add up to
$$
 \frac{[y_1 y_2]}{[(y_1 y_2)^{\frac{1}{2}} (y_3 \cdots y_r)^{\frac{1}{2}}  q] [(y_1 y_2)^{\frac{1}{2}} (y_3 \cdots y_r)^{-\frac{1}{2}}  q^{-1}]}.
$$
Subsequently, we apply \eqref{funid} to $a=y_1y_2$, $b=y_3$, $c = y_4 \cdots y_r q$. We find that the first three terms of the sum in \eqref{eqn:summingExp} add up to
$$
\frac{[y_1y_2y_3]}{[(y_1y_2y_3)^{\frac{1}{2}} (y_4 \cdots y_r)^{\frac{1}{2}}  q] [(y_1y_2y_3)^{\frac{1}{2}} (y_4 \cdots y_r)^{-\frac{1}{2}}  q^{-1}]}.
$$
Repeating this procedure $r-1$ times, we arrive at the desired result
\begin{equation*}
\frac{[y]}{[y^{\frac{1}{2}} q] [y^{\frac{1}{2}} q^{-1}]}, \quad y:=y_1 \cdots y_r. \qedhere
\end{equation*}
\end{proof}

We end by remarking that the Magnificent Four formula from Theorem \ref{mainthm} reduces to the Awata--Kanno conjecture and the generating function of so-called tetrahedron invariants.
\begin{remark} \label{FMRrmk}
The analog of Proposition \ref{dimred} is obviously true in the higher rank case as well. If a $\T'$-fixed quotient $[\O_{\C^4}^{\oplus r} \twoheadrightarrow Q]$ corresponding to $\vec{\pi} = (\pi_1, \ldots, \pi_r)$ does \emph{not} factor through $\iota_* \O_{\C^3}^{\oplus r}$, where $\iota \colon \C^3 = \{x_4=0\} \hookrightarrow \C^4$ denotes the inclusion, then 
$$
[-\mathsf{v}_{\vec{\pi}}] \big|_{y_1 = \cdots = y_r = t_4} = 0.
$$
If it does factor, i.e.~each $\pi_\alpha$ is a plane partition, then $[-\mathsf{v}_{\vec{\pi}}] |_{y_1 = \cdots = y_r = t_4}$ is identical to the (fully equivariant) vertex of \cite{FMR}. Furthermore, for any $\vec{\pi} = (\pi_1, \ldots, \pi_r)$, where each $\pi_\alpha$ is a plane partition, we have
$$
(-1)^{|\vec{\pi}| + \mu_{\vec{\pi}}} = (-1)^{|\vec{\pi}|}.
$$
Therefore, we deduce the Awata--Kanno conjecture (Theorem \ref{FMRthm}), previously proved in \cite{FMR, AK1}:
$$
\sum_{n=0}^{\infty} \chi(\Quot^{n}_{r}(\C^3), \widehat{\O}^{\vir}) \, ((-1)^r q)^n = \sfZ_r^{\NP} \Big|_{(y_1 = \cdots = y_r = t_4)} = \mathrm{Exp}\Bigg(\frac{[t_1t_2][t_1t_3][t_2t_3][\kappa^r]}{[t_1][t_2][t_3][\kappa][\kappa^{\frac{r}{2}} q ]   [\kappa^{\frac{r}{2}} q^{-1} ]}\Bigg),
$$
where $\kappa = t_1t_2t_3 = t_4^{-1}$.
\end{remark}

\begin{remark}
Consider the singular 3-fold $$\Delta = \{x_1x_2x_3x_4 = 0\} = \bigcup_{i=1}^4 \C_i^3 \subset \C^4, \quad \quad \mathcal{E}_{\vec{r}} := \bigoplus_{i=1}^{4} \O_{\C_i^3}^{\oplus r_i},$$ where $\C_i^3 = \{x_i = 0\}$ and $\vec{r} = (r_1, r_2, r_3, r_4)$ are non-negative integers.  Based on the physics literature \cite{PYZ}, in \cite{FM}, the authors study so-called tetrahedron invariants. These are defined by an Oh--Thomas class of the Quot scheme $\Quot_{\Delta}^n(\mathcal{E}_{\vec{r}})$ parametrizing 0-dimensional quotients of length $n$ of $\mathcal{E}_{\vec{r}}$. 
In fact, for $r = \sum_i r_i$, $\Quot_{\Delta}^n(\mathcal{E}_{\vec{r}}) \subset \Quot_r^n(\C^4)$ is naturally a closed subscheme. Specializing $y_1 = \cdots = y_{r_1} = t_1$, $ y_{r_1+1} = \cdots = y_{r_1+r_2} = t_2$, $\ldots$, the generating function of Theorem \ref{mainthm} reduces to the one for tetrahedron invariants obtained in \cite{FM}. The fact that Theorem \ref{mainthm} implies the formula for the generating series of tetrahedron invariants follows from the results in \cite[App.~A]{FM} (which partially relies on the sign analysis of this paper). It is worth stressing that the proof of the formula for the tetrahedron generating function in \cite{FM} does \emph{not} require the factorizability results of this paper. 
\end{remark}

