 $Z_1$ & \makecell[r]{Misclass. Predictor} & \textsf{ethnicity} & \makecell[r]{Indicator variable; \\ 0 = Non-Hispanic white, \\ 1 = Hispanic} \\[.75cm]
 $Z_2$ & \makecell[r]{Misclass. Predictor} & \textsf{self\_pay} & \makecell[r]{Indicator variable; \\ 0 = Private ins. or Medicaid, \\ 1 = Self-Pay} \\[.75cm]
 $Z_3$ & \makecell[r]{Misclass. Predictor} & \textsf{prenatal\_m} & \makecell[r]{Continuous variable; \\ Month of pregnancy when prenatal care began}\\[.5cm]

\hline 
\end{tabular}
\end{threeparttable}
\end{table}

Table \ref{COMMA-vars-table} lists the variables of interest in this analysis. Using these variables, our goal is to fit the following model using the provided sample data. The \textit{true mediator mechanism} is defined as:
\begin{equation}
\begin{aligned}
\label{eq:COMMA-ex-true-mech}
\logit\{ P(M = 1 | X, \boldsymbol{C} ; \boldsymbol{\beta}) \} =& \beta_{0} + \beta_{1} \textsf{ethnicity} + \beta_{2} \textsf{age\_cs} + \beta_{3} \textsf{pre\_hyp} + \beta_{4} \textsf{bmi\_cs} + \beta_{5} \textsf{cig\_use} +\\
&\beta_{6} \textsf{prenatal\_m} + \beta_{7} \textsf{pre\_diab} + \beta_{8} \textsf{g\_diab}.
\end{aligned}
\end{equation}

For the \textit{observed mediator mechanisms}, we fit the following models:
\begin{equation}
\begin{aligned}
\label{eq:COMMA-ex-obs-mech}
\logit\{ P(\textsf{g\_hyp} = 1 | M = 1, \boldsymbol{Z} ; \boldsymbol{\gamma}) \} =& \gamma_{11} + \gamma_{21} \textsf{ethnicity} + \gamma_{31} \textsf{self\-pay} + \gamma_{41} \textsf{prenatal\_m}, \\
\logit\{ P(\textsf{g\_hyp} = 1 | M = 2, \boldsymbol{Z} ; \boldsymbol{\gamma}) \} =& \gamma_{12} + \gamma_{22} \textsf{ethnicity} + \gamma_{32} \textsf{self\-pay} + \gamma_{42} \textsf{prenatal\_m}.
\end{aligned}
\end{equation}

Finally, we consider the following \textit{outcome mechanism}:
\begin{equation}
\begin{aligned}
\label{eq:COMMA-ex-out-mech}
E(\textsf{birth\_wt} | X, \boldsymbol{C}, M; \boldsymbol{\theta}) =& \theta_{0} + \theta_{x1} \textsf{ethnicity} + \theta_{c1} \textsf{age\_cs} + \theta_{c2} \textsf{pre\_hyp} + \theta_{c3} \textsf{bmi\_cs} + \\ &\theta_{c4} \textsf{cig\_use} +
\theta_{c5} \textsf{prenatal\_m} + \theta_{c6} \textsf{pre\_diab} + \theta_{c7} \textsf{g\_diab} +\\ & \theta_m M + \theta_{xm} (\textsf{ethnicity} \times M).
\end{aligned}
\end{equation}

Before fitting these models using \textbf{COMMA}, we restructure our observed data by converting the coding of the \texttt{g\_hyp} variable and creating matrices containing $X$, $C$, and $Z$. 
\begin{lstlisting}
R> bw_mstar <- matrix(ifelse(NCHS2022_sample$g_hyp == 1, 1, 2),
R>                    ncol = 1)
R> bw_mstar_01 <- NCHS2022_sample$g_hyp
R> bw_z <- matrix(c(NCHS2022_sample$ethnicity,
R>                  NCHS2022_sample$self_pay,
R>                  NCHS2022_sample$prenatal_m),
R>                nrow = nrow(NCHS2022_sample), byrow = FALSE)
R> bw_x <- matrix(NCHS2022_sample$ethnicity, ncol = 1)
R> bw_c <- matrix(c(NCHS2022_sample$age_cs,
R>                  NCHS2022_sample$pre_hyp,
R>                  NCHS2022_sample$bmi_cs,
R>                  NCHS2022_sample$cig_use,
R>                  NCHS2022_sample$prenatal_m,
R>                  NCHS2022_sample$pre_diab,
R>                  NCHS2022_sample$g_diab),
R>                nrow = nrow(NCHS2022_sample), byrow = FALSE)
R> bw_y <- NCHS2022_sample$birth_wt
\end{lstlisting}
The proposed approaches require starting values for the parameters. We start all $\boldsymbol{\gamma}$ parameters at 0 and run regression models that assume no misclassification in $M^*$ to obtain starting values for $\boldsymbol{\beta}$ and $\boldsymbol{\theta}$.
\begin{lstlisting}
R> bw_beta_glm <- glm(bw_mstar_01 ~ bw_x + bw_c, 
R>                    family = "binomial"(link = "logit"))
R> bw_beta_start <- matrix(unname(coef(bw_beta_glm)), ncol = 1)
R> bw_gamma_start <- matrix(rep(0, 8), ncol = 2)
R> bw_theta_lm <- lm(bw_y ~ bw_x + bw_mstar_01 + bw_c + bw_x:bw_mstar_01)
R> bw_theta_start <- matrix(unname(coef(bw_theta_lm)))
\end{lstlisting}

First, we estimate model parameters using our proposed EM algorithm in the \texttt{COMMA\_EM} function.
\begin{lstlisting}
