R>                   outcome = bw_y,
R>                   outcome_distribution = "Normal",
R>                   interaction_indicator = TRUE,
R>                   x_matrix = bw_x,
R>                   z_matrix = bw_z,
R>                   c_matrix = bw_c,
R>                   beta_start = bw_beta_start,
R>                   gamma_start = bw_gamma_start,
R>                   theta_start = bw_theta_start,
R>                   sigma_start = sigma(bw_theta_lm),
R>                   tolerance = 1e-7,
R>                   max_em_iterations = 1500,
R>                   em_method = "squarem")
