R>                    outcome = lbw_y,
R>                    outcome_distribution = "Bernoulli",
R>                    interaction_indicator = TRUE,
R>                    x_matrix = bw_x,
R>                    z_matrix = bw_z,
R>                    c_matrix = bw_c,
R>                    beta_start = lbw_beta_start,
R>                    gamma_start = lbw_gamma_start,
R>                    theta_start = lbw_theta_start,
R>                    tolerance = 1e-7,
