R> normal_sd_beta <- matrix(c(10, 10, 10, 10, 10, NA, NA, NA, NA, NA),
R>                          nrow = 2, byrow = TRUE)
R> normal_mu_gamma1 <- array(data = c(0, NA, 0, NA, 0, NA, 0, NA),
