R>                           dim = c(2,2,2))
R> normal_mu_gamma2 <- array(rep(c(0, NA), 8), dim = c(2,2,2,2))
R> normal_sd_gamma2 <- array(rep(c(10, NA), 8), dim = c(2,2,2,2))
R> beta_prior_parameters <- list(mu = normal_mu_beta,
R>                               sigma = normal_sd_beta)
R> gamma1_prior_parameters <- list(mu = normal_mu_gamma1,
R>                                 sigma = normal_sd_gamma1)
R> gamma2_prior_parameters <- list(mu = normal_mu_gamma2,
