R> 7 naive_gamma2[1,1,2]         6.28             6.37  
R> 8 naive_gamma2[1,2,1]         0.0139           0.0103
R> 9 naive_gamma2[1,2,2]         0.0664           0.0559
\end{lstlisting}

Our goal is to evaluate the predictive accuracy of our misclassification model for pretrial failure to VPRAI recommendations. We evaluate these risk assessments through a receiver operating curve (ROC) analysis. For this analysis, we first use the $\boldsymbol{\beta}$ estimates from the EM algorithm to compute bias-corrected pretrial failure probabilities for all observations in the dataset. 

\begin{lstlisting}
R> beta_estimates <- matrix(vprai_EM$Estimates[1:5], ncol = 1)
R> p_pretrial_failure <- true_classification_prob(beta_estimates,
R>                                                x)
R> VPRAI_synthetic_data$p_pretrial_failure <- 
R>    p_pretrial_failure$Probability[which(p_pretrial_failure$Y == 1)]
\end{lstlisting}

Because we do not have ``ground truth'' pretrial failure outcomes for every individual in the dataset, we follow the misclassification-adjusted ROC analysis procedure from \cite{zawistowski2017corrected}. This procedure requires estimates of the conditional predictive probability of pretrial failure for each subject. We estimate these probabilities using an internal \textbf{COMBO} function. 
\begin{lstlisting}
R> Ystar1_matrix <- matrix(c(Ystar1_01, 1 - Ystar1_01),
R>                         ncol = 2, byrow = FALSE)
R> Ystar2_matrix <- matrix(c(Ystar2_01, 1 - Ystar2_01),
R>                         ncol = 2, byrow = FALSE)
R> X_design <- matrix(c(rep(1, nrow(x)), c(x)),
R>                    nrow = nrow(x), byrow = FALSE)
R> pi_matrix <- COMBO:::pi_compute(beta_estimates, X_design, 
R>                                 nrow(X_design), 2)
R> Z1_design <- matrix(c(rep(1, nrow(z1)), c(z1)),
R>                     ncol = 2, byrow = FALSE)
R> gamma1_estimates <- matrix(vprai_EM$Estimates[6:9],
R>                            ncol = 2, byrow = FALSE)
R> pistar1_matrix <- COMBO:::pistar_compute(gamma1_estimates, Z1_design,
R>                                          nrow(Z1_design), 2)
R> Z2_design <- matrix(c(rep(1, nrow(z2)), c(z2)),
R>                     ncol = 2, byrow = FALSE)
R> gamma2_estimates <- array(vprai_EM$Estimates[10:17], dim = c(2,2,2))
R> pistar2_array <- COMBO:::pitilde_compute(gamma2_estimates, Z2_design,
R>                                          nrow(Z2_design), 2)
R> predictive_prob_pf <- COMBO:::w_j_2stage(Ystar1_matrix,
R>                                          Ystar2_matrix,
R>                                          pistar2_array,
R>                                          pistar1_matrix,
R>                                          pi_matrix, 
R>                                          nrow(Ystar1_matrix), 2)
R> VPRAI_synthetic_data$predictive_prob_pf <- predictive_prob_pf[,1]
\end{lstlisting}

The resulting probabilities are used to compute misclassification-adjusted true positive rate (TPR) and false positive rate (FPR) estimates \citep{zawistowski2017corrected}. We use these rates to construct an ROC curve and estimate the area under the curve (AUC). 

\begin{lstlisting}
R> cutoffs <- seq(0, 1, by = .01)
R> bias_corrected_TPR <- rep(NA, length(cutoffs))
R> bias_corrected_FPR <- rep(NA, length(cutoffs))
R> for(i in 1:length(cutoffs)){
R>   
R>   cutoff_i <- cutoffs[i]
R>   model_recommendation <- ifelse(
R>     VPRAI_synthetic_data$p_pretrial_failure > cutoff_i, 1, 0)
R>   
R>   bias_corrected_TPR[i] <- sum(predictive_prob_pf[,1] * 
R>     model_recommendation) /
R>     sum(predictive_prob_pf[,1])
R>   
R>   bias_corrected_FPR[i] <- sum(predictive_prob_pf[,2] *
R>     model_recommendation) /
R>     sum(predictive_prob_pf[,2])  
R> }
R> 
R> bias_corrected_roc_data <- data.frame(TPR = bias_corrected_TPR,
R>                                       FPR = bias_corrected_FPR)
R> 
R> ggplot(data = bias_corrected_roc_data) +
R>   geom_line(aes(x = FPR, y = TPR), color = "#409DBE") +
R>   geom_point(aes(x = FPR, y = TPR), color = "#409DBE") +
R>   theme_minimal() +
R>   geom_abline(slope = 1, intercept = 0) 
R> 
R> trapz(fliplr(bias_corrected_FPR), fliplr(bias_corrected_TPR))
R> [1] 0.866636
\end{lstlisting}

The resulting AUC estimate is 0.867. The resulting ROC curve is provided in Figure \ref{synthetic-VPRAI-ROC}.

\begin{figure}[h!]
\begin{center}
\includegraphics[width = \textwidth]{synthetic-vprai-ROC.png}
\caption{Receiver-operating characteristic (ROC) curve for the misclassification-corrected predicted probability of pretrial failure from the synthetic VPRAI pretrial dataset. The ROC curve is obtained using the misclassification-adjusted ROC approach from \cite{zawistowski2017corrected}. FPR stands for false positive rate and TPR stands for true positive rate.}\label{synthetic-VPRAI-ROC}
\end{center}
\end{figure}

Next, we evaluate the predictive accuracy of our bias-corrected model compared to VPRAI recommendations only among individuals in the dataset who were released ahead of their trial date. We first define this subset, and then compare our model-estimated probability of pretrial failure among individuals who actually did and did not experience pretrial failure. 

\begin{lstlisting}
R> release_subset <- VPRAI_synthetic_data %>%
R>   filter(judge == 2)
R> release_subset %>%
R>   group_by(pretrial_failure) %>%
R>   summarise(avg_p_pretrial_failure = mean(p_pretrial_failure))
R> # A tibble: 2 x 2
R>   pretrial_failure avg_p_pretrial_failure
R>              <int>                  <dbl>
R> 1                0                  0.169
R> 2                1                  0.453
\end{lstlisting}

In the synthetic dataset, the estimated probability of pretrial failure was 0.166 among individuals who truly did not experience a pretrial failure and was 0.481 among individuals who truly did experience a pretrial failure. 

Using this subset, we construct an ROC curve (Figure \ref{synthetic-subset-ROC}) and estimate the AUC for our bias-corrected risk estimates. We include the VPRAI accuracy as a single point because it only provides a recommendation output, rather than a range of risk probabilities. 

\begin{lstlisting}
R> cutoffs <- seq(0, 1, by = .01)
R> model_sensitivity <- rep(NA, length(cutoffs))
R> model_specificity <- rep(NA, length(cutoffs))
R> for(i in 1:length(cutoffs)){
R>   
R>   cutoff_i <- cutoffs[i]
R>   model_recommendation <- ifelse(
R>     release_subset$p_pretrial_failure > cutoff_i, 1, 0)
R>   
R>   model_sensitivity[i] <- (length(which(model_recommendation == 1 &
R>     release_subset$pretrial_failure == 1))) /
R>     length(which(release_subset$pretrial_failure == 1))
R>   
R>   model_specificity[i] <- (length(which(model_recommendation == 0 &
R>     release_subset$pretrial_failure == 0))) /
R>     length(which(release_subset$pretrial_failure == 0)) 
R> }
R> 
R> VPRAI_sensitivity <- (length(which(release_subset$vprai == 1 &
R>                         release_subset$pretrial_failure == 1))) /
R>   length(which(release_subset$pretrial_failure == 1))
R> 
R> VPRAI_specificity <- (length(which(release_subset$vprai == 2 &
R>                         release_subset$pretrial_failure == 0))) /
R>   length(which(release_subset$pretrial_failure == 0))
R> 
R> model_roc_data <- data.frame("FPR" = c(1 - model_specificity,
R>                                        1 - VPRAI_specificity),
R>                              "TPR" = c(model_sensitivity,
R>                                        VPRAI_sensitivity),
R>                              "Source" = c(rep("Model", 101),
R>                                           "VPRAI"))
R> 
R> ggplot(data = model_roc_data) +
R>   geom_line(aes(x = FPR, y = TPR, color = Source)) +
R>   geom_point(aes(x = FPR, y = TPR, color = Source, size = Source)) +
R>   theme_minimal() +
R>   geom_abline(slope = 1, intercept = 0) +
R>   scale_color_manual(values = c("#409DBE", "#ECA698"))
R> 
R> ## Model AUC
R> trapz(fliplr(1 - model_specificity), fliplr(model_sensitivity))
R> [1] 0.789579
R> ## VPRAI AUC
R> release_subset$vprai_01 <- ifelse(release_subset$vprai == 1, 1, 0)
R> auc(release_subset$pretrial_failure, release_subset$vprai_01)
R> Setting levels: control = 0, case = 1
R> Setting direction: controls < cases
R> Area under the curve: 0.7164
\end{lstlisting}

\begin{figure}[h!]
\begin{center}
\includegraphics[width = \textwidth]{synthetic-subset-ROC.png}
\caption{Receiver-operating characteristic (ROC) curve for the misclassification-corrected predicted probability of pretrial failure from the synthetic VPRAI pretrial dataset, limited to released individuals who have gold standard pretrial failure outcomes. TPR and FPR of the synthetic VPRAI are included as a single point, since multiple cutoffs cannot be evaluated for the VPRAI algorithm (the VPRAI algorithm returns a ``release'' or ``detain'' recommendation, rather than a continuous risk prediction). FPR stands for false positive rate and TPR stands for true positive rate.}\label{synthetic-subset-ROC}
\end{center}
\end{figure}

In this synthetic example, our bias-corrected risk predictions achieve a higher AUC than that of the VPRAI, 0.790 vs. 0.716, respectively. 

\section{PVW and OLS Estimation Functions}\label{COMMA-PVS-OLS-appendix}
