\draw (0,1/2) -- (3);
\draw (0,1/2) -- (4);
\draw (0,1/2) -- (0,0);
\end{tikzpicture}
\end{equation}
with trees $a_1,a_2,a_3$ previously constructed. In particular, this provides a very efficient way to represent $F_n$ as a sum of $p$ rooted trees with $1+(p-1)n$ leaves for general $p\ge1$. 

\medskip 

\begin{definition}
For any integer $n\ge1$, we define $\CS_n$ as the set of planted trees with $p+(p-1)(n-1)$ leaves and $\CT_n$ the set of decorated trees from $\CT_n$ where each nodes except the root has $p$ upgoing edges among which exactly $\frac{p-1}{2}$ are dotted.
\end{definition}

\medskip 

